window.MASTERGUIDE_QUIZ_DATA = {"all": {"title": "PwnBox Academy Master Guide - Full Test Bank", "totalChapters": 10, "totalQuestions": 504, "chapters": [{"chapter": 1, "chapterTitle": "Core Threats & Attacks", "termCount": 10, "questionCount": 54, "questions": [{"id": "ch1_q01", "termRef": "malware", "type": "definition", "difficulty": "easy", "question": "What does the term 'Malware' literally stand for, and what is its core purpose?", "options": ["Managed Software \u2014 provides automatic patch updates", "Mainframe Software \u2014 used to manage large servers", "Modular Software \u2014 used to install browser plugins", "Malicious Software \u2014 designed to deliberately harm a system"], "correctIndex": 3, "explanation": "Malware = Malicious + Software. Koi bhi software jo jaan-boojh kar system ko harm karta hai \u2014 data churaana, corrupt karna, ya control lena."}, {"id": "ch1_q02", "termRef": "malware", "type": "category", "difficulty": "medium", "question": "Which of the following is NOT classified as a type of malware?", "options": ["Ransomware", "Trojan Horse", "Firewall", "Rootkit"], "correctIndex": 2, "explanation": "Firewall ek defensive tool hai, malware nahi. Rootkit, Trojan aur Ransomware \u2014 sab malware ke forms hain."}, {"id": "ch1_q03", "termRef": "malware", "type": "analogy", "difficulty": "easy", "question": "In the guide's disease analogy, which illness is compared to a computer worm?", "options": ["Malaria \u2014 spreads through mosquito bites", "Common Cold \u2014 spreads through air", "Jaundice \u2014 causes slow, silent damage", "Cholera \u2014 spreads rapidly through water"], "correctIndex": 3, "explanation": "Analogy mein worm ko cholera se compare kiya gaya \u2014 jaise cholera paani se spread hoti hai, worm bhi network se khud-b-khud spread hota hai."}, {"id": "ch1_q04", "termRef": "malware", "type": "real_world", "difficulty": "medium", "question": "What was the estimated global financial loss caused by the WannaCry ransomware attack in 2017?", "options": ["$400 million", "$40 million", "$4 billion or more", "$4 million"], "correctIndex": 2, "explanation": "WannaCry ne 150 countries mein NHS hospitals, Telef\u00f3nica Spain, FedEx ko paralyze kiya \u2014 $4 billion+ ka estimated loss hua, ek unpatched Windows vulnerability se."}, {"id": "ch1_q05", "termRef": "malware", "type": "defense", "difficulty": "medium", "question": "Which of these is NOT listed as a recommended defense against malware?", "options": ["Running updated antivirus software", "Applying OS and software patches promptly", "Keeping regular offline backups", "Clicking unknown links to verify if they are safe"], "correctIndex": 3, "explanation": "Guide bolti hai unknown links/files pe click MAT karo \u2014 verify karne ke liye click karna hi risky habit hai."}, {"id": "ch1_q06", "termRef": "malware", "type": "scenario", "difficulty": "hard", "question": "Your laptop has become slow, an unknown background process is consuming CPU, and you recently installed cracked software from an untrusted website. What is most likely happening?", "options": ["A necessary RAM upgrade is required", "The battery is nearing the end of its life", "A routine Windows update is running", "A malware infection introduced through the cracked software"], "correctIndex": 3, "explanation": "Untrusted source se cracked software install karna malware ka common entry point hai \u2014 unknown process aur slowdown classic symptoms hain."}, {"id": "ch1_q07", "termRef": "phishing", "type": "definition", "difficulty": "easy", "question": "What does an attacker fundamentally do in a phishing attack?", "options": ["Floods a network with traffic", "Directly breaches a server's database", "Creates a fake email or website to steal credentials", "Physically steals a device"], "correctIndex": 2, "explanation": "Phishing mein attacker legit dikhne wali fake email/website/SMS banaata hai jisme victim apni credentials daal deta hai."}, {"id": "ch1_q08", "termRef": "phishing", "type": "category", "difficulty": "medium", "question": "Phishing carried out over a phone call is known as what?", "options": ["Smishing", "Spear Phishing", "Vishing", "Whaling"], "correctIndex": 2, "explanation": "Vishing = Voice + Phishing. Smishing SMS se, Whaling CEOs ko target karta hai, Spear Phishing naam se targeted hota hai."}, {"id": "ch1_q09", "termRef": "phishing", "type": "real_world", "difficulty": "hard", "question": "How much money did Evaldas Rimasauskas steal from Google and Facebook using fake invoices (2013\u20132015)?", "options": ["Over $100 million", "Over $1 billion", "Over $10 million", "Around $500,000"], "correctIndex": 0, "explanation": "Rimasauskas ne Quanta Computer impersonate karke fake invoices bheji \u2014 Google aur Facebook ne actually $100M+ pay kar diya."}, {"id": "ch1_q10", "termRef": "phishing", "type": "defense", "difficulty": "medium", "question": "According to the guide, what should you do if an email urgently demands immediate action, such as 'your account will be closed in 24 hours'?", "options": ["Forward the email to friends for a second opinion", "Change your password before doing anything else", "Pause and verify independently instead of reacting to the urgency", "Click the link immediately to resolve it"], "correctIndex": 2, "explanation": "Guide specifically bolti hai \u2014 koi bhi urgency feel ho toh ruko, verify karo. Urgency create karna attacker ki common tactic hai."}, {"id": "ch1_q11", "termRef": "phishing", "type": "scenario", "difficulty": "hard", "question": "You receive an email addressed to you by name, appearing to be from your company's CEO, urgently requesting a wire transfer. What kind of attack is this most likely to be?", "options": ["SQL Injection", "A DDoS attack", "A botnet recruitment attempt", "Spear Phishing (or Whaling if the CEO is the actual target)"], "correctIndex": 3, "explanation": "Naam se target karna aur specific person ko address karna Spear Phishing ki nishaani hai \u2014 agar high-value target (CEO) hai toh Whaling bhi keh sakte hain."}, {"id": "ch1_q12", "termRef": "ransomware", "type": "definition", "difficulty": "easy", "question": "What happens during a ransomware attack?", "options": ["The network is shut down due to traffic overload", "Data is only copied, nothing is locked", "The entire system is permanently deleted", "Files are encrypted and a payment is demanded to unlock them"], "correctIndex": 3, "explanation": "Ransomware files ko encrypt (lock) kar deta hai, phir Bitcoin mein payment maanga jaata hai decryption key ke liye."}, {"id": "ch1_q13", "termRef": "ransomware", "type": "category", "difficulty": "medium", "question": "Which of the following are common ways ransomware spreads, according to the guide?", "options": ["Only through physical theft of devices", "Only through USB drives", "Phishing emails, malicious attachments, unpatched software, and RDP brute-forcing", "Only through social media messages"], "correctIndex": 2, "explanation": "Guide ke mutabik ransomware phishing emails, malicious attachments, unpatched software, aur RDP bruteforce se spread hota hai."}, {"id": "ch1_q14", "termRef": "ransomware", "type": "real_world", "difficulty": "medium", "question": "How much ransom was paid during the Colonial Pipeline attack in 2021?", "options": ["$440,000", "$4.4 billion", "$44 million", "$4.4 million"], "correctIndex": 3, "explanation": "DarkSide ransomware ne US ki sabse badi fuel pipeline band kar di \u2014 $4.4 million ransom diya gaya, east coast mein fuel shortage aur panic buying hui."}, {"id": "ch1_q15", "termRef": "ransomware", "type": "defense", "difficulty": "medium", "question": "What does the guide's '3-2-1 rule' refer to?", "options": ["Backups: 3 copies of data, 2 different media types, 1 stored offsite", "Passwords: 3 words, 2 numbers, 1 symbol", "Encryption: 3 keys, 2 algorithms, 1 vault", "Network layers: 3 firewalls, 2 IDS systems, 1 honeypot"], "correctIndex": 0, "explanation": "3-2-1 backup rule: 3 copies of data, 2 different media types, 1 copy offsite \u2014 ransomware recovery ke liye critical defense."}, {"id": "ch1_q16", "termRef": "ransomware", "type": "scenario", "difficulty": "hard", "question": "A note suddenly appears on your screen: 'Your files are encrypted. Pay 2 BTC within 48 hours.' According to the guide, what should you NOT do first?", "options": ["Check whether backups of the affected files exist", "Pay the ransom immediately", "Inform your IT/security team", "Disconnect the system from the network"], "correctIndex": 1, "explanation": "Guide specifically bolti hai \u2014 pay mat karo, koi guarantee nahi ki key milegi hi. Pehla step hamesha isolate karna aur verify karna hai."}, {"id": "ch1_q17", "termRef": "ransomware", "type": "category", "difficulty": "medium", "question": "According to the guide's 'How It Works' breakdown, what typically happens right after ransomware encrypts your files?", "options": ["The system automatically restarts", "Files are automatically restored from backup", "Antivirus software instantly detects and removes it", "A ransom note appears with a Bitcoin address"], "correctIndex": 3, "explanation": "Steps: install \u2192 files dhundhna \u2192 AES-256 se encrypt \u2192 ransom note dikhna with Bitcoin address \u2192 timer shuru."}, {"id": "ch1_q18", "termRef": "botnet", "type": "definition", "difficulty": "easy", "question": "What is a botnet?", "options": ["A single, highly powerful hacking tool", "An encrypted messaging application", "A network of infected computers remotely controlled by an attacker", "A type of antivirus software"], "correctIndex": 2, "explanation": "Botnet = hazaron/laakhon infected computers ka network jise ek 'bot herder' (attacker) remotely control karta hai."}, {"id": "ch1_q19", "termRef": "botnet", "type": "category", "difficulty": "medium", "question": "Which of the following is NOT a common use of a botnet, according to the guide?", "options": ["Sending spam", "Cryptocurrency mining", "Launching DDoS attacks", "Legitimate software development"], "correctIndex": 3, "explanation": "Guide ke mutabik botnet uses: DDoS attacks, spam sending, crypto mining, credential theft, ad fraud \u2014 legitimate development inmein nahi aata."}, {"id": "ch1_q20", "termRef": "botnet", "type": "real_world", "difficulty": "medium", "question": "What type of devices did the Mirai Botnet (2016) primarily infect?", "options": ["IoT devices such as cameras and routers", "Only laptops", "Only smartphones", "Only enterprise servers"], "correctIndex": 0, "explanation": "Mirai ne IoT devices (cameras, routers) infect kiye aur Dyn DNS pe DDoS kiya \u2014 Twitter, Netflix, Amazon, Reddit US mein down ho gaye."}, {"id": "ch1_q21", "termRef": "botnet", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use to describe a botnet?", "options": ["Someone is secretly remote-controlling your phone in the background", "Someone forces your hand to sign a cheque while you sleep", "A disease that spreads in different forms", "A postman is secretly reading your letters"], "correctIndex": 0, "explanation": "Botnet analogy: tum normal use kar rahe ho, but background mein koi tumhara device remotely spam/attack ke liye use kar raha hai."}, {"id": "ch1_q22", "termRef": "botnet", "type": "scenario", "difficulty": "hard", "question": "You notice your router has been sending heavy outbound traffic 24/7 that you never initiated. What does this most likely indicate?", "options": ["The router has become part of a botnet", "This is normal background sync activity", "The router's firmware is updating", "The ISP has made a billing error"], "correctIndex": 0, "explanation": "Bina wajah heavy outbound traffic \u2014 especially IoT device jaise router se \u2014 botnet infection ka classic sign hai (jaise Mirai)."}, {"id": "ch1_q23", "termRef": "ddos", "type": "definition", "difficulty": "easy", "question": "Why does a server crash during a DDoS attack?", "options": ["The server's hardware physically fails", "The database becomes corrupted", "The power supply is cut off", "Thousands of bots send so much traffic at once that the server cannot handle it"], "correctIndex": 3, "explanation": "DDoS mein distributed bots massive traffic bhejte hain jisse server overload ho ke crash/freeze ho jaata hai \u2014 real users access nahi kar paate."}, {"id": "ch1_q24", "termRef": "ddos", "type": "category", "difficulty": "medium", "question": "What is the main difference between DoS and DDoS?", "options": ["DoS only targets websites; DDoS only targets apps", "They are the same attack with different names", "DoS comes from a single machine; DDoS is distributed across thousands of machines", "DoS is more dangerous than DDoS"], "correctIndex": 2, "explanation": "DoS single machine se attack hai (block karna easy), DDoS distributed hai hazaron machines se (block karna almost impossible)."}, {"id": "ch1_q25", "termRef": "ddos", "type": "real_world", "difficulty": "hard", "question": "The 2018 GitHub DDoS attack was the largest recorded at the time. What was its peak traffic speed?", "options": ["13.5 Tbps", "1.35 Tbps", "135 Gbps", "1.35 Gbps"], "correctIndex": 1, "explanation": "GitHub pe 1.35 Tbps ka attack hua tha \u2014 Memcached servers ka amplification exploit karke. GitHub 10 minutes down raha, phir Akamai ne absorb kiya."}, {"id": "ch1_q26", "termRef": "ddos", "type": "defense", "difficulty": "medium", "question": "Which technique does the guide recommend as a defense against DDoS attacks?", "options": ["Installing antivirus software", "Using parameterized SQL queries", "Using a CDN (such as Cloudflare or Akamai) to absorb traffic", "Increasing password complexity"], "correctIndex": 2, "explanation": "DDoS defenses: CDN use karo, rate limiting, Anycast network diffusion, ISP-level filtering \u2014 antivirus/password yeh DDoS-specific defenses nahi hain."}, {"id": "ch1_q27", "termRef": "ddos", "type": "scenario", "difficulty": "hard", "question": "Your e-commerce site crashes during a big sale, and traffic logs show 50,000 different IPs sending requests within the same second. What is most likely happening?", "options": ["A zero-day exploit", "A phishing campaign", "A SQL Injection attack", "A DDoS attack"], "correctIndex": 3, "explanation": "Multiple distributed IPs se massive simultaneous traffic \u2014 classic DDoS signature, genuine sale traffic itna sudden aur distributed nahi hota."}, {"id": "ch1_q28", "termRef": "mitm", "type": "definition", "difficulty": "easy", "question": "What does an attacker do in a Man-in-the-Middle (MITM) attack?", "options": ["Directly crashes the target server", "Sends a fake email to steal credentials", "Secretly inserts themselves between two parties to read or modify their data", "Installs malware on the victim's system"], "correctIndex": 2, "explanation": "MITM mein attacker do communicating parties ke beech secretly aa jaata hai aur unka data intercept/modify karta hai bina unko pata chale."}, {"id": "ch1_q29", "termRef": "mitm", "type": "category", "difficulty": "medium", "question": "What is it called when an attacker sets up a fake WiFi hotspot to intercept traffic?", "options": ["DNS Spoofing", "ARP Spoofing", "Evil Twin", "SSL Stripping"], "correctIndex": 2, "explanation": "Evil Twin = fake WiFi hotspot jo legit se same naam ka hota hai. ARP/DNS spoofing aur SSL stripping alag MITM techniques hain."}, {"id": "ch1_q30", "termRef": "mitm", "type": "analogy", "difficulty": "medium", "question": "Which analogy does the guide use to explain MITM attacks?", "options": ["A postman opens your letter, alters it, reseals it, and delivers it", "Someone is secretly controlling your phone remotely", "Thousands of bots send traffic at once", "A disease that spreads in different forms"], "correctIndex": 0, "explanation": "Postman analogy \u2014 letter tumne bheja, par beech mein koi usse open/modify karke aage bhej deta hai bina dono parties ko pata chale."}, {"id": "ch1_q31", "termRef": "mitm", "type": "scenario", "difficulty": "hard", "question": "After connecting to free airport WiFi, your banking app login fails and you see a suspicious certificate warning. What is most likely happening?", "options": ["Your password has expired", "A MITM attack (possibly an Evil Twin or SSL Stripping)", "The app simply needs an update", "Routine server maintenance"], "correctIndex": 1, "explanation": "Public WiFi + certificate warning = classic MITM red flag. Attacker traffic intercept karne ki koshish kar raha ho sakta hai."}, {"id": "ch1_q32", "termRef": "mitm", "type": "real_world", "difficulty": "medium", "question": "According to the guide, what is the most common MITM technique used at public WiFi locations like coffee shops or airports?", "options": ["Evil Twin \u2014 a fake hotspot with the same name", "Recruiting the device into a botnet", "Automatic ransomware installation", "SQL injection through the router"], "correctIndex": 0, "explanation": "Public WiFi pe attacker Evil Twin (same naam ka fake hotspot) banaata hai \u2014 victim connect hota hai, attacker sab traffic dekh leta hai."}, {"id": "ch1_q33", "termRef": "sqli", "type": "definition", "difficulty": "easy", "question": "What does an attacker do in a SQL Injection attack?", "options": ["Enters SQL code into a web form to trick the database", "Physically hacks into the database server", "Floods the network with traffic", "Sends malware through email"], "correctIndex": 0, "explanation": "SQL Injection mein attacker web forms mein malicious SQL code daalta hai jo database directly execute kar leta hai bina proper sanitization ke."}, {"id": "ch1_q34", "termRef": "sqli", "type": "category", "difficulty": "medium", "question": "Why does SQL Injection work in the first place?", "options": ["When a server's RAM becomes full", "When a firewall is disabled", "When a website inserts unsanitized user input directly into a SQL query", "When an HTTPS certificate expires"], "correctIndex": 2, "explanation": "Root cause: unsanitized user input directly SQL query mein jaana \u2014 attacker apna SQL command as input de deta hai jo execute ho jaata hai."}, {"id": "ch1_q35", "termRef": "sqli", "type": "scenario", "difficulty": "hard", "question": "Typing `admin'--` into a login form's username field can bypass the password check. What concept does this demonstrate?", "options": ["XSS \u2014 a script injected into the browser", "CSRF \u2014 a forged, unwanted request", "SQL Injection \u2014 '--' is a SQL comment, so the rest of the query is ignored", "Phishing \u2014 a fake login page"], "correctIndex": 2, "explanation": "Guide ke code example ke mutabik `admin'--` se query ka password-check part comment ban jaata hai SQL mein, aur skip ho jaata hai \u2014 classic SQLi."}, {"id": "ch1_q36", "termRef": "sqli", "type": "real_world", "difficulty": "medium", "question": "How many credit card numbers were stolen in the Heartland Payment Systems breach (2008) via SQL injection?", "options": ["13 million", "1.3 million", "1.3 billion", "130 million"], "correctIndex": 3, "explanation": "SQL injection se 130 million credit card numbers chori huye, $140 million+ settlement \u2014 us waqt US history ki largest data breach thi."}, {"id": "ch1_q37", "termRef": "sqli", "type": "defense", "difficulty": "medium", "question": "What is the primary technique the guide recommends for defending against SQL Injection?", "options": ["Closing firewall ports", "Parameterized queries / prepared statements", "Installing antivirus software", "Increasing password length"], "correctIndex": 1, "explanation": "Parameterized queries/prepared statements user input ko SQL command ki tarah execute hone se rokte hain \u2014 sabse effective SQLi defense."}, {"id": "ch1_q38", "termRef": "xss", "type": "definition", "difficulty": "easy", "question": "What does an attacker do in a Cross-Site Scripting (XSS) attack?", "options": ["Injects malicious JavaScript into a website that runs in the victim's browser", "Floods the server's bandwidth", "Directly accesses the database", "Physically steals a device"], "correctIndex": 0, "explanation": "XSS mein attacker JS inject karta hai; jab victim page open karta hai, uska browser attacker ka script run kar deta hai \u2014 cookies/tokens chori ho sakte hain."}, {"id": "ch1_q39", "termRef": "xss", "type": "category", "difficulty": "medium", "question": "A script that gets permanently saved in a database (such as in a comment section) is which type of XSS?", "options": ["Reflected XSS", "Stored XSS", "Blind XSS", "DOM-based XSS"], "correctIndex": 1, "explanation": "Stored XSS = script database mein save ho jaata hai (e.g. comments), Reflected = URL mein, DOM-based = client-side manipulation."}, {"id": "ch1_q40", "termRef": "xss", "type": "real_world", "difficulty": "medium", "question": "How many profiles did the Samy Worm (MySpace, 2005) infect within a single day?", "options": ["Over 10 million", "Over 100,000", "Over 10,000", "Over 1 million"], "correctIndex": 3, "explanation": "Samy Kamkar ne XSS script daali, ek din mein 1 million+ profiles ne automatically 'Samy is my hero' add kar liya \u2014 history ka fastest spreading virus."}, {"id": "ch1_q41", "termRef": "xss", "type": "scenario", "difficulty": "hard", "question": "A user posts a script in a forum's comment box that steals cookies, and it gets saved permanently. What is the risk?", "options": ["Nothing happens, browsers block this automatically", "Only the commenter's own account will be compromised", "Every user who views the page will have their cookies sent to the attacker (Stored XSS)", "The forum's database will be deleted"], "correctIndex": 2, "explanation": "Yeh Stored XSS ka classic example hai \u2014 script database mein saved hai, jo bhi page open karega uska browser script run karega aur cookie chori hogi."}, {"id": "ch1_q42", "termRef": "xss", "type": "defense", "difficulty": "medium", "question": "What is the most fundamental step to protect a website from Stored/Reflected XSS?", "options": ["Use HTTPS only", "Close all firewall ports", "Escape or sanitize user input before rendering it as output", "Install antivirus software on the server"], "correctIndex": 2, "explanation": "User-supplied input ko HTML mein render karne se pehle escape karna (jaise `escapeHtml()`) XSS ka fundamental defense hai."}, {"id": "ch1_q43", "termRef": "csrf", "type": "definition", "difficulty": "easy", "question": "What happens in a CSRF (Cross-Site Request Forgery) attack?", "options": ["The attacker installs malware on the victim's device", "The attacker directly steals the victim's password", "The attacker floods the server with traffic", "The attacker tricks the victim's browser into performing an unwanted action using their active login session"], "correctIndex": 3, "explanation": "Tum logged in ho bank.com pe; evil website background mein bank.com ko request bhejti hai tumhare naam se \u2014 tumhare cookies/auth use karke."}, {"id": "ch1_q44", "termRef": "csrf", "type": "category", "difficulty": "medium", "question": "Why does CSRF work?", "options": ["The network connection is unencrypted", "Browsers automatically attach same-domain cookies to every request", "The user's password is weak", "The server's encryption is weak"], "correctIndex": 1, "explanation": "Browser automatically cookies attach karta hai same-domain requests mein \u2014 attacker isi cheez ka fayda uthata hai, tumhara browser khud auth kar deta hai."}, {"id": "ch1_q45", "termRef": "csrf", "type": "analogy", "difficulty": "medium", "question": "Which analogy does the guide use for CSRF?", "options": ["A postman opens and reads your letter", "Someone forces your hand to sign a cheque while you are asleep", "Someone is remotely controlling your phone", "A disease that spreads in different forms"], "correctIndex": 1, "explanation": "CSRF analogy: signature tumhara hai but tumne consciously sign nahi kiya \u2014 browser ne unknowingly action authorize kar diya, jaise neend mein sign karwaana."}, {"id": "ch1_q46", "termRef": "csrf", "type": "defense", "difficulty": "medium", "question": "Which technique does the guide recommend as a defense against CSRF?", "options": ["Regular data backups", "CSRF tokens \u2014 a unique token included in every request", "Antivirus scanning", "A strong password policy"], "correctIndex": 1, "explanation": "CSRF defenses: unique CSRF tokens har request mein, SameSite cookie attribute, aur server-side origin header verification."}, {"id": "ch1_q47", "termRef": "csrf", "type": "scenario", "difficulty": "hard", "question": "While logged into your bank account, you briefly open a random website in a new tab that closes itself immediately. Later, you discover an unauthorized transfer occurred. What likely happened?", "options": ["A botnet infection", "A DDoS attack", "A zero-day exploit", "A CSRF attack"], "correctIndex": 3, "explanation": "Background mein evil website ne tumhare active bank session (cookies) use karke unauthorized request bhej di \u2014 classic CSRF scenario."}, {"id": "ch1_q48", "termRef": "zeroday", "type": "definition", "difficulty": "easy", "question": "Why is it called a 'Zero-Day' exploit?", "options": ["The attack completes within a single day", "The exploit is sold for zero cost on the dark web", "The vendor has had zero days to build a fix, and attackers are already exploiting it", "The attack happens with zero seconds of warning"], "correctIndex": 2, "explanation": "Vulnerability abhi discover hua hai, patch exist nahi karta \u2014 vendor ke paas 'zero days' hain fix karne ke liye, aur attacker already exploit kar raha hai."}, {"id": "ch1_q49", "termRef": "zeroday", "type": "category", "difficulty": "medium", "question": "According to the guide, how much can a zero-day exploit sell for on the dark web?", "options": ["Around $100", "$1 million or more", "Around $1,000", "Around $10,000"], "correctIndex": 1, "explanation": "Zero-day exploits dark web pe $1M+ mein bikte hain \u2014 intelligence agencies bhi buy karti hain, Google Project Zero inhe hunt karta hai."}, {"id": "ch1_q50", "termRef": "zeroday", "type": "real_world", "difficulty": "hard", "question": "How many zero-day exploits did Stuxnet (2010) use simultaneously, which was considered unprecedented?", "options": ["1", "10", "2", "4"], "correctIndex": 3, "explanation": "Stuxnet ne 4 zero-days ek saath use kiye \u2014 Iran ke Natanz facility mein 1,000 centrifuges destroy kiye bina koi bomb use kiye."}, {"id": "ch1_q51", "termRef": "zeroday", "type": "scenario", "difficulty": "hard", "question": "A researcher discovers a new bug with no patch available yet, and attackers are already exploiting it in the wild. What is this called?", "options": ["A botnet attack", "A SQL Injection attack", "A phishing campaign", "A zero-day exploit"], "correctIndex": 3, "explanation": "Bina patch ke, already-exploited-in-the-wild vulnerability \u2014 yehi zero-day exploit ki definition hai."}, {"id": "ch1_q52", "termRef": "malware", "type": "category", "difficulty": "medium", "question": "How many of Chapter 1's 10 terms carry the 'Threat' badge in the guide?", "options": ["5", "3", "7", "All 10"], "correctIndex": 3, "explanation": "Chapter 1 ('Core Threats & Attacks') ke saare 10 terms \u2014 Malware se Zero-Day tak \u2014 'Threat' badge ke saath categorized hain."}, {"id": "ch1_q53", "termRef": "ransomware", "type": "category", "difficulty": "hard", "question": "Based on the guide's severity bars, which of these Chapter 1 threats has the highest listed severity?", "options": ["Ransomware (95%)", "Botnet (80%)", "DDoS (75%)", "CSRF (65%)"], "correctIndex": 0, "explanation": "Guide ke severity bars ke mutabik Ransomware 95% ke saath sabse high hai Chapter 1 mein, jabki Zero-day 98% ke saath overall highest hai."}, {"id": "ch1_q54", "termRef": "phishing", "type": "scenario", "difficulty": "hard", "question": "In a real attack chain, a phishing email first steals an employee's password, which the attacker then uses to perform SQL injection on the company database. What does this illustrate?", "options": ["Multi-stage attacks \u2014 one weak point (phishing) becomes the gateway to a bigger attack (SQLi)", "Phishing and SQLi are never used together", "This is a single-step attack", "This is purely theoretical and doesn't happen in reality"], "correctIndex": 0, "explanation": "Real-world attacks rarely single-technique hote hain \u2014 chapter ke saare threats ek dusre ke saath chain ban sakte hain, isliye har layer ki defense zaroori hai."}]}, {"chapter": 2, "chapterTitle": "Malware Types", "termCount": 10, "questionCount": 50, "questions": [{"id": "ch2_q01", "termRef": "virus", "type": "definition", "difficulty": "easy", "question": "What does a computer virus fundamentally do?", "options": ["Attaches itself to existing files and activates when the infected file is run", "Spreads automatically across a network without any user action", "Disguises itself as legitimate software to trick users into installing it", "Hides at the operating system's kernel level to avoid detection"], "correctIndex": 0, "explanation": "Virus ek malicious code hai jo existing files mein attach ho jaata hai \u2014 jab infected file run hoti hai, virus execute hota hai aur doosri files ko infect karna shuru karta hai."}, {"id": "ch2_q02", "termRef": "virus", "type": "category", "difficulty": "medium", "question": "What is the key characteristic that distinguishes a virus from a worm?", "options": ["A virus can spread entirely on its own across a network", "A virus always disguises itself as useful software", "A virus requires human action (like sharing a file) to spread further", "A virus hides at the kernel level of the OS"], "correctIndex": 2, "explanation": "Virus ko spread hone ke liye human help chahiye \u2014 infected file kisi ko deni padti hai (email, USB, download). Worm ke u\u0932\u091f, yeh automatic nahi hota."}, {"id": "ch2_q03", "termRef": "virus", "type": "real_world", "difficulty": "medium", "question": "The ILOVEYOU virus (2000) spread through an email attachment. How many computers did it infect within 10 days?", "options": ["500,000", "5 million", "50 million", "5 billion"], "correctIndex": 2, "explanation": "ILOVEYOU email attachment 'LOVE-LETTER-FOR-YOU.txt.vbs' ke through millions ne open kiya \u2014 10 din mein 50 million computers infect hue, $10 billion ka damage."}, {"id": "ch2_q04", "termRef": "virus", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use to describe how a virus spreads?", "options": ["Like thousands of bots flooding a server at once", "Like a biological flu virus \u2014 it needs contact with an infected carrier", "Like a postman secretly reading your mail", "Like a fake ID card used to gain trust"], "correctIndex": 1, "explanation": "Biological virus jaisa \u2014 apne aap nahi chalta, kisi infected insaan/file se contact chahiye. Ek infected USB \u2192 PC \u2192 shared drive \u2192 colleagues."}, {"id": "ch2_q05", "termRef": "virus", "type": "scenario", "difficulty": "hard", "question": "You share a USB drive containing an infected file with a colleague, and their computer soon shows the same symptoms as yours. What does this demonstrate?", "options": ["Classic worm behavior \u2014 it spread automatically across the network", "A supply chain attack through the USB manufacturer", "Classic virus behavior \u2014 it spreads only when a human action carries the infected file", "A rootkit hiding itself from both systems"], "correctIndex": 2, "explanation": "Virus ko spread hone ke liye human action chahiye \u2014 file share karna jaisa. Yeh worm se alag hai jo bina kisi help ke khud spread hota hai."}, {"id": "ch2_q06", "termRef": "worm", "type": "definition", "difficulty": "easy", "question": "What makes a worm different from ordinary malware in how it spreads?", "options": ["It requires a user to open an infected file first", "It spreads automatically across a network by exploiting vulnerabilities, with no human action needed", "It disguises itself as a useful application", "It only activates when a specific date is reached"], "correctIndex": 1, "explanation": "Worm standalone hai \u2014 kisi file se attach nahi hota, koi human action nahi chahiye. Network vulnerabilities exploit karke apne aap spread hota hai."}, {"id": "ch2_q07", "termRef": "worm", "type": "category", "difficulty": "medium", "question": "Besides spreading itself, what else can a worm do according to the guide?", "options": ["Carry additional payloads like ransomware or keyloggers and deliver them automatically", "Only record keystrokes", "Only display unwanted advertisements", "Only monitor browsing history"], "correctIndex": 0, "explanation": "Worm network bandwidth kha jaata hai aur side payloads bhi carry karta hai \u2014 jaise ransomware ya keyloggers automatically deliver karna."}, {"id": "ch2_q08", "termRef": "worm", "type": "real_world", "difficulty": "medium", "question": "WannaCry (2017) used the EternalBlue exploit and needed no user action at all. How many computers did it infect across 150 countries?", "options": ["300,000+", "3 million+", "30,000,000+", "30,000+"], "correctIndex": 0, "explanation": "WannaCry ne EternalBlue exploit (NSA ka stolen tool) use karke Windows SMB vulnerability attack ki \u2014 300,000+ computers, 150 countries, bina kisi user action ke."}, {"id": "ch2_q09", "termRef": "worm", "type": "scenario", "difficulty": "hard", "question": "Malware spreads from one machine to an entire office network overnight, with no employee clicking on anything or opening any file. What type of malware behavior does this match?", "options": ["A virus \u2014 requires a human carrier", "Adware \u2014 requires a bundled download", "A Trojan \u2014 requires voluntary installation", "A worm \u2014 self-spreading via network vulnerabilities"], "correctIndex": 3, "explanation": "Bina kisi human action ke poore network mein spread hona worm ki nishaani hai \u2014 ek infected machine se poora network infect ho sakta hai."}, {"id": "ch2_q10", "termRef": "worm", "type": "category", "difficulty": "medium", "question": "What is the practical impact of a worm on a network's infrastructure?", "options": ["It consumes network bandwidth and can overload servers", "It only intercepts keyboard input", "It only affects a single file on a single machine", "It only displays pop-up advertisements"], "correctIndex": 0, "explanation": "Worm network bandwidth kha jaata hai aur servers ko overload kar deta hai \u2014 apne aap replicate hote hue."}, {"id": "ch2_q11", "termRef": "trojan", "type": "definition", "difficulty": "easy", "question": "What is a Trojan Horse malware?", "options": ["Malware that hides at the operating system's kernel level", "Software that appears legitimate and useful but contains malicious code inside", "Malware that spreads automatically without any human action", "Malware that only displays unwanted advertisements"], "correctIndex": 1, "explanation": "Legit software ki tarah dikhta hai (game, utility, crack) par andar malicious code hota hai \u2014 tum khud install karte ho."}, {"id": "ch2_q12", "termRef": "trojan", "type": "category", "difficulty": "medium", "question": "Which of these is NOT one of the Trojan types mentioned in the guide?", "options": ["Downloader Trojan", "Polymorphic Trojan", "Backdoor Trojan", "Banking Trojan"], "correctIndex": 1, "explanation": "Guide mein listed types: Banking Trojans (credentials chori), RATs, Backdoor Trojans, aur Downloader Trojans \u2014 'Polymorphic Trojan' iss list mein nahi hai."}, {"id": "ch2_q13", "termRef": "trojan", "type": "real_world", "difficulty": "medium", "question": "The Zeus Trojan (2007\u20132010) stole banking credentials. How much money did it steal in total?", "options": ["Over $7 billion", "Over $700 million", "Over $7 million", "Over $70 million"], "correctIndex": 3, "explanation": "Zeus Trojan ne 70,000+ organizations affect kiye, $70 million+ chura liye including NASA computers \u2014 typically ek pirated game ke saath aata tha."}, {"id": "ch2_q14", "termRef": "trojan", "type": "analogy", "difficulty": "easy", "question": "Which historical reference inspired the name 'Trojan Horse' malware?", "options": ["A postman secretly opening private letters", "A disease spreading through unaware carriers", "A guard checking IDs at a building entrance", "The Greek mythology story of soldiers hidden inside a gift horse"], "correctIndex": 3, "explanation": "Greek mythology ke Trojan Horse jaisa \u2014 gift ke andar soldiers chhupe the, waise hi legit-looking software ke andar malicious code chhupa hota hai."}, {"id": "ch2_q15", "termRef": "trojan", "type": "scenario", "difficulty": "hard", "question": "You downloaded a cracked version of a paid game from an unofficial website, and weeks later your bank account was accessed without your permission. What likely happened?", "options": ["Your bank's server had a zero-day exploit", "A CSRF attack was executed through your browser", "A Banking Trojan was bundled with the cracked game", "A DDoS attack targeted your bank directly"], "correctIndex": 2, "explanation": "Cracked/pirated software ke saath Trojan bundle hona common hai \u2014 Zeus Trojan jaisa banking Trojan credentials chura leta hai."}, {"id": "ch2_q16", "termRef": "rootkit", "type": "definition", "difficulty": "easy", "question": "What does a rootkit do at a technical level?", "options": ["Spreads automatically through network vulnerabilities", "Records every keystroke a user types", "Installs itself at the operating system's deepest (kernel) level to hide itself and other malware", "Displays unwanted pop-up advertisements"], "correctIndex": 2, "explanation": "Rootkit OS ke deepest level (kernel) mein install hota hai aur apne aap ko aur doosre malware ko antivirus se hide karta hai."}, {"id": "ch2_q17", "termRef": "rootkit", "type": "category", "difficulty": "medium", "question": "Why is a rootkit especially dangerous compared to standard malware?", "options": ["It always disguises itself as a game or utility", "It always spreads without any human action", "Standard antivirus software often cannot detect it because it intercepts system calls and returns fake information", "It is limited to displaying advertisements only"], "correctIndex": 2, "explanation": "Rootkit OS ke andar se hi system calls intercept karta hai aur fake information return karta hai \u2014 remove karna almost impossible ho jaata hai."}, {"id": "ch2_q18", "termRef": "rootkit", "type": "real_world", "difficulty": "hard", "question": "The Sony BMG CD Rootkit scandal (2005) involved Sony secretly embedding a rootkit in music CDs. How many CDs were affected?", "options": ["220 million", "2.2 million", "22 million", "220,000"], "correctIndex": 2, "explanation": "Sony ne music CDs mein rootkit embed kiya DRM ke liye \u2014 22 million CDs affected, bina bataye users ke computers pe install ho jaata tha, massive public outrage."}, {"id": "ch2_q19", "termRef": "rootkit", "type": "scenario", "difficulty": "hard", "question": "Your antivirus keeps reporting the system as 'clean', but Task Manager doesn't show a process that is clearly consuming resources, and the system behaves suspiciously. What is most likely present?", "options": ["A rootkit hiding itself at the kernel level", "A DDoS attack originating from your machine", "Ordinary adware", "A simple phishing email"], "correctIndex": 0, "explanation": "Rootkit ki khaasiyat hi yeh hai ki woh antivirus aur task manager dono se khud ko chhupa leta hai \u2014 system calls intercept karke fake info deta hai."}, {"id": "ch2_q20", "termRef": "rootkit", "type": "category", "difficulty": "medium", "question": "What do the two parts of the word 'Rootkit' refer to?", "options": ["'Root' = a network protocol, 'Kit' = an encryption method", "'Root' = highest admin access, 'Kit' = a collection of tools", "'Root' = a hacking group, 'Kit' = a malware family", "'Root' = the file system, 'Kit' = an antivirus bypass"], "correctIndex": 1, "explanation": "'Root' matlab highest admin access, 'Kit' matlab tools ka collection \u2014 isliye rootkit naam pada."}, {"id": "ch2_q21", "termRef": "keylogger", "type": "definition", "difficulty": "easy", "question": "What does a keylogger do?", "options": ["Quietly records every keystroke and sends the log to the attacker", "Spreads automatically across a network", "Encrypts files and demands a ransom", "Displays unwanted advertisements automatically"], "correctIndex": 0, "explanation": "Background mein quietly tumhare keyboard ke har key press ko record karta hai, phir log file attacker ko bhejta hai \u2014 passwords, messages sab caught."}, {"id": "ch2_q22", "termRef": "keylogger", "type": "category", "difficulty": "medium", "question": "Which of these is NOT one of the keylogger types mentioned in the guide?", "options": ["Cloud-based keylogger", "Browser-based keylogger", "Software keylogger (OS-level hook)", "Hardware keylogger (physical device)"], "correctIndex": 0, "explanation": "Guide ke types: Software (OS level hook), Hardware (physical device between keyboard and PC), Browser-based (form data intercept) \u2014 'Cloud-based' iss list mein nahi hai."}, {"id": "ch2_q23", "termRef": "keylogger", "type": "defense", "difficulty": "medium", "question": "Which defense specifically neutralizes a keylogger's ability to steal a typed password?", "options": ["Using a VPN", "Regularly clearing your browser cache", "Enabling 2FA, since a stolen password alone becomes useless", "Installing a firewall"], "correctIndex": 2, "explanation": "2FA se keylogger useless ho jaata hai passwords ke liye \u2014 password chori bhi ho jaaye, dusra factor attacker ke paas nahi hota."}, {"id": "ch2_q24", "termRef": "keylogger", "type": "scenario", "difficulty": "hard", "question": "Your banking password was compromised despite never clicking any suspicious link, and you recently used a public library computer to check your email. What is a likely cause?", "options": ["A DDoS attack on the bank's servers", "A supply chain attack on your bank", "A hardware or software keylogger installed on the shared public computer", "A CSRF attack from a browser tab"], "correctIndex": 2, "explanation": "Public/shared computers pe keylogger install hone ka risk hota hai \u2014 physical device ya software hook se keystrokes record ho sakti hain."}, {"id": "ch2_q25", "termRef": "keylogger", "type": "category", "difficulty": "medium", "question": "How does a keylogger differ from spyware in scope, according to the guide?", "options": ["A keylogger is broader than spyware", "A keylogger only works on mobile devices", "A keylogger only captures keystrokes, while spyware is broader and can capture screenshots, location, and more", "They are exactly the same thing with different names"], "correctIndex": 2, "explanation": "Keylogger sirf keystrokes capture karta hai, jabki Spyware broader hai \u2014 screenshots, file access, location, social media, call logs sab."}, {"id": "ch2_q26", "termRef": "spyware", "type": "definition", "difficulty": "easy", "question": "What does spyware do once installed on a device?", "options": ["Silently monitors activities like browsing history, location, and camera/microphone access, and sends the data to the attacker", "Only records keyboard input", "Only displays unwanted advertisements", "Encrypts files and demands payment"], "correctIndex": 0, "explanation": "Background mein chup ke tumhari activities monitor karta hai \u2014 browsing history, location, contacts, camera/microphone access, screenshots \u2014 data attacker ko remotely bhejta hai."}, {"id": "ch2_q27", "termRef": "spyware", "type": "real_world", "difficulty": "hard", "question": "Pegasus Spyware (developed by NSO Group) was notable for what unusual infection method?", "options": ["It spread only through infected USB drives", "It required victims to enter their password on a fake page", "It required victims to download a fake update", "Zero-click exploits \u2014 the victim didn't need to click anything at all"], "correctIndex": 3, "explanation": "Pegasus iOS aur Android zero-click exploit se install hota tha \u2014 tumhe kuch click bhi nahi karna. Journalists, activists, world leaders targeted."}, {"id": "ch2_q28", "termRef": "spyware", "type": "scenario", "difficulty": "hard", "question": "A journalist's phone gets compromised without them ever clicking a link, downloading a file, or entering any credentials. What kind of attack does this most closely match?", "options": ["A zero-click spyware attack (like Pegasus)", "A brute force attack on their email password", "A SQL injection attack", "A DDoS attack on their phone carrier"], "correctIndex": 0, "explanation": "Zero-click exploits mein victim ko kuch bhi action lene ki zaroorat nahi \u2014 Pegasus jaisa spyware bina interaction ke install ho sakta hai."}, {"id": "ch2_q29", "termRef": "spyware", "type": "category", "difficulty": "medium", "question": "Which of these is within spyware's typical data-collection scope, according to the guide?", "options": ["Only network traffic between two servers", "Screenshots, camera/microphone access, and location data", "Only firewall log entries", "Only DNS lookup records"], "correctIndex": 1, "explanation": "Spyware broader scope rakhta hai \u2014 screenshots, file access, location, social media, call logs, camera/mic access sab collect kar sakta hai."}, {"id": "ch2_q30", "termRef": "spyware", "type": "category", "difficulty": "hard", "question": "Who reportedly used Pegasus spyware to monitor the network around journalist Jamal Khashoggi, according to the guide?", "options": ["Saudi Arabia", "A US intelligence agency", "A private cybercrime group", "North Korea"], "correctIndex": 0, "explanation": "Guide ke mutabik Saudi Arabia ne Pegasus use kiya journalist Jamal Khashoggi ke network ko monitor karne ke liye."}, {"id": "ch2_q31", "termRef": "adware", "type": "definition", "difficulty": "easy", "question": "What is the primary behavior of adware?", "options": ["Encrypts files and demands a ransom", "Automatically displays unwanted ads such as pop-ups and browser redirects", "Hides itself at the kernel level of the OS", "Records every keystroke silently"], "correctIndex": 1, "explanation": "Adware automatically ads show karta hai \u2014 popups, browser redirects, fake alerts. Revenue generate karta hai advertiser ke liye, free software ke saath bundled aata hai."}, {"id": "ch2_q32", "termRef": "adware", "type": "category", "difficulty": "medium", "question": "Beyond being annoying, what serious risk can adware pose?", "options": ["It can physically damage computer hardware", "It can single-handedly encrypt an entire hard drive", "It always installs a rootkit alongside itself", "Malvertising (malicious ads) can lead to downloading more serious malware"], "correctIndex": 3, "explanation": "Mostly annoying, but some adware spyware ka gateway hai \u2014 malvertising (malicious ads) se serious malware download ho sakta hai, browser settings hijack ho sakti hain."}, {"id": "ch2_q33", "termRef": "adware", "type": "scenario", "difficulty": "medium", "question": "After installing a free utility tool, your browser homepage changed on its own and you now see constant pop-up ads. What has most likely happened?", "options": ["A DDoS attack has occurred", "Adware was bundled with the free software", "A ransomware attack has encrypted your files", "SQL injection has affected your browser"], "correctIndex": 1, "explanation": "Free software ke saath adware bundled aana common hai \u2014 browser hijack, popups, redirects yeh sab adware ki classic symptoms hain."}, {"id": "ch2_q34", "termRef": "adware", "type": "category", "difficulty": "medium", "question": "How does adware typically reach a victim's system?", "options": ["Only through physical USB infection", "Only through unpatched server vulnerabilities", "Only through targeted phishing emails", "Bundled together with free software downloads"], "correctIndex": 3, "explanation": "Adware free software ke saath bundled aata hai often \u2014 user ko pata bhi nahi chalta ki install karte waqt adware bhi saath install ho gaya."}, {"id": "ch2_q35", "termRef": "adware", "type": "category", "difficulty": "hard", "question": "Compared to spyware, what is adware's primary purpose?", "options": ["Providing remote access to the attacker", "Generating advertising revenue rather than stealing personal data (though it can become a gateway to spyware)", "Encrypting files for ransom", "Stealing banking credentials directly"], "correctIndex": 1, "explanation": "Adware ka primary purpose ad revenue generate karna hai, spyware ka primary purpose data churana \u2014 lekin adware kabhi-kabhi spyware ka gateway ban jaata hai."}, {"id": "ch2_q36", "termRef": "fileless", "type": "definition", "difficulty": "easy", "question": "What makes fileless malware difficult for traditional antivirus to detect?", "options": ["It only operates during specific hours of the day", "It disguises its file name to look like a system file", "It only targets mobile devices, which antivirus can't scan", "It runs directly in RAM or abuses legitimate tools like PowerShell, without writing any file to disk"], "correctIndex": 3, "explanation": "Disk pe koi file nahi likhta, directly RAM mein run karta hai ya Windows ke legitimate tools (PowerShell, WMI) abuse karta hai \u2014 antivirus file scan nahi kar sakta kyunki file hi nahi hai."}, {"id": "ch2_q37", "termRef": "fileless", "type": "category", "difficulty": "medium", "question": "What is the technique of abusing an operating system's own legitimate tools for an attack called?", "options": ["Credential Stuffing", "Living-off-the-Land (LotL)", "Supply Chain Compromise", "Privilege Escalation"], "correctIndex": 1, "explanation": "Living-off-the-land (LotL) attack \u2014 PowerShell, cmd, regedit jaise Windows ke apne tools use karta hai, computer restart pe woh gone but damage ho chuka hota hai."}, {"id": "ch2_q38", "termRef": "fileless", "type": "real_world", "difficulty": "hard", "question": "During Operation Cobalt Kitty (2017), how long did the fileless malware attack on a Vietnamese bank remain undetected?", "options": ["6 days", "6 years", "6 months", "6 weeks"], "correctIndex": 2, "explanation": "Operation Cobalt Kitty mein PowerShell aur WMI tools use hone ki wajah se attack 6 mahine tak undetected raha \u2014 $200M+ theft attempt hua."}, {"id": "ch2_q39", "termRef": "fileless", "type": "scenario", "difficulty": "hard", "question": "After a system reboot, security investigators find no malicious file anywhere on disk, yet unusual activity had clearly occurred beforehand. What does this suggest?", "options": ["A fileless malware attack that ran entirely in RAM", "A Trojan disguised as a legitimate program", "Adware bundled with free software", "A standard virus that requires a host file"], "correctIndex": 0, "explanation": "Fileless malware disk pe koi trace nahi chhodta \u2014 RAM mein run hota hai, restart hote hi gayab ho jaata hai, but tab tak damage ho chuka hota hai."}, {"id": "ch2_q40", "termRef": "fileless", "type": "category", "difficulty": "medium", "question": "Which legitimate Windows tools are commonly abused in fileless malware attacks?", "options": ["File Explorer only", "Task Manager and Control Panel", "Notepad and Paint", "PowerShell, cmd, and WMI"], "correctIndex": 3, "explanation": "PowerShell, cmd, regedit \u2014 Windows ke apne legitimate tools use karta hai fileless malware, isliye detect karna mushkil hota hai."}, {"id": "ch2_q41", "termRef": "rat", "type": "definition", "difficulty": "easy", "question": "What can an attacker do once a Remote Access Trojan (RAT) is installed on a victim's PC?", "options": ["Only encrypt files for ransom", "Remotely control the mouse, keyboard, camera, microphone, and files, all without the victim's knowledge", "Only display unwanted advertisements", "Only monitor network bandwidth usage"], "correctIndex": 1, "explanation": "Attacker tumhara poora computer remotely control kar sakta hai \u2014 mouse, keyboard, camera, microphone, files, install software \u2014 TeamViewer jaisa but bina tumhari knowledge ke."}, {"id": "ch2_q42", "termRef": "rat", "type": "category", "difficulty": "medium", "question": "Which of the following is something a RAT-infected computer can be used for, according to the guide?", "options": ["Being added to a botnet", "Only serving as a VPN exit node", "Only mining cryptocurrency", "Only sending spam SMS messages"], "correctIndex": 0, "explanation": "Attacker screen dekh sakta hai live, camera on kar sakta hai, files copy/delete, keylog, bank transfers, screenshot, aur tumhare PC ko botnet mein add kar sakta hai."}, {"id": "ch2_q43", "termRef": "rat", "type": "real_world", "difficulty": "hard", "question": "The Blackshades RAT (2012\u20132014) was created by a 17-year-old and sold on the dark web for how much?", "options": ["$4", "$400", "$40", "$4,000"], "correctIndex": 2, "explanation": "17-year-old Swedish teen ne banaya, $40 pe dark web pe becha \u2014 700,000 computers compromise huye, FBI ne worldwide sting operation chalayi."}, {"id": "ch2_q44", "termRef": "rat", "type": "scenario", "difficulty": "hard", "question": "Your webcam indicator light turns on randomly when you're not using any camera app, and files seem to move on their own. What is most likely happening?", "options": ["A firmware update is in progress", "A Remote Access Trojan (RAT) is giving an attacker control of your device", "A routine antivirus scan is running", "Your webcam driver is malfunctioning"], "correctIndex": 1, "explanation": "Webcam randomly on hona aur files move hona bina apne action ke \u2014 RAT ki classic nishaani hai, attacker ke paas full remote control hai."}, {"id": "ch2_q45", "termRef": "rat", "type": "category", "difficulty": "medium", "question": "Which legitimate software does a RAT most closely resemble in function, minus the victim's consent?", "options": ["Antivirus software", "A password manager", "A web browser", "Remote desktop tools like TeamViewer"], "correctIndex": 3, "explanation": "TeamViewer jaisa, but without your knowledge \u2014 attacker legitimate remote-access tool jaisi hi functionality use karta hai bina consent ke."}, {"id": "ch2_q46", "termRef": "raas", "type": "definition", "difficulty": "easy", "question": "What is Ransomware as a Service (RaaS)?", "options": ["A government program that helps victims recover from ransomware", "A cloud service that automatically backs up files to prevent ransomware", "A type of antivirus subscription service", "A business model where ransomware developers rent out their malware to other attackers on the dark web"], "correctIndex": 3, "explanation": "SaaS ki tarah, but evil \u2014 ransomware developers apna malware dark web pe 'rent' pe dete hain, koi bhi coding nahi jaanta buy kar sakta hai."}, {"id": "ch2_q47", "termRef": "raas", "type": "category", "difficulty": "medium", "question": "In a typical RaaS revenue split, what percentage does the attacker (the person launching the attack) usually keep?", "options": ["90%", "30%", "50%", "70%"], "correctIndex": 3, "explanation": "70-30 split typically \u2014 attacker 70% leta hai ransom ka, developer 30% \u2014 support aur control panel bhi milta hai, pure criminal enterprise."}, {"id": "ch2_q48", "termRef": "raas", "type": "real_world", "difficulty": "medium", "question": "The DarkSide RaaS group (behind the Colonial Pipeline attack) reportedly had which unusual feature?", "options": ["A 'code of ethics' that told affiliates not to attack hospitals", "A public bug bounty program", "Free antivirus for its customers", "Government sponsorship from a G7 nation"], "correctIndex": 0, "explanation": "DarkSide RaaS ki professional website thi, customer support, even ek 'code of ethics' \u2014 hospitals attack mat karo. Pure criminal SaaS business model."}, {"id": "ch2_q49", "termRef": "raas", "type": "scenario", "difficulty": "hard", "question": "Someone with zero programming skills manages to launch a ransomware attack after paying a monthly subscription on the dark web. What business model made this possible?", "options": ["Social Engineering", "Ransomware as a Service (RaaS)", "Supply Chain Attack", "Credential Stuffing"], "correctIndex": 1, "explanation": "RaaS is barrier ko hata deta hai \u2014 koi bhi coding nahi jaanta hue bhi malware rent karke attack launch kar sakta hai."}, {"id": "ch2_q50", "termRef": "raas", "type": "category", "difficulty": "medium", "question": "What does RaaS provide to its 'customers' beyond just the malware itself, according to the guide?", "options": ["Physical hardware for the attack", "Government-issued cybersecurity certifications", "Support, a control panel, and even ransom negotiation services", "Free legal defense if caught"], "correctIndex": 2, "explanation": "Support bhi milta hai, control panel, ransom negotiation services \u2014 full criminal enterprise jaise organized business model."}]}, {"chapter": 3, "chapterTitle": "Defensive Tools & Technologies", "termCount": 10, "questionCount": 50, "questions": [{"id": "ch3_q01", "termRef": "firewall", "type": "definition", "difficulty": "easy", "question": "What does a firewall do?", "options": ["Removes malware that has already infected a system", "Records every keystroke a user types", "Encrypts sensitive data before it is transmitted", "Monitors network traffic and allows or blocks it based on predefined rules"], "correctIndex": 3, "explanation": "Firewall network traffic monitor karta hai aur predefined rules ke basis pe allow ya block karta hai \u2014 border guard ki tarah, passport check karke andar jaane deta hai."}, {"id": "ch3_q02", "termRef": "firewall", "type": "category", "difficulty": "medium", "question": "Which type of firewall performs deep packet inspection and is application-aware?", "options": ["WAF", "Packet Filtering firewall", "Stateful firewall", "NGFW (Next-Generation Firewall)"], "correctIndex": 3, "explanation": "Packet Filtering sirf IP/port check karta hai, Stateful connection state track karta hai, NGFW deep packet inspection karta hai aur app-aware hota hai."}, {"id": "ch3_q03", "termRef": "firewall", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use to explain a firewall?", "options": ["A CCTV control room watching thousands of cameras", "A postman opening and reading letters", "A building's security guard who checks IDs before letting people in", "A chemical lab's glove box for safe testing"], "correctIndex": 2, "explanation": "Building ka security guard analogy \u2014 trusted IP allow, unknown ports block. But smart attacker allowed port use karke bypass kar sakta hai."}, {"id": "ch3_q04", "termRef": "firewall", "type": "scenario", "difficulty": "hard", "question": "An attacker manages to bypass a firewall by disguising malicious traffic as normal traffic over an already-allowed port. What does this demonstrate about firewalls?", "options": ["Firewalls can detect and stop any type of attack automatically", "Firewalls enforce rules but a sufficiently disguised attack can still get through allowed ports", "Firewalls physically prevent all network intrusions", "Firewalls only work on wireless networks"], "correctIndex": 1, "explanation": "Guide khud bolti hai \u2014 smart attacker allowed port use karta hai (bypass). Firewall foolproof nahi hai, sirf ek layer of defense hai."}, {"id": "ch3_q05", "termRef": "firewall", "type": "category", "difficulty": "medium", "question": "Which firewall type is designed specifically to protect web applications?", "options": ["Packet Filtering", "WAF", "NGFW", "Stateful"], "correctIndex": 1, "explanation": "WAF (Web Application Firewall) web apps ke liye specifically design ki gayi hai, jabki baaki types general network traffic handle karte hain."}, {"id": "ch3_q06", "termRef": "antivirus", "type": "definition", "difficulty": "easy", "question": "What is one method antivirus software uses to detect malware?", "options": ["Rewriting the operating system's kernel", "Encrypting the entire hard drive automatically", "Physically isolating the hardware from the network", "Signature-based detection \u2014 matching known malware 'fingerprints'"], "correctIndex": 3, "explanation": "Signature-based: known malware ke 'fingerprints' se match karta hai. Heuristic: suspicious behavior detect karta hai. Sandboxing: isolated environment mein run karke dekhta hai."}, {"id": "ch3_q07", "termRef": "antivirus", "type": "category", "difficulty": "medium", "question": "What is a key limitation of signature-based antivirus software?", "options": ["It struggles against zero-day and polymorphic malware that changes its own code", "It requires a live internet connection to function at all", "It only works against ransomware, not other malware types", "It cannot run on Windows operating systems"], "correctIndex": 0, "explanation": "Signature-based antivirus sirf known threats detect karta hai \u2014 zero-day, fileless, polymorphic malware (jo apna code change karta hai) se bachna mushkil hai."}, {"id": "ch3_q08", "termRef": "antivirus", "type": "category", "difficulty": "medium", "question": "Which antivirus detection method involves running a suspicious file in an isolated environment to observe its behavior?", "options": ["Rate limiting", "Signature-based detection", "Packet filtering", "Sandboxing"], "correctIndex": 3, "explanation": "Sandboxing: isolated environment mein file run karke uska behavior observe kiya jaata hai \u2014 heuristic detection ka ek advanced form."}, {"id": "ch3_q09", "termRef": "antivirus", "type": "scenario", "difficulty": "hard", "question": "A brand-new piece of malware infects several systems before any antivirus vendor has released a signature for it. What does this illustrate?", "options": ["Antivirus software is completely useless in all situations", "The core limitation of purely signature-based antivirus against unknown threats", "The malware must be a rootkit specifically", "Firewalls are more important than antivirus in every case"], "correctIndex": 1, "explanation": "Naya malware jiska signature abhi exist hi nahi karta \u2014 signature-based antivirus use miss kar sakta hai, isliye behavior analysis zaroori hai."}, {"id": "ch3_q10", "termRef": "antivirus", "type": "category", "difficulty": "medium", "question": "What does the guide say is necessary alongside signature-based detection for modern protection?", "options": ["Disabling all software updates", "Using only hardware-based firewalls", "Behavior analysis combined with signature-based detection", "Relying purely on user common sense"], "correctIndex": 2, "explanation": "Guide ke mutabik modern AV + behavior analysis zaroori hai, sirf signature-based detection kaafi nahi hai naye threats ke against."}, {"id": "ch3_q11", "termRef": "ids", "type": "definition", "difficulty": "easy", "question": "What does an IDS (Intrusion Detection System) do when it spots suspicious activity?", "options": ["It automatically shuts down the entire network", "It automatically deletes the malicious files", "It sends an alert to the security team but does not block the traffic itself", "It automatically blocks the traffic in real time"], "correctIndex": 2, "explanation": "IDS network/system traffic monitor karta hai, kuch galat dikhta hai to alert bhejta hai \u2014 but khud kuch nahi karta, sirf bolta hai 'kuch ho raha hai!'"}, {"id": "ch3_q12", "termRef": "ids", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use for an IDS?", "options": ["A security guard who physically stops intruders", "A postman delivering mail", "A smoke detector \u2014 it alerts you to fire but doesn't put it out itself", "A vault door that locks automatically"], "correctIndex": 2, "explanation": "Smoke detector analogy \u2014 aag lagti hai, alarm bajta hai, but khud aag nahi bujhaata. IDS detect karta hai, response human/IPS ka kaam hai."}, {"id": "ch3_q13", "termRef": "ids", "type": "category", "difficulty": "medium", "question": "Which type of IDS monitors an entire network's traffic rather than a single machine?", "options": ["HIDS (Host-based IDS)", "NIDS (Network-based IDS)", "Anomaly-based IDS only", "Signature-based IDS only"], "correctIndex": 1, "explanation": "NIDS: network-based, poora network traffic dekhta hai. HIDS: host-based, ek specific machine dekhta hai \u2014 dono complementary hain."}, {"id": "ch3_q14", "termRef": "ids", "type": "category", "difficulty": "medium", "question": "What is the fundamental difference between an IDS and an IPS?", "options": ["IDS and IPS are exactly the same technology", "IDS only works on wireless networks", "IDS is more expensive than IPS", "IDS only alerts (passive); IPS alerts and automatically blocks (active)"], "correctIndex": 3, "explanation": "IDS = passive (sirf alert), IPS = active (alert + automatically block karta hai) \u2014 yehi fundamental difference hai."}, {"id": "ch3_q15", "termRef": "ids", "type": "scenario", "difficulty": "hard", "question": "A security team receives an alert about suspicious traffic, but the traffic itself was never blocked and continued flowing during the investigation. What kind of system generated this alert?", "options": ["An IDS (Intrusion Detection System)", "A firewall in blocking mode", "A WAF", "An IPS (Intrusion Prevention System)"], "correctIndex": 0, "explanation": "IDS sirf alert deta hai, traffic block nahi karta \u2014 isliye traffic continue flow hoti rehti hai jab tak koi human/IPS action na le."}, {"id": "ch3_q16", "termRef": "ips", "type": "definition", "difficulty": "easy", "question": "How does an IPS (Intrusion Prevention System) respond to a detected threat?", "options": ["It shuts down the entire company network", "It only logs the event for later manual review", "It sends an email to the CEO", "It automatically blocks the traffic in real time as it sits inline in the network path"], "correctIndex": 3, "explanation": "IPS network path mein inline hota hai \u2014 traffic isse hoke jaata hai, woh inspect karta hai, aur block kar sakta hai real-time mein."}, {"id": "ch3_q17", "termRef": "ips", "type": "category", "difficulty": "medium", "question": "What is a notable risk of deploying an IPS in a production environment?", "options": ["It only works on encrypted traffic", "False positives can block legitimate traffic and impact the business", "It requires physical access to every device", "It cannot be configured at all"], "correctIndex": 1, "explanation": "False positives ka risk \u2014 legitimate traffic bhi block ho sakta hai. Production systems mein carefully configure karna padta hai nahi to business impact hota hai."}, {"id": "ch3_q18", "termRef": "ips", "type": "scenario", "difficulty": "hard", "question": "After deploying a new security tool, some legitimate customer traffic starts getting blocked unexpectedly. What is the most likely cause?", "options": ["A DDoS attack against the customers", "A supply chain compromise", "A DNS poisoning attack", "An overly aggressive IPS configuration causing false positives"], "correctIndex": 3, "explanation": "IPS ka known risk hai false positives \u2014 sahi traffic ko bhi galat pattern match karke block kar sakta hai agar carefully configure na ho."}, {"id": "ch3_q19", "termRef": "ips", "type": "category", "difficulty": "medium", "question": "Where does an IPS typically sit within the network architecture?", "options": ["Completely outside the network, offline", "Only on the end-user's personal device", "Inline, directly in the path of network traffic", "Only inside the company's physical server room"], "correctIndex": 2, "explanation": "IPS inline hota hai \u2014 traffic isi se hoke guzarta hai, jisse woh real-time mein inspect aur block kar sakta hai."}, {"id": "ch3_q20", "termRef": "ips", "type": "category", "difficulty": "medium", "question": "Compared to an IDS, what additional capability does an IPS provide?", "options": ["Lower cost only", "Better logging format only", "Active, automatic blocking, not just passive alerting", "Support for more operating systems only"], "correctIndex": 2, "explanation": "IPS ka core value-add hai active response \u2014 sirf alert nahi, automatically block bhi karta hai real-time mein."}, {"id": "ch3_q21", "termRef": "siem", "type": "definition", "difficulty": "easy", "question": "What is the core function of a SIEM (Security Information & Event Management) system?", "options": ["Running penetration tests against the company's own systems", "Encrypting all company emails automatically", "Collecting and correlating logs from across an organization's security tools to identify threats", "Physically blocking network intrusions in real time"], "correctIndex": 2, "explanation": "SIEM poore organization ke saare security tools se logs collect karta hai ek jagah, correlate karta hai, patterns dhundta hai, aur threats identify karta hai."}, {"id": "ch3_q22", "termRef": "siem", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use to describe a SIEM?", "options": ["A postman delivering sealed letters", "A locked vault protecting valuables", "A mall's CCTV control room where a guard watches all cameras on one screen", "A firewall blocking unauthorized visitors"], "correctIndex": 2, "explanation": "CCTV control room analogy \u2014 hazaron cameras ek jagah, guard sab dekh sakta hai ek monitor pe. Alag-alag cameras dekhen to pattern miss ho jaaye, SIEM central view deta hai."}, {"id": "ch3_q23", "termRef": "siem", "type": "category", "difficulty": "medium", "question": "Which of these is listed as a real-world SIEM tool in the guide?", "options": ["Wireshark", "Nmap", "Splunk", "Metasploit"], "correctIndex": 2, "explanation": "Guide mein examples diye hain: Splunk, IBM QRadar, Microsoft Sentinel, LogRhythm \u2014 large enterprises mein terabytes of daily logs ek dashboard pe analyze hote hain."}, {"id": "ch3_q24", "termRef": "siem", "type": "category", "difficulty": "medium", "question": "Which team primarily relies on a SIEM as its main working tool?", "options": ["The HR department", "External auditors only", "The SOC (Security Operations Center) team", "The sales team"], "correctIndex": 2, "explanation": "SIEM SOC team ka main tool hai \u2014 poore organization ke logs ek jagah aa jaate hain jisse analysts patterns dhund sakte hain."}, {"id": "ch3_q25", "termRef": "siem", "type": "scenario", "difficulty": "hard", "question": "A security team notices a subtle attack pattern only after correlating logs from the firewall, the antivirus, and the VPN together \u2014 no single log source showed it clearly alone. What tool made this correlation possible?", "options": ["A single firewall log", "A single IDS alert", "A single antivirus console", "A SIEM"], "correctIndex": 3, "explanation": "SIEM ka poora purpose hi yeh hai \u2014 alag-alag sources ke logs ko correlate karna taaki pattern dikhe jo individually visible nahi hota."}, {"id": "ch3_q26", "termRef": "waf", "type": "definition", "difficulty": "easy", "question": "How does a WAF (Web Application Firewall) differ from a normal firewall?", "options": ["A WAF only works on internal company networks", "A WAF replaces the need for antivirus software entirely", "A WAF blocks all traffic from all sources equally", "A WAF analyzes HTTP traffic specifically, detecting things like SQL injection and XSS"], "correctIndex": 3, "explanation": "Normal firewall packets block karta hai, WAF HTTP traffic ko analyze karta hai specifically \u2014 SQL injection, XSS, CSRF detect aur block karta hai web layer pe."}, {"id": "ch3_q27", "termRef": "waf", "type": "category", "difficulty": "medium", "question": "Where does a WAF typically sit in relation to a web server?", "options": ["Between the web server and the internet", "Only inside a physical server room", "On the end-user's personal device", "Inside the database only"], "correctIndex": 0, "explanation": "Web server aur internet ke beech mein sits \u2014 Cloudflare, AWS WAF, Imperva popular solutions hain, har incoming web request scan karta hai."}, {"id": "ch3_q28", "termRef": "waf", "type": "category", "difficulty": "medium", "question": "Which of the following attack types is a WAF specifically designed to detect and block?", "options": ["Hardware keyloggers", "Lost or stolen laptops", "Physical server room break-ins", "SQL Injection and Cross-Site Scripting (XSS)"], "correctIndex": 3, "explanation": "WAF SQL injection, XSS, CSRF detect aur block karta hai web layer pe \u2014 web-application-specific attacks ke against protection deta hai."}, {"id": "ch3_q29", "termRef": "waf", "type": "scenario", "difficulty": "hard", "question": "An e-commerce website starts blocking malicious input attempts that try to manipulate its database queries through the login form, before they ever reach the application code. Which defensive tool is most likely responsible?", "options": ["An email security gateway", "A WAF", "A honeypot", "A hardware keylogger detector"], "correctIndex": 1, "explanation": "WAF specifically web-layer attacks jaise SQL injection ko web server tak pahunchne se pehle hi block kar deta hai."}, {"id": "ch3_q30", "termRef": "waf", "type": "category", "difficulty": "medium", "question": "Which of these companies offers a well-known WAF solution, according to the guide?", "options": ["Spotify", "Zoom", "Adobe", "Cloudflare"], "correctIndex": 3, "explanation": "Cloudflare, AWS WAF, Imperva \u2014 guide mein listed popular WAF solutions hain."}, {"id": "ch3_q31", "termRef": "endpoint", "type": "definition", "difficulty": "easy", "question": "What does Endpoint Security protect?", "options": ["Only the physical server room", "Only email communication", "Individual devices such as laptops, phones, and tablets", "Only the company's central database server"], "correctIndex": 2, "explanation": "Har individual device (endpoint) ko secure karna \u2014 laptops, phones, tablets, servers \u2014 sirf antivirus nahi, EDR tools real-time behavior monitor karte hain."}, {"id": "ch3_q32", "termRef": "endpoint", "type": "category", "difficulty": "medium", "question": "What does EDR (Endpoint Detection & Response) add beyond traditional antivirus?", "options": ["Real-time behavior analytics, threat hunting, and automated response", "Only faster virus scanning speed", "Only encrypted file storage", "Only better ad-blocking"], "correctIndex": 0, "explanation": "EDR tools (CrowdStrike, SentinelOne) behavior analytics, threat hunting, automated response sab karte hain \u2014 zero-day bhi detect ho sakta hai anomalous behavior se."}, {"id": "ch3_q33", "termRef": "endpoint", "type": "category", "difficulty": "medium", "question": "Which of these tools is mentioned in the guide as a modern EDR solution?", "options": ["Zoom", "Photoshop", "CrowdStrike", "Slack"], "correctIndex": 2, "explanation": "Guide mein CrowdStrike aur SentinelOne examples diye gaye hain \u2014 modern EDR tools jo behavior analytics use karte hain."}, {"id": "ch3_q34", "termRef": "endpoint", "type": "scenario", "difficulty": "hard", "question": "A zero-day threat with no known signature is caught because a security tool noticed unusual behavior on an employee's laptop, not because it matched a known malware pattern. Which category of tool did this?", "options": ["A basic packet-filtering firewall", "An EDR (Endpoint Detection & Response) tool", "A traditional signature-only antivirus", "A simple email spam filter"], "correctIndex": 1, "explanation": "EDR behavior-based detection use karta hai, isliye zero-day bhi anomalous behavior se pakda ja sakta hai \u2014 traditional signature-based antivirus yeh nahi kar paata."}, {"id": "ch3_q35", "termRef": "endpoint", "type": "category", "difficulty": "medium", "question": "Endpoint security has expanded beyond which single tool to become a broader strategy?", "options": ["Antivirus alone", "SIEM alone", "Firewalls alone", "VPNs alone"], "correctIndex": 0, "explanation": "Sirf antivirus nahi \u2014 EDR tools real-time behavior monitor karte hain, endpoint security ab ek broader strategy hai."}, {"id": "ch3_q36", "termRef": "dlp", "type": "definition", "difficulty": "easy", "question": "What is the main purpose of a DLP (Data Loss Prevention) system?", "options": ["Encrypting a company's entire hard drive", "Detecting and blocking network intrusions in real time", "Running penetration tests on company servers", "Preventing sensitive data from leaving the organization through email, USB, or cloud uploads"], "correctIndex": 3, "explanation": "Monitor aur control karta hai ki sensitive data (credit cards, SSN, confidential docs) organization se bahar na jaaye \u2014 email, USB, cloud uploads ke through."}, {"id": "ch3_q37", "termRef": "dlp", "type": "category", "difficulty": "medium", "question": "How does a DLP system typically identify sensitive data being sent out?", "options": ["Content inspection, scanning for patterns like 'confidential' markers", "Randomly blocking all outgoing emails", "Disabling internet access company-wide", "Physically inspecting employee bags at the door"], "correctIndex": 0, "explanation": "Content inspection \u2014 emails scan karta hai 'confidential' patterns ke liye, block kar deta hai ya alert deta hai."}, {"id": "ch3_q38", "termRef": "dlp", "type": "category", "difficulty": "medium", "question": "Against which specific type of risk is DLP described as especially useful?", "options": ["Zero-day exploits against the OS", "Physical building break-ins", "Distributed Denial of Service attacks", "Insider threats"], "correctIndex": 3, "explanation": "Insider threats ke against especially useful hai \u2014 jab koi andar ka hi banda sensitive data bahar bhejne ki koshish kare, DLP catch kar leta hai."}, {"id": "ch3_q39", "termRef": "dlp", "type": "scenario", "difficulty": "hard", "question": "An employee tries to email a spreadsheet containing customer credit card numbers to their personal Gmail account, and the email gets automatically blocked with an alert to security. Which tool caused this?", "options": ["DLP (Data Loss Prevention)", "A sandbox", "An IDS", "A honeypot"], "correctIndex": 0, "explanation": "DLP exactly is scenario ke liye design hui hai \u2014 sensitive data ko organization se bahar jaane se rokna, chahe woh insider ho ya accidental."}, {"id": "ch3_q40", "termRef": "dlp", "type": "category", "difficulty": "medium", "question": "Which of these would a DLP system most likely monitor and control?", "options": ["Incoming network ping requests", "Outgoing emails, USB transfers, and cloud uploads of sensitive data", "The company's public website design", "CPU temperature of servers"], "correctIndex": 1, "explanation": "DLP outgoing channels monitor karta hai jahan se sensitive data organization se bahar ja sakta hai \u2014 email, USB, cloud."}, {"id": "ch3_q41", "termRef": "sandbox", "type": "definition", "difficulty": "easy", "question": "What is a sandbox in cybersecurity?", "options": ["An isolated virtual environment where suspicious files can be run safely without affecting the real system", "A tool for cracking passwords", "A physical safe used to store backup drives", "A type of firewall rule for blocking IPs"], "correctIndex": 0, "explanation": "Isolated virtual environment jahan suspicious files ya programs run kiye jaate hain safely \u2014 agar malware hai to real system affect nahi hoga."}, {"id": "ch3_q42", "termRef": "sandbox", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use for a sandbox?", "options": ["A security guard checking IDs", "A postman delivering sealed letters", "A CCTV control room monitoring cameras", "A chemical lab's glove box for handling hazardous material safely"], "correctIndex": 3, "explanation": "Chemical lab mein hazardous material ke liye glove box jaisa \u2014 bahar effects nahi pahunch sakte, andar jaake experiment kar sakte ho safely."}, {"id": "ch3_q43", "termRef": "sandbox", "type": "category", "difficulty": "medium", "question": "What kinds of items are typically tested in a sandbox before being trusted, according to the guide?", "options": ["Email attachments, unknown executables, and browser extensions", "Only network cables", "Only employee ID badges", "Only physical hardware devices"], "correctIndex": 0, "explanation": "Email attachments, unknown executables, browser extensions \u2014 pehle sandbox mein run karo, behavior dekho, phir decide karo."}, {"id": "ch3_q44", "termRef": "sandbox", "type": "scenario", "difficulty": "hard", "question": "A security team runs a suspicious email attachment in an isolated virtual machine first to observe what it does, before allowing it anywhere near the real company network. What technique is this?", "options": ["Sandboxing", "Digital forensics", "Penetration testing", "Network segmentation"], "correctIndex": 0, "explanation": "Suspicious file ko isolated environment mein run karke behavior dekhna aur real system ko safe rakhna \u2014 yehi sandboxing hai."}, {"id": "ch3_q45", "termRef": "sandbox", "type": "category", "difficulty": "medium", "question": "What is the main benefit of automated malware analysis using a sandbox?", "options": ["It blocks all incoming network traffic", "It reveals a file's real behavior safely, without risking the actual system", "It permanently deletes all malware from the internet", "It automatically patches all known vulnerabilities"], "correctIndex": 1, "explanation": "Automated malware analysis ke liye use hota hai \u2014 file ka actual behavior dekha jaata hai bina real system ko risk mein daale."}, {"id": "ch3_q46", "termRef": "honeypot", "type": "definition", "difficulty": "easy", "question": "What is a honeypot?", "options": ["A password manager for employees", "A device that physically blocks USB ports", "A deliberately vulnerable fake system designed to lure and study attackers", "A tool for encrypting sensitive files"], "correctIndex": 2, "explanation": "Deliberately vulnerable fake system jo attackers ko lure karta hai \u2014 jab attacker ise target karta hai, security team unke tactics study kar sakti hai real-time mein."}, {"id": "ch3_q47", "termRef": "honeypot", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use to describe a honeypot?", "options": ["A police undercover operation or bait car used to lure and catch criminals", "A smoke detector alerting to danger", "A firewall blocking traffic", "A locked vault protecting valuables"], "correctIndex": 0, "explanation": "Police ka undercover operation ya bait car jaisa \u2014 deliberately exposed car chodh ke thieves attract karte hain, phir catch ya study karte hain."}, {"id": "ch3_q48", "termRef": "honeypot", "type": "category", "difficulty": "medium", "question": "What is the main benefit a security team gains from deploying a honeypot?", "options": ["Free legal protection against cybercrime", "Automatic patching of all software vulnerabilities", "Guaranteed elimination of all malware on the network", "Early warning and insight into attacker tactics, techniques, and tools"], "correctIndex": 3, "explanation": "Early warning system hai \u2014 attacker iska real system samajh ke attack karta hai, par actually decoy hai, unke methods log hote hain."}, {"id": "ch3_q49", "termRef": "honeypot", "type": "scenario", "difficulty": "hard", "question": "A company deliberately sets up a fake, poorly-secured server to attract attackers so its security team can study their techniques in real time. What is this technique called?", "options": ["A sandbox", "Network segmentation", "A honeypot", "A firewall"], "correctIndex": 2, "explanation": "Deliberately vulnerable decoy system attackers ko attract karta hai taaki unke tactics study kiye ja sakein \u2014 yehi honeypot ka core concept hai."}, {"id": "ch3_q50", "termRef": "honeypot", "type": "category", "difficulty": "medium", "question": "Why does an attacker fail to realize they are inside a honeypot?", "options": ["Because honeypots automatically disguise the attacker's own IP", "Because it is designed to convincingly look like a real, exploitable system", "Because honeypots require the attacker's login credentials first", "Because honeypots are always physically inaccessible"], "correctIndex": 1, "explanation": "Attacker iska real system samajh ke attack karta hai, par actually decoy hai \u2014 is illusion ki wajah se attacker apne methods reveal kar deta hai."}]}, {"chapter": 4, "chapterTitle": "Encryption & Protocols", "termCount": 10, "questionCount": 50, "questions": [{"id": "ch4_q01", "termRef": "encryption", "type": "definition", "difficulty": "easy", "question": "What does encryption fundamentally do to data?", "options": ["Compresses data to save storage space", "Automatically detects malware inside a file", "Permanently deletes the original data after backup", "Converts plaintext into unreadable ciphertext using an algorithm and a key"], "correctIndex": 3, "explanation": "Plaintext ko ciphertext mein convert karna using an algorithm aur key \u2014 bina key ke garbage, key ke saath original data."}, {"id": "ch4_q02", "termRef": "encryption", "type": "category", "difficulty": "medium", "question": "What is the main difference between symmetric and asymmetric encryption?", "options": ["Symmetric is always slower than asymmetric", "Symmetric encryption can only be used for video files", "Asymmetric encryption doesn't require any key at all", "Symmetric uses the same key for encryption and decryption; asymmetric uses a public/private key pair"], "correctIndex": 3, "explanation": "Symmetric: AES \u2014 same key encrypt aur decrypt karne ke liye, fast. Asymmetric: RSA \u2014 public key se encrypt, private key se decrypt, slower but more secure."}, {"id": "ch4_q03", "termRef": "encryption", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use to describe encryption?", "options": ["A smoke detector sounding an alarm", "A postman delivering sealed letters", "Writing a diary in a secret code language only you understand", "A guard checking IDs at a door"], "correctIndex": 2, "explanation": "Tumhara diary mein secret language likhna jaisa \u2014 sirf tumhe pata hai key kya hai, key ke saath padho, nahi to gibberish."}, {"id": "ch4_q04", "termRef": "encryption", "type": "category", "difficulty": "medium", "question": "Which encryption type is generally faster to perform?", "options": ["Both are exactly equal in speed always", "Asymmetric encryption", "Neither type has a speed difference", "Symmetric encryption"], "correctIndex": 3, "explanation": "Symmetric (AES) fast hai kyunki same key use hoti hai; asymmetric (RSA) slower hai but more secure key exchange ke liye."}, {"id": "ch4_q05", "termRef": "encryption", "type": "scenario", "difficulty": "hard", "question": "Two people who have never met before need to securely exchange a secret key over the internet before they can start using fast symmetric encryption. Which type of encryption is typically used to solve this initial exchange problem?", "options": ["Symmetric encryption alone", "A simple password only", "No encryption is needed", "Asymmetric encryption"], "correctIndex": 3, "explanation": "Asymmetric encryption (public/private key pair) securely key exchange karne ke liye use hoti hai, jiske baad fast symmetric encryption use ho sakti hai \u2014 yeh TLS handshake ka bhi core idea hai."}, {"id": "ch4_q06", "termRef": "e2ee", "type": "definition", "difficulty": "easy", "question": "What does End-to-End Encryption (E2EE) guarantee?", "options": ["The message is automatically translated to any language", "Only the sender and receiver can read the message \u2014 not even the service provider", "The message is stored permanently on the provider's server", "The message is visible to the service provider but not to third parties"], "correctIndex": 1, "explanation": "Message sirf sender ke device pe encrypt hota hai aur sirf receiver ke device pe decrypt hota hai \u2014 server bhi nahi padh sakta, even WhatsApp apne messages nahi padh sakta."}, {"id": "ch4_q07", "termRef": "e2ee", "type": "category", "difficulty": "medium", "question": "According to the guide, which messaging feature is a notable exception where E2EE is NOT applied by default?", "options": ["iMessage between two iPhones", "Signal's regular messages", "Telegram's normal chats (only Secret Chats use E2EE)", "WhatsApp's regular messages"], "correctIndex": 2, "explanation": "Telegram ke Secret Chats hi E2EE use karte hain \u2014 normal chats E2EE nahi hain! Yeh ek common misconception hai."}, {"id": "ch4_q08", "termRef": "e2ee", "type": "scenario", "difficulty": "hard", "question": "A government requests a messaging company hand over the plaintext content of a user's messages, but the company says it technically cannot comply because it never had access to the decrypted content. What technology explains this?", "options": ["End-to-End Encryption (E2EE)", "Network segmentation", "A simple firewall", "A WAF"], "correctIndex": 0, "explanation": "E2EE ki wajah se company khud bhi messages padh nahi sakti \u2014 decryption sirf receiver ke device pe hota hai."}, {"id": "ch4_q09", "termRef": "e2ee", "type": "category", "difficulty": "medium", "question": "Which protocol does WhatsApp use to implement its End-to-End Encryption?", "options": ["SFTP", "SSH", "TLS 1.3 only", "The Signal Protocol"], "correctIndex": 3, "explanation": "WhatsApp Signal Protocol use karta hai E2EE implement karne ke liye \u2014 Signal app khud bhi isi protocol pe based hai."}, {"id": "ch4_q10", "termRef": "e2ee", "type": "category", "difficulty": "medium", "question": "Is regular email typically protected by End-to-End Encryption?", "options": ["Only corporate email is E2EE", "Only Gmail is E2EE, all others are not", "No, regular email is not E2EE by default", "Yes, all email is always E2EE"], "correctIndex": 2, "explanation": "Regular email E2EE nahi hai by default \u2014 isliye email provider technically content padh sakta hai (jab tak koi extra tool use na ho)."}, {"id": "ch4_q11", "termRef": "aes", "type": "definition", "difficulty": "easy", "question": "What is AES?", "options": ["A network monitoring tool", "A type of firewall used to filter web traffic", "A government-approved symmetric encryption algorithm used as an industry standard", "An authentication protocol for logging into websites"], "correctIndex": 2, "explanation": "US government approved symmetric encryption algorithm. AES-128, AES-192, AES-256 (key size) \u2014 industry gold standard."}, {"id": "ch4_q12", "termRef": "aes", "type": "category", "difficulty": "medium", "question": "How practically breakable is AES-256 with today's computing power, according to the guide?", "options": ["Crackable within a day using a normal laptop", "Unbreakable \u2014 even a supercomputer would need billions of years", "Easily crackable within a few hours", "Already broken by known attacks"], "correctIndex": 1, "explanation": "AES-256 is unbreakable with today's computers \u2014 even supercomputer billions of years lagenge is se crack karne mein."}, {"id": "ch4_q13", "termRef": "aes", "type": "category", "difficulty": "medium", "question": "Which of these commonly uses AES encryption, according to the guide?", "options": ["Only old dial-up modems", "Only physical door locks", "Wi-Fi (WPA2), HTTPS, and disk encryption like BitLocker", "Only paper-based filing systems"], "correctIndex": 2, "explanation": "Wi-Fi (WPA2), HTTPS, file encryption, banking, WhatsApp messages, disk encryption (BitLocker, FileVault) \u2014 tum daily AES use karte ho without knowing."}, {"id": "ch4_q14", "termRef": "aes", "type": "scenario", "difficulty": "hard", "question": "Your laptop's disk encryption tool (BitLocker/FileVault) is protecting your files at rest. What underlying encryption algorithm is most likely doing the actual work?", "options": ["MD5", "SHA-256 hashing alone", "AES", "RSA only"], "correctIndex": 2, "explanation": "Disk encryption tools (BitLocker, FileVault) internally AES use karte hain \u2014 yeh symmetric encryption ka industry standard hai."}, {"id": "ch4_q15", "termRef": "aes", "type": "category", "difficulty": "easy", "question": "AES stands for what?", "options": ["Advanced Encryption Standard", "Automated Encryption System", "Authenticated Encryption Service", "Asymmetric Encryption Suite"], "correctIndex": 0, "explanation": "AES = Advanced Encryption Standard \u2014 industry gold standard symmetric encryption algorithm."}, {"id": "ch4_q16", "termRef": "pki", "type": "definition", "difficulty": "easy", "question": "What problem does PKI (Public Key Infrastructure) solve?", "options": ["It blocks malware from running on a device", "It verifies online identity, e.g., confirming that a website is genuinely who it claims to be", "It manages employee login passwords", "It compresses large files for faster transfer"], "correctIndex": 1, "explanation": "PKI public key pairs, digital certificates, Certificate Authorities (CA) ka poora framework hai \u2014 identity verify karta hai online."}, {"id": "ch4_q17", "termRef": "pki", "type": "category", "difficulty": "medium", "question": "What role does a Certificate Authority (CA) play in PKI?", "options": ["It physically manufactures network hardware", "It stores all users' passwords in plaintext", "It is a trusted issuer of digital certificates, like DigiCert or Let's Encrypt", "It blocks DDoS attacks directly"], "correctIndex": 2, "explanation": "CA (Certificate Authority): trusted issuer (DigiCert, Let's Encrypt), Digital Certificate: identity proof, CRL: revoked certificates ki list."}, {"id": "ch4_q18", "termRef": "pki", "type": "category", "difficulty": "medium", "question": "What does a CRL (Certificate Revocation List) contain?", "options": ["A list of certificates that have been revoked and should no longer be trusted", "A list of authorized VPN users", "A list of all encrypted files on a server", "A list of blocked IP addresses"], "correctIndex": 0, "explanation": "CRL: revoked certificates ki list \u2014 jo certificates ab valid nahi hain, unko track karne ke liye."}, {"id": "ch4_q19", "termRef": "pki", "type": "scenario", "difficulty": "hard", "question": "Your browser shows a padlock and confirms a site is genuinely 'google.com' rather than a fake lookalike site. Which underlying framework makes this identity verification possible?", "options": ["A firewall alone", "PKI (Public Key Infrastructure)", "DNS Poisoning defenses alone", "NAT"], "correctIndex": 1, "explanation": "PKI ka poora purpose hi identity verify karna hai online \u2014 CA-issued digital certificates ke through browser confirm karta hai ki site genuine hai."}, {"id": "ch4_q20", "termRef": "pki", "type": "category", "difficulty": "medium", "question": "Which of these is a component of PKI, according to the guide?", "options": ["Sandboxing environments", "Digital Certificate", "Honeypots", "Rate limiting rules"], "correctIndex": 1, "explanation": "PKI ke components: CA, Digital Certificate, aur CRL \u2014 yeh sab milke online trust management system banate hain."}, {"id": "ch4_q21", "termRef": "digicert", "type": "definition", "difficulty": "easy", "question": "What is a digital certificate?", "options": ["A type of malware detection signature", "A physical ID card issued by the government", "An electronic document that proves an entity's identity and contains its public key", "A backup copy of encrypted files"], "correctIndex": 2, "explanation": "Electronic document jo ek entity ki identity prove karta hai aur unki public key contain karta hai \u2014 CA issue karta hai."}, {"id": "ch4_q22", "termRef": "digicert", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use for a digital certificate?", "options": ["A postman delivering sealed letters", "A guard checking IDs at a building", "A passport \u2014 issued by a trusted authority, with your details and an expiry date", "A movie ticket used once"], "correctIndex": 2, "explanation": "Passport jaisa \u2014 government (CA) ne issue kiya, tumhara photo aur details hain (public key), expiry date hai, tamper-proof features hain."}, {"id": "ch4_q23", "termRef": "digicert", "type": "category", "difficulty": "medium", "question": "What does the browser's padlock icon in the address bar represent?", "options": ["That the website has no malware whatsoever", "A valid digital certificate being presented by the website", "That the website loads faster than others", "That the website is government-approved"], "correctIndex": 1, "explanation": "Browser ka padlock icon yahi hai \u2014 digital certificate present ho raha hai, matlab site apni identity prove kar rahi hai."}, {"id": "ch4_q24", "termRef": "digicert", "type": "category", "difficulty": "medium", "question": "Which of these is contained within a digital certificate, according to the guide?", "options": ["The owner's public key and the issuing CA's digital signature", "The user's plaintext password", "The user's home address", "The user's credit card number"], "correctIndex": 0, "explanation": "Contains: owner name, public key, issuing CA, validity dates, domain name, CA's digital signature (tamper proof)."}, {"id": "ch4_q25", "termRef": "digicert", "type": "scenario", "difficulty": "hard", "question": "A bank trusts a customer's document because it carries an official passport-like proof of identity issued by a recognized authority. What is the digital equivalent of this trust mechanism online?", "options": ["A firewall rule", "A digital certificate issued by a Certificate Authority", "A simple username and password", "An IDS alert"], "correctIndex": 1, "explanation": "Bank ne passport dekha \u2192 trust kiya \u2014 online iska equivalent digital certificate hai jo CA ne issue kiya."}, {"id": "ch4_q26", "termRef": "digisig", "type": "definition", "difficulty": "easy", "question": "What does a digital signature provide?", "options": ["Automatic encryption of the entire hard drive", "Protection against network flooding attacks", "Proof that a document was signed by a specific person and hasn't been tampered with (non-repudiation)", "A backup copy of the signed document"], "correctIndex": 2, "explanation": "Apni private key se document ko 'sign' karna \u2014 koi bhi tumhari public key se verify kar sakta hai ki document tumne hi sign kiya aur modify nahi hua. Non-repudiation provide karta hai."}, {"id": "ch4_q27", "termRef": "digisig", "type": "category", "difficulty": "medium", "question": "What is the first step in the digital signature process, according to the guide?", "options": ["Send the document over an unencrypted channel", "Compress the document into a zip file", "Delete the original document", "Generate a hash of the document"], "correctIndex": 3, "explanation": "Process: 1. Document ka hash generate karo, 2. private key se hash encrypt karo (= signature), 3. Receiver same hash generate kar verify karta hai."}, {"id": "ch4_q28", "termRef": "digisig", "type": "category", "difficulty": "medium", "question": "Which key is used to create a digital signature, and which key is used to verify it?", "options": ["No key is needed for either step", "The signer's private key creates it; the signer's public key verifies it", "The signer's public key creates it; the signer's private key verifies it", "Both creation and verification use the same shared secret password"], "correctIndex": 1, "explanation": "Private key se hash encrypt karke signature banta hai; receiver public key se signature decrypt karke verify karta hai."}, {"id": "ch4_q29", "termRef": "digisig", "type": "scenario", "difficulty": "hard", "question": "A contract's recipient can mathematically prove the sender actually signed it and that no one altered even a single word afterward. Which security concept guarantees this?", "options": ["Network segmentation", "NAT", "Digital Signature", "A firewall rule"], "correctIndex": 2, "explanation": "Digital signature non-repudiation provide karta hai \u2014 sender deny nahi kar sakta ki usne sign kiya, aur tampering bhi detect ho jaati hai."}, {"id": "ch4_q30", "termRef": "digisig", "type": "category", "difficulty": "medium", "question": "What security property specifically means 'the signer cannot later deny having signed the document'?", "options": ["Anonymity", "Availability", "Non-repudiation", "Confidentiality"], "correctIndex": 2, "explanation": "Non-repudiation exactly yehi property hai \u2014 digital signature ka primary benefit."}, {"id": "ch4_q31", "termRef": "ssl", "type": "definition", "difficulty": "easy", "question": "What is the current status of SSL, according to the guide?", "options": ["Still the most current and secure protocol in use", "Technically deprecated and replaced by TLS, though the term 'SSL' is still commonly used", "Never existed \u2014 it was always called TLS", "A hardware device used to encrypt disks"], "correctIndex": 1, "explanation": "Ab technically deprecated hai \u2014 TLS use hota hai, par 'SSL' term abhi bhi common usage mein hai."}, {"id": "ch4_q32", "termRef": "ssl", "type": "category", "difficulty": "medium", "question": "Why was SSL 3.0 specifically abandoned, according to the guide?", "options": ["It required a paid license to use", "It had the POODLE vulnerability", "It was too slow for modern internet speeds", "It was never adopted by any browser"], "correctIndex": 1, "explanation": "SSL 3.0 mein POODLE vulnerability thi isliye abandon kiya gaya \u2014 TLS 1.0 se aage evolution hua."}, {"id": "ch4_q33", "termRef": "ssl", "type": "category", "difficulty": "medium", "question": "What is the correct chronological evolution from SSL to the current standard, according to the guide?", "options": ["TLS 1.3 \u2192 SSL 3.0 \u2192 SSL 2.0 \u2192 TLS 1.0", "SSL 3.0 \u2192 TLS 1.3 \u2192 SSL 2.0 \u2192 TLS 1.0", "SSL 2.0 \u2192 SSL 3.0 \u2192 TLS 1.0 \u2192 TLS 1.3", "TLS 1.0 \u2192 SSL 2.0 \u2192 SSL 3.0 \u2192 TLS 1.3"], "correctIndex": 2, "explanation": "SSL 2.0 (1995) \u2192 SSL 3.0 \u2192 TLS 1.0 \u2192 TLS 1.1 \u2192 TLS 1.2 \u2192 TLS 1.3 (current) \u2014 yeh sahi chronological order hai."}, {"id": "ch4_q34", "termRef": "ssl", "type": "scenario", "difficulty": "hard", "question": "A colleague refers to a website's 'SSL certificate,' even though the site is actually using the modern TLS protocol underneath. What does this illustrate?", "options": ["SSL and TLS are entirely unrelated technologies", "The colleague is completely wrong and the site is insecure", "TLS is actually older than SSL", "The term 'SSL' is still used colloquially even though TLS has replaced it technically"], "correctIndex": 3, "explanation": "Guide khud bolti hai 'SSL' term abhi bhi common hai, chahe technically TLS use ho raha ho \u2014 industry jargon mein legacy naming persist karta hai."}, {"id": "ch4_q35", "termRef": "ssl", "type": "category", "difficulty": "easy", "question": "What does SSL stand for?", "options": ["Secure Sockets Layer", "Standard Socket Language", "Secure Server Login", "System Security Layer"], "correctIndex": 0, "explanation": "SSL = Secure Sockets Layer \u2014 secure communication protocol jo ab TLS se replace ho chuka hai."}, {"id": "ch4_q36", "termRef": "tls", "type": "definition", "difficulty": "easy", "question": "What is actually running behind the scenes when you use HTTPS today?", "options": ["Telnet", "FTP", "SSL 2.0", "TLS"], "correctIndex": 3, "explanation": "Jab tum HTTPS use karte ho, actually TLS run ho raha hai \u2014 current secure communication protocol jo encryption, authentication, integrity teeno provide karta hai."}, {"id": "ch4_q37", "termRef": "tls", "type": "category", "difficulty": "medium", "question": "What is the first step of a TLS handshake, according to the guide?", "options": ["The client says 'Hello, I support TLS 1.3'", "The server immediately sends encrypted data", "The client sends its password in plaintext", "The connection is closed automatically"], "correctIndex": 0, "explanation": "1. Client: 'Hello, I support TLS 1.3', 2. Server: 'OK, here's my certificate', 3. Key exchange, 4. Encrypted communication begins."}, {"id": "ch4_q38", "termRef": "tls", "type": "category", "difficulty": "medium", "question": "Which three properties does TLS provide together, according to the guide?", "options": ["Encryption, authentication, and integrity", "Speed, compression, and caching", "Backup, recovery, and archiving", "Firewalling, sandboxing, and logging"], "correctIndex": 0, "explanation": "TLS encryption, authentication, integrity \u2014 teeno provide karta hai simultaneously, sirf data hide karna nahi."}, {"id": "ch4_q39", "termRef": "tls", "type": "scenario", "difficulty": "hard", "question": "During a connection setup, the server sends its certificate to the client, and both sides then exchange keys before any actual data is sent. What process is this describing?", "options": ["A TLS handshake", "A firewall rule update", "A DDoS attack", "A DNS lookup"], "correctIndex": 0, "explanation": "Yeh exactly TLS handshake ka process hai \u2014 hello, certificate exchange, key exchange, phir encrypted communication begins."}, {"id": "ch4_q40", "termRef": "tls", "type": "category", "difficulty": "easy", "question": "What does TLS stand for?", "options": ["Transport Layer Security", "Trusted Local System", "Total Link Security", "Traffic Load Sensor"], "correctIndex": 0, "explanation": "TLS = Transport Layer Security \u2014 SSL ka successor, internet ki backbone security protocol."}, {"id": "ch4_q41", "termRef": "https", "type": "definition", "difficulty": "easy", "question": "What is HTTPS made of, according to the guide?", "options": ["HTTP + a VPN", "HTTP + a firewall", "HTTP + AES only", "HTTP + TLS"], "correctIndex": 3, "explanation": "HTTP (web protocol) + TLS (encryption) = HTTPS. Browser ka padlock icon = HTTPS."}, {"id": "ch4_q42", "termRef": "https", "type": "category", "difficulty": "medium", "question": "What common misconception does the guide correct about HTTPS?", "options": ["HTTPS makes a website completely immune to hacking", "HTTPS does not mean the site itself is trustworthy \u2014 it only means the connection is encrypted", "HTTPS automatically blocks all phishing attempts", "HTTPS is only used by government websites"], "correctIndex": 1, "explanation": "HTTPS = secure site NAHI. Sirf matlab hai connection encrypted hai. Fake phishing sites bhi HTTPS use karti hain. Padlock \u2260 trustworthy website."}, {"id": "ch4_q43", "termRef": "https", "type": "scenario", "difficulty": "hard", "question": "A phishing website has a valid padlock icon and uses HTTPS, yet it is still designed to steal your login credentials. What does this demonstrate?", "options": ["HTTPS automatically verifies a site's honesty", "The browser has a bug if this occurs", "HTTPS certificates are never issued to malicious sites, so this can't happen", "HTTPS only guarantees an encrypted connection, not that the site itself is legitimate"], "correctIndex": 3, "explanation": "Exactly the misconception the guide warns about \u2014 fake phishing sites bhi HTTPS use kar sakti hain, padlock trustworthiness ki guarantee nahi deta."}, {"id": "ch4_q44", "termRef": "https", "type": "category", "difficulty": "medium", "question": "What does the padlock icon in a browser's address bar specifically indicate?", "options": ["That the website has been manually reviewed by the browser vendor", "That the website has no ads", "That the website is hosted in the user's own country", "That HTTPS (encrypted transit) is being used"], "correctIndex": 3, "explanation": "Padlock icon = HTTPS active hai, data encrypted hai transit mein \u2014 MITM attacker garbled text hi dekhega \u2014 but yeh site ki legitimacy guarantee nahi karta."}, {"id": "ch4_q45", "termRef": "https", "type": "category", "difficulty": "medium", "question": "If a MITM attacker intercepts traffic on an HTTPS-protected connection, what will they typically see?", "options": ["The exact plaintext of the conversation", "Only the sender's IP address in plaintext, nothing else", "Garbled, encrypted text they cannot easily read", "A full copy of the user's password in plaintext, always"], "correctIndex": 2, "explanation": "Data encrypted hai transit mein \u2014 MITM attacker garbled text hi dekhega, yehi HTTPS ka core protection hai."}, {"id": "ch4_q46", "termRef": "ssh", "type": "definition", "difficulty": "easy", "question": "What is SSH primarily used for?", "options": ["Encrypting emails end-to-end", "Securely accessing a remote server from the command line", "Scanning files for malware signatures", "Blocking malicious web traffic"], "correctIndex": 1, "explanation": "Remote server ko securely access karna command line se \u2014 web developers, system admins daily use karte hain."}, {"id": "ch4_q47", "termRef": "ssh", "type": "category", "difficulty": "medium", "question": "Which older, unencrypted protocol did SSH replace in 1995?", "options": ["HTTP", "SMTP", "FTP", "Telnet"], "correctIndex": 3, "explanation": "Telnet (unencrypted predecessor) ko replace kiya 1995 mein \u2014 SSH ne encrypted alternative provide kiya."}, {"id": "ch4_q48", "termRef": "ssh", "type": "category", "difficulty": "medium", "question": "What is a more secure alternative to password login when using SSH?", "options": ["Using a 4-digit PIN instead", "Disabling authentication entirely", "SSH keys, where the public key sits on the server and the private key stays with the user", "Sharing the same password across all servers"], "correctIndex": 2, "explanation": "Password ke alawa SSH keys use kar sakte ho \u2014 more secure. Public key server pe, private key tumhare paas \u2014 brute force practically impossible."}, {"id": "ch4_q49", "termRef": "ssh", "type": "scenario", "difficulty": "hard", "question": "A system administrator connects to a remote Linux server to run commands, and the entire session is encrypted so no one on the network can see the commands or their output. Which protocol enables this?", "options": ["Plain Telnet", "Plain HTTP", "Unencrypted FTP", "SSH"], "correctIndex": 3, "explanation": "SSH exactly is use case ke liye design hui hai \u2014 encrypted remote server access via command line."}, {"id": "ch4_q50", "termRef": "ssh", "type": "category", "difficulty": "medium", "question": "Why is brute-forcing an SSH connection secured with SSH keys considered 'practically impossible'?", "options": ["Because SSH blocks all connection attempts automatically", "Because SSH doesn't allow remote connections at all", "Because the private key never leaves the user's device and isn't a guessable password", "Because SSH keys expire every second"], "correctIndex": 2, "explanation": "Private key kabhi network pe transmit nahi hoti aur itni complex hoti hai ki brute force practically impossible ho jaata hai."}]}, {"chapter": 5, "chapterTitle": "Identity & Access Management", "termCount": 10, "questionCount": 50, "questions": [{"id": "ch5_q01", "termRef": "2fa", "type": "definition", "difficulty": "easy", "question": "What does Two-Factor Authentication (2FA) require at login?", "options": ["Something you know (password) plus something you have or are (like an OTP or fingerprint)", "Only your device's IP address", "Only a security question", "Only a strong, complex password"], "correctIndex": 0, "explanation": "Login ke liye 2 cheezein chahiye: kuch tum jaante ho (password) + kuch tumhare paas hai (phone OTP) ya kuch tum ho (fingerprint) \u2014 password chori bhi ho to koi faida nahi attacker ko."}, {"id": "ch5_q02", "termRef": "2fa", "type": "category", "difficulty": "medium", "question": "Which 2FA method is described as the weakest, due to SIM swap risk?", "options": ["SMS OTP", "Biometric", "Hardware Key (YubiKey)", "Authenticator App"], "correctIndex": 0, "explanation": "SMS OTP (weakest \u2014 SIM swap possible), Authenticator App (better), Hardware Key (strongest \u2014 YubiKey), Biometric."}, {"id": "ch5_q03", "termRef": "2fa", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use for 2FA?", "options": ["An ATM \u2014 you need both your PIN and your physical card", "A postman delivering sealed letters", "A chemical lab's glove box", "A CCTV control room"], "correctIndex": 0, "explanation": "ATM analogy \u2014 PIN (kuch tum jaante ho) + ATM card (kuch tumhare paas hai). Sirf PIN nahi, sirf card nahi \u2014 dono chahiye."}, {"id": "ch5_q04", "termRef": "2fa", "type": "real_world", "difficulty": "hard", "question": "In the 2023 MGM Resorts hack, how much loss was directly attributed to missing MFA, according to the guide?", "options": ["$1 million", "$1 billion", "$10 million", "$100 million or more"], "correctIndex": 3, "explanation": "Social engineering se employee credentials mili, agar proper MFA hota to hack fail ho jaata \u2014 $100M+ loss directly 2FA missing ki wajah se."}, {"id": "ch5_q05", "termRef": "2fa", "type": "scenario", "difficulty": "hard", "question": "An attacker steals your password through a phishing email, but fails to log into your account because they don't have the OTP sent to your phone. What protected you?", "options": ["Network segmentation", "A firewall", "A honeypot", "2FA (Two-Factor Authentication)"], "correctIndex": 3, "explanation": "2FA exactly is scenario ke liye design hui hai \u2014 password chori bhi ho jaaye, dusra factor attacker ke paas nahi hota."}, {"id": "ch5_q06", "termRef": "mfa", "type": "definition", "difficulty": "easy", "question": "How does MFA differ from 2FA?", "options": ["MFA and 2FA are completely unrelated concepts", "MFA only applies to banking systems", "MFA can use two or more factors, while 2FA specifically means exactly two", "2FA is stronger than MFA in every case"], "correctIndex": 2, "explanation": "2FA specifically 2 factors. MFA = 2 ya zyada factors \u2014 MFA is 2FA ka superset."}, {"id": "ch5_q07", "termRef": "mfa", "type": "category", "difficulty": "medium", "question": "Which of these is NOT one of the three core MFA factor categories listed in the guide?", "options": ["Inherence (something you are)", "Possession (something you have)", "Knowledge (something you know)", "Location you frequently visit"], "correctIndex": 3, "explanation": "Three core categories: Knowledge (password), Possession (phone/token), Inherence (biometric). Location-based hai ek bonus layer, core category nahi."}, {"id": "ch5_q08", "termRef": "mfa", "type": "category", "difficulty": "medium", "question": "Which factor category does a fingerprint scan belong to?", "options": ["Location (where you are)", "Possession (something you have)", "Inherence (something you are)", "Knowledge (something you know)"], "correctIndex": 2, "explanation": "\ud83d\udc41\ufe0f Are: fingerprint, face, iris, voice \u2014 yeh sab Inherence category mein aate hain."}, {"id": "ch5_q09", "termRef": "mfa", "type": "scenario", "difficulty": "hard", "question": "A company requires employees to enter a password, tap approve on an authenticator app, AND scan their fingerprint to log in. How many distinct factor categories does this use?", "options": ["Three \u2014 knowledge, possession, and inherence", "Only one \u2014 knowledge", "Only two \u2014 possession and inherence", "Zero, since these aren't real factors"], "correctIndex": 0, "explanation": "Password = knowledge, authenticator app = possession, fingerprint = inherence \u2014 teeno categories mix karna MFA ko harder to breach banata hai."}, {"id": "ch5_q10", "termRef": "mfa", "type": "category", "difficulty": "medium", "question": "Why does mixing multiple factor categories make an account harder to breach?", "options": ["Because it disables the password entirely", "Because it changes the account's IP address", "Because it slows down the login page loading time", "Because an attacker would need to compromise multiple, fundamentally different types of proof simultaneously"], "correctIndex": 3, "explanation": "Mix karo \u2014 harder to breach, kyunki attacker ko alag-alag categories (jaante ho, paas hai, tum ho) sabhi compromise karni padengi."}, {"id": "ch5_q11", "termRef": "iam", "type": "definition", "difficulty": "easy", "question": "What does IAM (Identity & Access Management) define?", "options": ["How malware is detected on endpoints", "Which user can access which resource within an organization", "How fast a network connection is", "How data is encrypted during transit"], "correctIndex": 1, "explanation": "Framework aur tools jo define karte hain ki kaun user kaun sa resource access kar sakta hai \u2014 user accounts banao, permissions assign karo, review karo."}, {"id": "ch5_q12", "termRef": "iam", "type": "category", "difficulty": "medium", "question": "What does the 'Principle of Least Privilege' in IAM mean?", "options": ["Every user should have full admin access by default", "Access should never be reviewed once granted", "Each user should only get the minimum access absolutely necessary for their job", "Only the CEO should have any system access"], "correctIndex": 2, "explanation": "Least Privilege: har user sirf woh access mile jo kaam ke liye absolutely zaroori hai \u2014 extra nahi."}, {"id": "ch5_q13", "termRef": "iam", "type": "category", "difficulty": "medium", "question": "Which of these is mentioned in the guide as a popular IAM tool?", "options": ["Okta", "Photoshop", "Slack", "Zoom"], "correctIndex": 0, "explanation": "Okta, Microsoft Azure AD popular IAM tools hain guide ke mutabik."}, {"id": "ch5_q14", "termRef": "iam", "type": "scenario", "difficulty": "hard", "question": "A database administrator requests access to the company's billing system for an unrelated task, but the request is denied because it isn't required for their role. What IAM principle is being enforced?", "options": ["Least Privilege", "Zero Trust exclusively", "Single Sign-On", "Multi-Factor Authentication"], "correctIndex": 0, "explanation": "Agar DB admin ko billing system access nahi chahiye kaam ke liye, nahi milega \u2014 yehi Least Privilege principle hai."}, {"id": "ch5_q15", "termRef": "iam", "type": "category", "difficulty": "medium", "question": "What two actions does an IAM system typically perform for every user, according to the guide?", "options": ["Only monitor internet speed", "Only manage physical door locks", "Only track employee attendance", "Create accounts and assign permissions"], "correctIndex": 3, "explanation": "User accounts banao, permissions assign karo, review karo \u2014 yeh IAM ke core functions hain."}, {"id": "ch5_q16", "termRef": "pam", "type": "definition", "difficulty": "easy", "question": "What does PAM (Privileged Access Management) specifically protect?", "options": ["Only the physical office building", "Privileged accounts like admins, root, and service accounts", "Regular employee email accounts only", "Only guest WiFi access"], "correctIndex": 1, "explanation": "IAM ka subset jo specifically privileged accounts (admins, root, service accounts) ko protect karta hai \u2014 highest risk accounts."}, {"id": "ch5_q17", "termRef": "pam", "type": "category", "difficulty": "medium", "question": "What is 'just-in-time access' in the context of PAM?", "options": ["Granting privileged access only when it is actually needed, not permanently", "Giving every employee permanent admin rights", "Allowing access only during office hours", "Removing all access controls entirely"], "correctIndex": 0, "explanation": "Just-in-time access (sirf jab zaroori) \u2014 PAM ka ek key feature, permanent privileged access ka risk kam karta hai."}, {"id": "ch5_q18", "termRef": "pam", "type": "category", "difficulty": "medium", "question": "Which PAM feature records what an admin actually did during a privileged session?", "options": ["MFA enforcement", "Just-in-time access", "Password vaulting", "Session recording"], "correctIndex": 3, "explanation": "Session recording (admin ne kya kiya) ek core PAM feature hai \u2014 accountability aur audit ke liye zaroori."}, {"id": "ch5_q19", "termRef": "pam", "type": "category", "difficulty": "medium", "question": "Why are privileged accounts considered especially high-risk, according to the guide?", "options": ["Because they are only used for marketing tasks", "Because they are never used by anyone in the company", "Because they have no password at all", "Because controlling them means gaining full control of the system"], "correctIndex": 3, "explanation": "These accounts are highest risk \u2014 inka control matlab full system control, isliye special protection zaroori hai."}, {"id": "ch5_q20", "termRef": "pam", "type": "scenario", "difficulty": "hard", "question": "A company automatically rotates its admin account passwords regularly and stores them in a secure vault rather than letting employees memorize static passwords. Which PAM feature does this describe?", "options": ["Token-based authentication", "Single Sign-On", "Zero Trust", "Password vaulting"], "correctIndex": 3, "explanation": "Password vaulting (auto-rotate passwords) \u2014 PAM ka feature jo privileged account passwords ko securely manage karta hai."}, {"id": "ch5_q21", "termRef": "sso", "type": "definition", "difficulty": "easy", "question": "What does Single Sign-On (SSO) allow a user to do?", "options": ["Log in once and automatically gain access to multiple connected apps", "Only access one app forever without any other access", "Use a different password for every single application", "Bypass all authentication requirements entirely"], "correctIndex": 0, "explanation": "Ek baar login karo (Google ya company account se), sab apps automatically accessible \u2014 'Sign in with Google' = SSO."}, {"id": "ch5_q22", "termRef": "sso", "type": "category", "difficulty": "medium", "question": "Which technologies commonly power SSO behind the scenes, according to the guide?", "options": ["DNS and DHCP", "OAuth and SAML", "TCP and UDP", "AES and RSA only"], "correctIndex": 1, "explanation": "Token exchange hota hai behind the scenes (OAuth, SAML) \u2014 yeh SSO ko technically implement karne wale protocols hain."}, {"id": "ch5_q23", "termRef": "sso", "type": "category", "difficulty": "medium", "question": "What is the biggest security risk associated with SSO?", "options": ["It makes logging in slower for users", "If the SSO account is compromised, all connected apps become compromised too", "It requires every app to have a separate password", "It cannot be used with MFA at all"], "correctIndex": 1, "explanation": "SSO account compromise = sab apps compromise \u2014 isliye SSO account pe strong MFA absolutely zaroori. 'Single point of failure' bhi ho sakta hai."}, {"id": "ch5_q24", "termRef": "sso", "type": "scenario", "difficulty": "hard", "question": "An attacker compromises an employee's single company Google account and suddenly gains access to a dozen connected internal tools without needing separate passwords for each. What made this possible?", "options": ["SSO \u2014 a single compromised account exposed every connected app", "Network segmentation failure", "A firewall bypass", "A honeypot misconfiguration"], "correctIndex": 0, "explanation": "Yeh exactly SSO ka risk hai \u2014 single point of failure, isliye strong MFA SSO account pe zaroori hai."}, {"id": "ch5_q25", "termRef": "sso", "type": "category", "difficulty": "easy", "question": "Which everyday feature is a real-world example of SSO?", "options": ["Using a physical key to open a door", "Entering a separate password for every website", "Scanning a fingerprint on your own phone only", "'Sign in with Google' buttons on other websites"], "correctIndex": 3, "explanation": "'Sign in with Google' = SSO \u2014 ek baar login, sab apps automatically accessible."}, {"id": "ch5_q26", "termRef": "zerotrust", "type": "definition", "difficulty": "easy", "question": "What is the core principle of Zero Trust Security?", "options": ["Trust is based purely on job title", "Trust every device that connects to the internal network automatically", "Never trust, always verify \u2014 no user or device is trusted by default, inside or outside the network", "Only verify users once a year"], "correctIndex": 2, "explanation": "Traditional model: network ke andar ho to trusted. Zero Trust: andar ya bahar koi fark nahi \u2014 har request verify karo, least privilege do, assume breach."}, {"id": "ch5_q27", "termRef": "zerotrust", "type": "category", "difficulty": "medium", "question": "Why has Zero Trust become especially important in the remote work and cloud era, according to the guide?", "options": ["Because cloud services don't require any authentication", "Because passwords have become obsolete entirely", "Because all employees now work from a single physical office", "Because the traditional concept of a fixed 'corporate network' boundary no longer applies"], "correctIndex": 3, "explanation": "Remote work, cloud era mein 'corporate network' ka concept gone. Employees anywhere se kaam karte hain \u2014 Zero Trust ke bina insider threats devastating ho sakte hain."}, {"id": "ch5_q28", "termRef": "zerotrust", "type": "real_world", "difficulty": "hard", "question": "Google's BeyondCorp, the industry's first large-scale Zero Trust implementation, was built following which major security incident?", "options": ["The SolarWinds breach", "The WannaCry outbreak", "The Colonial Pipeline attack", "Operation Aurora (2010 China hack)"], "correctIndex": 3, "explanation": "Google ka BeyondCorp \u2014 post-Operation Aurora (2010 China hack) \u2014 industry ka pehla large-scale Zero Trust implementation, ab industry standard recommendation."}, {"id": "ch5_q29", "termRef": "zerotrust", "type": "scenario", "difficulty": "hard", "question": "An employee working from home, connected via the company VPN, is still required to re-verify their identity for every sensitive request, exactly as if they were an unknown external user. What philosophy is being applied?", "options": ["SSO without MFA", "No security policy at all", "Zero Trust Security", "Traditional perimeter-based trust"], "correctIndex": 2, "explanation": "'Never trust, always verify' \u2014 andar ya bahar koi fark nahi, har request verify karna Zero Trust ka core hai."}, {"id": "ch5_q30", "termRef": "zerotrust", "type": "category", "difficulty": "medium", "question": "How does the traditional security model differ fundamentally from Zero Trust?", "options": ["There is no real difference between the two models", "Traditional model trusts anyone already inside the network; Zero Trust trusts no one by default", "Zero Trust only applies to physical security, not digital", "Traditional model has no concept of passwords at all"], "correctIndex": 1, "explanation": "Traditional model: network ke andar ho to trusted. Zero Trust: 'Trust but verify' se 'Never trust, always verify' ki taraf shift."}, {"id": "ch5_q31", "termRef": "accesscontrol", "type": "definition", "difficulty": "easy", "question": "What is the general purpose of access control models?", "options": ["Managing a company's physical inventory", "Encrypting network traffic between two devices", "Detecting malware signatures automatically", "Enforcing policy on who can access which resources"], "correctIndex": 3, "explanation": "Resources tak kaun ja sakta hai \u2014 policy enforcement, alag-alag models (DAC, MAC, RBAC, ABAC) yeh alag tareeke se karte hain."}, {"id": "ch5_q32", "termRef": "accesscontrol", "type": "category", "difficulty": "medium", "question": "In which access control model does the system (rather than the resource owner) decide access, typically used for classified/military data?", "options": ["ABAC (Attribute-Based Access Control)", "RBAC (Role-Based Access Control)", "DAC (Discretionary Access Control)", "MAC (Mandatory Access Control)"], "correctIndex": 3, "explanation": "MAC: system decide karta hai (military, classified). DAC: owner decide karta hai (files on your PC)."}, {"id": "ch5_q33", "termRef": "accesscontrol", "type": "category", "difficulty": "medium", "question": "Which access control model grants permissions based on job roles, like 'HR', 'Finance', or 'Developer'?", "options": ["MAC (Mandatory Access Control)", "None of these use roles", "DAC (Discretionary Access Control)", "RBAC (Role-Based Access Control)"], "correctIndex": 3, "explanation": "RBAC: role-based (employees, managers, admins). HR role = employee data access, Finance role = payroll access, Developer role = code repo access."}, {"id": "ch5_q34", "termRef": "accesscontrol", "type": "scenario", "difficulty": "hard", "question": "An access control system grants or denies a request based on multiple real-time factors like the time of day, the user's location, and the device being used. Which model does this describe?", "options": ["RBAC (Role-Based Access Control) alone", "MAC (Mandatory Access Control) alone", "DAC (Discretionary Access Control)", "ABAC (Attribute-Based Access Control)"], "correctIndex": 3, "explanation": "ABAC: attribute-based (time, location, device) \u2014 yeh multiple dynamic factors ke basis pe access decide karta hai."}, {"id": "ch5_q35", "termRef": "accesscontrol", "type": "category", "difficulty": "medium", "question": "In RBAC, what happens automatically when an employee's role changes (e.g. from developer to manager)?", "options": ["Nothing changes; permissions must be manually reset from scratch", "Their permissions automatically change to match the new role", "Their account is permanently deleted", "Their password is reset to a default value"], "correctIndex": 1, "explanation": "Role change karo, permissions automatically change \u2014 yeh RBAC ka core benefit hai, manual reassignment ki zaroorat nahi."}, {"id": "ch5_q36", "termRef": "authn", "type": "definition", "difficulty": "easy", "question": "What question does Authentication answer?", "options": ["'Where are you located?'", "'What can you do?'", "'Who are you?'", "'How much data can you access?'"], "correctIndex": 2, "explanation": "Identity verify karna \u2014 prove karo tum wahi ho jo tum claim karte ho. Password, biometric, token \u2014 sab authentication methods hain."}, {"id": "ch5_q37", "termRef": "authn", "type": "category", "difficulty": "medium", "question": "Which of these is described as an authentication method in the guide?", "options": ["A CDN", "A CVE score", "Password", "A firewall rule"], "correctIndex": 2, "explanation": "Password, biometric, token \u2014 sab authentication methods hain, identity verify karne ke liye."}, {"id": "ch5_q38", "termRef": "authn", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use for authentication versus authorization?", "options": ["Authentication is a passport check; authorization is what areas your visa allows you into", "Authentication is a lock; authorization is a key duplicate", "Authentication is a CCTV camera; authorization is a smoke detector", "Authentication is a firewall; authorization is a VPN"], "correctIndex": 0, "explanation": "Authentication = WHO are you? (Passport check). Authorization = WHAT can you do? (Visa allows entry to certain areas)."}, {"id": "ch5_q39", "termRef": "authn", "type": "scenario", "difficulty": "hard", "question": "A user successfully proves their identity with a correct username, password, and fingerprint scan. Which security step has just occurred?", "options": ["Authorization", "Network segmentation", "Authentication", "Encryption"], "correctIndex": 2, "explanation": "Identity verify hona \u2014 'tum kaun ho' prove karna \u2014 yeh authentication hai, authorization ke pehle ka step."}, {"id": "ch5_q40", "termRef": "authn", "type": "category", "difficulty": "medium", "question": "What comes logically before Authorization in the access process?", "options": ["Network segmentation", "Encryption", "Digital forensics", "Authentication"], "correctIndex": 3, "explanation": "Pehle identity prove karo (Authentication), phir decide hota hai kya access hai (Authorization) \u2014 authentication pehle aata hai."}, {"id": "ch5_q41", "termRef": "authz", "type": "definition", "difficulty": "easy", "question": "What does Authorization determine after a user has logged in?", "options": ["Whether the user's password is strong enough", "Whether the user's device has antivirus installed", "What resources and actions the authenticated user is permitted to access", "The user's physical location"], "correctIndex": 2, "explanation": "Authenticated user ko kya resources access karne ki permission hai \u2014 login ke baad \u2014 'can this user read/write/delete this file?'"}, {"id": "ch5_q42", "termRef": "authz", "type": "category", "difficulty": "hard", "question": "What is 'Broken Access Control', and where does it rank on the OWASP Top 10?", "options": ["It's when a password is too short; it ranks #10", "It's a type of physical break-in; not covered by OWASP", "It's a hardware failure in a firewall; it isn't part of OWASP Top 10", "It's when authorization checks fail, allowing unauthorized access; it ranks #1 on OWASP Top 10"], "correctIndex": 3, "explanation": "Broken Access Control \u2014 OWASP Top 10 mein #1. User A ki ID change karke User B ka data access karna (IDOR) \u2014 horizontal aur vertical privilege escalation."}, {"id": "ch5_q43", "termRef": "authz", "type": "category", "difficulty": "medium", "question": "What does IDOR (Insecure Direct Object Reference) typically involve?", "options": ["Changing an ID in a request to access another user's data without permission", "Installing a rootkit on a server", "Sending too many login requests at once", "Encrypting a database with a weak key"], "correctIndex": 0, "explanation": "User A ki ID change karke User B ka data access karna (IDOR) \u2014 Broken Access Control ka classic example."}, {"id": "ch5_q44", "termRef": "authz", "type": "scenario", "difficulty": "hard", "question": "A logged-in user changes a number in the website's URL from their own account ID to someone else's, and successfully views that other person's private data. What vulnerability class does this fall under?", "options": ["Broken Access Control / IDOR", "DNS Poisoning", "SQL Injection", "Cross-Site Scripting"], "correctIndex": 0, "explanation": "Yeh classic IDOR (Insecure Direct Object Reference) hai, jo Broken Access Control ke under aata hai \u2014 OWASP Top 10 ka #1 issue."}, {"id": "ch5_q45", "termRef": "authz", "type": "category", "difficulty": "medium", "question": "What is the difference between horizontal and vertical privilege escalation?", "options": ["Horizontal means gaining admin rights; vertical means accessing peer data", "Horizontal is accessing another same-level user's data; vertical is gaining higher-level (admin) privileges", "They are the same thing with different names", "Neither relates to Broken Access Control"], "correctIndex": 1, "explanation": "Horizontal: User A ka access User B ke data tak (same level). Vertical: normal user se admin tak escalate karna."}, {"id": "ch5_q46", "termRef": "token", "type": "definition", "difficulty": "easy", "question": "What is the purpose of a token after a user logs in?", "options": ["It automatically encrypts the entire disk", "It permanently deletes the user's password", "It blocks all future login attempts", "It replaces the password for subsequent requests, so the user doesn't need to log in repeatedly"], "correctIndex": 3, "explanation": "Login ke baad server ek token deta hai (string of characters) \u2014 agle requests mein password ki jagah token bhejo, limited time ke liye valid."}, {"id": "ch5_q47", "termRef": "token", "type": "category", "difficulty": "medium", "question": "What are the three parts of a JWT (JSON Web Token), separated by dots?", "options": ["Header, Payload, Signature", "Key, Value, Hash", "Source, Destination, Port", "Username, Password, IP address"], "correctIndex": 0, "explanation": "Header.Payload.Signature \u2014 3 parts dot se separated. Payload mein user info (encrypted nahi, base64 encoded!), signature server verify karta hai."}, {"id": "ch5_q48", "termRef": "token", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use for a token?", "options": ["A CCTV camera in a control room", "A postman delivering sealed letters", "A movie ticket \u2014 you showed ID once at the counter, now you just show the ticket", "A firewall blocking traffic"], "correctIndex": 2, "explanation": "Movie ticket jaisa \u2014 counter pe ID dikhaya (login), ticket mila (token). Ab har movie hall mein token dikhao \u2014 baar baar ID nahi dikhani, ticket expire hoti hai."}, {"id": "ch5_q49", "termRef": "token", "type": "category", "difficulty": "hard", "question": "Is the payload section of a JWT encrypted?", "options": ["Yes, it's protected by RSA encryption", "Yes, it's fully AES-256 encrypted", "No, it's only base64 encoded, not encrypted", "It doesn't contain any user information at all"], "correctIndex": 2, "explanation": "Payload mein user info encrypted nahi hai, base64 encoded hai! \u2014 matlab koi bhi decode kar sakta hai (par tamper nahi kar sakta bina signature tode)."}, {"id": "ch5_q50", "termRef": "token", "type": "scenario", "difficulty": "hard", "question": "After a user logs in once, their app keeps making requests over the next hour without ever asking for the password again \u2014 until the token eventually expires. What mechanism explains this?", "options": ["A firewall allowing unlimited requests", "A honeypot logging all requests", "A token, such as a JWT, replacing repeated password entry", "A CASB monitoring cloud data"], "correctIndex": 2, "explanation": "Token limited time ke liye valid hai \u2014 expire hone tak baar baar login karne ki zaroorat nahi, movie ticket jaisa concept."}]}, {"chapter": 6, "chapterTitle": "Network & Cloud Security", "termCount": 10, "questionCount": 50, "questions": [{"id": "ch6_q01", "termRef": "vpn", "type": "definition", "difficulty": "easy", "question": "What does a VPN create between your device and its server?", "options": ["A firewall rule set", "A backup copy of your files", "A physical cable connection", "An encrypted tunnel that hides your traffic from ISPs, admins, and hackers"], "correctIndex": 3, "explanation": "Tumhare device aur VPN server ke beech encrypted tunnel \u2014 ISP, network admin, hackers koi nahi dekh sakta tum kya browse kar rahe ho."}, {"id": "ch6_q02", "termRef": "vpn", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use to describe a VPN?", "options": ["A smoke detector", "A postman reading your letters", "An opaque armored tube versus a glass tunnel that everyone can see through", "A guard checking IDs"], "correctIndex": 2, "explanation": "Normal internet = glass tunnel \u2014 sab dekh sakte hain. VPN = opaque armored tube \u2014 bahar se kuch nazar nahi."}, {"id": "ch6_q03", "termRef": "vpn", "type": "category", "difficulty": "medium", "question": "What warning does the guide give about free VPN services?", "options": ["They are illegal in every country", "They may sell your data", "They are always faster than paid VPNs", "They cannot be used on mobile devices"], "correctIndex": 1, "explanation": "Free VPNs se beware \u2014 they sell your data. Privacy protect karne ke naam pe khud data bech sakte hain."}, {"id": "ch6_q04", "termRef": "vpn", "type": "scenario", "difficulty": "hard", "question": "You connect to a coffee shop's public WiFi while using a VPN, and even someone monitoring the WiFi network cannot see which websites you're visiting. What is enabling this protection?", "options": ["The VPN's encrypted tunnel", "DNS caching", "A honeypot on the network", "The coffee shop's firewall"], "correctIndex": 0, "explanation": "VPN encrypted tunnel banaata hai \u2014 public WiFi pe safety ke liye ek prime use case hai."}, {"id": "ch6_q05", "termRef": "vpn", "type": "category", "difficulty": "medium", "question": "What IP address does a website see when you're browsing through a VPN?", "options": ["The website's own IP address", "No IP address at all", "Your actual home IP address, unchanged", "The VPN server's IP address, not your own"], "correctIndex": 3, "explanation": "Tumhara IP bhi VPN server ka IP dikhta hai \u2014 yeh regional content access aur privacy ke liye use hota hai."}, {"id": "ch6_q06", "termRef": "netseg", "type": "definition", "difficulty": "easy", "question": "What does network segmentation do?", "options": ["Combines multiple small networks into one large network", "Encrypts all data on a single server", "Divides a large network into smaller isolated segments to contain damage", "Blocks all outbound internet traffic entirely"], "correctIndex": 2, "explanation": "Ek bada network ko smaller segments mein divide karna (VLANs, subnets) \u2014 finance network se developer network alag."}, {"id": "ch6_q07", "termRef": "netseg", "type": "category", "difficulty": "medium", "question": "What specific attack behavior does network segmentation help prevent?", "options": ["Weak password usage by employees", "Physical theft of laptops", "Phishing emails reaching employee inboxes", "Lateral movement \u2014 an attacker moving freely across the whole network after compromising one machine"], "correctIndex": 3, "explanation": "Lateral movement prevent karta hai \u2014 attacker ek machine compromise kare par poore network mein freely nahi ghoom sakta."}, {"id": "ch6_q08", "termRef": "netseg", "type": "scenario", "difficulty": "hard", "question": "A worm compromises one workstation in the marketing department, but is unable to spread into the finance department's systems because they sit on a completely separate network segment. What prevented the spread?", "options": ["A VPN", "NAT", "Network segmentation", "DNS Poisoning defenses"], "correctIndex": 2, "explanation": "Ek zone compromise ho to doosre safe rahein \u2014 yeh network segmentation ka core benefit hai, jaise Colonial Pipeline worm ko bhi is se roka ja sakta tha."}, {"id": "ch6_q09", "termRef": "netseg", "type": "category", "difficulty": "medium", "question": "Which real-world incident does the guide say could have been contained better with proper network segmentation?", "options": ["The MGM Resorts hack", "The Capital One breach", "The Colonial Pipeline attack", "The GitHub DDoS attack"], "correctIndex": 2, "explanation": "Colonial Pipeline worm bhi segmentation se rok sakte the \u2014 guide is example ko specifically mention karti hai."}, {"id": "ch6_q10", "termRef": "netseg", "type": "category", "difficulty": "medium", "question": "Which technical tools does the guide mention for implementing network segmentation?", "options": ["VLANs and subnets", "Digital certificates and CAs", "Password managers and vaults", "Honeypots and sandboxes"], "correctIndex": 0, "explanation": "Ek bada network ko smaller segments mein divide karna (VLANs, subnets) \u2014 yeh technical implementation ka tareeka hai."}, {"id": "ch6_q11", "termRef": "dnspois", "type": "definition", "difficulty": "easy", "question": "What happens during DNS poisoning?", "options": ["Fake records get injected into a DNS server's cache, redirecting users to the wrong IP", "A user's browser history gets deleted", "All DNS servers worldwide go offline simultaneously", "A DNS server is physically destroyed"], "correctIndex": 0, "explanation": "DNS server ki cache mein fake records inject karna \u2014 'google.com = galat IP' record return karta hai, user attacker site pe pahunch jaata hai."}, {"id": "ch6_q12", "termRef": "dnspois", "type": "analogy", "difficulty": "medium", "question": "How does the guide describe what DNS itself is, before explaining poisoning?", "options": ["A type of encrypted messaging protocol", "A firewall rule engine", "A backup storage system", "The 'phone book' of the internet, translating domain names into IP addresses"], "correctIndex": 3, "explanation": "Phone book of internet \u2014 'google.com' \u2192 '142.250.195.46' translate karta hai. DNS poisoning is phonebook mein galat entries daalna hai."}, {"id": "ch6_q13", "termRef": "dnspois", "type": "scenario", "difficulty": "hard", "question": "A user types 'google.com' correctly into their browser, but ends up on a fake malicious website instead. Which attack likely caused this, assuming their own device isn't infected?", "options": ["A CASB failure", "A firewall misconfiguration", "DNS Poisoning", "SSH key theft"], "correctIndex": 2, "explanation": "DNS poisoning se galat IP wapas milta hai even though URL sahi type kiya gaya \u2014 user ko pata bhi nahi chalta ki fake site pe pahunch gaya."}, {"id": "ch6_q14", "termRef": "dnspois", "type": "category", "difficulty": "medium", "question": "What does a poisoned DNS cache record for a legitimate domain like 'google.com' actually contain?", "options": ["The user's own personal IP address", "The correct IP address, but encrypted differently", "An incorrect IP address controlled by the attacker", "No IP address at all"], "correctIndex": 2, "explanation": "'google.com = 1.2.3.4' \u2014 yeh galat IP hai par DNS ye record return karta hai jab poisoning ho chuki ho."}, {"id": "ch6_q15", "termRef": "dnspois", "type": "category", "difficulty": "medium", "question": "DNS poisoning is essentially an attack on which core internet function?", "options": ["User authentication", "File encryption at rest", "Data compression", "Domain name to IP address translation"], "correctIndex": 3, "explanation": "DNS ka core function domain name ko IP address mein translate karna hai \u2014 poisoning isi function ko corrupt karta hai."}, {"id": "ch6_q16", "termRef": "nat", "type": "definition", "difficulty": "easy", "question": "What is the primary security benefit of NAT (Network Address Translation)?", "options": ["It automatically manages user passwords", "It encrypts all internet traffic automatically", "Internal devices' private IPs are hidden from the internet, so they can't be accessed directly", "It blocks all malware regardless of source"], "correctIndex": 2, "explanation": "Router andar private IPs maintain karta hai, internet se direct access nahi hota internal devices ko \u2014 security benefit."}, {"id": "ch6_q17", "termRef": "nat", "type": "category", "difficulty": "medium", "question": "In a typical home network, what does the outside internet see?", "options": ["Only the phone's IP, never the laptop's", "Every individual device's private IP address", "Only the router's single public IP address", "Nothing at all, the network is invisible"], "correctIndex": 2, "explanation": "Router: 103.45.67.89 \u2014 public IP. Internet pe sirf router ka IP dikhta hai, andar ke devices ke private IPs hidden rehte hain."}, {"id": "ch6_q18", "termRef": "nat", "type": "category", "difficulty": "medium", "question": "Which of these is an example of a private IP address, as shown in the guide's home network example?", "options": ["8.8.8.8", "192.168.1.5", "1.1.1.1", "103.45.67.89"], "correctIndex": 1, "explanation": "Phone: 192.168.1.5, Laptop: 192.168.1.6 \u2014 yeh private IPs hain, sirf ghar ke network ke andar valid."}, {"id": "ch6_q19", "termRef": "nat", "type": "scenario", "difficulty": "hard", "question": "An attacker scanning the internet cannot directly find or connect to your home laptop's private IP address, even though they can see your router's public IP. What is providing this protection?", "options": ["NAT (Network Address Translation)", "A VPN", "DNS Poisoning defenses", "SSH keys"], "correctIndex": 0, "explanation": "NAT internal devices ko internet se direct access se protect karta hai, sirf router ka public IP visible hota hai."}, {"id": "ch6_q20", "termRef": "nat", "type": "category", "difficulty": "easy", "question": "What does NAT stand for?", "options": ["Network Access Token", "Network Authentication Tool", "New Application Traffic", "Network Address Translation"], "correctIndex": 3, "explanation": "NAT = Network Address Translation \u2014 private IPs hide karna internet se, security ka ek natural side-benefit."}, {"id": "ch6_q21", "termRef": "sdn", "type": "definition", "difficulty": "easy", "question": "What does SDN (Software Defined Networking) enable compared to traditional networks?", "options": ["Removing the need for any network security at all", "Only allowing wireless connections", "Physically rewiring the network every time a policy changes", "Centralized, software-based control of the network instead of manual hardware configuration"], "correctIndex": 3, "explanation": "Traditional networks mein hardware configure karo manually. SDN mein software se network control hota hai centrally."}, {"id": "ch6_q22", "termRef": "sdn", "type": "category", "difficulty": "medium", "question": "What security advantage does SDN offer when a threat is detected?", "options": ["It permanently deletes all network logs", "It requires a technician to physically unplug a cable", "It disables the internet for the entire company", "The SDN controller can automatically isolate the affected network segment"], "correctIndex": 3, "explanation": "Threat detect hote hi, SDN controller automatically affected segment isolate kar sakta hai \u2014 faster response to threats."}, {"id": "ch6_q23", "termRef": "sdn", "type": "category", "difficulty": "medium", "question": "Which environments does the guide say typically rely on SDN-like architecture?", "options": ["Standalone offline computers", "Cloud networks", "Physical paper filing systems", "Old dial-up modem networks"], "correctIndex": 1, "explanation": "Cloud networks aise hi work karte hain \u2014 micro-segmentation easily implement, SDN-based architecture common hai."}, {"id": "ch6_q24", "termRef": "sdn", "type": "scenario", "difficulty": "hard", "question": "As soon as a security tool flags anomalous traffic, the network automatically reconfigures itself in seconds to isolate the affected segment, without any human manually reconfiguring hardware. What technology enables this rapid response?", "options": ["DNS Poisoning defenses", "SSH key rotation", "NAT alone", "SDN (Software Defined Networking)"], "correctIndex": 3, "explanation": "SDN security policies dynamically apply ho sakti hain \u2014 automated, fast response jo traditional hardware configuration se possible nahi tha."}, {"id": "ch6_q25", "termRef": "sdn", "type": "category", "difficulty": "medium", "question": "What does SDN make easier to implement, according to the guide?", "options": ["Micro-segmentation", "Manual firewall rule entry only", "Paper-based audit trails", "Physical cable management"], "correctIndex": 0, "explanation": "Micro-segmentation easily implement \u2014 SDN ki flexibility isse possible banati hai."}, {"id": "ch6_q26", "termRef": "casb", "type": "definition", "difficulty": "easy", "question": "What does a CASB (Cloud Access Security Broker) primarily monitor?", "options": ["Hardware keyloggers on employee laptops", "What data employees send to cloud apps and detect unauthorized ('shadow IT') app usage", "Email spam filtering rules only", "Physical access to the server room"], "correctIndex": 1, "explanation": "Employees cloud apps (Google Drive, Dropbox, Salesforce) use karte hain \u2014 CASB monitor karta hai kya data cloud pe ja raha hai."}, {"id": "ch6_q27", "termRef": "casb", "type": "category", "difficulty": "medium", "question": "What is 'shadow IT', which a CASB helps detect?", "options": ["A backup server hidden in a data center", "A type of ransomware", "A hacking group operating in the dark web", "Unauthorized apps or cloud services being used without IT department approval"], "correctIndex": 3, "explanation": "Unauthorized apps ka use ('shadow IT') detect karta hai \u2014 jab employees bina approval ke apne cloud tools use karte hain."}, {"id": "ch6_q28", "termRef": "casb", "type": "scenario", "difficulty": "hard", "question": "An employee uploads a confidential company document to their personal Dropbox account, and a security tool immediately flags and alerts the security team. Which tool caught this?", "options": ["CASB", "NAT", "SSH", "DNS Poisoning protection"], "correctIndex": 0, "explanation": "Employee ne confidential doc Dropbox personal pe upload kiya, CASB detect karta hai \u2014 alert ya block. DLP + cloud = CASB."}, {"id": "ch6_q29", "termRef": "casb", "type": "category", "difficulty": "medium", "question": "How does the guide describe CASB in relation to DLP?", "options": ["CASB replaces the need for any encryption", "CASB has nothing to do with DLP", "CASB is essentially DLP combined with cloud visibility", "CASB is only for physical security"], "correctIndex": 2, "explanation": "DLP + cloud = CASB \u2014 guide explicitly is combination ko describe karti hai."}, {"id": "ch6_q30", "termRef": "casb", "type": "category", "difficulty": "medium", "question": "Which of these apps would a CASB typically monitor employee usage of?", "options": ["Only the company's internal firewall", "Only the office printer", "Only the company's physical badge system", "Google Drive, Dropbox, and Salesforce"], "correctIndex": 3, "explanation": "Employees cloud apps (Google Drive, Dropbox, Salesforce) use karte hain \u2014 CASB inhi apps pe data flow monitor karta hai."}, {"id": "ch6_q31", "termRef": "iot", "type": "definition", "difficulty": "easy", "question": "What is the Internet of Things (IoT)?", "options": ["Internet-connected physical devices like smart bulbs, cameras, and thermostats", "A type of encryption algorithm", "A network security monitoring tool", "A cloud storage provider"], "correctIndex": 0, "explanation": "Smart devices jo internet se connected hain \u2014 smart bulbs, cameras, fridges, thermostats, wearables, industrial sensors, medical devices."}, {"id": "ch6_q32", "termRef": "iot", "type": "category", "difficulty": "medium", "question": "How many IoT devices are expected globally by 2030, according to the guide?", "options": ["7.5 million", "75 billion or more", "7.5 billion", "750,000"], "correctIndex": 1, "explanation": "2030 tak 75 billion+ IoT devices expected \u2014 har device ek potential entry point banta hai."}, {"id": "ch6_q33", "termRef": "iot", "type": "category", "difficulty": "medium", "question": "What common security problem does the guide highlight about most IoT devices?", "options": ["They often have weak passwords, outdated firmware, and no security updates", "They cannot connect to the internet at all", "They are only used by governments", "They are always more secure than laptops"], "correctIndex": 0, "explanation": "Most IoT devices have terrible security \u2014 no updates, weak passwords, old firmware \u2014 isliye har device ek potential entry point banta hai."}, {"id": "ch6_q34", "termRef": "iot", "type": "scenario", "difficulty": "hard", "question": "A smart doorbell, a smart thermostat, and a smart TV in your house all still have their default factory passwords set. What does this collectively represent?", "options": ["An expanded attack surface due to poor IoT security practices", "A DNS poisoning vulnerability specifically", "A guaranteed DDoS attack within 24 hours", "No risk at all since they're just household appliances"], "correctIndex": 0, "explanation": "Default passwords change na karna common IoT mistake hai \u2014 har unsecured device ek potential entry point ban jaata hai attackers ke liye."}, {"id": "ch6_q35", "termRef": "iot", "type": "category", "difficulty": "medium", "question": "Which of these is an example of an IoT device, according to the guide's list?", "options": ["A traditional desktop PC only", "A smart bulb", "A landline telephone", "A physical paper document"], "correctIndex": 1, "explanation": "Smart bulbs, cameras, fridges, thermostats, wearables, industrial sensors, medical devices \u2014 sab IoT devices hain."}, {"id": "ch6_q36", "termRef": "iotsec", "type": "definition", "difficulty": "easy", "question": "Why does the guide describe securing IoT devices as especially difficult?", "options": ["Because IoT devices don't connect to the internet at all", "Because IoT devices are always encrypted by default", "Because IoT devices have unlimited processing power", "Limited processing power, no screen for setup, and vendors rarely issue updates"], "correctIndex": 3, "explanation": "Limited processing power (can't run complex security), no screen/keyboard for setup, vendors update nahi karte, users default passwords change nahi karte."}, {"id": "ch6_q37", "termRef": "iotsec", "type": "real_world", "difficulty": "hard", "question": "In the 2017 casino hack, attackers used a smart fish tank thermometer to exfiltrate how much data from the casino's high-roller database?", "options": ["100MB", "100GB", "1GB", "10GB"], "correctIndex": 3, "explanation": "Casino ka smart fish tank thermometer hack hua \u2014 attackers ne isse network access liya aur casino's high-roller database exfiltrate ki, 10GB data."}, {"id": "ch6_q38", "termRef": "iotsec", "type": "category", "difficulty": "medium", "question": "Which of these is a recommended best practice for IoT security, according to the guide?", "options": ["Keep IoT devices on a separate network/VLAN from critical systems", "Connect every IoT device directly to the main corporate network", "Always keep default passwords unchanged for compatibility", "Never update IoT device firmware, to avoid breaking it"], "correctIndex": 0, "explanation": "Default passwords change karo, separate network/VLAN pe rakho IoT devices, firmware update karo, unnecessary features disable karo, network monitoring rakho."}, {"id": "ch6_q39", "termRef": "iotsec", "type": "scenario", "difficulty": "hard", "question": "A seemingly harmless smart device on a network becomes the entry point for a much larger data breach into supposedly unrelated systems. Which real-world incident does this describe?", "options": ["The GitHub DDoS attack", "The Zeus Trojan campaign", "The Colonial Pipeline attack", "The casino fish tank thermometer hack"], "correctIndex": 3, "explanation": "Hospital/casino hack via fish tank thermometer (2017) \u2014 exactly is scenario ko describe karta hai, ek chhota IoT device bada breach ka entry point bana."}, {"id": "ch6_q40", "termRef": "iotsec", "type": "category", "difficulty": "medium", "question": "Why is IoT device lifecycle a security challenge, according to the guide?", "options": ["Devices never need power and thus never need updates", "Devices are replaced every month, causing config chaos", "Devices are always managed by a dedicated IT team", "Devices can remain in use for 10-20 years, often without ongoing security support"], "correctIndex": 3, "explanation": "Long lifecycle (10-20 years) \u2014 vendor support kabhi khatam ho jaata hai but device abhi bhi use ho raha hota hai, security gap create karta hai."}, {"id": "ch6_q41", "termRef": "netsec", "type": "definition", "difficulty": "easy", "question": "What does Network Security encompass, as an umbrella term?", "options": ["Only physical locks on server room doors", "Only antivirus software installed on individual laptops", "Only employee training programs", "Policies, tools, and practices that protect network infrastructure from unauthorized access, misuse, and denial"], "correctIndex": 3, "explanation": "Policies, tools, aur practices jo network infrastructure protect karte hain \u2014 unauthorized access, misuse, modification, denial prevent karna."}, {"id": "ch6_q42", "termRef": "netsec", "type": "category", "difficulty": "medium", "question": "What is 'defense in depth', as described in the guide's Network Security layers?", "options": ["Removing all layers to simplify the network", "Only using antivirus and nothing else", "Relying on a single very strong firewall alone", "Using multiple layers (firewall, IDS, WAF, endpoint, SIEM) so that if one layer fails, another catches the threat"], "correctIndex": 3, "explanation": "Defense in depth \u2014 ek layer breach ho to doosri catch kare. Firewall \u2192 IDS \u2192 WAF \u2192 Endpoint \u2192 SIEM \u2014 layered approach best practice hai."}, {"id": "ch6_q43", "termRef": "netsec", "type": "category", "difficulty": "medium", "question": "Which of these tools is listed as a component of overall Network Security?", "options": ["Firewall", "A physical paper filing cabinet", "A coffee machine", "An office chair"], "correctIndex": 0, "explanation": "Firewall, IDS/IPS, VPN, segmentation sab Network Security ke components hain."}, {"id": "ch6_q44", "termRef": "netsec", "type": "scenario", "difficulty": "hard", "question": "An attacker bypasses the firewall, but is then caught by the IDS, and even if that failed too, the WAF would have blocked the web-layer attack anyway. What security philosophy is being demonstrated?", "options": ["Zero Trust alone", "Defense in depth", "Single Sign-On", "Network Address Translation alone"], "correctIndex": 1, "explanation": "Ek layer breach ho to doosri catch kare \u2014 yeh defense in depth ka core idea hai, multiple layers overlapping protection dete hain."}, {"id": "ch6_q45", "termRef": "netsec", "type": "category", "difficulty": "easy", "question": "Which order does the guide list as a typical layered defense-in-depth stack?", "options": ["SIEM \u2192 Firewall \u2192 Endpoint \u2192 IDS \u2192 WAF", "Endpoint \u2192 SIEM \u2192 Firewall \u2192 WAF \u2192 IDS", "Firewall \u2192 IDS \u2192 WAF \u2192 Endpoint \u2192 SIEM", "WAF \u2192 SIEM \u2192 IDS \u2192 Firewall \u2192 Endpoint"], "correctIndex": 2, "explanation": "Firewall \u2192 IDS \u2192 WAF \u2192 Endpoint \u2192 SIEM \u2014 layered approach best practice hai jo guide mein specifically likha gaya hai."}, {"id": "ch6_q46", "termRef": "threatactor", "type": "definition", "difficulty": "easy", "question": "What is a 'threat actor'?", "options": ["Only an insider employee", "Anyone who carries out a cyberattack, regardless of their motivation or skill level", "Only a piece of malicious software", "Only a government employee working in cybersecurity"], "correctIndex": 1, "explanation": "Koi bhi jo cyberattack kare \u2014 multiple types: nation-state, cybercriminals, hacktivists, insider threats, script kiddies."}, {"id": "ch6_q47", "termRef": "threatactor", "type": "category", "difficulty": "medium", "question": "Which threat actor type is primarily motivated by political causes?", "options": ["Nation-State actors", "Cybercriminals", "Hacktivists", "Script Kiddies"], "correctIndex": 2, "explanation": "Hacktivists: Political (Anonymous) \u2014 cybercriminals financial motivation rakhte hain, nation-state government-backed hote hain."}, {"id": "ch6_q48", "termRef": "threatactor", "type": "category", "difficulty": "medium", "question": "Why does knowing the type of threat actor matter for defense, according to the guide?", "options": ["It reveals their likely motivation and resources, helping tailor defenses accordingly", "It has no practical impact on defense strategy at all", "It determines which color the security badge should be", "It only matters for legal prosecution, not security"], "correctIndex": 0, "explanation": "Threat actor type se pata chalta hai motivation kya hai, resources kitne hain \u2014 nation-state actors ka zero-day budget \u2260 script kiddie ka free tools."}, {"id": "ch6_q49", "termRef": "threatactor", "type": "scenario", "difficulty": "hard", "question": "A government-backed group like Russia's APT28 launches a highly sophisticated, well-funded, multi-year campaign against a target. Which threat actor category does this represent?", "options": ["Script Kiddie", "Hacktivist", "Insider Threat", "Nation-State"], "correctIndex": 3, "explanation": "Nation-State: government-backed (Russia APT28, China APT40) \u2014 highly resourced aur sophisticated compared to other threat actor types."}, {"id": "ch6_q50", "termRef": "threatactor", "type": "category", "difficulty": "medium", "question": "Which threat actor type does the guide describe as motivated purely by financial gain?", "options": ["Cybercriminals", "Script Kiddies", "Hacktivists", "Nation-State actors"], "correctIndex": 0, "explanation": "Cybercriminals: Financial motivation \u2014 yeh unhe hacktivists (political) ya nation-state (geopolitical) se alag karta hai."}]}, {"chapter": 7, "chapterTitle": "Advanced Threats & Social Engineering", "termCount": 10, "questionCount": 50, "questions": [{"id": "ch7_q01", "termRef": "apt", "type": "definition", "difficulty": "easy", "question": "What is an APT (Advanced Persistent Threat)?", "options": ["A firewall configuration error", "A quick, single-hit ransomware attack", "A basic phishing email sent to random users", "A long-term, targeted attack where an attacker stays hidden inside a network for months or years"], "correctIndex": 3, "explanation": "Long-term targeted attack \u2014 attacker mahino ya saalo tak network mein chupa rehta hai bina detect hue. Nation-states typically karte hain."}, {"id": "ch7_q02", "termRef": "apt", "type": "category", "difficulty": "medium", "question": "What does the 'Persistent' in APT specifically refer to?", "options": ["A single attack that happens instantly", "A months- or years-long campaign inside the target's network", "The attacker's persistence in sending spam emails", "A malware that repeatedly crashes the system"], "correctIndex": 1, "explanation": "Persistent: Months/years long campaign \u2014 yehi APT ko ordinary attacks se alag banata hai."}, {"id": "ch7_q03", "termRef": "apt", "type": "real_world", "difficulty": "hard", "question": "The SolarWinds (2020) APT attack, attributed to Russia's SVR, went undetected for how long inside US government agencies?", "options": ["9 years", "9 days", "9 months", "9 weeks"], "correctIndex": 2, "explanation": "Russia's SVR ne SolarWinds software update mein malware inject kiya (supply chain), 18,000 organizations infected, US government agencies breach \u2014 9 months undetected."}, {"id": "ch7_q04", "termRef": "apt", "type": "category", "difficulty": "medium", "question": "What is typically the goal of an APT, as opposed to a quick ransomware attack?", "options": ["Immediate financial extortion only", "Displaying advertisements to the target", "Data exfiltration or sabotage, not a quick financial hit", "Testing a company's firewall configuration"], "correctIndex": 2, "explanation": "Goal: data exfiltration ya sabotage \u2014 not ransomware quick hit. APT ka objective long-term rehta hai."}, {"id": "ch7_q05", "termRef": "apt", "type": "scenario", "difficulty": "hard", "question": "Security investigators discover that an attacker had quiet, ongoing access to a company's network for over a year before being detected, slowly extracting sensitive data the whole time. What type of threat does this match?", "options": ["Adware", "An APT (Advanced Persistent Threat)", "A DDoS attack", "A simple phishing attempt"], "correctIndex": 1, "explanation": "Long-term stealth presence, gradual data exfiltration \u2014 yeh exactly APT ki defining characteristic hai."}, {"id": "ch7_q06", "termRef": "espionage", "type": "definition", "difficulty": "easy", "question": "What is Cyber Espionage?", "options": ["Stealing sensitive government or corporate information through digital means", "Publicly disclosing a company's security vulnerabilities", "A defensive tool used to detect intrusions", "A type of ransomware that targets governments only"], "correctIndex": 0, "explanation": "Government ya corporations ke sensitive information chori karna digital means se \u2014 traditional spy agencies ka cyber equivalent."}, {"id": "ch7_q07", "termRef": "espionage", "type": "category", "difficulty": "medium", "question": "Which of these groups is mentioned in the guide as associated with cyber espionage?", "options": ["APT28 'Fancy Bear' (Russia)", "The Tor Project", "MITRE", "OWASP"], "correctIndex": 0, "explanation": "China (APT40, APT10), Russia (APT28 Fancy Bear, APT29 Cozy Bear), North Korea (Lazarus Group), Iran \u2014 sab cyber espionage players hain."}, {"id": "ch7_q08", "termRef": "espionage", "type": "category", "difficulty": "medium", "question": "What kind of information is typically targeted in cyber espionage, according to the guide?", "options": ["Only social media likes and comments", "Only publicly available news articles", "Military plans, technology secrets, and trade secrets", "Only weather forecast data"], "correctIndex": 2, "explanation": "Military plans, technology secrets, diplomatic cables, trade secrets \u2014 sab target hote hain cyber espionage mein."}, {"id": "ch7_q09", "termRef": "espionage", "type": "category", "difficulty": "hard", "question": "Which nation-state group is specifically associated with North Korea, according to the guide?", "options": ["Lazarus Group", "APT28 Fancy Bear", "APT40", "APT29 Cozy Bear"], "correctIndex": 0, "explanation": "North Korea ka Lazarus Group \u2014 guide mein specifically North Korea se associate kiya gaya hai."}, {"id": "ch7_q10", "termRef": "espionage", "type": "scenario", "difficulty": "hard", "question": "A foreign intelligence agency secretly accesses a defense contractor's servers to steal blueprints for a new weapons system. What is this an example of?", "options": ["A simple DDoS attack", "Cyber Espionage", "Adware distribution", "Credential stuffing"], "correctIndex": 1, "explanation": "Sensitive military/technology information government ke through chori karna \u2014 exactly cyber espionage ki definition hai."}, {"id": "ch7_q11", "termRef": "warfare", "type": "definition", "difficulty": "easy", "question": "What is Cyber Warfare?", "options": ["State-sponsored cyberattacks designed to disrupt or damage another nation", "A friendly competition between two companies' security teams", "A type of antivirus software update", "A training exercise for ethical hackers"], "correctIndex": 0, "explanation": "State-sponsored cyberattacks dusre nations ko disrupt ya damage karne ke liye \u2014 power grids, water systems, financial systems target hote hain."}, {"id": "ch7_q12", "termRef": "warfare", "type": "category", "difficulty": "medium", "question": "According to the guide, cyber is considered which numbered 'domain of warfare'?", "options": ["Not considered a domain of warfare at all", "The 3rd domain, after land and sea", "The 1st and only domain of modern warfare", "The 5th domain, alongside land, sea, air, and space"], "correctIndex": 3, "explanation": "5th domain of warfare \u2014 land, sea, air, space, cyber. Iska matlab hai cyber attacks ko literally war ke acts ki tarah treat kiya jaata hai."}, {"id": "ch7_q13", "termRef": "warfare", "type": "real_world", "difficulty": "hard", "question": "NotPetya, which spread from a Ukraine-targeted cyberattack, caused how much in global damage?", "options": ["$1 billion", "$10 billion or more", "$100 million", "$1 trillion"], "correctIndex": 1, "explanation": "NotPetya Ukraine attack ($10B+ global damage) \u2014 guide is figure ko specifically cyber warfare ke context mein mention karti hai."}, {"id": "ch7_q14", "termRef": "warfare", "type": "category", "difficulty": "medium", "question": "Which of these is listed as a real cyber warfare example in the guide?", "options": ["The Blackshades RAT case", "The Capital One breach", "The MGM Resorts hack", "Ukraine power grid attacks by Russia (2015, 2016)"], "correctIndex": 3, "explanation": "Ukraine power grid attacks by Russia (2015, 2016), Estonia DDoS (2007), Stuxnet vs Iran, NotPetya \u2014 sab examples of cyber warfare acts of war."}, {"id": "ch7_q15", "termRef": "warfare", "type": "category", "difficulty": "medium", "question": "What kind of systems are the primary targets in cyber warfare, according to the guide?", "options": ["Power grids, water systems, and military systems", "Only personal social media accounts", "Only university research databases", "Only online shopping websites"], "correctIndex": 0, "explanation": "Power grids, water systems, financial systems, military systems target hote hain \u2014 critical infrastructure cyber warfare ka main focus hai."}, {"id": "ch7_q16", "termRef": "supply", "type": "definition", "difficulty": "easy", "question": "What is a Supply Chain Attack?", "options": ["Sending phishing emails directly to the target", "Flooding a target's website with traffic", "Directly hacking the target's own servers with no third party involved", "Compromising a trusted third-party vendor so the real target installs infected software unknowingly"], "correctIndex": 3, "explanation": "Direct target attack mushkil hai, to attacker uske software supplier, hardware vendor, ya IT provider ko compromise karta hai."}, {"id": "ch7_q17", "termRef": "supply", "type": "category", "difficulty": "medium", "question": "Why is a supply chain attack especially devastating in terms of scale?", "options": ["It requires physical access to every victim's building", "Compromising one vendor can simultaneously compromise thousands of that vendor's customers", "It only ever affects a single individual user", "It only works against small startups"], "correctIndex": 1, "explanation": "Scale: ek vendor compromise = hazaron customers compromise simultaneously \u2014 defense very difficult hai."}, {"id": "ch7_q18", "termRef": "supply", "type": "real_world", "difficulty": "hard", "question": "The XZ Utils backdoor (2024) was inserted after how long a patient social engineering effort, according to the guide?", "options": ["2 weeks", "2 years", "2 months", "2 days"], "correctIndex": 1, "explanation": "Open source library mein backdoor inject kiya gaya 2 years ke patient social engineering ke baad \u2014 nearly compromised OpenSSH on millions of Linux servers."}, {"id": "ch7_q19", "termRef": "supply", "type": "category", "difficulty": "medium", "question": "Why do supply chain attacks often bypass normal security measures?", "options": ["They only target air-gapped systems", "The malicious software comes from a trusted, already-approved source", "They require the victim's password beforehand", "They always use zero antivirus-detectable code"], "correctIndex": 1, "explanation": "Trusted source se aata hai \u2014 security bypasses. Target khud infected software install kar leta hai thinking it's legitimate."}, {"id": "ch7_q20", "termRef": "supply", "type": "scenario", "difficulty": "hard", "question": "Thousands of organizations unknowingly install a legitimate software update from a trusted vendor, not realizing attackers compromised the vendor's build process to embed malware in it. What kind of attack is this?", "options": ["A Supply Chain Attack", "Credential Stuffing", "A phishing campaign", "A DDoS attack"], "correctIndex": 0, "explanation": "Yeh exactly SolarWinds Orion (2020) jaisa scenario hai \u2014 trusted vendor compromise karke uske customers ko target karna."}, {"id": "ch7_q21", "termRef": "social", "type": "definition", "difficulty": "easy", "question": "What does Social Engineering exploit, rather than technical vulnerabilities?", "options": ["A software bug in a web application", "Human psychology, manipulating people into revealing information or performing actions", "A weak encryption algorithm", "An unpatched operating system vulnerability"], "correctIndex": 1, "explanation": "Humans ko manipulate karke confidential info reveal karwana ya actions perform karwana \u2014 technical skills ki zaroorat nahi, psychological manipulation."}, {"id": "ch7_q22", "termRef": "social", "type": "category", "difficulty": "medium", "question": "What is 'baiting' as a social engineering technique?", "options": ["Physically following someone through a secure door", "Creating a fake identity claiming to be IT support", "Offering IT help in exchange for a password", "Leaving an infected USB drive somewhere the victim will find and plug it in"], "correctIndex": 3, "explanation": "Baiting: Infected USB chhodna parking mein \u2014 victim curiosity se plug in kar deta hai, malware install ho jaata hai."}, {"id": "ch7_q23", "termRef": "social", "type": "category", "difficulty": "medium", "question": "What is 'tailgating' in the context of social engineering?", "options": ["Sending a fake email pretending to be a bank", "Offering fake IT help in exchange for a password", "Physically following someone through a secure door without their own access credentials", "Leaving an infected USB drive in a parking lot"], "correctIndex": 2, "explanation": "Tailgating: Physically follow someone through a secure door \u2014 a physical social engineering technique."}, {"id": "ch7_q24", "termRef": "social", "type": "scenario", "difficulty": "hard", "question": "An attacker calls an employee claiming to be from the IT department, saying the employee's PC is infected, and asks for remote access to 'fix' it. Which technique is this?", "options": ["Network segmentation bypass", "SQL Injection", "A supply chain attack", "Social Engineering (pretexting)"], "correctIndex": 3, "explanation": "'Tumhara PC virus infected hai, main IT se hun, abhi remote access do' \u2014 yahi social engineering hai. Firewall bypass nahi kiya, tumhe manipulate kiya."}, {"id": "ch7_q25", "termRef": "social", "type": "category", "difficulty": "medium", "question": "What is 'quid pro quo' in social engineering, according to the guide?", "options": ["Creating a fake CA-issued certificate", "Physically tailgating through a secure door", "Leaving an infected USB drive as bait", "Offering something (like IT help) in exchange for information such as a password"], "correctIndex": 3, "explanation": "Quid Pro Quo: 'IT help ke badle password do' \u2014 ek transaction jaisa dikhta hai lekin manipulation hai."}, {"id": "ch7_q26", "termRef": "brute", "type": "definition", "difficulty": "easy", "question": "What does a brute force attack do?", "options": ["Exploits a software vulnerability directly", "Encrypts files and demands a ransom", "Systematically tries every possible password/key combination until the correct one is found", "Tricks a user into revealing their password voluntarily"], "correctIndex": 2, "explanation": "Systematically har possible password/key combination try karna jab tak sahi na mile \u2014 simple 4-digit PIN = 10,000 combinations."}, {"id": "ch7_q27", "termRef": "brute", "type": "category", "difficulty": "medium", "question": "Which brute force variant uses a list of commonly used words and phrases instead of every possible combination?", "options": ["Dictionary Attack", "Simple Brute Force", "Hybrid Attack", "Rainbow Table"], "correctIndex": 0, "explanation": "Dictionary Attack: Common words list use karta hai, jabki Simple Brute Force har combination try karta hai (aaa, aab, aac...)."}, {"id": "ch7_q28", "termRef": "brute", "type": "defense", "difficulty": "medium", "question": "Which defense against brute force attacks locks an account after a small number of failed login attempts?", "options": ["Rate limiting", "Long passwords alone", "MFA alone", "CAPTCHA alone"], "correctIndex": 0, "explanation": "Rate limiting \u2014 3 attempts failed \u2192 lockout. Yeh ek specific defense hai jo failed attempts ko count karke account lock karti hai."}, {"id": "ch7_q29", "termRef": "brute", "type": "scenario", "difficulty": "hard", "question": "An attacker's automated tool systematically tries thousands of pre-computed password hashes against a stolen hash file, looking for a match. Which brute-force technique is this closest to?", "options": ["Supply chain attack", "Social engineering", "Rainbow Table attack", "Simple sequential brute force (aaa, aab, aac...)"], "correctIndex": 2, "explanation": "Rainbow Table: Pre-computed hash lookups \u2014 yeh ek efficient technique hai jo pehle se calculated hashes ka use karti hai."}, {"id": "ch7_q30", "termRef": "brute", "type": "category", "difficulty": "medium", "question": "Which password is described as breakable 'in seconds' due to its commonness?", "options": ["'abc123'", "A biometric fingerprint", "'Tr0ub4dor&3'", "A 20-character random string"], "correctIndex": 0, "explanation": "'abc123' jaise common passwords seconds mein crack ho jaate hain \u2014 length aur complexity dono zaroori hain."}, {"id": "ch7_q31", "termRef": "cred", "type": "definition", "difficulty": "easy", "question": "What is Credential Stuffing?", "options": ["Tricking a user into revealing their password via a fake email", "Physically stealing a written password note", "Guessing a password character by character", "Using leaked username-password pairs from one breach to try logging into many other sites"], "correctIndex": 3, "explanation": "Data breach se leaked username-password pairs ko automated tools se hazaron other sites pe try karna."}, {"id": "ch7_q32", "termRef": "cred", "type": "category", "difficulty": "medium", "question": "Why does credential stuffing work so effectively against people who reuse passwords?", "options": ["It works only on sites that don't use HTTPS", "It requires physical access to the victim's device", "It only works against government accounts", "A single breach on one site can compromise all of their accounts across many other sites"], "correctIndex": 3, "explanation": "Same password everywhere use karte ho? Ek site breach = sab sites compromise \u2014 yehi credential stuffing ka core risk hai."}, {"id": "ch7_q33", "termRef": "cred", "type": "category", "difficulty": "medium", "question": "Even at a very low success rate, why can credential stuffing still cause massive impact?", "options": ["Because it only needs a single attempt to work", "Because every attempt is guaranteed to succeed", "Because it targets only one account at a time by design", "Because billions of leaked credentials are available, so even 0.1% success means millions of accounts"], "correctIndex": 3, "explanation": "0.1% success rate bhi millions of accounts = huge impact, kyunki billions of credentials dark web pe available hain."}, {"id": "ch7_q34", "termRef": "cred", "type": "defense", "difficulty": "medium", "question": "What is the single most effective personal defense against credential stuffing, according to the guide?", "options": ["Using the same strong password everywhere for consistency", "Disabling all password requirements", "Never logging into any website", "Using a unique password for every site with a password manager"], "correctIndex": 3, "explanation": "Unique password har site pe \u2014 password manager use karo (Bitwarden, 1Password) \u2014 isse ek breach dusri sites ko affect nahi karta."}, {"id": "ch7_q35", "termRef": "cred", "type": "scenario", "difficulty": "hard", "question": "After a data breach at one shopping website, an attacker successfully logs into a completely unrelated user's email account using the exact same leaked username and password. What attack technique was used?", "options": ["SQL Injection", "Brute Force", "Credential Stuffing", "Cyber Espionage"], "correctIndex": 2, "explanation": "Same leaked credentials ko dusri site pe try karna \u2014 exactly credential stuffing ki definition hai, password reuse ka direct consequence."}, {"id": "ch7_q36", "termRef": "insider", "type": "definition", "difficulty": "easy", "question": "Which of these is one of the three insider threat types listed in the guide?", "options": ["Automated \u2014 a bot with no human control", "External \u2014 someone with no access at all", "Negligent \u2014 someone who accidentally makes a security mistake", "Anonymous \u2014 someone using Tor exclusively"], "correctIndex": 2, "explanation": "Malicious: deliberately data steal ya damage kare. Negligent: accidentally security mistake kare. Compromised: external attacker ne account hijack kiya."}, {"id": "ch7_q37", "termRef": "insider", "type": "category", "difficulty": "medium", "question": "Which technology does the guide say is used to detect insider threats through behavioral deviation?", "options": ["A basic packet-filtering firewall", "NAT alone", "SSL alone", "UEBA (User & Entity Behavior Analytics)"], "correctIndex": 3, "explanation": "UEBA (behavior analytics) \u2014 normal se deviation. Unusual access times, large data downloads, off-hours logins."}, {"id": "ch7_q38", "termRef": "insider", "type": "real_world", "difficulty": "hard", "question": "Edward Snowden, an NSA contractor, copied how many classified documents in the 2013 insider threat case?", "options": ["17 million", "1.7 million", "170,000", "17,000"], "correctIndex": 1, "explanation": "NSA contractor Snowden \u2014 1.7 million classified documents copied aur media ko diye \u2014 sab access legitimate tha, audit trail nahi tha."}, {"id": "ch7_q39", "termRef": "insider", "type": "category", "difficulty": "medium", "question": "What made the Snowden case difficult to catch in real time, according to the guide?", "options": ["He physically broke into an NSA data center", "He bribed multiple NSA employees", "He used a zero-day exploit to gain access", "His access to the documents was entirely legitimate \u2014 there was no audit trail flagging the bulk download"], "correctIndex": 3, "explanation": "Sab access legitimate tha \u2014 audit trail nahi tha ki woh itna sab ek saath download kar raha hai \u2014 is is insider threat detection ki mushkil ko highlight karta hai."}, {"id": "ch7_q40", "termRef": "insider", "type": "scenario", "difficulty": "hard", "question": "A disgruntled employee deliberately deletes critical company files right before resigning. Which type of insider threat does this represent?", "options": ["Malicious insider threat", "Negligent insider threat", "Not an insider threat at all", "Compromised insider threat"], "correctIndex": 0, "explanation": "Malicious: deliberately data steal ya damage kare (disgruntled employee) \u2014 exactly is scenario ko match karta hai."}, {"id": "ch7_q41", "termRef": "kiddie", "type": "definition", "difficulty": "easy", "question": "What is a Script Kiddie?", "options": ["A software developer who builds security tools", "A highly skilled nation-state hacker", "An unskilled individual who uses publicly available hacking tools without understanding how they work", "A cybersecurity professional working in a SOC"], "correctIndex": 2, "explanation": "Unskilled individuals jo publicly available tools/scripts use karte hain attacks ke liye bina understanding ke \u2014 'point and click' hacking."}, {"id": "ch7_q42", "termRef": "kiddie", "type": "category", "difficulty": "medium", "question": "Why are script kiddies still considered a real threat, despite their lack of skill?", "options": ["They always target only large corporations", "Their sheer numbers can add up to a significant collective impact, like a large DDoS", "They are immune to law enforcement action", "They always have nation-state level funding"], "correctIndex": 1, "explanation": "Volume mein dangerous \u2014 hazaron script kiddies = significant DDoS. Basic vulnerabilities exploit kar lete hain."}, {"id": "ch7_q43", "termRef": "kiddie", "type": "category", "difficulty": "medium", "question": "What does the prevalence of script kiddies successfully exploiting basic vulnerabilities reveal about an organization?", "options": ["The importance of keeping systems patched", "That their SIEM is broken", "That their firewall is definitely misconfigured", "That they must be a target of nation-state espionage"], "correctIndex": 0, "explanation": "Patched systems ka importance inhi se pata chalta hai \u2014 agar basic vulnerabilities patched na hon, script kiddies bhi exploit kar sakte hain."}, {"id": "ch7_q44", "termRef": "kiddie", "type": "scenario", "difficulty": "hard", "question": "A teenager downloads a free hacking tool from a forum and, without understanding how it works internally, manages to deface a poorly-secured small business website. What category of threat actor does this represent?", "options": ["Nation-State actor", "APT group", "Script Kiddie", "Insider Threat"], "correctIndex": 2, "explanation": "'Point and click' hacking bina samjhe \u2014 exactly script kiddie ki definition hai, unlike sophisticated APT groups."}, {"id": "ch7_q45", "termRef": "kiddie", "type": "category", "difficulty": "medium", "question": "How do experienced hackers generally view script kiddies, according to the guide?", "options": ["As the most dangerous threat actor category overall", "As completely harmless with zero impact", "As equivalent to nation-state actors in skill", "Not seriously in terms of skill, but their volume is still a legitimate threat"], "correctIndex": 3, "explanation": "Real hackers inhe seriously nahi lete, par inka sheer volume ek threat hai \u2014 dono baaten guide mein explicitly likhi hain."}, {"id": "ch7_q46", "termRef": "cyberphys", "type": "definition", "difficulty": "easy", "question": "What are Cyber-Physical Systems?", "options": ["Only refers to social media platforms", "Systems where digital and physical worlds meet, like industrial control systems and SCADA", "Purely software applications with no hardware component", "Only refers to smartphones and tablets"], "correctIndex": 1, "explanation": "Systems jahan digital aur physical world meet karte hain \u2014 industrial control systems (ICS), SCADA, power plants, water treatment, hospital equipment."}, {"id": "ch7_q47", "termRef": "cyberphys", "type": "category", "difficulty": "medium", "question": "Why does the guide describe attacks on cyber-physical systems as 'life-and-death scenarios'?", "options": ["They cannot be executed remotely at all", "A hack can cause real physical harm, like poisoning water or disabling hospital equipment", "They only affect video game servers", "They only ever result in minor data theft"], "correctIndex": 1, "explanation": "Power grid hack \u2192 lights off city mein. Water treatment hack \u2192 poison in water. Hospital device hack \u2192 patient harm \u2014 not just data theft."}, {"id": "ch7_q48", "termRef": "cyberphys", "type": "category", "difficulty": "medium", "question": "Which term refers to the industrial/physical-facing technology (as opposed to standard IT) that has become critical to secure?", "options": ["SSO (Single Sign-On)", "OT (Operational Technology)", "DLP (Data Loss Prevention)", "CASB (Cloud Access Security Broker)"], "correctIndex": 1, "explanation": "OT (Operational Technology) security critical ho gayi hai \u2014 smart cities, connected infrastructure, Industry 4.0 ki wajah se attack surface badh gaya hai."}, {"id": "ch7_q49", "termRef": "cyberphys", "type": "scenario", "difficulty": "hard", "question": "An attacker gains digital access to a hospital's connected medical equipment and remotely alters its settings, directly endangering patients. What category of attack does this fall under?", "options": ["Cyber-Physical attack", "Adware infection", "A simple phishing campaign", "Credential stuffing"], "correctIndex": 0, "explanation": "Digital command jiske physical, real-world consequences hain \u2014 exactly cyber-physical systems attack ki definition hai."}, {"id": "ch7_q50", "termRef": "cyberphys", "type": "category", "difficulty": "medium", "question": "Why is 'more connectivity' identified as a growing risk factor for cyber-physical systems?", "options": ["More connected infrastructure means a larger attack surface for attackers to exploit", "More connectivity always makes systems automatically more secure", "Connectivity only matters for social media platforms", "Connectivity has no relationship to security risk at all"], "correctIndex": 0, "explanation": "Smart cities, connected infrastructure, Industry 4.0 \u2014 jitna zyada connectivity, utna zyada attack surface."}]}, {"chapter": 8, "chapterTitle": "Governance & Compliance", "termCount": 10, "questionCount": 50, "questions": [{"id": "ch8_q01", "termRef": "risk", "type": "definition", "difficulty": "easy", "question": "How does the guide define Risk in cybersecurity terms?", "options": ["Risk = Threat \u00d7 Vulnerability \u00d7 Impact", "Risk = Only the size of the company", "Risk = Only the cost of a firewall", "Risk = Only the number of employees"], "correctIndex": 0, "explanation": "Risk = Threat \u00d7 Vulnerability \u00d7 Impact \u2014 identify karo kya risks hain, kitni probability hai, agar hua to kitna damage."}, {"id": "ch8_q02", "termRef": "risk", "type": "category", "difficulty": "medium", "question": "Which of these is NOT one of the four ways to treat a risk, according to the guide?", "options": ["Mitigate", "Ignore", "Transfer (insurance)", "Accept"], "correctIndex": 1, "explanation": "Decide karo accept karo, mitigate karo, transfer karo (insurance) ya avoid karo \u2014 'Ignore' formal risk treatment option nahi hai."}, {"id": "ch8_q03", "termRef": "risk", "type": "category", "difficulty": "medium", "question": "Why is it practically impossible to eliminate every single risk, according to the guide?", "options": ["It is practically and financially impossible; an acceptable risk level must be defined instead", "Because all risks are always equally severe", "Because risks are randomly generated and unpredictable", "Because insurance companies forbid it"], "correctIndex": 0, "explanation": "Har risk ko eliminate karna practically/financially impossible hai \u2014 business decision hai, acceptable risk level define karna zaroori hai."}, {"id": "ch8_q04", "termRef": "risk", "type": "category", "difficulty": "medium", "question": "What is the correct order of the risk management framework cycle, according to the guide?", "options": ["Repeat \u2192 Treatment \u2192 Monitoring \u2192 Assessment", "Risk Assessment \u2192 Treatment \u2192 Monitoring \u2192 Repeat", "Monitoring \u2192 Repeat \u2192 Assessment \u2192 Treatment", "Treatment \u2192 Assessment \u2192 Repeat \u2192 Monitoring"], "correctIndex": 1, "explanation": "Risk Assessment \u2192 Treatment \u2192 Monitoring \u2192 Repeat \u2014 yeh cyclical framework guide mein specifically diya gaya hai."}, {"id": "ch8_q05", "termRef": "risk", "type": "scenario", "difficulty": "hard", "question": "A company decides to purchase cyber insurance instead of spending heavily to fully prevent a low-probability, high-cost risk. Which risk treatment strategy is this?", "options": ["Mitigate", "Avoid", "Accept", "Transfer"], "correctIndex": 3, "explanation": "Transfer karo (insurance) \u2014 yeh risk ko kisi third party ko transfer karna hai, exactly jaise cyber insurance karti hai."}, {"id": "ch8_q06", "termRef": "compliance", "type": "definition", "difficulty": "easy", "question": "What does compliance mean in cybersecurity?", "options": ["Personally choosing your own preferred security tools", "A synonym for encryption", "Following laws and standards as a legal obligation", "Only applies to government agencies, never businesses"], "correctIndex": 2, "explanation": "Laws aur standards follow karna \u2014 legal obligation, jaise GDPR, PCI-DSS, HIPAA, ISO 27001, SOC 2."}, {"id": "ch8_q07", "termRef": "compliance", "type": "category", "difficulty": "medium", "question": "Which compliance standard specifically protects credit card data?", "options": ["PCI-DSS", "ISO 27001", "HIPAA", "GDPR"], "correctIndex": 0, "explanation": "PCI-DSS: Credit card data. GDPR: EU data privacy. HIPAA: US healthcare data \u2014 sab alag domains cover karte hain."}, {"id": "ch8_q08", "termRef": "compliance", "type": "category", "difficulty": "hard", "question": "What critical distinction does the guide make between compliance and real security?", "options": ["Compliance is always identical to real security, with no difference at all", "Compliance means a company can never be breached", "Compliance is more important than actual security in every scenario", "Compliance is only a minimum bar; a compliant system can still be insecure"], "correctIndex": 3, "explanation": "Critical distinction! Compliant system can still be insecure. Compliance is minimum bar. Many breached companies were 'compliant.'"}, {"id": "ch8_q09", "termRef": "compliance", "type": "category", "difficulty": "medium", "question": "How severe can GDPR fines be, according to the guide?", "options": ["A flat $100 fee regardless of company size", "There are no financial penalties under GDPR", "Fines apply only to companies based in the EU, never elsewhere", "Up to 4% of global revenue"], "correctIndex": 3, "explanation": "GDPR: EU data privacy (fines up to 4% revenue) \u2014 yeh ek significant financial risk hai non-compliant companies ke liye."}, {"id": "ch8_q10", "termRef": "compliance", "type": "scenario", "difficulty": "hard", "question": "A company passes all its official PCI-DSS compliance audits, yet still suffers a major data breach shortly afterward due to a security gap the audit didn't cover. What does this illustrate?", "options": ["Compliance and security are always exactly the same thing", "Compliance is a minimum bar, not a guarantee of actual security", "The breach must have been the auditor's direct fault legally", "PCI-DSS audits are always 100% accurate and thorough"], "correctIndex": 1, "explanation": "Guide explicitly warns \u2014 many breached companies were 'compliant.' Compliance \u2260 Security, yeh critical distinction hai."}, {"id": "ch8_q11", "termRef": "insurance", "type": "definition", "difficulty": "easy", "question": "What does cyber insurance typically cover?", "options": ["Free antivirus software for all employees", "Physical damage to office furniture", "Ransomware payments, breach notification costs, legal fees, and business interruption", "Employee salary increases"], "correctIndex": 2, "explanation": "Ransomware payment, data breach notification costs, legal fees, business interruption, regulatory fines, PR/crisis management."}, {"id": "ch8_q12", "termRef": "insurance", "type": "category", "difficulty": "medium", "question": "What do insurers increasingly require before issuing a cyber insurance policy, according to the guide?", "options": ["A public disclosure of the company's source code", "MFA, EDR, and backups being mandatory in place", "A guarantee of zero prior security incidents ever", "A minimum of 100 employees"], "correctIndex": 1, "explanation": "Insurers ab MFA, EDR, backups mandatory require karte hain policy ke liye \u2014 poor security = no insurance ya very high premium."}, {"id": "ch8_q13", "termRef": "insurance", "type": "category", "difficulty": "medium", "question": "Why has cyber insurance premium been increasing significantly, according to the guide?", "options": ["Due to the surge in ransomware attacks", "Because MFA has become obsolete", "Because compliance requirements have been removed", "Due to fewer companies buying policies"], "correctIndex": 0, "explanation": "Premium increasingly expensive \u2014 ransomware surge se, insurers ko zyada claims handle karne padte hain."}, {"id": "ch8_q14", "termRef": "insurance", "type": "scenario", "difficulty": "hard", "question": "A company applies for cyber insurance but is denied coverage because it doesn't use MFA or maintain regular backups. What does this reflect about the insurance industry today?", "options": ["Insurers no longer offer any cyber insurance products at all", "MFA and backups have no relevance to insurance decisions", "Insurers now require baseline security practices before offering coverage", "This company will automatically be exempt from all cyberattacks"], "correctIndex": 2, "explanation": "Poor security = no insurance ya very high premium \u2014 insurers ne apni requirements tighten kar di hain ransomware surge ki wajah se."}, {"id": "ch8_q15", "termRef": "insurance", "type": "category", "difficulty": "medium", "question": "Besides ransomware payments, what other cost category does cyber insurance help cover, according to the guide?", "options": ["Employee holiday bonuses", "PR and crisis management costs", "Office rent payments", "Marketing campaign costs"], "correctIndex": 1, "explanation": "Ransomware payment, data breach notification costs, legal fees, business interruption, regulatory fines, PR/crisis management \u2014 sab cover hota hai."}, {"id": "ch8_q16", "termRef": "vuln", "type": "definition", "difficulty": "easy", "question": "How does the guide define a 'Vulnerability' in cybersecurity terminology?", "options": ["An actual code or method used to exploit a weakness", "A weakness, such as unpatched software or a misconfiguration", "A public database listing known attackers", "The potential for harm from an attacker wanting to cause damage"], "correctIndex": 1, "explanation": "Vulnerability: weakness (unpatched software, misconfiguration). Threat: potential for harm. Exploit: actual code/method to use the vulnerability."}, {"id": "ch8_q17", "termRef": "vuln", "type": "category", "difficulty": "medium", "question": "What does CVE stand for?", "options": ["Common Vulnerabilities & Exposures", "Cyber Vulnerability Engine", "Certified Vulnerability Evaluation", "Central Vendor Exchange"], "correctIndex": 0, "explanation": "CVE: Common Vulnerabilities & Exposures \u2014 public database jahan known vulnerabilities track ki jaati hain."}, {"id": "ch8_q18", "termRef": "vuln", "type": "real_world", "difficulty": "hard", "question": "What was the CVSS score of CVE-2021-44228 (Log4Shell), the vulnerability described as literally maximum severity?", "options": ["8/10", "7/10", "9/10", "10/10"], "correctIndex": 3, "explanation": "CVE-2021-44228 (Log4Shell) = 10/10 \u2014 literally maximum severity, yeh guide mein specifically iska example diya gaya hai."}, {"id": "ch8_q19", "termRef": "vuln", "type": "category", "difficulty": "medium", "question": "What CVSS score range does the guide say counts as 'Critical'?", "options": ["0.0 exactly", "1.0 to 3.0", "9.0 and above", "5.0 to 6.0"], "correctIndex": 2, "explanation": "0-10 severity rating. 9.0+ = Critical \u2014 patching priority = CVSS score, higher score means more urgent."}, {"id": "ch8_q20", "termRef": "vuln", "type": "scenario", "difficulty": "hard", "question": "A security researcher discovers a weakness in a company's software but has no code yet to actually take advantage of it. In the guide's terminology, what has been found so far?", "options": ["A vulnerability, but not yet an exploit", "An exploit, but not yet a vulnerability", "A CVE score of exactly zero", "A threat actor"], "correctIndex": 0, "explanation": "Vulnerability = weakness itself. Exploit = actual code/method to use the vulnerability \u2014 dono alag concepts hain."}, {"id": "ch8_q21", "termRef": "pentest", "type": "definition", "difficulty": "easy", "question": "What is Penetration Testing?", "options": ["Company-authorized security professionals attacking systems to find weaknesses before real attackers do", "A method for training employees on phishing awareness only", "A tool for encrypting sensitive files", "An unauthorized attack carried out by criminals"], "correctIndex": 0, "explanation": "Company authorize karta hai security professionals ko attack karne ke liye \u2014 vulnerabilities find karo before real attackers do."}, {"id": "ch8_q22", "termRef": "pentest", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use for penetration testing?", "options": ["A bank legally telling a security expert to 'try to rob us' and fixing the gaps found", "A postman opening and reading letters", "A movie ticket used once for entry", "A smoke detector alerting to danger"], "correctIndex": 0, "explanation": "Bank apne security expert ko bolti hai 'try to rob us' \u2014 legally. Expert koshish karta hai, gaps dhundhta hai, fix hote hain before real robber try kare."}, {"id": "ch8_q23", "termRef": "pentest", "type": "category", "difficulty": "medium", "question": "Which penetration testing type gives the tester no prior information about the target, making it more realistic?", "options": ["Black Box", "Grey Box", "White Box", "Red Team only"], "correctIndex": 0, "explanation": "Black Box: No prior info (realistic). White Box: full access/info given. Grey Box: partial info."}, {"id": "ch8_q24", "termRef": "pentest", "type": "category", "difficulty": "medium", "question": "What term describes penetration testers who are authorized to legally test a system's security?", "options": ["Script kiddies", "Threat actors", "White hat hackers", "Cybercriminals"], "correctIndex": 2, "explanation": "Ethical hackers = white hat hackers \u2014 legally authorized to find vulnerabilities before criminals do."}, {"id": "ch8_q25", "termRef": "pentest", "type": "scenario", "difficulty": "hard", "question": "A company hires a firm and gives them full internal documentation, source code, and architecture diagrams to test the system as thoroughly as possible. Which type of penetration test is this?", "options": ["Script Kiddie testing", "White Box", "Black Box", "Grey Box"], "correctIndex": 1, "explanation": "White Box: Full access/info given \u2014 jitna zyada info tester ke paas hai, utna thorough test possible hai."}, {"id": "ch8_q26", "termRef": "resilience", "type": "definition", "difficulty": "easy", "question": "What is Cyber Resilience, as distinct from prevention?", "options": ["A type of firewall configuration", "The ability to survive an attack and recover quickly, assuming a breach will happen", "A tool for encrypting network traffic", "Only about preventing every attack from ever happening"], "correctIndex": 1, "explanation": "Prevention = attack hone mat do. Resilience = attack hone ke baad bhi business continue karo, jaldi recover karo \u2014 'assume breach' philosophy."}, {"id": "ch8_q27", "termRef": "resilience", "type": "category", "difficulty": "medium", "question": "Which of these is listed as a component of cyber resilience, according to the guide?", "options": ["Free coffee for employees", "A social media marketing plan", "A larger office building", "An Incident Response plan"], "correctIndex": 3, "explanation": "Components: Incident Response plan, backups, disaster recovery, business continuity plan, crisis communication, lessons learned."}, {"id": "ch8_q28", "termRef": "resilience", "type": "category", "difficulty": "medium", "question": "What does RTO (Recovery Time Objective) define?", "options": ["The length of a penetration test", "The number of employees affected by an attack", "The target time within which systems should be restored after an incident", "The total cost of a data breach"], "correctIndex": 2, "explanation": "RTO (Recovery Time Objective) aur RPO define karo \u2014 RTO specifically restore hone ke liye target time define karta hai."}, {"id": "ch8_q29", "termRef": "resilience", "type": "category", "difficulty": "hard", "question": "What modern philosophy does the guide say drives cyber resilience thinking?", "options": ["'Assume breach' \u2014 it WILL happen, so be ready", "'Never trust anyone, including your own IT team'", "'Only focus on prevention, never on recovery'", "'Ignore incidents until they escalate publicly'"], "correctIndex": 0, "explanation": "Modern philosophy: 'assume breach' \u2014 it WILL happen, be ready, isliye resilience prevention jitna hi important hai."}, {"id": "ch8_q30", "termRef": "resilience", "type": "scenario", "difficulty": "hard", "question": "After a ransomware attack, a company restores full operations within hours because it had a tested incident response plan, offline backups, and a clear business continuity strategy. What does this demonstrate?", "options": ["Strong cyber resilience", "Zero Trust security", "A CASB deployment", "A successful penetration test"], "correctIndex": 0, "explanation": "Attack hone ke baad bhi business jaldi continue karna \u2014 exactly cyber resilience ka goal hai, prevention se alag."}, {"id": "ch8_q31", "termRef": "cti", "type": "definition", "difficulty": "easy", "question": "What does CTI (Cyber Threat Intelligence) provide?", "options": ["A physical security camera system", "Actionable, collected information about threat actors and their tactics, for proactive defense", "A backup solution for critical files", "A tool for encrypting company emails"], "correctIndex": 1, "explanation": "Threat actors, their tactics, techniques, procedures (TTPs), indicators of compromise (IoCs) ke baare mein collected aur analyzed information."}, {"id": "ch8_q32", "termRef": "cti", "type": "category", "difficulty": "medium", "question": "Which type of CTI is aimed at board-level, strategic risk decisions?", "options": ["Operational CTI", "Technical CTI", "Strategic CTI", "Tactical CTI"], "correctIndex": 2, "explanation": "Strategic (board level \u2014 risk decisions), Operational (active campaigns), Tactical (specific TTPs), Technical (IPs, hashes, domains)."}, {"id": "ch8_q33", "termRef": "cti", "type": "category", "difficulty": "medium", "question": "Which type of CTI deals with specific technical indicators like IPs, hashes, and domains?", "options": ["Operational CTI", "Tactical CTI", "Technical CTI", "Strategic CTI"], "correctIndex": 2, "explanation": "Technical (SOC \u2014 IPs, hashes, domains) \u2014 yeh sabse granular level hai, SOC analysts ke liye directly usable."}, {"id": "ch8_q34", "termRef": "cti", "type": "category", "difficulty": "hard", "question": "What does TTP stand for in the context of Cyber Threat Intelligence?", "options": ["Transport Traffic Protocol", "Total Threat Prevention", "Trusted Third Party", "Tactics, Techniques, Procedures"], "correctIndex": 3, "explanation": "TTPs (tactics, techniques, procedures) \u2014 threat actors ke behavior patterns document karne ka standard tareeka."}, {"id": "ch8_q35", "termRef": "cti", "type": "scenario", "difficulty": "hard", "question": "A security team receives a report listing specific malicious IP addresses and file hashes seen in a recent campaign, which they immediately load into their SIEM to block. What level of CTI did they use?", "options": ["None of these, this is just antivirus data", "Technical CTI", "Only Tactical CTI", "Strategic CTI"], "correctIndex": 1, "explanation": "IPs, hashes, domains \u2014 yeh Technical CTI ka scope hai, directly SOC tools mein usable hota hai."}, {"id": "ch8_q36", "termRef": "cybercrime", "type": "definition", "difficulty": "easy", "question": "What is Cyber Crime?", "options": ["Only refers to physical theft of computer hardware", "Illegal activities carried out through computers or the internet", "A synonym for penetration testing", "Only refers to government-sponsored attacks"], "correctIndex": 1, "explanation": "Computer ya internet ke through illegal activities \u2014 financial fraud, identity theft, ransomware, hacking, dark web markets, cyber stalking."}, {"id": "ch8_q37", "termRef": "cybercrime", "type": "category", "difficulty": "hard", "question": "What is the estimated global annual cost of cybercrime in 2023, according to the guide?", "options": ["$8 trillion or more", "$8 billion", "$800 million", "$8 million"], "correctIndex": 0, "explanation": "$8 trillion+ global annual cost (2023) \u2014 yeh cybercrime ki scale ko dikhata hai global economy pe."}, {"id": "ch8_q38", "termRef": "cybercrime", "type": "category", "difficulty": "medium", "question": "Which Indian law covers cyber crimes, according to the guide?", "options": ["The Indian Penal Code alone, without any IT-specific law", "The Companies Act 2013", "The Consumer Protection Act", "The IT Act 2000 (amended 2008)"], "correctIndex": 3, "explanation": "IT Act 2000 (amended 2008) covers cyber crimes in India \u2014 cyber cells in major cities handle enforcement."}, {"id": "ch8_q39", "termRef": "cybercrime", "type": "category", "difficulty": "medium", "question": "Where does the guide say cyber crime incidents can be reported in India?", "options": ["A local police station only, no online option exists", "Only a private law firm", "cybercrime.gov.in", "Only the RBI website"], "correctIndex": 2, "explanation": "Incidents report karo: cybercrime.gov.in \u2014 India mein official reporting portal jo guide mein mention kiya gaya hai."}, {"id": "ch8_q40", "termRef": "cybercrime", "type": "category", "difficulty": "medium", "question": "According to the guide, which IT Act section deals with unauthorized access?", "options": ["Section 43", "Section 100", "Section 66", "Section 67"], "correctIndex": 2, "explanation": "Section 66 = unauthorized access, Section 67 = obscene content \u2014 yeh specific sections guide mein cite kiye gaye hain."}, {"id": "ch8_q41", "termRef": "bully", "type": "definition", "difficulty": "easy", "question": "What is Cyber Bullying?", "options": ["Online harassment, threatening, or humiliation carried out via digital platforms", "A defensive tool that blocks unwanted network traffic", "A type of encryption used in social media apps", "A type of penetration test done for training purposes"], "correctIndex": 0, "explanation": "Digital platforms pe harassment, threatening, humiliation \u2014 social media, gaming, messaging apps ke through hoti hai."}, {"id": "ch8_q42", "termRef": "bully", "type": "category", "difficulty": "medium", "question": "What is 'doxxing', as mentioned in the guide's discussion of cyber bullying?", "options": ["Sending an encrypted message to a friend", "A method for securely backing up data", "Publishing someone's private information publicly without consent", "A type of penetration testing technique"], "correctIndex": 2, "explanation": "Doxxing (private info public karna), revenge porn, trolling, fake profiles \u2014 sab cyber bullying ke forms hain."}, {"id": "ch8_q43", "termRef": "bully", "type": "category", "difficulty": "medium", "question": "What does the guide recommend as a first step if you experience cyber bullying?", "options": ["Ignore it completely and never report it", "Immediately delete all your social media accounts permanently", "Confront the bully in person alone", "Take screenshots as evidence"], "correctIndex": 3, "explanation": "Screenshots rakho evidence ke liye, platform report karo, cyber cell complaint karo \u2014 yeh recommended steps hain."}, {"id": "ch8_q44", "termRef": "bully", "type": "category", "difficulty": "medium", "question": "What kind of consequences does the guide highlight as resulting from cyber bullying?", "options": ["Serious mental health consequences", "Purely financial losses only", "Only minor inconvenience with no lasting impact", "Only affects the bully, not the victim"], "correctIndex": 0, "explanation": "Serious mental health consequences \u2014 guide is impact ko explicitly highlight karti hai, halka mudda nahi hai."}, {"id": "ch8_q45", "termRef": "bully", "type": "scenario", "difficulty": "hard", "question": "Someone's private address and phone number are posted publicly online without their consent, as part of an ongoing harassment campaign. What specific tactic does this represent?", "options": ["Cyber espionage", "Supply chain attack", "Credential stuffing", "Doxxing"], "correctIndex": 3, "explanation": "Private info public karna bina consent ke \u2014 exactly doxxing ki definition hai, cyber bullying ka ek severe form."}, {"id": "ch8_q46", "termRef": "forensics", "type": "definition", "difficulty": "easy", "question": "What is Digital Forensics?", "options": ["A method for training employees on phishing awareness", "Collecting, preserving, and analyzing digital evidence after an incident, for possible use in court", "A type of penetration testing", "A tool for automatically blocking malware in real time"], "correctIndex": 1, "explanation": "Incident ke baad digital evidence collect, preserve, analyze, aur present karna \u2014 court mein use hone ke liye \u2014 disk images, memory dumps, network logs sab include."}, {"id": "ch8_q47", "termRef": "forensics", "type": "category", "difficulty": "medium", "question": "What is a 'write blocker' used for in digital forensics?", "options": ["Encrypting a hard drive automatically", "Preventing employees from writing emails", "Preventing any accidental modification to the original evidence during analysis", "Blocking all outgoing network traffic permanently"], "correctIndex": 2, "explanation": "Write blockers use karo, hashes verify karo, chain of custody maintain karo \u2014 evidence ka original tamper nahi hona chahiye."}, {"id": "ch8_q48", "termRef": "forensics", "type": "category", "difficulty": "medium", "question": "What happens to tampered digital evidence in a court proceeding, according to the guide?", "options": ["It is automatically considered stronger proof", "It is used exactly the same as untampered evidence", "It becomes inadmissible in court", "It is destroyed by the court immediately"], "correctIndex": 2, "explanation": "Tampered evidence court mein inadmissible hai \u2014 isliye evidence integrity maintain karna critical hai."}, {"id": "ch8_q49", "termRef": "forensics", "type": "category", "difficulty": "medium", "question": "Besides disk images, what other type of digital evidence does the guide mention forensic investigators collect?", "options": ["Memory dumps and network logs", "Only handwritten notes from employees", "Only social media likes and shares", "Only physical photographs of the server room"], "correctIndex": 0, "explanation": "Disk images, memory dumps, network logs, deleted file recovery \u2014 sab forensic evidence collection ke part hain."}, {"id": "ch8_q50", "termRef": "forensics", "type": "scenario", "difficulty": "hard", "question": "An investigator makes a forensic copy of a compromised server's hard drive and works only on that copy, never touching the original, while documenting every handling step. What core principle is being followed?", "options": ["Maintaining evidence integrity through chain of custody", "Zero Trust security", "Risk transfer via insurance", "Penetration testing methodology"], "correctIndex": 0, "explanation": "Original kabhi touch nahi \u2014 sirf forensic copy pe kaam karo, evidence integrity aur chain of custody maintain karna key principle hai."}]}, {"chapter": 9, "chapterTitle": "Operations & Response", "termCount": 10, "questionCount": 50, "questions": [{"id": "ch9_q01", "termRef": "ir", "type": "definition", "difficulty": "easy", "question": "What is Incident Response?", "options": ["A structured process for handling a security incident from detection through recovery", "A method for preventing all attacks permanently", "A type of firewall configuration", "A tool for encrypting files automatically"], "correctIndex": 0, "explanation": "Security incident handle karna \u2014 structured process, NIST phases follow karta hai."}, {"id": "ch9_q02", "termRef": "ir", "type": "category", "difficulty": "medium", "question": "Which of these is the correct order of the NIST Incident Response phases, according to the guide?", "options": ["Lessons Learned \u2192 Preparation \u2192 Detection \u2192 Recovery \u2192 Containment \u2192 Eradication", "Containment \u2192 Eradication \u2192 Preparation \u2192 Recovery \u2192 Detection \u2192 Lessons Learned", "Preparation \u2192 Detection & Analysis \u2192 Containment \u2192 Eradication \u2192 Recovery \u2192 Lessons Learned", "Recovery \u2192 Preparation \u2192 Containment \u2192 Detection \u2192 Eradication \u2192 Lessons Learned"], "correctIndex": 2, "explanation": "1. Preparation, 2. Detection & Analysis, 3. Containment, 4. Eradication, 5. Recovery, 6. Lessons Learned \u2014 yeh NIST ka standard order hai."}, {"id": "ch9_q03", "termRef": "ir", "type": "category", "difficulty": "medium", "question": "What does CSIRT stand for?", "options": ["Computer Security Incident Response Team", "Critical Software Integration Response Team", "Central Security Information Report Tool", "Cyber Systems Internal Risk Tracker"], "correctIndex": 0, "explanation": "IR Team = CSIRT (Computer Security Incident Response Team) \u2014 SOC analysts detect karte hain, IR team respond karta hai."}, {"id": "ch9_q04", "termRef": "ir", "type": "category", "difficulty": "medium", "question": "What are pre-defined, documented sets of IR steps for common scenarios called?", "options": ["Honeypots", "Sandboxes", "Playbooks", "Firewalls"], "correctIndex": 2, "explanation": "Playbooks pre-defined hote hain \u2014 jab specific incident type hota hai, team pehle se defined steps follow karti hai."}, {"id": "ch9_q05", "termRef": "ir", "type": "scenario", "difficulty": "hard", "question": "After containing a ransomware attack and restoring systems, a security team holds a formal meeting to document what went wrong and how to prevent it next time. Which IR phase does this represent?", "options": ["Preparation", "Lessons Learned", "Containment", "Detection & Analysis"], "correctIndex": 1, "explanation": "Lessons Learned: Post-mortem \u2014 yeh final phase hai jahan incident se seekh kar future preparation improve ki jaati hai."}, {"id": "ch9_q06", "termRef": "soc", "type": "definition", "difficulty": "easy", "question": "What is a SOC (Security Operations Center)?", "options": ["A tool for encrypting files at rest", "A physical lock on the server room door", "A dedicated team and facility that monitors an organization's security 24/7/365", "A type of firewall hardware"], "correctIndex": 2, "explanation": "Dedicated team aur facility jo 24/7/365 organization ki security monitor karti hai \u2014 SIEM se alerts aate hain, analysts investigate karte hain."}, {"id": "ch9_q07", "termRef": "soc", "type": "category", "difficulty": "medium", "question": "Which SOC tier is responsible for advanced threat hunting and deep analysis?", "options": ["There is only one tier", "Tier 3", "Tier 2", "Tier 1"], "correctIndex": 1, "explanation": "Tier 1: alert triage. Tier 2: investigation. Tier 3: threat hunting, advanced analysis \u2014 hierarchy of increasing expertise."}, {"id": "ch9_q08", "termRef": "soc", "type": "category", "difficulty": "medium", "question": "According to the guide, what is the most common entry-level career point in cybersecurity?", "options": ["Penetration Tester", "Chief Information Security Officer", "Digital Forensics Lead", "SOC Analyst"], "correctIndex": 3, "explanation": "SOC Analyst \u2014 cybersecurity mein most common entry point. Well paid career path bhi hai."}, {"id": "ch9_q09", "termRef": "soc", "type": "category", "difficulty": "medium", "question": "Which SOC tier handles initial alert triage?", "options": ["Tier 3", "None, alerts go directly to management", "Tier 1", "Tier 2"], "correctIndex": 2, "explanation": "Tier 1: alert triage \u2014 pehla level jo initial alerts ko sort aur prioritize karta hai."}, {"id": "ch9_q10", "termRef": "soc", "type": "scenario", "difficulty": "hard", "question": "An analyst quickly reviews an incoming SIEM alert to decide whether it needs deeper investigation or can be dismissed as a false positive. Which SOC tier is most likely performing this task?", "options": ["External auditors", "Only management", "Tier 1", "Tier 3"], "correctIndex": 2, "explanation": "Tier 1 ka kaam hi alert triage hai \u2014 quickly assess karna ki alert genuine hai ya false positive."}, {"id": "ch9_q11", "termRef": "hygiene", "type": "definition", "difficulty": "easy", "question": "What is Cyber Hygiene?", "options": ["A type of encryption algorithm", "A legal compliance framework", "Regular security practices that significantly reduce risk, like physical hygiene habits", "A tool for detecting network intrusions automatically"], "correctIndex": 2, "explanation": "Regular security practices jo risk significantly reduce karte hain \u2014 just like physical hygiene, consistent daily habits."}, {"id": "ch9_q12", "termRef": "hygiene", "type": "category", "difficulty": "medium", "question": "What percentage of attacks could be prevented by patching and basic hygiene, according to the guide?", "options": ["80%", "50%", "20%", "10%"], "correctIndex": 0, "explanation": "80% of attacks patching aur basic hygiene se prevent ho sakte the \u2014 yeh statistic guide mein specifically diya gaya hai."}, {"id": "ch9_q13", "termRef": "hygiene", "type": "category", "difficulty": "medium", "question": "Which of these is listed as a cyber hygiene essential in the guide?", "options": ["Ignoring software updates", "Reusing the same password across sites", "Disabling all backups", "MFA everywhere"], "correctIndex": 3, "explanation": "Strong unique passwords + manager, MFA everywhere, software updates promptly, regular backups, phishing awareness, least privilege, encrypt sensitive data."}, {"id": "ch9_q14", "termRef": "hygiene", "type": "scenario", "difficulty": "hard", "question": "An organization avoids most common attacks simply by consistently applying updates, using unique passwords, and enabling MFA across all accounts \u2014 no advanced tools involved. What does this illustrate?", "options": ["The need for penetration testing alone", "The power of basic cyber hygiene", "The requirement for cyber insurance", "The necessity of an expensive SOC"], "correctIndex": 1, "explanation": "80% of attacks basic hygiene se prevent ho sakte the \u2014 yeh exactly demonstrate karta hai ki fundamentals kitne powerful hain."}, {"id": "ch9_q15", "termRef": "hygiene", "type": "category", "difficulty": "medium", "question": "Which principle from IAM is also listed as part of good cyber hygiene?", "options": ["Shared admin passwords", "No authentication required", "Least privilege", "Maximum privilege for all"], "correctIndex": 2, "explanation": "Least privilege bhi cyber hygiene essentials mein listed hai \u2014 yeh dikhata hai ki concepts ek dusre se linked hote hain."}, {"id": "ch9_q16", "termRef": "coc", "type": "definition", "difficulty": "easy", "question": "What does Chain of Custody document?", "options": ["The list of all firewall rules in place", "The company's annual revenue and profits", "Where evidence is, who handled it, when, and how", "The number of employees in the SOC"], "correctIndex": 2, "explanation": "Documentation jo track karta hai evidence kahan hai, kisne handle kiya, kab, aur kaise."}, {"id": "ch9_q17", "termRef": "coc", "type": "category", "difficulty": "medium", "question": "What happens to evidence in a criminal case if the chain of custody is broken?", "options": ["The evidence automatically becomes stronger proof", "The evidence can become inadmissible in court", "Nothing changes; it remains fully valid regardless", "The case is immediately dismissed with no other consequence"], "correctIndex": 1, "explanation": "Criminal cases mein agar chain break ho to evidence inadmissible ho sakta hai court mein \u2014 legal validity directly is process pe depend karti hai."}, {"id": "ch9_q18", "termRef": "coc", "type": "category", "difficulty": "medium", "question": "In digital forensics, what should investigators avoid touching directly, working only on a copy instead?", "options": ["The original evidence/disk", "The forensic report template", "The incident response playbook", "The SIEM dashboard"], "correctIndex": 0, "explanation": "Original kabhi touch nahi \u2014 sirf forensic copy pe kaam karo, chain of custody maintain karne ke liye zaroori hai."}, {"id": "ch9_q19", "termRef": "coc", "type": "scenario", "difficulty": "hard", "question": "A disk image is taken from a compromised server, its hash is verified, it's placed in sealed storage, and every transport step is logged in detail. What process is being followed here?", "options": ["Risk transfer via insurance", "Penetration testing methodology", "Chain of Custody documentation", "Cyber hygiene practices"], "correctIndex": 2, "explanation": "Disk image lena \u2192 hash verify \u2192 sealed storage \u2192 transport log \u2192 analysis \u2014 har step documented, exactly chain of custody process hai."}, {"id": "ch9_q20", "termRef": "coc", "type": "category", "difficulty": "medium", "question": "Why is documenting who handled evidence and when considered critical?", "options": ["It proves the evidence wasn't tampered with, supporting its admissibility in court", "It replaces the need for encryption entirely", "It has no legal relevance at all", "It only matters for internal HR purposes"], "correctIndex": 0, "explanation": "Documentation evidence ki integrity prove karne ke liye zaroori hai \u2014 court mein admissibility isi par depend karti hai."}, {"id": "ch9_q21", "termRef": "uem", "type": "definition", "difficulty": "easy", "question": "What does UEM (Unified Endpoint Management) allow an organization to do?", "options": ["Only manage employee email accounts", "Only manage physical servers in a data center", "Manage all devices (laptops, phones, tablets) from a single platform", "Only encrypt files on a single device"], "correctIndex": 2, "explanation": "Organization ke saare devices (laptops, phones, tablets) ek platform se manage karna \u2014 policies enforce karo, software deploy karo, remote wipe karo."}, {"id": "ch9_q22", "termRef": "uem", "type": "category", "difficulty": "medium", "question": "Why has UEM become especially important, according to the guide?", "options": ["Because desktop computers are now obsolete", "Because of the BYOD (Bring Your Own Device) era, where employees use personal phones for work email", "Because all companies have banned smartphones entirely", "Because it replaces the need for any password policy"], "correctIndex": 1, "explanation": "BYOD era mein employees apne phones pe corporate email use karte hain \u2014 UEM security policies enforce karta hai without fully controlling personal devices."}, {"id": "ch9_q23", "termRef": "uem", "type": "category", "difficulty": "medium", "question": "What capability does UEM provide if a device is lost or stolen?", "options": ["Nothing can be done at all", "Remote wipe", "Instant device replacement, shipped free", "Automatic physical recovery of the device"], "correctIndex": 1, "explanation": "Remote wipe karo agar device lost ho \u2014 yeh UEM ka ek key security feature hai jo data ko protect karta hai."}, {"id": "ch9_q24", "termRef": "uem", "type": "scenario", "difficulty": "hard", "question": "An employee's personal phone, which also has corporate email set up, gets lost at an airport. The IT team remotely wipes only the corporate data on the device without touching personal photos. What technology enabled this selective control?", "options": ["A firewall", "SSH", "NAT", "UEM (Unified Endpoint Management)"], "correctIndex": 3, "explanation": "UEM policies enforce karta hai without fully controlling personal devices \u2014 exactly BYOD ke liye design kiya gaya feature."}, {"id": "ch9_q25", "termRef": "uem", "type": "category", "difficulty": "medium", "question": "Which of these is a core function of UEM, according to the guide?", "options": ["Enforcing security policies across all managed devices", "Only managing office furniture inventory", "Only tracking employee attendance", "Only handling company payroll"], "correctIndex": 0, "explanation": "Policies enforce karo, software deploy karo, remote wipe karo \u2014 sab UEM ke core functions hain."}, {"id": "ch9_q26", "termRef": "backup", "type": "definition", "difficulty": "easy", "question": "Why is backup called the 'last line of defense against ransomware'?", "options": ["It's a copy of your data that lets you recover without paying the attacker", "It physically blocks all network intrusions", "It encrypts every file permanently", "It automatically detects and removes malware"], "correctIndex": 0, "explanation": "Data ki copy \u2014 last line of defense against ransomware. Agar backup ho, ransom pay karne ki zaroorat nahi padti."}, {"id": "ch9_q27", "termRef": "backup", "type": "category", "difficulty": "medium", "question": "In the 3-2-1 backup rule, what does the '1' represent?", "options": ["1 encryption algorithm used", "1 offsite/offline copy", "1 employee responsible for backups", "1 password for all backups"], "correctIndex": 1, "explanation": "3 copies of data, 2 different storage media types, 1 offsite/offline copy \u2014 offline backup ransomware encrypt nahi kar sakta."}, {"id": "ch9_q28", "termRef": "backup", "type": "category", "difficulty": "medium", "question": "What critical mistake does the guide warn about regarding backup credentials?", "options": ["Storing backups in more than one location", "Using the same account credentials for cloud backup as for the main system", "Testing backups too frequently", "Encrypting the backup data"], "correctIndex": 1, "explanation": "Cloud backup alag account mein \u2014 not same credentials \u2014 agar same ho, ransomware attacker backup bhi encrypt/delete kar sakta hai."}, {"id": "ch9_q29", "termRef": "backup", "type": "category", "difficulty": "medium", "question": "What does the guide say about organizations that have backups but never test restoring them?", "options": ["Testing backups is unnecessary if storage space is limited", "This is the recommended best practice", "Many discover the backup is broken only when an actual disaster strikes", "They are always perfectly safe with no risk at all"], "correctIndex": 2, "explanation": "Backup hai par restore nahi kiya kabhi? Useless. Regular restore tests mandatory \u2014 warna disaster ke waqt pata chalta hai backup kaam nahi kar raha."}, {"id": "ch9_q30", "termRef": "backup", "type": "scenario", "difficulty": "hard", "question": "During a ransomware incident, a company discovers its cloud backup was encrypted too, because the backup used the exact same login credentials as the main compromised system. What mistake caused this?", "options": ["Using an offline backup instead of cloud", "Testing the backup too often", "Following the 3-2-1 rule too strictly", "Not keeping the backup account separate with different credentials"], "correctIndex": 3, "explanation": "Cloud backup alag account mein rakhna chahiye \u2014 not same credentials, warna attacker backup ko bhi compromise kar sakta hai."}, {"id": "ch9_q31", "termRef": "keymgmt", "type": "definition", "difficulty": "easy", "question": "What does Encryption Key Management involve?", "options": ["Only backing up data to the cloud", "Only creating strong passwords for user accounts", "Only encrypting a single file once", "Managing the lifecycle of encryption keys \u2014 generation, distribution, storage, rotation, destruction"], "correctIndex": 3, "explanation": "Encryption keys ka lifecycle manage karna \u2014 generation, distribution, storage, rotation, destruction."}, {"id": "ch9_q32", "termRef": "keymgmt", "type": "category", "difficulty": "medium", "question": "What is the most common mistake in key management, according to the guide?", "options": ["Using AES instead of RSA", "Rotating keys too frequently", "Storing encryption keys in the same location as the data they protect", "Using a Hardware Security Module"], "correctIndex": 2, "explanation": "Keys data ke saath same jagah store nahi karni (sabse common mistake) \u2014 agar attacker data access kare, keys bhi mil jaayengi."}, {"id": "ch9_q33", "termRef": "keymgmt", "type": "category", "difficulty": "medium", "question": "What is an HSM (Hardware Security Module)?", "options": ["A type of software firewall", "Dedicated hardware that physically protects encryption keys", "A cloud-based password manager", "A network monitoring dashboard"], "correctIndex": 1, "explanation": "Hardware Security Module \u2014 dedicated hardware jo keys physically protect karta hai. Banks, governments use karte hain."}, {"id": "ch9_q34", "termRef": "keymgmt", "type": "category", "difficulty": "medium", "question": "Do encryption keys stored in an HSM ever leave the device, according to the guide?", "options": ["Yes, they are exported daily for backup", "Yes, they are emailed to administrators regularly", "Yes, but only once a year", "No, keys never leave the HSM"], "correctIndex": 3, "explanation": "Keys kabhi HSM se bahar nahi jaate \u2014 yeh HSM ka core security guarantee hai."}, {"id": "ch9_q35", "termRef": "keymgmt", "type": "scenario", "difficulty": "hard", "question": "An attacker steals an entire encrypted database along with the encryption key, which was carelessly stored in the same folder. What mistake made the encryption effectively useless?", "options": ["Rotating the key too often", "Using AES instead of RSA", "Using a Hardware Security Module", "Storing the key alongside the data it protects"], "correctIndex": 3, "explanation": "Yeh exactly guide ke mutabik 'sabse common mistake' hai \u2014 keys data ke saath store karna encryption ko pointless bana deta hai."}, {"id": "ch9_q36", "termRef": "cloudsec", "type": "definition", "difficulty": "easy", "question": "What is the 'Shared Responsibility' model in Cloud Security?", "options": ["The cloud provider is responsible for absolutely everything, always", "The cloud provider secures the infrastructure; the customer secures their data, access, and configuration", "The customer is responsible for absolutely everything, always", "Responsibility is randomly assigned each month"], "correctIndex": 1, "explanation": "AWS/Azure/GCP \u2192 cloud infrastructure secure karte hain. Customer \u2192 data, access, application, configuration secure karna customer ki responsibility."}, {"id": "ch9_q37", "termRef": "cloudsec", "type": "real_world", "difficulty": "hard", "question": "The Capital One breach (2019), caused by a misconfigured AWS WAF, exposed how many credit applications and led to what settlement amount?", "options": ["100 million applications, $190 million settlement", "10 million applications, $19 million settlement", "100,000 applications, $1.9 million settlement", "1 billion applications, $1.9 billion settlement"], "correctIndex": 0, "explanation": "Misconfigured AWS WAF se 100 million credit applications exposed. $190M settlement \u2014 ex-Amazon employee ne exploit kiya, misconfiguration, not AWS's fault."}, {"id": "ch9_q38", "termRef": "cloudsec", "type": "category", "difficulty": "medium", "question": "Which of these is listed as a common cloud misconfiguration in the guide?", "options": ["Too much encryption at rest", "Too many MFA prompts", "Overly restrictive firewall rules", "Public S3 buckets"], "correctIndex": 3, "explanation": "Public S3 buckets, weak IAM roles, no encryption at rest, default security groups allowing all traffic, exposed credentials in code repositories."}, {"id": "ch9_q39", "termRef": "cloudsec", "type": "category", "difficulty": "medium", "question": "In the Capital One breach, whose fault was the security failure, according to the guide?", "options": ["The customer's (Capital One's) misconfiguration, not AWS's fault", "No one's fault; it was purely bad luck", "Entirely AWS's fault as the cloud provider", "The end customers whose data was exposed"], "correctIndex": 0, "explanation": "Misconfiguration, not AWS's fault \u2014 yeh exactly shared responsibility model ko illustrate karta hai, customer ki configuration responsibility thi."}, {"id": "ch9_q40", "termRef": "cloudsec", "type": "scenario", "difficulty": "hard", "question": "A company's sensitive database is exposed to the public internet not because of a flaw in AWS itself, but because the company's own security team left default settings unchanged. Whose responsibility does this fall under, per the shared responsibility model?", "options": ["The internet service provider's responsibility", "The customer's responsibility", "The cloud provider's responsibility", "No one's responsibility since it's automated"], "correctIndex": 1, "explanation": "Customer \u2192 data, access, application, configuration secure karna customer ki responsibility hai, exactly jaisa Capital One case mein hua."}, {"id": "ch9_q41", "termRef": "emailsec", "type": "definition", "difficulty": "easy", "question": "Why is email security so critical, according to the guide?", "options": ["Only 1% of attacks involve email", "Email is never used by attackers", "91% of cyberattacks start from a phishing email", "Email is completely immune to all attacks by default"], "correctIndex": 2, "explanation": "91% of cyberattacks start from phishing email \u2014 email sabse exploited vector hai, isliye security critical hai."}, {"id": "ch9_q42", "termRef": "emailsec", "type": "category", "difficulty": "medium", "question": "Which technology publishes a list of servers authorized to send email on behalf of a domain?", "options": ["SPF", "DMARC", "TLS", "DKIM"], "correctIndex": 0, "explanation": "SPF: Authorized mail servers list. DKIM: email digital signature. DMARC: policy for SPF/DKIM failures."}, {"id": "ch9_q43", "termRef": "emailsec", "type": "category", "difficulty": "medium", "question": "Which technology defines what should happen when SPF or DKIM checks fail for an email?", "options": ["DMARC", "DKIM alone", "SPF alone", "TLS alone"], "correctIndex": 0, "explanation": "DMARC: Policy for SPF/DKIM failures \u2014 yeh decide karta hai failed emails ka kya karna hai (reject, quarantine, etc.)."}, {"id": "ch9_q44", "termRef": "emailsec", "type": "category", "difficulty": "medium", "question": "What is the recommended combination for preventing email spoofing on your own domain, according to the guide?", "options": ["SPF + DKIM + DMARC configured together", "Only a firewall on the mail server", "Only a strong company password policy", "Only antivirus on the email server"], "correctIndex": 0, "explanation": "SPF+DKIM+DMARC configure karo apne domain pe \u2014 email spoofing prevent karta hai, tino saath use karna best practice hai."}, {"id": "ch9_q45", "termRef": "emailsec", "type": "scenario", "difficulty": "hard", "question": "A malicious email pretending to be from your own company domain is automatically rejected by the recipient's mail server because it fails an authenticity check based on your domain's published security policy. What technology likely caused this rejection?", "options": ["A WAF", "A honeypot", "NAT", "DMARC"], "correctIndex": 3, "explanation": "DMARC policy define karta hai ki SPF/DKIM fail hone pe email ka kya karna hai \u2014 reject karna is policy ka result hai."}, {"id": "ch9_q46", "termRef": "physec", "type": "definition", "difficulty": "easy", "question": "Why does the guide emphasize that cybersecurity isn't purely digital?", "options": ["Only software matters; hardware access is irrelevant", "Physical security has no relevance to cybersecurity at all", "Physical attacks stopped being a threat years ago", "The best firewall is useless if an attacker can physically access a server room"], "correctIndex": 3, "explanation": "Best firewall bhi useless hai agar attacker physically server room mein ghus jaaye \u2014 lock pick, RFID clone, tailgating physical attacks real hain."}, {"id": "ch9_q47", "termRef": "physec", "type": "category", "difficulty": "medium", "question": "What is a 'mantrap' in the context of physical security?", "options": ["A type of encrypted USB drive", "A double-door airlock that only lets one person through at a time after verification", "A trap set to catch script kiddies online", "A software tool for catching malware"], "correctIndex": 1, "explanation": "Mantrap (double door airlock) \u2014 physical access control jo ek time pe sirf ek verified person ko andar aane deta hai."}, {"id": "ch9_q48", "termRef": "physec", "type": "category", "difficulty": "medium", "question": "Which of these is listed as a physical security control in the guide?", "options": ["Keycards and biometrics", "SPF email records", "TLS handshakes", "SQL parameterized queries"], "correctIndex": 0, "explanation": "Keycards, biometrics, CCTV, guards, mantrap, cable locks on laptops, screen locks, clean desk policy, visitor logs \u2014 sab physical security controls hain."}, {"id": "ch9_q49", "termRef": "physec", "type": "scenario", "difficulty": "hard", "question": "An attacker follows closely behind an employee through a secure badge-access door without swiping their own card, and nobody stops them. Which physical security failure does this represent?", "options": ["A weak TLS handshake", "Tailgating that could have been prevented with a mantrap or vigilant staff", "A DNS poisoning attack", "A CASB misconfiguration"], "correctIndex": 1, "explanation": "Tailgating physical social engineering technique hai \u2014 mantrap jaisa control isko prevent karne ke liye design hua hai."}, {"id": "ch9_q50", "termRef": "physec", "type": "category", "difficulty": "medium", "question": "What does a 'clean desk policy' aim to prevent?", "options": ["Sensitive documents being left visible and accessible to unauthorized people", "Employees using two monitors instead of one", "Employees personalizing their workspace", "Employees eating lunch at their desks"], "correctIndex": 0, "explanation": "Clean desk policy \u2014 sensitive documents khule na chhode jaayein jahan koi bhi dekh/le sakta ho, ek physical security best practice."}]}, {"chapter": 10, "chapterTitle": "Emerging & Essential Concepts", "termCount": 10, "questionCount": 50, "questions": [{"id": "ch10_q01", "termRef": "aisec", "type": "definition", "difficulty": "easy", "question": "What does 'AI Security' cover, according to the guide?", "options": ["Only antivirus software that uses no AI at all", "AI being used both as a tool for attackers and as a tool for defenders", "Only the security of self-driving cars", "Only AI being used to write marketing content"], "correctIndex": 1, "explanation": "AI as attacker aur defender \u2014 new arms race. Deepfake phishing, AI-generated malware ek taraf; anomaly detection, automated response doosri taraf."}, {"id": "ch10_q02", "termRef": "aisec", "type": "category", "difficulty": "medium", "question": "Which of these is listed as an example of 'AI as attacker' in the guide?", "options": ["Deepfake phishing using cloned voice or video", "Behavior analytics (UEBA)", "Automated threat response in a SIEM", "Smart log analysis at scale"], "correctIndex": 0, "explanation": "AI as Attacker: Deepfake phishing (voice/video clone), AI-generated perfect spear phishing emails, automated vulnerability discovery."}, {"id": "ch10_q03", "termRef": "aisec", "type": "real_world", "difficulty": "hard", "question": "WormGPT (2023) was notable for what capability?", "options": ["Detecting deepfakes with perfect accuracy", "Providing free cybersecurity training to students", "Generating phishing emails and malware code with no ethical restrictions, available on the dark web", "Automatically patching vulnerabilities for free"], "correctIndex": 2, "explanation": "WormGPT: ChatGPT jaise AI model, sans restrictions \u2014 phishing emails, malware code generate karta tha, dark web pe subscribe kiya ja sakta tha."}, {"id": "ch10_q04", "termRef": "aisec", "type": "category", "difficulty": "medium", "question": "Which of these is listed as an example of 'AI as defender' in the guide?", "options": ["Adversarial attacks on ML models", "AI-generated malware", "Anomaly detection and automated threat response", "AI-generated spear phishing emails"], "correctIndex": 2, "explanation": "AI as Defender: Anomaly detection, automated threat response, behavior analytics (UEBA), log analysis at scale, vulnerability prediction, smart SIEM."}, {"id": "ch10_q05", "termRef": "aisec", "type": "scenario", "difficulty": "hard", "question": "An attacker uses an AI tool to clone a CEO's voice and calls an employee requesting an urgent wire transfer. What category of AI-enabled threat does this represent?", "options": ["Automated vulnerability discovery", "Deepfake phishing", "Behavior analytics detection", "Smart SIEM defense"], "correctIndex": 1, "explanation": "Deepfake phishing (voice/video clone) \u2014 exactly is scenario ko match karta hai, AI ka attacker-side use."}, {"id": "ch10_q06", "termRef": "root", "type": "definition", "difficulty": "easy", "question": "What does 'root' mean in Linux/Unix systems?", "options": ["Superuser \u2014 full, unrestricted access to the system", "A type of encryption key", "A basic guest-level account with minimal access", "A network monitoring tool"], "correctIndex": 0, "explanation": "Linux/Unix mein 'root' = superuser = god mode. Windows mein 'Administrator'. Full unrestricted access \u2014 files delete, users create, services install."}, {"id": "ch10_q07", "termRef": "root", "type": "category", "difficulty": "medium", "question": "What is 'vertical privilege escalation'?", "options": ["Encrypting a file with a stronger algorithm", "Accessing another same-level user's data", "Moving laterally across a segmented network", "Going from a low-level user account to admin/root access"], "correctIndex": 3, "explanation": "Vertical privilege escalation (user \u2192 admin) \u2014 attackers hamesha root access tak escalate karne ki koshish karte hain."}, {"id": "ch10_q08", "termRef": "root", "type": "category", "difficulty": "medium", "question": "What is the Windows equivalent term for 'root' access on Linux/Unix systems?", "options": ["Domain User", "Standard User", "Administrator", "Guest"], "correctIndex": 2, "explanation": "Linux/Unix mein 'root', Windows mein 'Administrator' \u2014 dono terms same level of full access refer karte hain."}, {"id": "ch10_q09", "termRef": "root", "type": "scenario", "difficulty": "hard", "question": "A low-privilege user account on a compromised server exploits a vulnerability to gain full administrator control of the entire system. What is this called?", "options": ["Network segmentation bypass", "Horizontal privilege escalation", "A CASB failure", "Vertical privilege escalation"], "correctIndex": 3, "explanation": "Low-level user access se root access tak jaana \u2014 yehi vertical privilege escalation ki definition hai, ek critical vulnerability class."}, {"id": "ch10_q10", "termRef": "root", "type": "category", "difficulty": "medium", "question": "What is the goal an attacker typically has once inside a system with limited access, according to the guide?", "options": ["Immediately leaving the system without further action", "Only changing the desktop wallpaper", "Only reading publicly available files", "Escalating to root access for full control"], "correctIndex": 3, "explanation": "Attackers always try to escalate to root \u2014 full control ke liye yeh unka common goal hota hai."}, {"id": "ch10_q11", "termRef": "pwdcrack", "type": "definition", "difficulty": "easy", "question": "How do properly designed systems store passwords, according to the guide?", "options": ["As plain text for easy recovery", "Written down on paper only", "Only in the user's memory, never stored", "As a hash, not as plain text"], "correctIndex": 3, "explanation": "Proper systems passwords plain text nahi store karte \u2014 hash store karte hain. SHA256('password123') = fixed string."}, {"id": "ch10_q12", "termRef": "pwdcrack", "type": "category", "difficulty": "medium", "question": "Which tools does the guide mention as GPU-accelerated password cracking tools?", "options": ["Wireshark and Nmap", "Okta and Azure AD", "Splunk and QRadar", "Hashcat and John the Ripper"], "correctIndex": 3, "explanation": "Hashcat, John the Ripper \u2014 GPU-accelerated password cracking. RTX 4090 = 300 billion MD5 hashes/second."}, {"id": "ch10_q13", "termRef": "pwdcrack", "type": "defense", "difficulty": "medium", "question": "Which hashing algorithms does the guide specifically recommend NEVER using for passwords?", "options": ["Any algorithm at all is forbidden", "scrypt", "MD5 or SHA1", "bcrypt or Argon2"], "correctIndex": 2, "explanation": "Never use MD5 or SHA1 for passwords \u2014 instead bcrypt, Argon2, scrypt use karo, jo specifically slow hashing ke liye designed hain."}, {"id": "ch10_q14", "termRef": "pwdcrack", "type": "defense", "difficulty": "hard", "question": "What is the purpose of adding a 'salt' before hashing a password?", "options": ["Defeating precomputed rainbow table attacks", "Making the password visible in plain text for recovery", "Removing the need for a password entirely", "Speeding up the hashing process significantly"], "correctIndex": 0, "explanation": "Salt (random string add karo before hashing) \u2014 rainbow tables defeat karo, ek same password bhi alag hash produce karega alag salt ke saath."}, {"id": "ch10_q15", "termRef": "pwdcrack", "type": "scenario", "difficulty": "hard", "question": "The password 'password' gets cracked instantly, while 'Tr0ub4dor&3' takes years to crack using the same tool. What does this illustrate?", "options": ["GPU-based cracking tools don't affect crack time at all", "Password complexity and length dramatically affect crack resistance", "Only password length matters, complexity is irrelevant", "All passwords are equally vulnerable regardless of complexity"], "correctIndex": 1, "explanation": "'password' = cracked instantly, 'Tr0ub4dor&3' = years \u2014 yeh directly demonstrate karta hai ki complexity aur length crack resistance ko kitna affect karte hain."}, {"id": "ch10_q16", "termRef": "dos", "type": "definition", "difficulty": "easy", "question": "What is a DoS (Denial of Service) attack?", "options": ["A method for securely managing passwords", "An attack that only steals data, never disrupts availability", "An attack from a single source designed to make a service unavailable", "A type of encrypted backup process"], "correctIndex": 2, "explanation": "Single source se service unavailable karna \u2014 DoS: single machine se attack, DDoS: distributed sources se."}, {"id": "ch10_q17", "termRef": "dos", "type": "category", "difficulty": "medium", "question": "Why is a pure DoS attack described as easier to block than a DDoS attack?", "options": ["Because DoS attacks are illegal but DDoS is not", "Because DoS attacks never actually reach the target server", "Because DoS attacks always use encrypted traffic", "Since it comes from a single machine, you can simply ban that one IP"], "correctIndex": 3, "explanation": "DoS: Single machine se attack. Easy to block (IP ban karo). Limited bandwidth/impact \u2014 DDoS is is se harder hai kyunki hazaron sources hote hain."}, {"id": "ch10_q18", "termRef": "dos", "type": "category", "difficulty": "medium", "question": "Which type of DoS attack exhausts server resources using half-open TCP connections?", "options": ["Application layer attack", "Protocol attack (TCP SYN flood)", "Volumetric attack", "None of these types exist"], "correctIndex": 1, "explanation": "Protocol (TCP SYN flood \u2014 half-open connections exhaust karo), Volumetric (flood karo), Application layer (HTTP requests \u2014 web server crash)."}, {"id": "ch10_q19", "termRef": "dos", "type": "category", "difficulty": "medium", "question": "Which type of DoS attack works by sending HTTP requests that crash the web server directly at the application layer?", "options": ["Protocol attack", "None, this doesn't exist", "Application layer attack", "Volumetric attack"], "correctIndex": 2, "explanation": "Application layer (HTTP requests \u2014 web server crash) \u2014 each type needs different defense, according to the guide."}, {"id": "ch10_q20", "termRef": "dos", "type": "scenario", "difficulty": "hard", "question": "A single machine floods a small website with traffic, and the site's admin quickly identifies and blocks that one IP address, resolving the issue within minutes. What made this attack relatively easy to mitigate?", "options": ["It was a DoS attack from a single source, not a distributed DDoS", "It was an APT campaign", "It was a credential stuffing attempt", "It was actually a supply chain attack"], "correctIndex": 0, "explanation": "DoS single machine se attack hai isliye easy to block hai \u2014 ek IP ban karke resolve ho sakta hai, DDoS ke against yeh mushkil hota."}, {"id": "ch10_q21", "termRef": "ueba", "type": "definition", "difficulty": "easy", "question": "What does UEBA (User & Entity Behavior Analytics) do?", "options": ["Encrypts all network traffic automatically", "Manages a company's cloud storage costs", "Uses machine learning to baseline normal behavior and flag deviations", "Physically blocks unauthorized building access"], "correctIndex": 2, "explanation": "Machine learning se user aur entity ka normal behavior baseline karo, phir deviations flag karo."}, {"id": "ch10_q22", "termRef": "ueba", "type": "category", "difficulty": "medium", "question": "In the guide's example, what does UEBA flag when 'John usually logs in 9-5 from India'?", "options": ["John changing his own password", "John using a company laptop", "Any login during normal business hours", "A sudden 3am login from Russia"], "correctIndex": 3, "explanation": "John usually 9-5 India se login karta hai. Suddenly 3am Russia se login = red flag \u2014 behavioral deviation detect hoti hai."}, {"id": "ch10_q23", "termRef": "ueba", "type": "category", "difficulty": "medium", "question": "What kind of threats can UEBA detect that signature-based tools might miss?", "options": ["Only known malware with existing signatures", "Only threats from outside the organization, never insiders", "Zero-day threats, through unusual behavior rather than known signatures", "Only physical break-ins"], "correctIndex": 2, "explanation": "Zero-day threats bhi pakad sakta hai unusual behavior se \u2014 signature se nahi, behavior se detect karta hai."}, {"id": "ch10_q24", "termRef": "ueba", "type": "category", "difficulty": "medium", "question": "Which of these is listed as something UEBA can detect, according to the guide?", "options": ["Only hardware temperature spikes", "Only weather changes affecting servers", "Only software license expiration", "Data exfiltration and privilege abuse"], "correctIndex": 3, "explanation": "Detects: Insider threats, compromised accounts, data exfiltration, privilege abuse \u2014 sab behavior deviation ke through pakde jaate hain."}, {"id": "ch10_q25", "termRef": "ueba", "type": "scenario", "difficulty": "hard", "question": "An employee who normally downloads a few files a week suddenly downloads the company's entire customer database at 2am on a Sunday. A security tool automatically flags this as unusual. Which technology is most likely responsible?", "options": ["SSH", "UEBA", "NAT", "A digital certificate"], "correctIndex": 1, "explanation": "Unusual access times, large data downloads, off-hours logins \u2014 exactly UEBA jo behavior baseline se deviation detect karta hai."}, {"id": "ch10_q26", "termRef": "darkweb", "type": "definition", "difficulty": "easy", "question": "What technology is required to access the Dark Web?", "options": ["A standard web browser with no special software", "Tor", "A special type of antivirus", "A VPN alone, without any other tool"], "correctIndex": 1, "explanation": "Dark Web: Tor needed, anonymous, not indexed by Google \u2014 ek hidden part of the internet."}, {"id": "ch10_q27", "termRef": "darkweb", "type": "category", "difficulty": "medium", "question": "Roughly what percentage of the internet does the guide say makes up the 'Surface Web'?", "options": ["90%", "6%", "50%", "4%"], "correctIndex": 3, "explanation": "Surface Web: Google index karta hai (4%), Deep Web: not indexed (90%), Dark Web: Tor needed, not indexed (6%)."}, {"id": "ch10_q28", "termRef": "darkweb", "type": "analogy", "difficulty": "medium", "question": "Which analogy does the guide use to describe the layers of the internet?", "options": ["A postman delivering sealed letters", "A phone book listing every website", "A library with locked and unlocked sections", "An ocean, with the Dark Web compared to the Mariana Trench"], "correctIndex": 3, "explanation": "Ocean ki tarah \u2014 Surface = visible waala hissa, Deep = underwater, Dark = Mariana Trench, reach karna mushkil, genuinely dangerous creatures wahan."}, {"id": "ch10_q29", "termRef": "darkweb", "type": "category", "difficulty": "medium", "question": "Who originally created the Tor Project, according to the guide?", "options": ["The United Nations", "Google", "The US Navy", "A private cybercrime organization"], "correctIndex": 2, "explanation": "Tor Project made by US Navy \u2014 journalist whistleblowers, censorship bypass jaise legitimate uses bhi hain, dark web = mostly evil nahi hai."}, {"id": "ch10_q30", "termRef": "darkweb", "type": "category", "difficulty": "medium", "question": "Which of these is listed as a legitimate use of the Dark Web, according to the guide?", "options": ["Only stolen credential sales", "Only hacking-for-hire services", "Censorship bypass for activists in restrictive countries", "Only illegal drug marketplaces"], "correctIndex": 2, "explanation": "Dark web = journalist whistleblowers, censorship bypass (Iran, China activists), privacy enthusiasts \u2014 'not all evil'."}, {"id": "ch10_q31", "termRef": "cpa", "type": "definition", "difficulty": "easy", "question": "What is a Cyber-Physical Attack?", "options": ["A purely theoretical scenario that has never actually happened", "A cyberattack whose consequences manifest in the physical world", "An attack that only steals digital data with no real-world impact", "A type of physical break-in with no digital component"], "correctIndex": 1, "explanation": "Cyber attack jiske physical consequences hain \u2014 power grids off karna, traffic lights hack, water poison \u2014 digital command = physical disaster."}, {"id": "ch10_q32", "termRef": "cpa", "type": "real_world", "difficulty": "hard", "question": "In the Florida Water Treatment attack (2021), by how much did the hacker increase the sodium hydroxide levels?", "options": ["111x", "1.1x", "11x", "1,100x"], "correctIndex": 0, "explanation": "Hacker ne Oldsmar city ke water treatment plant ka SCADA system access kiya aur sodium hydroxide 111x badha diya \u2014 drinking water poison attempt, operator ne catch kiya."}, {"id": "ch10_q33", "termRef": "cpa", "type": "category", "difficulty": "medium", "question": "Who ultimately prevented disaster in the Florida Water Treatment attack case, according to the guide?", "options": ["A firewall automatically blocked the attacker", "The FBI intervened remotely in real time", "A human operator noticed and reversed the change", "An automated AI defense system"], "correctIndex": 2, "explanation": "Operator ne catch kiya, disaster averted \u2014 is case mein human vigilance ne bade damage ko roka."}, {"id": "ch10_q34", "termRef": "cpa", "type": "category", "difficulty": "medium", "question": "Which growing trend does the guide say is increasing the risk of cyber-physical attacks?", "options": ["Companies abandoning cloud computing entirely", "The decline of internet usage overall", "Smart cities and connected infrastructure (Industry 4.0)", "A reduction in the number of IoT devices"], "correctIndex": 2, "explanation": "Smart cities, connected infrastructure, Industry 4.0 \u2014 jitna zyada connectivity, utna zyada attack surface."}, {"id": "ch10_q35", "termRef": "cpa", "type": "scenario", "difficulty": "hard", "question": "An attacker gains access to a city's water treatment SCADA system and attempts to alter chemical dosing levels to dangerous amounts, but a vigilant operator catches and reverses it in time. What type of attack was attempted?", "options": ["A DDoS attack", "A Cyber-Physical Attack", "Credential stuffing", "A supply chain attack"], "correctIndex": 1, "explanation": "Digital command = physical disaster attempt \u2014 exactly cyber-physical attack ki definition, jaisa Florida water treatment case mein hua."}, {"id": "ch10_q36", "termRef": "cloudiam", "type": "definition", "difficulty": "easy", "question": "What does Cloud IAM control?", "options": ["Only email spam filtering rules", "Only physical access to a data center building", "Only which fonts are used in a cloud application", "Access to cloud provider resources like S3 buckets, EC2 instances, and databases"], "correctIndex": 3, "explanation": "Cloud provider ke resources (S3, EC2, databases) tak access control \u2014 roles, policies, permissions, kaunsa service kaunsa resource access kar sakta hai."}, {"id": "ch10_q37", "termRef": "cloudiam", "type": "category", "difficulty": "medium", "question": "What is the most common cause of cloud breaches, according to the guide?", "options": ["Encryption being too strong", "Misconfigured Cloud IAM", "Weather-related outages", "Physical theft of cloud servers"], "correctIndex": 1, "explanation": "Misconfigured Cloud IAM = most common cloud breach cause \u2014 yeh directly Capital One jaise breaches se bhi connect hota hai."}, {"id": "ch10_q38", "termRef": "cloudiam", "type": "category", "difficulty": "medium", "question": "Which of these is a recommended Cloud IAM best practice, according to the guide?", "options": ["Sharing long-lived access keys among all team members", "Not using the root account for daily use", "Disabling MFA on the root account", "Using the root account for all daily tasks"], "correctIndex": 1, "explanation": "Least privilege \u2014 root account daily use mat karo. MFA on root. Roles use karo instead of long-lived access keys."}, {"id": "ch10_q39", "termRef": "cloudiam", "type": "category", "difficulty": "medium", "question": "Which logging feature does the guide recommend enabling for cloud access auditing (specifically for AWS)?", "options": ["SPF records", "DNS Poisoning logs", "SSH key logs", "CloudTrail"], "correctIndex": 3, "explanation": "CloudTrail logging enable karo \u2014 regular access review ke saath, yeh AWS-specific auditing tool hai."}, {"id": "ch10_q40", "termRef": "cloudiam", "type": "scenario", "difficulty": "hard", "question": "A junior developer is given the cloud root account's long-lived access key for a simple daily task instead of a scoped, temporary role. What best practice does this violate?", "options": ["Using roles instead of long-lived access keys, and not using root for daily tasks", "The 3-2-1 backup rule", "The NIST Incident Response phases", "Chain of custody documentation"], "correctIndex": 0, "explanation": "Roles use karo instead of long-lived access keys, root account daily use mat karo \u2014 is scenario mein dono best practices violate ho rahi hain."}, {"id": "ch10_q41", "termRef": "databreach", "type": "definition", "difficulty": "easy", "question": "What is a Data Breach?", "options": ["A planned, authorized penetration test", "Sensitive or confidential information ending up in unauthorized hands", "A type of encrypted backup process", "A firewall configuration update"], "correctIndex": 1, "explanation": "Sensitive, confidential ya protected information unauthorized parties ke hands mein jaana \u2014 intentional ya accidental dono ho sakta hai."}, {"id": "ch10_q42", "termRef": "databreach", "type": "category", "difficulty": "medium", "question": "What is the average cost of a data breach, according to the guide (citing IBM 2023 data)?", "options": ["$4.45 million", "$445,000", "$44.5 million", "$4,450"], "correctIndex": 0, "explanation": "Average cost: $4.45 million (IBM 2023) \u2014 yeh statistic guide mein specifically diya gaya hai."}, {"id": "ch10_q43", "termRef": "databreach", "type": "category", "difficulty": "medium", "question": "Within how many hours must a data breach be reported under GDPR, according to the guide?", "options": ["7 days", "7 hours", "72 hours", "24 hours"], "correctIndex": 2, "explanation": "GDPR notification 72 hours mein required \u2014 yeh ek strict regulatory deadline hai companies ke liye."}, {"id": "ch10_q44", "termRef": "databreach", "type": "real_world", "difficulty": "hard", "question": "A 2018 report suggested that 1.1 billion Indians' Aadhaar data was accessible for how much money via WhatsApp?", "options": ["\u20b9500", "\u20b95,000", "\u20b950", "\u20b950,000"], "correctIndex": 0, "explanation": "Report aaya ki 1.1 billion Indians ka Aadhaar data accessible tha for \u20b9500 via WhatsApp \u2014 UIDAI ne deny kiya, par investigation ne serious vulnerabilities found."}, {"id": "ch10_q45", "termRef": "databreach", "type": "category", "difficulty": "medium", "question": "Which of these is listed as an aftermath consequence of a data breach, according to the guide?", "options": ["No impact on customer trust whatsoever", "Guaranteed government bailout funding", "Automatic exemption from future regulations", "Average stock price drop of 7.5%"], "correctIndex": 3, "explanation": "Stock price drop (avg 7.5%), customer trust loss, class action lawsuits, regulatory fines, executives fired \u2014 sab aftermath consequences hain."}, {"id": "ch10_q46", "termRef": "framework", "type": "definition", "difficulty": "easy", "question": "What is a Cybersecurity Framework?", "options": ["A type of encryption algorithm", "A physical lock mechanism for server rooms", "A single specific antivirus product", "A structured approach to managing cybersecurity risk"], "correctIndex": 3, "explanation": "Structured approach to manage cybersecurity risk \u2014 building code jaisa, ek common language aur standard approach deta hai."}, {"id": "ch10_q47", "termRef": "framework", "type": "category", "difficulty": "medium", "question": "What are the 5 core functions of the NIST Cybersecurity Framework (CSF)?", "options": ["Identify, Protect, Detect, Respond, Recover", "Plan, Build, Test, Deploy, Maintain", "Encrypt, Decrypt, Hash, Salt, Verify", "Scan, Patch, Report, Audit, Repeat"], "correctIndex": 0, "explanation": "NIST CSF: 1. Identify (assets, risks samjho), 2. Protect, 3. Detect, 4. Respond, 5. Recover \u2014 5 core functions."}, {"id": "ch10_q48", "termRef": "framework", "type": "category", "difficulty": "medium", "question": "Which framework specifically documents actual adversary tactics as a matrix?", "options": ["CIS Controls", "ISO 27001", "OWASP Top 10", "MITRE ATT&CK"], "correctIndex": 3, "explanation": "MITRE ATT&CK: Adversary tactics matrix \u2014 actual attack techniques documented, ek unique framework focused on attacker behavior."}, {"id": "ch10_q49", "termRef": "framework", "type": "analogy", "difficulty": "medium", "question": "Which analogy does the guide use to describe a cybersecurity framework?", "options": ["A CCTV control room watching cameras", "A building code for architecture \u2014 a common standard so engineers don't build inconsistently", "A postman delivering sealed letters", "A movie ticket used once for entry"], "correctIndex": 1, "explanation": "Building code for architecture jaisa \u2014 alag-alag engineers alag-alag sochein to inconsistency, framework ek common language aur standard approach deta hai."}, {"id": "ch10_q50", "termRef": "framework", "type": "category", "difficulty": "medium", "question": "Which framework specifically focuses on web application vulnerabilities?", "options": ["OWASP Top 10", "MITRE ATT&CK", "CIS Controls", "NIST CSF"], "correctIndex": 0, "explanation": "OWASP Top 10: Web vulnerabilities \u2014 ISO 27001 international standard hai, MITRE ATT&CK adversary tactics, CIS Controls top 18 security actions."}]}]}, "1": {"chapter": 1, "chapterTitle": "Core Threats & Attacks", "termCount": 10, "questionCount": 54, "questions": [{"id": "ch1_q01", "termRef": "malware", "type": "definition", "difficulty": "easy", "question": "What does the term 'Malware' literally stand for, and what is its core purpose?", "options": ["Managed Software \u2014 provides automatic patch updates", "Mainframe Software \u2014 used to manage large servers", "Modular Software \u2014 used to install browser plugins", "Malicious Software \u2014 designed to deliberately harm a system"], "correctIndex": 3, "explanation": "Malware = Malicious + Software. Koi bhi software jo jaan-boojh kar system ko harm karta hai \u2014 data churaana, corrupt karna, ya control lena."}, {"id": "ch1_q02", "termRef": "malware", "type": "category", "difficulty": "medium", "question": "Which of the following is NOT classified as a type of malware?", "options": ["Ransomware", "Trojan Horse", "Firewall", "Rootkit"], "correctIndex": 2, "explanation": "Firewall ek defensive tool hai, malware nahi. Rootkit, Trojan aur Ransomware \u2014 sab malware ke forms hain."}, {"id": "ch1_q03", "termRef": "malware", "type": "analogy", "difficulty": "easy", "question": "In the guide's disease analogy, which illness is compared to a computer worm?", "options": ["Malaria \u2014 spreads through mosquito bites", "Common Cold \u2014 spreads through air", "Jaundice \u2014 causes slow, silent damage", "Cholera \u2014 spreads rapidly through water"], "correctIndex": 3, "explanation": "Analogy mein worm ko cholera se compare kiya gaya \u2014 jaise cholera paani se spread hoti hai, worm bhi network se khud-b-khud spread hota hai."}, {"id": "ch1_q04", "termRef": "malware", "type": "real_world", "difficulty": "medium", "question": "What was the estimated global financial loss caused by the WannaCry ransomware attack in 2017?", "options": ["$400 million", "$40 million", "$4 billion or more", "$4 million"], "correctIndex": 2, "explanation": "WannaCry ne 150 countries mein NHS hospitals, Telef\u00f3nica Spain, FedEx ko paralyze kiya \u2014 $4 billion+ ka estimated loss hua, ek unpatched Windows vulnerability se."}, {"id": "ch1_q05", "termRef": "malware", "type": "defense", "difficulty": "medium", "question": "Which of these is NOT listed as a recommended defense against malware?", "options": ["Running updated antivirus software", "Applying OS and software patches promptly", "Keeping regular offline backups", "Clicking unknown links to verify if they are safe"], "correctIndex": 3, "explanation": "Guide bolti hai unknown links/files pe click MAT karo \u2014 verify karne ke liye click karna hi risky habit hai."}, {"id": "ch1_q06", "termRef": "malware", "type": "scenario", "difficulty": "hard", "question": "Your laptop has become slow, an unknown background process is consuming CPU, and you recently installed cracked software from an untrusted website. What is most likely happening?", "options": ["A necessary RAM upgrade is required", "The battery is nearing the end of its life", "A routine Windows update is running", "A malware infection introduced through the cracked software"], "correctIndex": 3, "explanation": "Untrusted source se cracked software install karna malware ka common entry point hai \u2014 unknown process aur slowdown classic symptoms hain."}, {"id": "ch1_q07", "termRef": "phishing", "type": "definition", "difficulty": "easy", "question": "What does an attacker fundamentally do in a phishing attack?", "options": ["Floods a network with traffic", "Directly breaches a server's database", "Creates a fake email or website to steal credentials", "Physically steals a device"], "correctIndex": 2, "explanation": "Phishing mein attacker legit dikhne wali fake email/website/SMS banaata hai jisme victim apni credentials daal deta hai."}, {"id": "ch1_q08", "termRef": "phishing", "type": "category", "difficulty": "medium", "question": "Phishing carried out over a phone call is known as what?", "options": ["Smishing", "Spear Phishing", "Vishing", "Whaling"], "correctIndex": 2, "explanation": "Vishing = Voice + Phishing. Smishing SMS se, Whaling CEOs ko target karta hai, Spear Phishing naam se targeted hota hai."}, {"id": "ch1_q09", "termRef": "phishing", "type": "real_world", "difficulty": "hard", "question": "How much money did Evaldas Rimasauskas steal from Google and Facebook using fake invoices (2013\u20132015)?", "options": ["Over $100 million", "Over $1 billion", "Over $10 million", "Around $500,000"], "correctIndex": 0, "explanation": "Rimasauskas ne Quanta Computer impersonate karke fake invoices bheji \u2014 Google aur Facebook ne actually $100M+ pay kar diya."}, {"id": "ch1_q10", "termRef": "phishing", "type": "defense", "difficulty": "medium", "question": "According to the guide, what should you do if an email urgently demands immediate action, such as 'your account will be closed in 24 hours'?", "options": ["Forward the email to friends for a second opinion", "Change your password before doing anything else", "Pause and verify independently instead of reacting to the urgency", "Click the link immediately to resolve it"], "correctIndex": 2, "explanation": "Guide specifically bolti hai \u2014 koi bhi urgency feel ho toh ruko, verify karo. Urgency create karna attacker ki common tactic hai."}, {"id": "ch1_q11", "termRef": "phishing", "type": "scenario", "difficulty": "hard", "question": "You receive an email addressed to you by name, appearing to be from your company's CEO, urgently requesting a wire transfer. What kind of attack is this most likely to be?", "options": ["SQL Injection", "A DDoS attack", "A botnet recruitment attempt", "Spear Phishing (or Whaling if the CEO is the actual target)"], "correctIndex": 3, "explanation": "Naam se target karna aur specific person ko address karna Spear Phishing ki nishaani hai \u2014 agar high-value target (CEO) hai toh Whaling bhi keh sakte hain."}, {"id": "ch1_q12", "termRef": "ransomware", "type": "definition", "difficulty": "easy", "question": "What happens during a ransomware attack?", "options": ["The network is shut down due to traffic overload", "Data is only copied, nothing is locked", "The entire system is permanently deleted", "Files are encrypted and a payment is demanded to unlock them"], "correctIndex": 3, "explanation": "Ransomware files ko encrypt (lock) kar deta hai, phir Bitcoin mein payment maanga jaata hai decryption key ke liye."}, {"id": "ch1_q13", "termRef": "ransomware", "type": "category", "difficulty": "medium", "question": "Which of the following are common ways ransomware spreads, according to the guide?", "options": ["Only through physical theft of devices", "Only through USB drives", "Phishing emails, malicious attachments, unpatched software, and RDP brute-forcing", "Only through social media messages"], "correctIndex": 2, "explanation": "Guide ke mutabik ransomware phishing emails, malicious attachments, unpatched software, aur RDP bruteforce se spread hota hai."}, {"id": "ch1_q14", "termRef": "ransomware", "type": "real_world", "difficulty": "medium", "question": "How much ransom was paid during the Colonial Pipeline attack in 2021?", "options": ["$440,000", "$4.4 billion", "$44 million", "$4.4 million"], "correctIndex": 3, "explanation": "DarkSide ransomware ne US ki sabse badi fuel pipeline band kar di \u2014 $4.4 million ransom diya gaya, east coast mein fuel shortage aur panic buying hui."}, {"id": "ch1_q15", "termRef": "ransomware", "type": "defense", "difficulty": "medium", "question": "What does the guide's '3-2-1 rule' refer to?", "options": ["Backups: 3 copies of data, 2 different media types, 1 stored offsite", "Passwords: 3 words, 2 numbers, 1 symbol", "Encryption: 3 keys, 2 algorithms, 1 vault", "Network layers: 3 firewalls, 2 IDS systems, 1 honeypot"], "correctIndex": 0, "explanation": "3-2-1 backup rule: 3 copies of data, 2 different media types, 1 copy offsite \u2014 ransomware recovery ke liye critical defense."}, {"id": "ch1_q16", "termRef": "ransomware", "type": "scenario", "difficulty": "hard", "question": "A note suddenly appears on your screen: 'Your files are encrypted. Pay 2 BTC within 48 hours.' According to the guide, what should you NOT do first?", "options": ["Check whether backups of the affected files exist", "Pay the ransom immediately", "Inform your IT/security team", "Disconnect the system from the network"], "correctIndex": 1, "explanation": "Guide specifically bolti hai \u2014 pay mat karo, koi guarantee nahi ki key milegi hi. Pehla step hamesha isolate karna aur verify karna hai."}, {"id": "ch1_q17", "termRef": "ransomware", "type": "category", "difficulty": "medium", "question": "According to the guide's 'How It Works' breakdown, what typically happens right after ransomware encrypts your files?", "options": ["The system automatically restarts", "Files are automatically restored from backup", "Antivirus software instantly detects and removes it", "A ransom note appears with a Bitcoin address"], "correctIndex": 3, "explanation": "Steps: install \u2192 files dhundhna \u2192 AES-256 se encrypt \u2192 ransom note dikhna with Bitcoin address \u2192 timer shuru."}, {"id": "ch1_q18", "termRef": "botnet", "type": "definition", "difficulty": "easy", "question": "What is a botnet?", "options": ["A single, highly powerful hacking tool", "An encrypted messaging application", "A network of infected computers remotely controlled by an attacker", "A type of antivirus software"], "correctIndex": 2, "explanation": "Botnet = hazaron/laakhon infected computers ka network jise ek 'bot herder' (attacker) remotely control karta hai."}, {"id": "ch1_q19", "termRef": "botnet", "type": "category", "difficulty": "medium", "question": "Which of the following is NOT a common use of a botnet, according to the guide?", "options": ["Sending spam", "Cryptocurrency mining", "Launching DDoS attacks", "Legitimate software development"], "correctIndex": 3, "explanation": "Guide ke mutabik botnet uses: DDoS attacks, spam sending, crypto mining, credential theft, ad fraud \u2014 legitimate development inmein nahi aata."}, {"id": "ch1_q20", "termRef": "botnet", "type": "real_world", "difficulty": "medium", "question": "What type of devices did the Mirai Botnet (2016) primarily infect?", "options": ["IoT devices such as cameras and routers", "Only laptops", "Only smartphones", "Only enterprise servers"], "correctIndex": 0, "explanation": "Mirai ne IoT devices (cameras, routers) infect kiye aur Dyn DNS pe DDoS kiya \u2014 Twitter, Netflix, Amazon, Reddit US mein down ho gaye."}, {"id": "ch1_q21", "termRef": "botnet", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use to describe a botnet?", "options": ["Someone is secretly remote-controlling your phone in the background", "Someone forces your hand to sign a cheque while you sleep", "A disease that spreads in different forms", "A postman is secretly reading your letters"], "correctIndex": 0, "explanation": "Botnet analogy: tum normal use kar rahe ho, but background mein koi tumhara device remotely spam/attack ke liye use kar raha hai."}, {"id": "ch1_q22", "termRef": "botnet", "type": "scenario", "difficulty": "hard", "question": "You notice your router has been sending heavy outbound traffic 24/7 that you never initiated. What does this most likely indicate?", "options": ["The router has become part of a botnet", "This is normal background sync activity", "The router's firmware is updating", "The ISP has made a billing error"], "correctIndex": 0, "explanation": "Bina wajah heavy outbound traffic \u2014 especially IoT device jaise router se \u2014 botnet infection ka classic sign hai (jaise Mirai)."}, {"id": "ch1_q23", "termRef": "ddos", "type": "definition", "difficulty": "easy", "question": "Why does a server crash during a DDoS attack?", "options": ["The server's hardware physically fails", "The database becomes corrupted", "The power supply is cut off", "Thousands of bots send so much traffic at once that the server cannot handle it"], "correctIndex": 3, "explanation": "DDoS mein distributed bots massive traffic bhejte hain jisse server overload ho ke crash/freeze ho jaata hai \u2014 real users access nahi kar paate."}, {"id": "ch1_q24", "termRef": "ddos", "type": "category", "difficulty": "medium", "question": "What is the main difference between DoS and DDoS?", "options": ["DoS only targets websites; DDoS only targets apps", "They are the same attack with different names", "DoS comes from a single machine; DDoS is distributed across thousands of machines", "DoS is more dangerous than DDoS"], "correctIndex": 2, "explanation": "DoS single machine se attack hai (block karna easy), DDoS distributed hai hazaron machines se (block karna almost impossible)."}, {"id": "ch1_q25", "termRef": "ddos", "type": "real_world", "difficulty": "hard", "question": "The 2018 GitHub DDoS attack was the largest recorded at the time. What was its peak traffic speed?", "options": ["13.5 Tbps", "1.35 Tbps", "135 Gbps", "1.35 Gbps"], "correctIndex": 1, "explanation": "GitHub pe 1.35 Tbps ka attack hua tha \u2014 Memcached servers ka amplification exploit karke. GitHub 10 minutes down raha, phir Akamai ne absorb kiya."}, {"id": "ch1_q26", "termRef": "ddos", "type": "defense", "difficulty": "medium", "question": "Which technique does the guide recommend as a defense against DDoS attacks?", "options": ["Installing antivirus software", "Using parameterized SQL queries", "Using a CDN (such as Cloudflare or Akamai) to absorb traffic", "Increasing password complexity"], "correctIndex": 2, "explanation": "DDoS defenses: CDN use karo, rate limiting, Anycast network diffusion, ISP-level filtering \u2014 antivirus/password yeh DDoS-specific defenses nahi hain."}, {"id": "ch1_q27", "termRef": "ddos", "type": "scenario", "difficulty": "hard", "question": "Your e-commerce site crashes during a big sale, and traffic logs show 50,000 different IPs sending requests within the same second. What is most likely happening?", "options": ["A zero-day exploit", "A phishing campaign", "A SQL Injection attack", "A DDoS attack"], "correctIndex": 3, "explanation": "Multiple distributed IPs se massive simultaneous traffic \u2014 classic DDoS signature, genuine sale traffic itna sudden aur distributed nahi hota."}, {"id": "ch1_q28", "termRef": "mitm", "type": "definition", "difficulty": "easy", "question": "What does an attacker do in a Man-in-the-Middle (MITM) attack?", "options": ["Directly crashes the target server", "Sends a fake email to steal credentials", "Secretly inserts themselves between two parties to read or modify their data", "Installs malware on the victim's system"], "correctIndex": 2, "explanation": "MITM mein attacker do communicating parties ke beech secretly aa jaata hai aur unka data intercept/modify karta hai bina unko pata chale."}, {"id": "ch1_q29", "termRef": "mitm", "type": "category", "difficulty": "medium", "question": "What is it called when an attacker sets up a fake WiFi hotspot to intercept traffic?", "options": ["DNS Spoofing", "ARP Spoofing", "Evil Twin", "SSL Stripping"], "correctIndex": 2, "explanation": "Evil Twin = fake WiFi hotspot jo legit se same naam ka hota hai. ARP/DNS spoofing aur SSL stripping alag MITM techniques hain."}, {"id": "ch1_q30", "termRef": "mitm", "type": "analogy", "difficulty": "medium", "question": "Which analogy does the guide use to explain MITM attacks?", "options": ["A postman opens your letter, alters it, reseals it, and delivers it", "Someone is secretly controlling your phone remotely", "Thousands of bots send traffic at once", "A disease that spreads in different forms"], "correctIndex": 0, "explanation": "Postman analogy \u2014 letter tumne bheja, par beech mein koi usse open/modify karke aage bhej deta hai bina dono parties ko pata chale."}, {"id": "ch1_q31", "termRef": "mitm", "type": "scenario", "difficulty": "hard", "question": "After connecting to free airport WiFi, your banking app login fails and you see a suspicious certificate warning. What is most likely happening?", "options": ["Your password has expired", "A MITM attack (possibly an Evil Twin or SSL Stripping)", "The app simply needs an update", "Routine server maintenance"], "correctIndex": 1, "explanation": "Public WiFi + certificate warning = classic MITM red flag. Attacker traffic intercept karne ki koshish kar raha ho sakta hai."}, {"id": "ch1_q32", "termRef": "mitm", "type": "real_world", "difficulty": "medium", "question": "According to the guide, what is the most common MITM technique used at public WiFi locations like coffee shops or airports?", "options": ["Evil Twin \u2014 a fake hotspot with the same name", "Recruiting the device into a botnet", "Automatic ransomware installation", "SQL injection through the router"], "correctIndex": 0, "explanation": "Public WiFi pe attacker Evil Twin (same naam ka fake hotspot) banaata hai \u2014 victim connect hota hai, attacker sab traffic dekh leta hai."}, {"id": "ch1_q33", "termRef": "sqli", "type": "definition", "difficulty": "easy", "question": "What does an attacker do in a SQL Injection attack?", "options": ["Enters SQL code into a web form to trick the database", "Physically hacks into the database server", "Floods the network with traffic", "Sends malware through email"], "correctIndex": 0, "explanation": "SQL Injection mein attacker web forms mein malicious SQL code daalta hai jo database directly execute kar leta hai bina proper sanitization ke."}, {"id": "ch1_q34", "termRef": "sqli", "type": "category", "difficulty": "medium", "question": "Why does SQL Injection work in the first place?", "options": ["When a server's RAM becomes full", "When a firewall is disabled", "When a website inserts unsanitized user input directly into a SQL query", "When an HTTPS certificate expires"], "correctIndex": 2, "explanation": "Root cause: unsanitized user input directly SQL query mein jaana \u2014 attacker apna SQL command as input de deta hai jo execute ho jaata hai."}, {"id": "ch1_q35", "termRef": "sqli", "type": "scenario", "difficulty": "hard", "question": "Typing `admin'--` into a login form's username field can bypass the password check. What concept does this demonstrate?", "options": ["XSS \u2014 a script injected into the browser", "CSRF \u2014 a forged, unwanted request", "SQL Injection \u2014 '--' is a SQL comment, so the rest of the query is ignored", "Phishing \u2014 a fake login page"], "correctIndex": 2, "explanation": "Guide ke code example ke mutabik `admin'--` se query ka password-check part comment ban jaata hai SQL mein, aur skip ho jaata hai \u2014 classic SQLi."}, {"id": "ch1_q36", "termRef": "sqli", "type": "real_world", "difficulty": "medium", "question": "How many credit card numbers were stolen in the Heartland Payment Systems breach (2008) via SQL injection?", "options": ["13 million", "1.3 million", "1.3 billion", "130 million"], "correctIndex": 3, "explanation": "SQL injection se 130 million credit card numbers chori huye, $140 million+ settlement \u2014 us waqt US history ki largest data breach thi."}, {"id": "ch1_q37", "termRef": "sqli", "type": "defense", "difficulty": "medium", "question": "What is the primary technique the guide recommends for defending against SQL Injection?", "options": ["Closing firewall ports", "Parameterized queries / prepared statements", "Installing antivirus software", "Increasing password length"], "correctIndex": 1, "explanation": "Parameterized queries/prepared statements user input ko SQL command ki tarah execute hone se rokte hain \u2014 sabse effective SQLi defense."}, {"id": "ch1_q38", "termRef": "xss", "type": "definition", "difficulty": "easy", "question": "What does an attacker do in a Cross-Site Scripting (XSS) attack?", "options": ["Injects malicious JavaScript into a website that runs in the victim's browser", "Floods the server's bandwidth", "Directly accesses the database", "Physically steals a device"], "correctIndex": 0, "explanation": "XSS mein attacker JS inject karta hai; jab victim page open karta hai, uska browser attacker ka script run kar deta hai \u2014 cookies/tokens chori ho sakte hain."}, {"id": "ch1_q39", "termRef": "xss", "type": "category", "difficulty": "medium", "question": "A script that gets permanently saved in a database (such as in a comment section) is which type of XSS?", "options": ["Reflected XSS", "Stored XSS", "Blind XSS", "DOM-based XSS"], "correctIndex": 1, "explanation": "Stored XSS = script database mein save ho jaata hai (e.g. comments), Reflected = URL mein, DOM-based = client-side manipulation."}, {"id": "ch1_q40", "termRef": "xss", "type": "real_world", "difficulty": "medium", "question": "How many profiles did the Samy Worm (MySpace, 2005) infect within a single day?", "options": ["Over 10 million", "Over 100,000", "Over 10,000", "Over 1 million"], "correctIndex": 3, "explanation": "Samy Kamkar ne XSS script daali, ek din mein 1 million+ profiles ne automatically 'Samy is my hero' add kar liya \u2014 history ka fastest spreading virus."}, {"id": "ch1_q41", "termRef": "xss", "type": "scenario", "difficulty": "hard", "question": "A user posts a script in a forum's comment box that steals cookies, and it gets saved permanently. What is the risk?", "options": ["Nothing happens, browsers block this automatically", "Only the commenter's own account will be compromised", "Every user who views the page will have their cookies sent to the attacker (Stored XSS)", "The forum's database will be deleted"], "correctIndex": 2, "explanation": "Yeh Stored XSS ka classic example hai \u2014 script database mein saved hai, jo bhi page open karega uska browser script run karega aur cookie chori hogi."}, {"id": "ch1_q42", "termRef": "xss", "type": "defense", "difficulty": "medium", "question": "What is the most fundamental step to protect a website from Stored/Reflected XSS?", "options": ["Use HTTPS only", "Close all firewall ports", "Escape or sanitize user input before rendering it as output", "Install antivirus software on the server"], "correctIndex": 2, "explanation": "User-supplied input ko HTML mein render karne se pehle escape karna (jaise `escapeHtml()`) XSS ka fundamental defense hai."}, {"id": "ch1_q43", "termRef": "csrf", "type": "definition", "difficulty": "easy", "question": "What happens in a CSRF (Cross-Site Request Forgery) attack?", "options": ["The attacker installs malware on the victim's device", "The attacker directly steals the victim's password", "The attacker floods the server with traffic", "The attacker tricks the victim's browser into performing an unwanted action using their active login session"], "correctIndex": 3, "explanation": "Tum logged in ho bank.com pe; evil website background mein bank.com ko request bhejti hai tumhare naam se \u2014 tumhare cookies/auth use karke."}, {"id": "ch1_q44", "termRef": "csrf", "type": "category", "difficulty": "medium", "question": "Why does CSRF work?", "options": ["The network connection is unencrypted", "Browsers automatically attach same-domain cookies to every request", "The user's password is weak", "The server's encryption is weak"], "correctIndex": 1, "explanation": "Browser automatically cookies attach karta hai same-domain requests mein \u2014 attacker isi cheez ka fayda uthata hai, tumhara browser khud auth kar deta hai."}, {"id": "ch1_q45", "termRef": "csrf", "type": "analogy", "difficulty": "medium", "question": "Which analogy does the guide use for CSRF?", "options": ["A postman opens and reads your letter", "Someone forces your hand to sign a cheque while you are asleep", "Someone is remotely controlling your phone", "A disease that spreads in different forms"], "correctIndex": 1, "explanation": "CSRF analogy: signature tumhara hai but tumne consciously sign nahi kiya \u2014 browser ne unknowingly action authorize kar diya, jaise neend mein sign karwaana."}, {"id": "ch1_q46", "termRef": "csrf", "type": "defense", "difficulty": "medium", "question": "Which technique does the guide recommend as a defense against CSRF?", "options": ["Regular data backups", "CSRF tokens \u2014 a unique token included in every request", "Antivirus scanning", "A strong password policy"], "correctIndex": 1, "explanation": "CSRF defenses: unique CSRF tokens har request mein, SameSite cookie attribute, aur server-side origin header verification."}, {"id": "ch1_q47", "termRef": "csrf", "type": "scenario", "difficulty": "hard", "question": "While logged into your bank account, you briefly open a random website in a new tab that closes itself immediately. Later, you discover an unauthorized transfer occurred. What likely happened?", "options": ["A botnet infection", "A DDoS attack", "A zero-day exploit", "A CSRF attack"], "correctIndex": 3, "explanation": "Background mein evil website ne tumhare active bank session (cookies) use karke unauthorized request bhej di \u2014 classic CSRF scenario."}, {"id": "ch1_q48", "termRef": "zeroday", "type": "definition", "difficulty": "easy", "question": "Why is it called a 'Zero-Day' exploit?", "options": ["The attack completes within a single day", "The exploit is sold for zero cost on the dark web", "The vendor has had zero days to build a fix, and attackers are already exploiting it", "The attack happens with zero seconds of warning"], "correctIndex": 2, "explanation": "Vulnerability abhi discover hua hai, patch exist nahi karta \u2014 vendor ke paas 'zero days' hain fix karne ke liye, aur attacker already exploit kar raha hai."}, {"id": "ch1_q49", "termRef": "zeroday", "type": "category", "difficulty": "medium", "question": "According to the guide, how much can a zero-day exploit sell for on the dark web?", "options": ["Around $100", "$1 million or more", "Around $1,000", "Around $10,000"], "correctIndex": 1, "explanation": "Zero-day exploits dark web pe $1M+ mein bikte hain \u2014 intelligence agencies bhi buy karti hain, Google Project Zero inhe hunt karta hai."}, {"id": "ch1_q50", "termRef": "zeroday", "type": "real_world", "difficulty": "hard", "question": "How many zero-day exploits did Stuxnet (2010) use simultaneously, which was considered unprecedented?", "options": ["1", "10", "2", "4"], "correctIndex": 3, "explanation": "Stuxnet ne 4 zero-days ek saath use kiye \u2014 Iran ke Natanz facility mein 1,000 centrifuges destroy kiye bina koi bomb use kiye."}, {"id": "ch1_q51", "termRef": "zeroday", "type": "scenario", "difficulty": "hard", "question": "A researcher discovers a new bug with no patch available yet, and attackers are already exploiting it in the wild. What is this called?", "options": ["A botnet attack", "A SQL Injection attack", "A phishing campaign", "A zero-day exploit"], "correctIndex": 3, "explanation": "Bina patch ke, already-exploited-in-the-wild vulnerability \u2014 yehi zero-day exploit ki definition hai."}, {"id": "ch1_q52", "termRef": "malware", "type": "category", "difficulty": "medium", "question": "How many of Chapter 1's 10 terms carry the 'Threat' badge in the guide?", "options": ["5", "3", "7", "All 10"], "correctIndex": 3, "explanation": "Chapter 1 ('Core Threats & Attacks') ke saare 10 terms \u2014 Malware se Zero-Day tak \u2014 'Threat' badge ke saath categorized hain."}, {"id": "ch1_q53", "termRef": "ransomware", "type": "category", "difficulty": "hard", "question": "Based on the guide's severity bars, which of these Chapter 1 threats has the highest listed severity?", "options": ["Ransomware (95%)", "Botnet (80%)", "DDoS (75%)", "CSRF (65%)"], "correctIndex": 0, "explanation": "Guide ke severity bars ke mutabik Ransomware 95% ke saath sabse high hai Chapter 1 mein, jabki Zero-day 98% ke saath overall highest hai."}, {"id": "ch1_q54", "termRef": "phishing", "type": "scenario", "difficulty": "hard", "question": "In a real attack chain, a phishing email first steals an employee's password, which the attacker then uses to perform SQL injection on the company database. What does this illustrate?", "options": ["Multi-stage attacks \u2014 one weak point (phishing) becomes the gateway to a bigger attack (SQLi)", "Phishing and SQLi are never used together", "This is a single-step attack", "This is purely theoretical and doesn't happen in reality"], "correctIndex": 0, "explanation": "Real-world attacks rarely single-technique hote hain \u2014 chapter ke saare threats ek dusre ke saath chain ban sakte hain, isliye har layer ki defense zaroori hai."}]}, "2": {"chapter": 2, "chapterTitle": "Malware Types", "termCount": 10, "questionCount": 50, "questions": [{"id": "ch2_q01", "termRef": "virus", "type": "definition", "difficulty": "easy", "question": "What does a computer virus fundamentally do?", "options": ["Attaches itself to existing files and activates when the infected file is run", "Spreads automatically across a network without any user action", "Disguises itself as legitimate software to trick users into installing it", "Hides at the operating system's kernel level to avoid detection"], "correctIndex": 0, "explanation": "Virus ek malicious code hai jo existing files mein attach ho jaata hai \u2014 jab infected file run hoti hai, virus execute hota hai aur doosri files ko infect karna shuru karta hai."}, {"id": "ch2_q02", "termRef": "virus", "type": "category", "difficulty": "medium", "question": "What is the key characteristic that distinguishes a virus from a worm?", "options": ["A virus can spread entirely on its own across a network", "A virus always disguises itself as useful software", "A virus requires human action (like sharing a file) to spread further", "A virus hides at the kernel level of the OS"], "correctIndex": 2, "explanation": "Virus ko spread hone ke liye human help chahiye \u2014 infected file kisi ko deni padti hai (email, USB, download). Worm ke u\u0932\u091f, yeh automatic nahi hota."}, {"id": "ch2_q03", "termRef": "virus", "type": "real_world", "difficulty": "medium", "question": "The ILOVEYOU virus (2000) spread through an email attachment. How many computers did it infect within 10 days?", "options": ["500,000", "5 million", "50 million", "5 billion"], "correctIndex": 2, "explanation": "ILOVEYOU email attachment 'LOVE-LETTER-FOR-YOU.txt.vbs' ke through millions ne open kiya \u2014 10 din mein 50 million computers infect hue, $10 billion ka damage."}, {"id": "ch2_q04", "termRef": "virus", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use to describe how a virus spreads?", "options": ["Like thousands of bots flooding a server at once", "Like a biological flu virus \u2014 it needs contact with an infected carrier", "Like a postman secretly reading your mail", "Like a fake ID card used to gain trust"], "correctIndex": 1, "explanation": "Biological virus jaisa \u2014 apne aap nahi chalta, kisi infected insaan/file se contact chahiye. Ek infected USB \u2192 PC \u2192 shared drive \u2192 colleagues."}, {"id": "ch2_q05", "termRef": "virus", "type": "scenario", "difficulty": "hard", "question": "You share a USB drive containing an infected file with a colleague, and their computer soon shows the same symptoms as yours. What does this demonstrate?", "options": ["Classic worm behavior \u2014 it spread automatically across the network", "A supply chain attack through the USB manufacturer", "Classic virus behavior \u2014 it spreads only when a human action carries the infected file", "A rootkit hiding itself from both systems"], "correctIndex": 2, "explanation": "Virus ko spread hone ke liye human action chahiye \u2014 file share karna jaisa. Yeh worm se alag hai jo bina kisi help ke khud spread hota hai."}, {"id": "ch2_q06", "termRef": "worm", "type": "definition", "difficulty": "easy", "question": "What makes a worm different from ordinary malware in how it spreads?", "options": ["It requires a user to open an infected file first", "It spreads automatically across a network by exploiting vulnerabilities, with no human action needed", "It disguises itself as a useful application", "It only activates when a specific date is reached"], "correctIndex": 1, "explanation": "Worm standalone hai \u2014 kisi file se attach nahi hota, koi human action nahi chahiye. Network vulnerabilities exploit karke apne aap spread hota hai."}, {"id": "ch2_q07", "termRef": "worm", "type": "category", "difficulty": "medium", "question": "Besides spreading itself, what else can a worm do according to the guide?", "options": ["Carry additional payloads like ransomware or keyloggers and deliver them automatically", "Only record keystrokes", "Only display unwanted advertisements", "Only monitor browsing history"], "correctIndex": 0, "explanation": "Worm network bandwidth kha jaata hai aur side payloads bhi carry karta hai \u2014 jaise ransomware ya keyloggers automatically deliver karna."}, {"id": "ch2_q08", "termRef": "worm", "type": "real_world", "difficulty": "medium", "question": "WannaCry (2017) used the EternalBlue exploit and needed no user action at all. How many computers did it infect across 150 countries?", "options": ["300,000+", "3 million+", "30,000,000+", "30,000+"], "correctIndex": 0, "explanation": "WannaCry ne EternalBlue exploit (NSA ka stolen tool) use karke Windows SMB vulnerability attack ki \u2014 300,000+ computers, 150 countries, bina kisi user action ke."}, {"id": "ch2_q09", "termRef": "worm", "type": "scenario", "difficulty": "hard", "question": "Malware spreads from one machine to an entire office network overnight, with no employee clicking on anything or opening any file. What type of malware behavior does this match?", "options": ["A virus \u2014 requires a human carrier", "Adware \u2014 requires a bundled download", "A Trojan \u2014 requires voluntary installation", "A worm \u2014 self-spreading via network vulnerabilities"], "correctIndex": 3, "explanation": "Bina kisi human action ke poore network mein spread hona worm ki nishaani hai \u2014 ek infected machine se poora network infect ho sakta hai."}, {"id": "ch2_q10", "termRef": "worm", "type": "category", "difficulty": "medium", "question": "What is the practical impact of a worm on a network's infrastructure?", "options": ["It consumes network bandwidth and can overload servers", "It only intercepts keyboard input", "It only affects a single file on a single machine", "It only displays pop-up advertisements"], "correctIndex": 0, "explanation": "Worm network bandwidth kha jaata hai aur servers ko overload kar deta hai \u2014 apne aap replicate hote hue."}, {"id": "ch2_q11", "termRef": "trojan", "type": "definition", "difficulty": "easy", "question": "What is a Trojan Horse malware?", "options": ["Malware that hides at the operating system's kernel level", "Software that appears legitimate and useful but contains malicious code inside", "Malware that spreads automatically without any human action", "Malware that only displays unwanted advertisements"], "correctIndex": 1, "explanation": "Legit software ki tarah dikhta hai (game, utility, crack) par andar malicious code hota hai \u2014 tum khud install karte ho."}, {"id": "ch2_q12", "termRef": "trojan", "type": "category", "difficulty": "medium", "question": "Which of these is NOT one of the Trojan types mentioned in the guide?", "options": ["Downloader Trojan", "Polymorphic Trojan", "Backdoor Trojan", "Banking Trojan"], "correctIndex": 1, "explanation": "Guide mein listed types: Banking Trojans (credentials chori), RATs, Backdoor Trojans, aur Downloader Trojans \u2014 'Polymorphic Trojan' iss list mein nahi hai."}, {"id": "ch2_q13", "termRef": "trojan", "type": "real_world", "difficulty": "medium", "question": "The Zeus Trojan (2007\u20132010) stole banking credentials. How much money did it steal in total?", "options": ["Over $7 billion", "Over $700 million", "Over $7 million", "Over $70 million"], "correctIndex": 3, "explanation": "Zeus Trojan ne 70,000+ organizations affect kiye, $70 million+ chura liye including NASA computers \u2014 typically ek pirated game ke saath aata tha."}, {"id": "ch2_q14", "termRef": "trojan", "type": "analogy", "difficulty": "easy", "question": "Which historical reference inspired the name 'Trojan Horse' malware?", "options": ["A postman secretly opening private letters", "A disease spreading through unaware carriers", "A guard checking IDs at a building entrance", "The Greek mythology story of soldiers hidden inside a gift horse"], "correctIndex": 3, "explanation": "Greek mythology ke Trojan Horse jaisa \u2014 gift ke andar soldiers chhupe the, waise hi legit-looking software ke andar malicious code chhupa hota hai."}, {"id": "ch2_q15", "termRef": "trojan", "type": "scenario", "difficulty": "hard", "question": "You downloaded a cracked version of a paid game from an unofficial website, and weeks later your bank account was accessed without your permission. What likely happened?", "options": ["Your bank's server had a zero-day exploit", "A CSRF attack was executed through your browser", "A Banking Trojan was bundled with the cracked game", "A DDoS attack targeted your bank directly"], "correctIndex": 2, "explanation": "Cracked/pirated software ke saath Trojan bundle hona common hai \u2014 Zeus Trojan jaisa banking Trojan credentials chura leta hai."}, {"id": "ch2_q16", "termRef": "rootkit", "type": "definition", "difficulty": "easy", "question": "What does a rootkit do at a technical level?", "options": ["Spreads automatically through network vulnerabilities", "Records every keystroke a user types", "Installs itself at the operating system's deepest (kernel) level to hide itself and other malware", "Displays unwanted pop-up advertisements"], "correctIndex": 2, "explanation": "Rootkit OS ke deepest level (kernel) mein install hota hai aur apne aap ko aur doosre malware ko antivirus se hide karta hai."}, {"id": "ch2_q17", "termRef": "rootkit", "type": "category", "difficulty": "medium", "question": "Why is a rootkit especially dangerous compared to standard malware?", "options": ["It always disguises itself as a game or utility", "It always spreads without any human action", "Standard antivirus software often cannot detect it because it intercepts system calls and returns fake information", "It is limited to displaying advertisements only"], "correctIndex": 2, "explanation": "Rootkit OS ke andar se hi system calls intercept karta hai aur fake information return karta hai \u2014 remove karna almost impossible ho jaata hai."}, {"id": "ch2_q18", "termRef": "rootkit", "type": "real_world", "difficulty": "hard", "question": "The Sony BMG CD Rootkit scandal (2005) involved Sony secretly embedding a rootkit in music CDs. How many CDs were affected?", "options": ["220 million", "2.2 million", "22 million", "220,000"], "correctIndex": 2, "explanation": "Sony ne music CDs mein rootkit embed kiya DRM ke liye \u2014 22 million CDs affected, bina bataye users ke computers pe install ho jaata tha, massive public outrage."}, {"id": "ch2_q19", "termRef": "rootkit", "type": "scenario", "difficulty": "hard", "question": "Your antivirus keeps reporting the system as 'clean', but Task Manager doesn't show a process that is clearly consuming resources, and the system behaves suspiciously. What is most likely present?", "options": ["A rootkit hiding itself at the kernel level", "A DDoS attack originating from your machine", "Ordinary adware", "A simple phishing email"], "correctIndex": 0, "explanation": "Rootkit ki khaasiyat hi yeh hai ki woh antivirus aur task manager dono se khud ko chhupa leta hai \u2014 system calls intercept karke fake info deta hai."}, {"id": "ch2_q20", "termRef": "rootkit", "type": "category", "difficulty": "medium", "question": "What do the two parts of the word 'Rootkit' refer to?", "options": ["'Root' = a network protocol, 'Kit' = an encryption method", "'Root' = highest admin access, 'Kit' = a collection of tools", "'Root' = a hacking group, 'Kit' = a malware family", "'Root' = the file system, 'Kit' = an antivirus bypass"], "correctIndex": 1, "explanation": "'Root' matlab highest admin access, 'Kit' matlab tools ka collection \u2014 isliye rootkit naam pada."}, {"id": "ch2_q21", "termRef": "keylogger", "type": "definition", "difficulty": "easy", "question": "What does a keylogger do?", "options": ["Quietly records every keystroke and sends the log to the attacker", "Spreads automatically across a network", "Encrypts files and demands a ransom", "Displays unwanted advertisements automatically"], "correctIndex": 0, "explanation": "Background mein quietly tumhare keyboard ke har key press ko record karta hai, phir log file attacker ko bhejta hai \u2014 passwords, messages sab caught."}, {"id": "ch2_q22", "termRef": "keylogger", "type": "category", "difficulty": "medium", "question": "Which of these is NOT one of the keylogger types mentioned in the guide?", "options": ["Cloud-based keylogger", "Browser-based keylogger", "Software keylogger (OS-level hook)", "Hardware keylogger (physical device)"], "correctIndex": 0, "explanation": "Guide ke types: Software (OS level hook), Hardware (physical device between keyboard and PC), Browser-based (form data intercept) \u2014 'Cloud-based' iss list mein nahi hai."}, {"id": "ch2_q23", "termRef": "keylogger", "type": "defense", "difficulty": "medium", "question": "Which defense specifically neutralizes a keylogger's ability to steal a typed password?", "options": ["Using a VPN", "Regularly clearing your browser cache", "Enabling 2FA, since a stolen password alone becomes useless", "Installing a firewall"], "correctIndex": 2, "explanation": "2FA se keylogger useless ho jaata hai passwords ke liye \u2014 password chori bhi ho jaaye, dusra factor attacker ke paas nahi hota."}, {"id": "ch2_q24", "termRef": "keylogger", "type": "scenario", "difficulty": "hard", "question": "Your banking password was compromised despite never clicking any suspicious link, and you recently used a public library computer to check your email. What is a likely cause?", "options": ["A DDoS attack on the bank's servers", "A supply chain attack on your bank", "A hardware or software keylogger installed on the shared public computer", "A CSRF attack from a browser tab"], "correctIndex": 2, "explanation": "Public/shared computers pe keylogger install hone ka risk hota hai \u2014 physical device ya software hook se keystrokes record ho sakti hain."}, {"id": "ch2_q25", "termRef": "keylogger", "type": "category", "difficulty": "medium", "question": "How does a keylogger differ from spyware in scope, according to the guide?", "options": ["A keylogger is broader than spyware", "A keylogger only works on mobile devices", "A keylogger only captures keystrokes, while spyware is broader and can capture screenshots, location, and more", "They are exactly the same thing with different names"], "correctIndex": 2, "explanation": "Keylogger sirf keystrokes capture karta hai, jabki Spyware broader hai \u2014 screenshots, file access, location, social media, call logs sab."}, {"id": "ch2_q26", "termRef": "spyware", "type": "definition", "difficulty": "easy", "question": "What does spyware do once installed on a device?", "options": ["Silently monitors activities like browsing history, location, and camera/microphone access, and sends the data to the attacker", "Only records keyboard input", "Only displays unwanted advertisements", "Encrypts files and demands payment"], "correctIndex": 0, "explanation": "Background mein chup ke tumhari activities monitor karta hai \u2014 browsing history, location, contacts, camera/microphone access, screenshots \u2014 data attacker ko remotely bhejta hai."}, {"id": "ch2_q27", "termRef": "spyware", "type": "real_world", "difficulty": "hard", "question": "Pegasus Spyware (developed by NSO Group) was notable for what unusual infection method?", "options": ["It spread only through infected USB drives", "It required victims to enter their password on a fake page", "It required victims to download a fake update", "Zero-click exploits \u2014 the victim didn't need to click anything at all"], "correctIndex": 3, "explanation": "Pegasus iOS aur Android zero-click exploit se install hota tha \u2014 tumhe kuch click bhi nahi karna. Journalists, activists, world leaders targeted."}, {"id": "ch2_q28", "termRef": "spyware", "type": "scenario", "difficulty": "hard", "question": "A journalist's phone gets compromised without them ever clicking a link, downloading a file, or entering any credentials. What kind of attack does this most closely match?", "options": ["A zero-click spyware attack (like Pegasus)", "A brute force attack on their email password", "A SQL injection attack", "A DDoS attack on their phone carrier"], "correctIndex": 0, "explanation": "Zero-click exploits mein victim ko kuch bhi action lene ki zaroorat nahi \u2014 Pegasus jaisa spyware bina interaction ke install ho sakta hai."}, {"id": "ch2_q29", "termRef": "spyware", "type": "category", "difficulty": "medium", "question": "Which of these is within spyware's typical data-collection scope, according to the guide?", "options": ["Only network traffic between two servers", "Screenshots, camera/microphone access, and location data", "Only firewall log entries", "Only DNS lookup records"], "correctIndex": 1, "explanation": "Spyware broader scope rakhta hai \u2014 screenshots, file access, location, social media, call logs, camera/mic access sab collect kar sakta hai."}, {"id": "ch2_q30", "termRef": "spyware", "type": "category", "difficulty": "hard", "question": "Who reportedly used Pegasus spyware to monitor the network around journalist Jamal Khashoggi, according to the guide?", "options": ["Saudi Arabia", "A US intelligence agency", "A private cybercrime group", "North Korea"], "correctIndex": 0, "explanation": "Guide ke mutabik Saudi Arabia ne Pegasus use kiya journalist Jamal Khashoggi ke network ko monitor karne ke liye."}, {"id": "ch2_q31", "termRef": "adware", "type": "definition", "difficulty": "easy", "question": "What is the primary behavior of adware?", "options": ["Encrypts files and demands a ransom", "Automatically displays unwanted ads such as pop-ups and browser redirects", "Hides itself at the kernel level of the OS", "Records every keystroke silently"], "correctIndex": 1, "explanation": "Adware automatically ads show karta hai \u2014 popups, browser redirects, fake alerts. Revenue generate karta hai advertiser ke liye, free software ke saath bundled aata hai."}, {"id": "ch2_q32", "termRef": "adware", "type": "category", "difficulty": "medium", "question": "Beyond being annoying, what serious risk can adware pose?", "options": ["It can physically damage computer hardware", "It can single-handedly encrypt an entire hard drive", "It always installs a rootkit alongside itself", "Malvertising (malicious ads) can lead to downloading more serious malware"], "correctIndex": 3, "explanation": "Mostly annoying, but some adware spyware ka gateway hai \u2014 malvertising (malicious ads) se serious malware download ho sakta hai, browser settings hijack ho sakti hain."}, {"id": "ch2_q33", "termRef": "adware", "type": "scenario", "difficulty": "medium", "question": "After installing a free utility tool, your browser homepage changed on its own and you now see constant pop-up ads. What has most likely happened?", "options": ["A DDoS attack has occurred", "Adware was bundled with the free software", "A ransomware attack has encrypted your files", "SQL injection has affected your browser"], "correctIndex": 1, "explanation": "Free software ke saath adware bundled aana common hai \u2014 browser hijack, popups, redirects yeh sab adware ki classic symptoms hain."}, {"id": "ch2_q34", "termRef": "adware", "type": "category", "difficulty": "medium", "question": "How does adware typically reach a victim's system?", "options": ["Only through physical USB infection", "Only through unpatched server vulnerabilities", "Only through targeted phishing emails", "Bundled together with free software downloads"], "correctIndex": 3, "explanation": "Adware free software ke saath bundled aata hai often \u2014 user ko pata bhi nahi chalta ki install karte waqt adware bhi saath install ho gaya."}, {"id": "ch2_q35", "termRef": "adware", "type": "category", "difficulty": "hard", "question": "Compared to spyware, what is adware's primary purpose?", "options": ["Providing remote access to the attacker", "Generating advertising revenue rather than stealing personal data (though it can become a gateway to spyware)", "Encrypting files for ransom", "Stealing banking credentials directly"], "correctIndex": 1, "explanation": "Adware ka primary purpose ad revenue generate karna hai, spyware ka primary purpose data churana \u2014 lekin adware kabhi-kabhi spyware ka gateway ban jaata hai."}, {"id": "ch2_q36", "termRef": "fileless", "type": "definition", "difficulty": "easy", "question": "What makes fileless malware difficult for traditional antivirus to detect?", "options": ["It only operates during specific hours of the day", "It disguises its file name to look like a system file", "It only targets mobile devices, which antivirus can't scan", "It runs directly in RAM or abuses legitimate tools like PowerShell, without writing any file to disk"], "correctIndex": 3, "explanation": "Disk pe koi file nahi likhta, directly RAM mein run karta hai ya Windows ke legitimate tools (PowerShell, WMI) abuse karta hai \u2014 antivirus file scan nahi kar sakta kyunki file hi nahi hai."}, {"id": "ch2_q37", "termRef": "fileless", "type": "category", "difficulty": "medium", "question": "What is the technique of abusing an operating system's own legitimate tools for an attack called?", "options": ["Credential Stuffing", "Living-off-the-Land (LotL)", "Supply Chain Compromise", "Privilege Escalation"], "correctIndex": 1, "explanation": "Living-off-the-land (LotL) attack \u2014 PowerShell, cmd, regedit jaise Windows ke apne tools use karta hai, computer restart pe woh gone but damage ho chuka hota hai."}, {"id": "ch2_q38", "termRef": "fileless", "type": "real_world", "difficulty": "hard", "question": "During Operation Cobalt Kitty (2017), how long did the fileless malware attack on a Vietnamese bank remain undetected?", "options": ["6 days", "6 years", "6 months", "6 weeks"], "correctIndex": 2, "explanation": "Operation Cobalt Kitty mein PowerShell aur WMI tools use hone ki wajah se attack 6 mahine tak undetected raha \u2014 $200M+ theft attempt hua."}, {"id": "ch2_q39", "termRef": "fileless", "type": "scenario", "difficulty": "hard", "question": "After a system reboot, security investigators find no malicious file anywhere on disk, yet unusual activity had clearly occurred beforehand. What does this suggest?", "options": ["A fileless malware attack that ran entirely in RAM", "A Trojan disguised as a legitimate program", "Adware bundled with free software", "A standard virus that requires a host file"], "correctIndex": 0, "explanation": "Fileless malware disk pe koi trace nahi chhodta \u2014 RAM mein run hota hai, restart hote hi gayab ho jaata hai, but tab tak damage ho chuka hota hai."}, {"id": "ch2_q40", "termRef": "fileless", "type": "category", "difficulty": "medium", "question": "Which legitimate Windows tools are commonly abused in fileless malware attacks?", "options": ["File Explorer only", "Task Manager and Control Panel", "Notepad and Paint", "PowerShell, cmd, and WMI"], "correctIndex": 3, "explanation": "PowerShell, cmd, regedit \u2014 Windows ke apne legitimate tools use karta hai fileless malware, isliye detect karna mushkil hota hai."}, {"id": "ch2_q41", "termRef": "rat", "type": "definition", "difficulty": "easy", "question": "What can an attacker do once a Remote Access Trojan (RAT) is installed on a victim's PC?", "options": ["Only encrypt files for ransom", "Remotely control the mouse, keyboard, camera, microphone, and files, all without the victim's knowledge", "Only display unwanted advertisements", "Only monitor network bandwidth usage"], "correctIndex": 1, "explanation": "Attacker tumhara poora computer remotely control kar sakta hai \u2014 mouse, keyboard, camera, microphone, files, install software \u2014 TeamViewer jaisa but bina tumhari knowledge ke."}, {"id": "ch2_q42", "termRef": "rat", "type": "category", "difficulty": "medium", "question": "Which of the following is something a RAT-infected computer can be used for, according to the guide?", "options": ["Being added to a botnet", "Only serving as a VPN exit node", "Only mining cryptocurrency", "Only sending spam SMS messages"], "correctIndex": 0, "explanation": "Attacker screen dekh sakta hai live, camera on kar sakta hai, files copy/delete, keylog, bank transfers, screenshot, aur tumhare PC ko botnet mein add kar sakta hai."}, {"id": "ch2_q43", "termRef": "rat", "type": "real_world", "difficulty": "hard", "question": "The Blackshades RAT (2012\u20132014) was created by a 17-year-old and sold on the dark web for how much?", "options": ["$4", "$400", "$40", "$4,000"], "correctIndex": 2, "explanation": "17-year-old Swedish teen ne banaya, $40 pe dark web pe becha \u2014 700,000 computers compromise huye, FBI ne worldwide sting operation chalayi."}, {"id": "ch2_q44", "termRef": "rat", "type": "scenario", "difficulty": "hard", "question": "Your webcam indicator light turns on randomly when you're not using any camera app, and files seem to move on their own. What is most likely happening?", "options": ["A firmware update is in progress", "A Remote Access Trojan (RAT) is giving an attacker control of your device", "A routine antivirus scan is running", "Your webcam driver is malfunctioning"], "correctIndex": 1, "explanation": "Webcam randomly on hona aur files move hona bina apne action ke \u2014 RAT ki classic nishaani hai, attacker ke paas full remote control hai."}, {"id": "ch2_q45", "termRef": "rat", "type": "category", "difficulty": "medium", "question": "Which legitimate software does a RAT most closely resemble in function, minus the victim's consent?", "options": ["Antivirus software", "A password manager", "A web browser", "Remote desktop tools like TeamViewer"], "correctIndex": 3, "explanation": "TeamViewer jaisa, but without your knowledge \u2014 attacker legitimate remote-access tool jaisi hi functionality use karta hai bina consent ke."}, {"id": "ch2_q46", "termRef": "raas", "type": "definition", "difficulty": "easy", "question": "What is Ransomware as a Service (RaaS)?", "options": ["A government program that helps victims recover from ransomware", "A cloud service that automatically backs up files to prevent ransomware", "A type of antivirus subscription service", "A business model where ransomware developers rent out their malware to other attackers on the dark web"], "correctIndex": 3, "explanation": "SaaS ki tarah, but evil \u2014 ransomware developers apna malware dark web pe 'rent' pe dete hain, koi bhi coding nahi jaanta buy kar sakta hai."}, {"id": "ch2_q47", "termRef": "raas", "type": "category", "difficulty": "medium", "question": "In a typical RaaS revenue split, what percentage does the attacker (the person launching the attack) usually keep?", "options": ["90%", "30%", "50%", "70%"], "correctIndex": 3, "explanation": "70-30 split typically \u2014 attacker 70% leta hai ransom ka, developer 30% \u2014 support aur control panel bhi milta hai, pure criminal enterprise."}, {"id": "ch2_q48", "termRef": "raas", "type": "real_world", "difficulty": "medium", "question": "The DarkSide RaaS group (behind the Colonial Pipeline attack) reportedly had which unusual feature?", "options": ["A 'code of ethics' that told affiliates not to attack hospitals", "A public bug bounty program", "Free antivirus for its customers", "Government sponsorship from a G7 nation"], "correctIndex": 0, "explanation": "DarkSide RaaS ki professional website thi, customer support, even ek 'code of ethics' \u2014 hospitals attack mat karo. Pure criminal SaaS business model."}, {"id": "ch2_q49", "termRef": "raas", "type": "scenario", "difficulty": "hard", "question": "Someone with zero programming skills manages to launch a ransomware attack after paying a monthly subscription on the dark web. What business model made this possible?", "options": ["Social Engineering", "Ransomware as a Service (RaaS)", "Supply Chain Attack", "Credential Stuffing"], "correctIndex": 1, "explanation": "RaaS is barrier ko hata deta hai \u2014 koi bhi coding nahi jaanta hue bhi malware rent karke attack launch kar sakta hai."}, {"id": "ch2_q50", "termRef": "raas", "type": "category", "difficulty": "medium", "question": "What does RaaS provide to its 'customers' beyond just the malware itself, according to the guide?", "options": ["Physical hardware for the attack", "Government-issued cybersecurity certifications", "Support, a control panel, and even ransom negotiation services", "Free legal defense if caught"], "correctIndex": 2, "explanation": "Support bhi milta hai, control panel, ransom negotiation services \u2014 full criminal enterprise jaise organized business model."}]}, "3": {"chapter": 3, "chapterTitle": "Defensive Tools & Technologies", "termCount": 10, "questionCount": 50, "questions": [{"id": "ch3_q01", "termRef": "firewall", "type": "definition", "difficulty": "easy", "question": "What does a firewall do?", "options": ["Removes malware that has already infected a system", "Records every keystroke a user types", "Encrypts sensitive data before it is transmitted", "Monitors network traffic and allows or blocks it based on predefined rules"], "correctIndex": 3, "explanation": "Firewall network traffic monitor karta hai aur predefined rules ke basis pe allow ya block karta hai \u2014 border guard ki tarah, passport check karke andar jaane deta hai."}, {"id": "ch3_q02", "termRef": "firewall", "type": "category", "difficulty": "medium", "question": "Which type of firewall performs deep packet inspection and is application-aware?", "options": ["WAF", "Packet Filtering firewall", "Stateful firewall", "NGFW (Next-Generation Firewall)"], "correctIndex": 3, "explanation": "Packet Filtering sirf IP/port check karta hai, Stateful connection state track karta hai, NGFW deep packet inspection karta hai aur app-aware hota hai."}, {"id": "ch3_q03", "termRef": "firewall", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use to explain a firewall?", "options": ["A CCTV control room watching thousands of cameras", "A postman opening and reading letters", "A building's security guard who checks IDs before letting people in", "A chemical lab's glove box for safe testing"], "correctIndex": 2, "explanation": "Building ka security guard analogy \u2014 trusted IP allow, unknown ports block. But smart attacker allowed port use karke bypass kar sakta hai."}, {"id": "ch3_q04", "termRef": "firewall", "type": "scenario", "difficulty": "hard", "question": "An attacker manages to bypass a firewall by disguising malicious traffic as normal traffic over an already-allowed port. What does this demonstrate about firewalls?", "options": ["Firewalls can detect and stop any type of attack automatically", "Firewalls enforce rules but a sufficiently disguised attack can still get through allowed ports", "Firewalls physically prevent all network intrusions", "Firewalls only work on wireless networks"], "correctIndex": 1, "explanation": "Guide khud bolti hai \u2014 smart attacker allowed port use karta hai (bypass). Firewall foolproof nahi hai, sirf ek layer of defense hai."}, {"id": "ch3_q05", "termRef": "firewall", "type": "category", "difficulty": "medium", "question": "Which firewall type is designed specifically to protect web applications?", "options": ["Packet Filtering", "WAF", "NGFW", "Stateful"], "correctIndex": 1, "explanation": "WAF (Web Application Firewall) web apps ke liye specifically design ki gayi hai, jabki baaki types general network traffic handle karte hain."}, {"id": "ch3_q06", "termRef": "antivirus", "type": "definition", "difficulty": "easy", "question": "What is one method antivirus software uses to detect malware?", "options": ["Rewriting the operating system's kernel", "Encrypting the entire hard drive automatically", "Physically isolating the hardware from the network", "Signature-based detection \u2014 matching known malware 'fingerprints'"], "correctIndex": 3, "explanation": "Signature-based: known malware ke 'fingerprints' se match karta hai. Heuristic: suspicious behavior detect karta hai. Sandboxing: isolated environment mein run karke dekhta hai."}, {"id": "ch3_q07", "termRef": "antivirus", "type": "category", "difficulty": "medium", "question": "What is a key limitation of signature-based antivirus software?", "options": ["It struggles against zero-day and polymorphic malware that changes its own code", "It requires a live internet connection to function at all", "It only works against ransomware, not other malware types", "It cannot run on Windows operating systems"], "correctIndex": 0, "explanation": "Signature-based antivirus sirf known threats detect karta hai \u2014 zero-day, fileless, polymorphic malware (jo apna code change karta hai) se bachna mushkil hai."}, {"id": "ch3_q08", "termRef": "antivirus", "type": "category", "difficulty": "medium", "question": "Which antivirus detection method involves running a suspicious file in an isolated environment to observe its behavior?", "options": ["Rate limiting", "Signature-based detection", "Packet filtering", "Sandboxing"], "correctIndex": 3, "explanation": "Sandboxing: isolated environment mein file run karke uska behavior observe kiya jaata hai \u2014 heuristic detection ka ek advanced form."}, {"id": "ch3_q09", "termRef": "antivirus", "type": "scenario", "difficulty": "hard", "question": "A brand-new piece of malware infects several systems before any antivirus vendor has released a signature for it. What does this illustrate?", "options": ["Antivirus software is completely useless in all situations", "The core limitation of purely signature-based antivirus against unknown threats", "The malware must be a rootkit specifically", "Firewalls are more important than antivirus in every case"], "correctIndex": 1, "explanation": "Naya malware jiska signature abhi exist hi nahi karta \u2014 signature-based antivirus use miss kar sakta hai, isliye behavior analysis zaroori hai."}, {"id": "ch3_q10", "termRef": "antivirus", "type": "category", "difficulty": "medium", "question": "What does the guide say is necessary alongside signature-based detection for modern protection?", "options": ["Disabling all software updates", "Using only hardware-based firewalls", "Behavior analysis combined with signature-based detection", "Relying purely on user common sense"], "correctIndex": 2, "explanation": "Guide ke mutabik modern AV + behavior analysis zaroori hai, sirf signature-based detection kaafi nahi hai naye threats ke against."}, {"id": "ch3_q11", "termRef": "ids", "type": "definition", "difficulty": "easy", "question": "What does an IDS (Intrusion Detection System) do when it spots suspicious activity?", "options": ["It automatically shuts down the entire network", "It automatically deletes the malicious files", "It sends an alert to the security team but does not block the traffic itself", "It automatically blocks the traffic in real time"], "correctIndex": 2, "explanation": "IDS network/system traffic monitor karta hai, kuch galat dikhta hai to alert bhejta hai \u2014 but khud kuch nahi karta, sirf bolta hai 'kuch ho raha hai!'"}, {"id": "ch3_q12", "termRef": "ids", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use for an IDS?", "options": ["A security guard who physically stops intruders", "A postman delivering mail", "A smoke detector \u2014 it alerts you to fire but doesn't put it out itself", "A vault door that locks automatically"], "correctIndex": 2, "explanation": "Smoke detector analogy \u2014 aag lagti hai, alarm bajta hai, but khud aag nahi bujhaata. IDS detect karta hai, response human/IPS ka kaam hai."}, {"id": "ch3_q13", "termRef": "ids", "type": "category", "difficulty": "medium", "question": "Which type of IDS monitors an entire network's traffic rather than a single machine?", "options": ["HIDS (Host-based IDS)", "NIDS (Network-based IDS)", "Anomaly-based IDS only", "Signature-based IDS only"], "correctIndex": 1, "explanation": "NIDS: network-based, poora network traffic dekhta hai. HIDS: host-based, ek specific machine dekhta hai \u2014 dono complementary hain."}, {"id": "ch3_q14", "termRef": "ids", "type": "category", "difficulty": "medium", "question": "What is the fundamental difference between an IDS and an IPS?", "options": ["IDS and IPS are exactly the same technology", "IDS only works on wireless networks", "IDS is more expensive than IPS", "IDS only alerts (passive); IPS alerts and automatically blocks (active)"], "correctIndex": 3, "explanation": "IDS = passive (sirf alert), IPS = active (alert + automatically block karta hai) \u2014 yehi fundamental difference hai."}, {"id": "ch3_q15", "termRef": "ids", "type": "scenario", "difficulty": "hard", "question": "A security team receives an alert about suspicious traffic, but the traffic itself was never blocked and continued flowing during the investigation. What kind of system generated this alert?", "options": ["An IDS (Intrusion Detection System)", "A firewall in blocking mode", "A WAF", "An IPS (Intrusion Prevention System)"], "correctIndex": 0, "explanation": "IDS sirf alert deta hai, traffic block nahi karta \u2014 isliye traffic continue flow hoti rehti hai jab tak koi human/IPS action na le."}, {"id": "ch3_q16", "termRef": "ips", "type": "definition", "difficulty": "easy", "question": "How does an IPS (Intrusion Prevention System) respond to a detected threat?", "options": ["It shuts down the entire company network", "It only logs the event for later manual review", "It sends an email to the CEO", "It automatically blocks the traffic in real time as it sits inline in the network path"], "correctIndex": 3, "explanation": "IPS network path mein inline hota hai \u2014 traffic isse hoke jaata hai, woh inspect karta hai, aur block kar sakta hai real-time mein."}, {"id": "ch3_q17", "termRef": "ips", "type": "category", "difficulty": "medium", "question": "What is a notable risk of deploying an IPS in a production environment?", "options": ["It only works on encrypted traffic", "False positives can block legitimate traffic and impact the business", "It requires physical access to every device", "It cannot be configured at all"], "correctIndex": 1, "explanation": "False positives ka risk \u2014 legitimate traffic bhi block ho sakta hai. Production systems mein carefully configure karna padta hai nahi to business impact hota hai."}, {"id": "ch3_q18", "termRef": "ips", "type": "scenario", "difficulty": "hard", "question": "After deploying a new security tool, some legitimate customer traffic starts getting blocked unexpectedly. What is the most likely cause?", "options": ["A DDoS attack against the customers", "A supply chain compromise", "A DNS poisoning attack", "An overly aggressive IPS configuration causing false positives"], "correctIndex": 3, "explanation": "IPS ka known risk hai false positives \u2014 sahi traffic ko bhi galat pattern match karke block kar sakta hai agar carefully configure na ho."}, {"id": "ch3_q19", "termRef": "ips", "type": "category", "difficulty": "medium", "question": "Where does an IPS typically sit within the network architecture?", "options": ["Completely outside the network, offline", "Only on the end-user's personal device", "Inline, directly in the path of network traffic", "Only inside the company's physical server room"], "correctIndex": 2, "explanation": "IPS inline hota hai \u2014 traffic isi se hoke guzarta hai, jisse woh real-time mein inspect aur block kar sakta hai."}, {"id": "ch3_q20", "termRef": "ips", "type": "category", "difficulty": "medium", "question": "Compared to an IDS, what additional capability does an IPS provide?", "options": ["Lower cost only", "Better logging format only", "Active, automatic blocking, not just passive alerting", "Support for more operating systems only"], "correctIndex": 2, "explanation": "IPS ka core value-add hai active response \u2014 sirf alert nahi, automatically block bhi karta hai real-time mein."}, {"id": "ch3_q21", "termRef": "siem", "type": "definition", "difficulty": "easy", "question": "What is the core function of a SIEM (Security Information & Event Management) system?", "options": ["Running penetration tests against the company's own systems", "Encrypting all company emails automatically", "Collecting and correlating logs from across an organization's security tools to identify threats", "Physically blocking network intrusions in real time"], "correctIndex": 2, "explanation": "SIEM poore organization ke saare security tools se logs collect karta hai ek jagah, correlate karta hai, patterns dhundta hai, aur threats identify karta hai."}, {"id": "ch3_q22", "termRef": "siem", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use to describe a SIEM?", "options": ["A postman delivering sealed letters", "A locked vault protecting valuables", "A mall's CCTV control room where a guard watches all cameras on one screen", "A firewall blocking unauthorized visitors"], "correctIndex": 2, "explanation": "CCTV control room analogy \u2014 hazaron cameras ek jagah, guard sab dekh sakta hai ek monitor pe. Alag-alag cameras dekhen to pattern miss ho jaaye, SIEM central view deta hai."}, {"id": "ch3_q23", "termRef": "siem", "type": "category", "difficulty": "medium", "question": "Which of these is listed as a real-world SIEM tool in the guide?", "options": ["Wireshark", "Nmap", "Splunk", "Metasploit"], "correctIndex": 2, "explanation": "Guide mein examples diye hain: Splunk, IBM QRadar, Microsoft Sentinel, LogRhythm \u2014 large enterprises mein terabytes of daily logs ek dashboard pe analyze hote hain."}, {"id": "ch3_q24", "termRef": "siem", "type": "category", "difficulty": "medium", "question": "Which team primarily relies on a SIEM as its main working tool?", "options": ["The HR department", "External auditors only", "The SOC (Security Operations Center) team", "The sales team"], "correctIndex": 2, "explanation": "SIEM SOC team ka main tool hai \u2014 poore organization ke logs ek jagah aa jaate hain jisse analysts patterns dhund sakte hain."}, {"id": "ch3_q25", "termRef": "siem", "type": "scenario", "difficulty": "hard", "question": "A security team notices a subtle attack pattern only after correlating logs from the firewall, the antivirus, and the VPN together \u2014 no single log source showed it clearly alone. What tool made this correlation possible?", "options": ["A single firewall log", "A single IDS alert", "A single antivirus console", "A SIEM"], "correctIndex": 3, "explanation": "SIEM ka poora purpose hi yeh hai \u2014 alag-alag sources ke logs ko correlate karna taaki pattern dikhe jo individually visible nahi hota."}, {"id": "ch3_q26", "termRef": "waf", "type": "definition", "difficulty": "easy", "question": "How does a WAF (Web Application Firewall) differ from a normal firewall?", "options": ["A WAF only works on internal company networks", "A WAF replaces the need for antivirus software entirely", "A WAF blocks all traffic from all sources equally", "A WAF analyzes HTTP traffic specifically, detecting things like SQL injection and XSS"], "correctIndex": 3, "explanation": "Normal firewall packets block karta hai, WAF HTTP traffic ko analyze karta hai specifically \u2014 SQL injection, XSS, CSRF detect aur block karta hai web layer pe."}, {"id": "ch3_q27", "termRef": "waf", "type": "category", "difficulty": "medium", "question": "Where does a WAF typically sit in relation to a web server?", "options": ["Between the web server and the internet", "Only inside a physical server room", "On the end-user's personal device", "Inside the database only"], "correctIndex": 0, "explanation": "Web server aur internet ke beech mein sits \u2014 Cloudflare, AWS WAF, Imperva popular solutions hain, har incoming web request scan karta hai."}, {"id": "ch3_q28", "termRef": "waf", "type": "category", "difficulty": "medium", "question": "Which of the following attack types is a WAF specifically designed to detect and block?", "options": ["Hardware keyloggers", "Lost or stolen laptops", "Physical server room break-ins", "SQL Injection and Cross-Site Scripting (XSS)"], "correctIndex": 3, "explanation": "WAF SQL injection, XSS, CSRF detect aur block karta hai web layer pe \u2014 web-application-specific attacks ke against protection deta hai."}, {"id": "ch3_q29", "termRef": "waf", "type": "scenario", "difficulty": "hard", "question": "An e-commerce website starts blocking malicious input attempts that try to manipulate its database queries through the login form, before they ever reach the application code. Which defensive tool is most likely responsible?", "options": ["An email security gateway", "A WAF", "A honeypot", "A hardware keylogger detector"], "correctIndex": 1, "explanation": "WAF specifically web-layer attacks jaise SQL injection ko web server tak pahunchne se pehle hi block kar deta hai."}, {"id": "ch3_q30", "termRef": "waf", "type": "category", "difficulty": "medium", "question": "Which of these companies offers a well-known WAF solution, according to the guide?", "options": ["Spotify", "Zoom", "Adobe", "Cloudflare"], "correctIndex": 3, "explanation": "Cloudflare, AWS WAF, Imperva \u2014 guide mein listed popular WAF solutions hain."}, {"id": "ch3_q31", "termRef": "endpoint", "type": "definition", "difficulty": "easy", "question": "What does Endpoint Security protect?", "options": ["Only the physical server room", "Only email communication", "Individual devices such as laptops, phones, and tablets", "Only the company's central database server"], "correctIndex": 2, "explanation": "Har individual device (endpoint) ko secure karna \u2014 laptops, phones, tablets, servers \u2014 sirf antivirus nahi, EDR tools real-time behavior monitor karte hain."}, {"id": "ch3_q32", "termRef": "endpoint", "type": "category", "difficulty": "medium", "question": "What does EDR (Endpoint Detection & Response) add beyond traditional antivirus?", "options": ["Real-time behavior analytics, threat hunting, and automated response", "Only faster virus scanning speed", "Only encrypted file storage", "Only better ad-blocking"], "correctIndex": 0, "explanation": "EDR tools (CrowdStrike, SentinelOne) behavior analytics, threat hunting, automated response sab karte hain \u2014 zero-day bhi detect ho sakta hai anomalous behavior se."}, {"id": "ch3_q33", "termRef": "endpoint", "type": "category", "difficulty": "medium", "question": "Which of these tools is mentioned in the guide as a modern EDR solution?", "options": ["Zoom", "Photoshop", "CrowdStrike", "Slack"], "correctIndex": 2, "explanation": "Guide mein CrowdStrike aur SentinelOne examples diye gaye hain \u2014 modern EDR tools jo behavior analytics use karte hain."}, {"id": "ch3_q34", "termRef": "endpoint", "type": "scenario", "difficulty": "hard", "question": "A zero-day threat with no known signature is caught because a security tool noticed unusual behavior on an employee's laptop, not because it matched a known malware pattern. Which category of tool did this?", "options": ["A basic packet-filtering firewall", "An EDR (Endpoint Detection & Response) tool", "A traditional signature-only antivirus", "A simple email spam filter"], "correctIndex": 1, "explanation": "EDR behavior-based detection use karta hai, isliye zero-day bhi anomalous behavior se pakda ja sakta hai \u2014 traditional signature-based antivirus yeh nahi kar paata."}, {"id": "ch3_q35", "termRef": "endpoint", "type": "category", "difficulty": "medium", "question": "Endpoint security has expanded beyond which single tool to become a broader strategy?", "options": ["Antivirus alone", "SIEM alone", "Firewalls alone", "VPNs alone"], "correctIndex": 0, "explanation": "Sirf antivirus nahi \u2014 EDR tools real-time behavior monitor karte hain, endpoint security ab ek broader strategy hai."}, {"id": "ch3_q36", "termRef": "dlp", "type": "definition", "difficulty": "easy", "question": "What is the main purpose of a DLP (Data Loss Prevention) system?", "options": ["Encrypting a company's entire hard drive", "Detecting and blocking network intrusions in real time", "Running penetration tests on company servers", "Preventing sensitive data from leaving the organization through email, USB, or cloud uploads"], "correctIndex": 3, "explanation": "Monitor aur control karta hai ki sensitive data (credit cards, SSN, confidential docs) organization se bahar na jaaye \u2014 email, USB, cloud uploads ke through."}, {"id": "ch3_q37", "termRef": "dlp", "type": "category", "difficulty": "medium", "question": "How does a DLP system typically identify sensitive data being sent out?", "options": ["Content inspection, scanning for patterns like 'confidential' markers", "Randomly blocking all outgoing emails", "Disabling internet access company-wide", "Physically inspecting employee bags at the door"], "correctIndex": 0, "explanation": "Content inspection \u2014 emails scan karta hai 'confidential' patterns ke liye, block kar deta hai ya alert deta hai."}, {"id": "ch3_q38", "termRef": "dlp", "type": "category", "difficulty": "medium", "question": "Against which specific type of risk is DLP described as especially useful?", "options": ["Zero-day exploits against the OS", "Physical building break-ins", "Distributed Denial of Service attacks", "Insider threats"], "correctIndex": 3, "explanation": "Insider threats ke against especially useful hai \u2014 jab koi andar ka hi banda sensitive data bahar bhejne ki koshish kare, DLP catch kar leta hai."}, {"id": "ch3_q39", "termRef": "dlp", "type": "scenario", "difficulty": "hard", "question": "An employee tries to email a spreadsheet containing customer credit card numbers to their personal Gmail account, and the email gets automatically blocked with an alert to security. Which tool caused this?", "options": ["DLP (Data Loss Prevention)", "A sandbox", "An IDS", "A honeypot"], "correctIndex": 0, "explanation": "DLP exactly is scenario ke liye design hui hai \u2014 sensitive data ko organization se bahar jaane se rokna, chahe woh insider ho ya accidental."}, {"id": "ch3_q40", "termRef": "dlp", "type": "category", "difficulty": "medium", "question": "Which of these would a DLP system most likely monitor and control?", "options": ["Incoming network ping requests", "Outgoing emails, USB transfers, and cloud uploads of sensitive data", "The company's public website design", "CPU temperature of servers"], "correctIndex": 1, "explanation": "DLP outgoing channels monitor karta hai jahan se sensitive data organization se bahar ja sakta hai \u2014 email, USB, cloud."}, {"id": "ch3_q41", "termRef": "sandbox", "type": "definition", "difficulty": "easy", "question": "What is a sandbox in cybersecurity?", "options": ["An isolated virtual environment where suspicious files can be run safely without affecting the real system", "A tool for cracking passwords", "A physical safe used to store backup drives", "A type of firewall rule for blocking IPs"], "correctIndex": 0, "explanation": "Isolated virtual environment jahan suspicious files ya programs run kiye jaate hain safely \u2014 agar malware hai to real system affect nahi hoga."}, {"id": "ch3_q42", "termRef": "sandbox", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use for a sandbox?", "options": ["A security guard checking IDs", "A postman delivering sealed letters", "A CCTV control room monitoring cameras", "A chemical lab's glove box for handling hazardous material safely"], "correctIndex": 3, "explanation": "Chemical lab mein hazardous material ke liye glove box jaisa \u2014 bahar effects nahi pahunch sakte, andar jaake experiment kar sakte ho safely."}, {"id": "ch3_q43", "termRef": "sandbox", "type": "category", "difficulty": "medium", "question": "What kinds of items are typically tested in a sandbox before being trusted, according to the guide?", "options": ["Email attachments, unknown executables, and browser extensions", "Only network cables", "Only employee ID badges", "Only physical hardware devices"], "correctIndex": 0, "explanation": "Email attachments, unknown executables, browser extensions \u2014 pehle sandbox mein run karo, behavior dekho, phir decide karo."}, {"id": "ch3_q44", "termRef": "sandbox", "type": "scenario", "difficulty": "hard", "question": "A security team runs a suspicious email attachment in an isolated virtual machine first to observe what it does, before allowing it anywhere near the real company network. What technique is this?", "options": ["Sandboxing", "Digital forensics", "Penetration testing", "Network segmentation"], "correctIndex": 0, "explanation": "Suspicious file ko isolated environment mein run karke behavior dekhna aur real system ko safe rakhna \u2014 yehi sandboxing hai."}, {"id": "ch3_q45", "termRef": "sandbox", "type": "category", "difficulty": "medium", "question": "What is the main benefit of automated malware analysis using a sandbox?", "options": ["It blocks all incoming network traffic", "It reveals a file's real behavior safely, without risking the actual system", "It permanently deletes all malware from the internet", "It automatically patches all known vulnerabilities"], "correctIndex": 1, "explanation": "Automated malware analysis ke liye use hota hai \u2014 file ka actual behavior dekha jaata hai bina real system ko risk mein daale."}, {"id": "ch3_q46", "termRef": "honeypot", "type": "definition", "difficulty": "easy", "question": "What is a honeypot?", "options": ["A password manager for employees", "A device that physically blocks USB ports", "A deliberately vulnerable fake system designed to lure and study attackers", "A tool for encrypting sensitive files"], "correctIndex": 2, "explanation": "Deliberately vulnerable fake system jo attackers ko lure karta hai \u2014 jab attacker ise target karta hai, security team unke tactics study kar sakti hai real-time mein."}, {"id": "ch3_q47", "termRef": "honeypot", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use to describe a honeypot?", "options": ["A police undercover operation or bait car used to lure and catch criminals", "A smoke detector alerting to danger", "A firewall blocking traffic", "A locked vault protecting valuables"], "correctIndex": 0, "explanation": "Police ka undercover operation ya bait car jaisa \u2014 deliberately exposed car chodh ke thieves attract karte hain, phir catch ya study karte hain."}, {"id": "ch3_q48", "termRef": "honeypot", "type": "category", "difficulty": "medium", "question": "What is the main benefit a security team gains from deploying a honeypot?", "options": ["Free legal protection against cybercrime", "Automatic patching of all software vulnerabilities", "Guaranteed elimination of all malware on the network", "Early warning and insight into attacker tactics, techniques, and tools"], "correctIndex": 3, "explanation": "Early warning system hai \u2014 attacker iska real system samajh ke attack karta hai, par actually decoy hai, unke methods log hote hain."}, {"id": "ch3_q49", "termRef": "honeypot", "type": "scenario", "difficulty": "hard", "question": "A company deliberately sets up a fake, poorly-secured server to attract attackers so its security team can study their techniques in real time. What is this technique called?", "options": ["A sandbox", "Network segmentation", "A honeypot", "A firewall"], "correctIndex": 2, "explanation": "Deliberately vulnerable decoy system attackers ko attract karta hai taaki unke tactics study kiye ja sakein \u2014 yehi honeypot ka core concept hai."}, {"id": "ch3_q50", "termRef": "honeypot", "type": "category", "difficulty": "medium", "question": "Why does an attacker fail to realize they are inside a honeypot?", "options": ["Because honeypots automatically disguise the attacker's own IP", "Because it is designed to convincingly look like a real, exploitable system", "Because honeypots require the attacker's login credentials first", "Because honeypots are always physically inaccessible"], "correctIndex": 1, "explanation": "Attacker iska real system samajh ke attack karta hai, par actually decoy hai \u2014 is illusion ki wajah se attacker apne methods reveal kar deta hai."}]}, "4": {"chapter": 4, "chapterTitle": "Encryption & Protocols", "termCount": 10, "questionCount": 50, "questions": [{"id": "ch4_q01", "termRef": "encryption", "type": "definition", "difficulty": "easy", "question": "What does encryption fundamentally do to data?", "options": ["Compresses data to save storage space", "Automatically detects malware inside a file", "Permanently deletes the original data after backup", "Converts plaintext into unreadable ciphertext using an algorithm and a key"], "correctIndex": 3, "explanation": "Plaintext ko ciphertext mein convert karna using an algorithm aur key \u2014 bina key ke garbage, key ke saath original data."}, {"id": "ch4_q02", "termRef": "encryption", "type": "category", "difficulty": "medium", "question": "What is the main difference between symmetric and asymmetric encryption?", "options": ["Symmetric is always slower than asymmetric", "Symmetric encryption can only be used for video files", "Asymmetric encryption doesn't require any key at all", "Symmetric uses the same key for encryption and decryption; asymmetric uses a public/private key pair"], "correctIndex": 3, "explanation": "Symmetric: AES \u2014 same key encrypt aur decrypt karne ke liye, fast. Asymmetric: RSA \u2014 public key se encrypt, private key se decrypt, slower but more secure."}, {"id": "ch4_q03", "termRef": "encryption", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use to describe encryption?", "options": ["A smoke detector sounding an alarm", "A postman delivering sealed letters", "Writing a diary in a secret code language only you understand", "A guard checking IDs at a door"], "correctIndex": 2, "explanation": "Tumhara diary mein secret language likhna jaisa \u2014 sirf tumhe pata hai key kya hai, key ke saath padho, nahi to gibberish."}, {"id": "ch4_q04", "termRef": "encryption", "type": "category", "difficulty": "medium", "question": "Which encryption type is generally faster to perform?", "options": ["Both are exactly equal in speed always", "Asymmetric encryption", "Neither type has a speed difference", "Symmetric encryption"], "correctIndex": 3, "explanation": "Symmetric (AES) fast hai kyunki same key use hoti hai; asymmetric (RSA) slower hai but more secure key exchange ke liye."}, {"id": "ch4_q05", "termRef": "encryption", "type": "scenario", "difficulty": "hard", "question": "Two people who have never met before need to securely exchange a secret key over the internet before they can start using fast symmetric encryption. Which type of encryption is typically used to solve this initial exchange problem?", "options": ["Symmetric encryption alone", "A simple password only", "No encryption is needed", "Asymmetric encryption"], "correctIndex": 3, "explanation": "Asymmetric encryption (public/private key pair) securely key exchange karne ke liye use hoti hai, jiske baad fast symmetric encryption use ho sakti hai \u2014 yeh TLS handshake ka bhi core idea hai."}, {"id": "ch4_q06", "termRef": "e2ee", "type": "definition", "difficulty": "easy", "question": "What does End-to-End Encryption (E2EE) guarantee?", "options": ["The message is automatically translated to any language", "Only the sender and receiver can read the message \u2014 not even the service provider", "The message is stored permanently on the provider's server", "The message is visible to the service provider but not to third parties"], "correctIndex": 1, "explanation": "Message sirf sender ke device pe encrypt hota hai aur sirf receiver ke device pe decrypt hota hai \u2014 server bhi nahi padh sakta, even WhatsApp apne messages nahi padh sakta."}, {"id": "ch4_q07", "termRef": "e2ee", "type": "category", "difficulty": "medium", "question": "According to the guide, which messaging feature is a notable exception where E2EE is NOT applied by default?", "options": ["iMessage between two iPhones", "Signal's regular messages", "Telegram's normal chats (only Secret Chats use E2EE)", "WhatsApp's regular messages"], "correctIndex": 2, "explanation": "Telegram ke Secret Chats hi E2EE use karte hain \u2014 normal chats E2EE nahi hain! Yeh ek common misconception hai."}, {"id": "ch4_q08", "termRef": "e2ee", "type": "scenario", "difficulty": "hard", "question": "A government requests a messaging company hand over the plaintext content of a user's messages, but the company says it technically cannot comply because it never had access to the decrypted content. What technology explains this?", "options": ["End-to-End Encryption (E2EE)", "Network segmentation", "A simple firewall", "A WAF"], "correctIndex": 0, "explanation": "E2EE ki wajah se company khud bhi messages padh nahi sakti \u2014 decryption sirf receiver ke device pe hota hai."}, {"id": "ch4_q09", "termRef": "e2ee", "type": "category", "difficulty": "medium", "question": "Which protocol does WhatsApp use to implement its End-to-End Encryption?", "options": ["SFTP", "SSH", "TLS 1.3 only", "The Signal Protocol"], "correctIndex": 3, "explanation": "WhatsApp Signal Protocol use karta hai E2EE implement karne ke liye \u2014 Signal app khud bhi isi protocol pe based hai."}, {"id": "ch4_q10", "termRef": "e2ee", "type": "category", "difficulty": "medium", "question": "Is regular email typically protected by End-to-End Encryption?", "options": ["Only corporate email is E2EE", "Only Gmail is E2EE, all others are not", "No, regular email is not E2EE by default", "Yes, all email is always E2EE"], "correctIndex": 2, "explanation": "Regular email E2EE nahi hai by default \u2014 isliye email provider technically content padh sakta hai (jab tak koi extra tool use na ho)."}, {"id": "ch4_q11", "termRef": "aes", "type": "definition", "difficulty": "easy", "question": "What is AES?", "options": ["A network monitoring tool", "A type of firewall used to filter web traffic", "A government-approved symmetric encryption algorithm used as an industry standard", "An authentication protocol for logging into websites"], "correctIndex": 2, "explanation": "US government approved symmetric encryption algorithm. AES-128, AES-192, AES-256 (key size) \u2014 industry gold standard."}, {"id": "ch4_q12", "termRef": "aes", "type": "category", "difficulty": "medium", "question": "How practically breakable is AES-256 with today's computing power, according to the guide?", "options": ["Crackable within a day using a normal laptop", "Unbreakable \u2014 even a supercomputer would need billions of years", "Easily crackable within a few hours", "Already broken by known attacks"], "correctIndex": 1, "explanation": "AES-256 is unbreakable with today's computers \u2014 even supercomputer billions of years lagenge is se crack karne mein."}, {"id": "ch4_q13", "termRef": "aes", "type": "category", "difficulty": "medium", "question": "Which of these commonly uses AES encryption, according to the guide?", "options": ["Only old dial-up modems", "Only physical door locks", "Wi-Fi (WPA2), HTTPS, and disk encryption like BitLocker", "Only paper-based filing systems"], "correctIndex": 2, "explanation": "Wi-Fi (WPA2), HTTPS, file encryption, banking, WhatsApp messages, disk encryption (BitLocker, FileVault) \u2014 tum daily AES use karte ho without knowing."}, {"id": "ch4_q14", "termRef": "aes", "type": "scenario", "difficulty": "hard", "question": "Your laptop's disk encryption tool (BitLocker/FileVault) is protecting your files at rest. What underlying encryption algorithm is most likely doing the actual work?", "options": ["MD5", "SHA-256 hashing alone", "AES", "RSA only"], "correctIndex": 2, "explanation": "Disk encryption tools (BitLocker, FileVault) internally AES use karte hain \u2014 yeh symmetric encryption ka industry standard hai."}, {"id": "ch4_q15", "termRef": "aes", "type": "category", "difficulty": "easy", "question": "AES stands for what?", "options": ["Advanced Encryption Standard", "Automated Encryption System", "Authenticated Encryption Service", "Asymmetric Encryption Suite"], "correctIndex": 0, "explanation": "AES = Advanced Encryption Standard \u2014 industry gold standard symmetric encryption algorithm."}, {"id": "ch4_q16", "termRef": "pki", "type": "definition", "difficulty": "easy", "question": "What problem does PKI (Public Key Infrastructure) solve?", "options": ["It blocks malware from running on a device", "It verifies online identity, e.g., confirming that a website is genuinely who it claims to be", "It manages employee login passwords", "It compresses large files for faster transfer"], "correctIndex": 1, "explanation": "PKI public key pairs, digital certificates, Certificate Authorities (CA) ka poora framework hai \u2014 identity verify karta hai online."}, {"id": "ch4_q17", "termRef": "pki", "type": "category", "difficulty": "medium", "question": "What role does a Certificate Authority (CA) play in PKI?", "options": ["It physically manufactures network hardware", "It stores all users' passwords in plaintext", "It is a trusted issuer of digital certificates, like DigiCert or Let's Encrypt", "It blocks DDoS attacks directly"], "correctIndex": 2, "explanation": "CA (Certificate Authority): trusted issuer (DigiCert, Let's Encrypt), Digital Certificate: identity proof, CRL: revoked certificates ki list."}, {"id": "ch4_q18", "termRef": "pki", "type": "category", "difficulty": "medium", "question": "What does a CRL (Certificate Revocation List) contain?", "options": ["A list of certificates that have been revoked and should no longer be trusted", "A list of authorized VPN users", "A list of all encrypted files on a server", "A list of blocked IP addresses"], "correctIndex": 0, "explanation": "CRL: revoked certificates ki list \u2014 jo certificates ab valid nahi hain, unko track karne ke liye."}, {"id": "ch4_q19", "termRef": "pki", "type": "scenario", "difficulty": "hard", "question": "Your browser shows a padlock and confirms a site is genuinely 'google.com' rather than a fake lookalike site. Which underlying framework makes this identity verification possible?", "options": ["A firewall alone", "PKI (Public Key Infrastructure)", "DNS Poisoning defenses alone", "NAT"], "correctIndex": 1, "explanation": "PKI ka poora purpose hi identity verify karna hai online \u2014 CA-issued digital certificates ke through browser confirm karta hai ki site genuine hai."}, {"id": "ch4_q20", "termRef": "pki", "type": "category", "difficulty": "medium", "question": "Which of these is a component of PKI, according to the guide?", "options": ["Sandboxing environments", "Digital Certificate", "Honeypots", "Rate limiting rules"], "correctIndex": 1, "explanation": "PKI ke components: CA, Digital Certificate, aur CRL \u2014 yeh sab milke online trust management system banate hain."}, {"id": "ch4_q21", "termRef": "digicert", "type": "definition", "difficulty": "easy", "question": "What is a digital certificate?", "options": ["A type of malware detection signature", "A physical ID card issued by the government", "An electronic document that proves an entity's identity and contains its public key", "A backup copy of encrypted files"], "correctIndex": 2, "explanation": "Electronic document jo ek entity ki identity prove karta hai aur unki public key contain karta hai \u2014 CA issue karta hai."}, {"id": "ch4_q22", "termRef": "digicert", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use for a digital certificate?", "options": ["A postman delivering sealed letters", "A guard checking IDs at a building", "A passport \u2014 issued by a trusted authority, with your details and an expiry date", "A movie ticket used once"], "correctIndex": 2, "explanation": "Passport jaisa \u2014 government (CA) ne issue kiya, tumhara photo aur details hain (public key), expiry date hai, tamper-proof features hain."}, {"id": "ch4_q23", "termRef": "digicert", "type": "category", "difficulty": "medium", "question": "What does the browser's padlock icon in the address bar represent?", "options": ["That the website has no malware whatsoever", "A valid digital certificate being presented by the website", "That the website loads faster than others", "That the website is government-approved"], "correctIndex": 1, "explanation": "Browser ka padlock icon yahi hai \u2014 digital certificate present ho raha hai, matlab site apni identity prove kar rahi hai."}, {"id": "ch4_q24", "termRef": "digicert", "type": "category", "difficulty": "medium", "question": "Which of these is contained within a digital certificate, according to the guide?", "options": ["The owner's public key and the issuing CA's digital signature", "The user's plaintext password", "The user's home address", "The user's credit card number"], "correctIndex": 0, "explanation": "Contains: owner name, public key, issuing CA, validity dates, domain name, CA's digital signature (tamper proof)."}, {"id": "ch4_q25", "termRef": "digicert", "type": "scenario", "difficulty": "hard", "question": "A bank trusts a customer's document because it carries an official passport-like proof of identity issued by a recognized authority. What is the digital equivalent of this trust mechanism online?", "options": ["A firewall rule", "A digital certificate issued by a Certificate Authority", "A simple username and password", "An IDS alert"], "correctIndex": 1, "explanation": "Bank ne passport dekha \u2192 trust kiya \u2014 online iska equivalent digital certificate hai jo CA ne issue kiya."}, {"id": "ch4_q26", "termRef": "digisig", "type": "definition", "difficulty": "easy", "question": "What does a digital signature provide?", "options": ["Automatic encryption of the entire hard drive", "Protection against network flooding attacks", "Proof that a document was signed by a specific person and hasn't been tampered with (non-repudiation)", "A backup copy of the signed document"], "correctIndex": 2, "explanation": "Apni private key se document ko 'sign' karna \u2014 koi bhi tumhari public key se verify kar sakta hai ki document tumne hi sign kiya aur modify nahi hua. Non-repudiation provide karta hai."}, {"id": "ch4_q27", "termRef": "digisig", "type": "category", "difficulty": "medium", "question": "What is the first step in the digital signature process, according to the guide?", "options": ["Send the document over an unencrypted channel", "Compress the document into a zip file", "Delete the original document", "Generate a hash of the document"], "correctIndex": 3, "explanation": "Process: 1. Document ka hash generate karo, 2. private key se hash encrypt karo (= signature), 3. Receiver same hash generate kar verify karta hai."}, {"id": "ch4_q28", "termRef": "digisig", "type": "category", "difficulty": "medium", "question": "Which key is used to create a digital signature, and which key is used to verify it?", "options": ["No key is needed for either step", "The signer's private key creates it; the signer's public key verifies it", "The signer's public key creates it; the signer's private key verifies it", "Both creation and verification use the same shared secret password"], "correctIndex": 1, "explanation": "Private key se hash encrypt karke signature banta hai; receiver public key se signature decrypt karke verify karta hai."}, {"id": "ch4_q29", "termRef": "digisig", "type": "scenario", "difficulty": "hard", "question": "A contract's recipient can mathematically prove the sender actually signed it and that no one altered even a single word afterward. Which security concept guarantees this?", "options": ["Network segmentation", "NAT", "Digital Signature", "A firewall rule"], "correctIndex": 2, "explanation": "Digital signature non-repudiation provide karta hai \u2014 sender deny nahi kar sakta ki usne sign kiya, aur tampering bhi detect ho jaati hai."}, {"id": "ch4_q30", "termRef": "digisig", "type": "category", "difficulty": "medium", "question": "What security property specifically means 'the signer cannot later deny having signed the document'?", "options": ["Anonymity", "Availability", "Non-repudiation", "Confidentiality"], "correctIndex": 2, "explanation": "Non-repudiation exactly yehi property hai \u2014 digital signature ka primary benefit."}, {"id": "ch4_q31", "termRef": "ssl", "type": "definition", "difficulty": "easy", "question": "What is the current status of SSL, according to the guide?", "options": ["Still the most current and secure protocol in use", "Technically deprecated and replaced by TLS, though the term 'SSL' is still commonly used", "Never existed \u2014 it was always called TLS", "A hardware device used to encrypt disks"], "correctIndex": 1, "explanation": "Ab technically deprecated hai \u2014 TLS use hota hai, par 'SSL' term abhi bhi common usage mein hai."}, {"id": "ch4_q32", "termRef": "ssl", "type": "category", "difficulty": "medium", "question": "Why was SSL 3.0 specifically abandoned, according to the guide?", "options": ["It required a paid license to use", "It had the POODLE vulnerability", "It was too slow for modern internet speeds", "It was never adopted by any browser"], "correctIndex": 1, "explanation": "SSL 3.0 mein POODLE vulnerability thi isliye abandon kiya gaya \u2014 TLS 1.0 se aage evolution hua."}, {"id": "ch4_q33", "termRef": "ssl", "type": "category", "difficulty": "medium", "question": "What is the correct chronological evolution from SSL to the current standard, according to the guide?", "options": ["TLS 1.3 \u2192 SSL 3.0 \u2192 SSL 2.0 \u2192 TLS 1.0", "SSL 3.0 \u2192 TLS 1.3 \u2192 SSL 2.0 \u2192 TLS 1.0", "SSL 2.0 \u2192 SSL 3.0 \u2192 TLS 1.0 \u2192 TLS 1.3", "TLS 1.0 \u2192 SSL 2.0 \u2192 SSL 3.0 \u2192 TLS 1.3"], "correctIndex": 2, "explanation": "SSL 2.0 (1995) \u2192 SSL 3.0 \u2192 TLS 1.0 \u2192 TLS 1.1 \u2192 TLS 1.2 \u2192 TLS 1.3 (current) \u2014 yeh sahi chronological order hai."}, {"id": "ch4_q34", "termRef": "ssl", "type": "scenario", "difficulty": "hard", "question": "A colleague refers to a website's 'SSL certificate,' even though the site is actually using the modern TLS protocol underneath. What does this illustrate?", "options": ["SSL and TLS are entirely unrelated technologies", "The colleague is completely wrong and the site is insecure", "TLS is actually older than SSL", "The term 'SSL' is still used colloquially even though TLS has replaced it technically"], "correctIndex": 3, "explanation": "Guide khud bolti hai 'SSL' term abhi bhi common hai, chahe technically TLS use ho raha ho \u2014 industry jargon mein legacy naming persist karta hai."}, {"id": "ch4_q35", "termRef": "ssl", "type": "category", "difficulty": "easy", "question": "What does SSL stand for?", "options": ["Secure Sockets Layer", "Standard Socket Language", "Secure Server Login", "System Security Layer"], "correctIndex": 0, "explanation": "SSL = Secure Sockets Layer \u2014 secure communication protocol jo ab TLS se replace ho chuka hai."}, {"id": "ch4_q36", "termRef": "tls", "type": "definition", "difficulty": "easy", "question": "What is actually running behind the scenes when you use HTTPS today?", "options": ["Telnet", "FTP", "SSL 2.0", "TLS"], "correctIndex": 3, "explanation": "Jab tum HTTPS use karte ho, actually TLS run ho raha hai \u2014 current secure communication protocol jo encryption, authentication, integrity teeno provide karta hai."}, {"id": "ch4_q37", "termRef": "tls", "type": "category", "difficulty": "medium", "question": "What is the first step of a TLS handshake, according to the guide?", "options": ["The client says 'Hello, I support TLS 1.3'", "The server immediately sends encrypted data", "The client sends its password in plaintext", "The connection is closed automatically"], "correctIndex": 0, "explanation": "1. Client: 'Hello, I support TLS 1.3', 2. Server: 'OK, here's my certificate', 3. Key exchange, 4. Encrypted communication begins."}, {"id": "ch4_q38", "termRef": "tls", "type": "category", "difficulty": "medium", "question": "Which three properties does TLS provide together, according to the guide?", "options": ["Encryption, authentication, and integrity", "Speed, compression, and caching", "Backup, recovery, and archiving", "Firewalling, sandboxing, and logging"], "correctIndex": 0, "explanation": "TLS encryption, authentication, integrity \u2014 teeno provide karta hai simultaneously, sirf data hide karna nahi."}, {"id": "ch4_q39", "termRef": "tls", "type": "scenario", "difficulty": "hard", "question": "During a connection setup, the server sends its certificate to the client, and both sides then exchange keys before any actual data is sent. What process is this describing?", "options": ["A TLS handshake", "A firewall rule update", "A DDoS attack", "A DNS lookup"], "correctIndex": 0, "explanation": "Yeh exactly TLS handshake ka process hai \u2014 hello, certificate exchange, key exchange, phir encrypted communication begins."}, {"id": "ch4_q40", "termRef": "tls", "type": "category", "difficulty": "easy", "question": "What does TLS stand for?", "options": ["Transport Layer Security", "Trusted Local System", "Total Link Security", "Traffic Load Sensor"], "correctIndex": 0, "explanation": "TLS = Transport Layer Security \u2014 SSL ka successor, internet ki backbone security protocol."}, {"id": "ch4_q41", "termRef": "https", "type": "definition", "difficulty": "easy", "question": "What is HTTPS made of, according to the guide?", "options": ["HTTP + a VPN", "HTTP + a firewall", "HTTP + AES only", "HTTP + TLS"], "correctIndex": 3, "explanation": "HTTP (web protocol) + TLS (encryption) = HTTPS. Browser ka padlock icon = HTTPS."}, {"id": "ch4_q42", "termRef": "https", "type": "category", "difficulty": "medium", "question": "What common misconception does the guide correct about HTTPS?", "options": ["HTTPS makes a website completely immune to hacking", "HTTPS does not mean the site itself is trustworthy \u2014 it only means the connection is encrypted", "HTTPS automatically blocks all phishing attempts", "HTTPS is only used by government websites"], "correctIndex": 1, "explanation": "HTTPS = secure site NAHI. Sirf matlab hai connection encrypted hai. Fake phishing sites bhi HTTPS use karti hain. Padlock \u2260 trustworthy website."}, {"id": "ch4_q43", "termRef": "https", "type": "scenario", "difficulty": "hard", "question": "A phishing website has a valid padlock icon and uses HTTPS, yet it is still designed to steal your login credentials. What does this demonstrate?", "options": ["HTTPS automatically verifies a site's honesty", "The browser has a bug if this occurs", "HTTPS certificates are never issued to malicious sites, so this can't happen", "HTTPS only guarantees an encrypted connection, not that the site itself is legitimate"], "correctIndex": 3, "explanation": "Exactly the misconception the guide warns about \u2014 fake phishing sites bhi HTTPS use kar sakti hain, padlock trustworthiness ki guarantee nahi deta."}, {"id": "ch4_q44", "termRef": "https", "type": "category", "difficulty": "medium", "question": "What does the padlock icon in a browser's address bar specifically indicate?", "options": ["That the website has been manually reviewed by the browser vendor", "That the website has no ads", "That the website is hosted in the user's own country", "That HTTPS (encrypted transit) is being used"], "correctIndex": 3, "explanation": "Padlock icon = HTTPS active hai, data encrypted hai transit mein \u2014 MITM attacker garbled text hi dekhega \u2014 but yeh site ki legitimacy guarantee nahi karta."}, {"id": "ch4_q45", "termRef": "https", "type": "category", "difficulty": "medium", "question": "If a MITM attacker intercepts traffic on an HTTPS-protected connection, what will they typically see?", "options": ["The exact plaintext of the conversation", "Only the sender's IP address in plaintext, nothing else", "Garbled, encrypted text they cannot easily read", "A full copy of the user's password in plaintext, always"], "correctIndex": 2, "explanation": "Data encrypted hai transit mein \u2014 MITM attacker garbled text hi dekhega, yehi HTTPS ka core protection hai."}, {"id": "ch4_q46", "termRef": "ssh", "type": "definition", "difficulty": "easy", "question": "What is SSH primarily used for?", "options": ["Encrypting emails end-to-end", "Securely accessing a remote server from the command line", "Scanning files for malware signatures", "Blocking malicious web traffic"], "correctIndex": 1, "explanation": "Remote server ko securely access karna command line se \u2014 web developers, system admins daily use karte hain."}, {"id": "ch4_q47", "termRef": "ssh", "type": "category", "difficulty": "medium", "question": "Which older, unencrypted protocol did SSH replace in 1995?", "options": ["HTTP", "SMTP", "FTP", "Telnet"], "correctIndex": 3, "explanation": "Telnet (unencrypted predecessor) ko replace kiya 1995 mein \u2014 SSH ne encrypted alternative provide kiya."}, {"id": "ch4_q48", "termRef": "ssh", "type": "category", "difficulty": "medium", "question": "What is a more secure alternative to password login when using SSH?", "options": ["Using a 4-digit PIN instead", "Disabling authentication entirely", "SSH keys, where the public key sits on the server and the private key stays with the user", "Sharing the same password across all servers"], "correctIndex": 2, "explanation": "Password ke alawa SSH keys use kar sakte ho \u2014 more secure. Public key server pe, private key tumhare paas \u2014 brute force practically impossible."}, {"id": "ch4_q49", "termRef": "ssh", "type": "scenario", "difficulty": "hard", "question": "A system administrator connects to a remote Linux server to run commands, and the entire session is encrypted so no one on the network can see the commands or their output. Which protocol enables this?", "options": ["Plain Telnet", "Plain HTTP", "Unencrypted FTP", "SSH"], "correctIndex": 3, "explanation": "SSH exactly is use case ke liye design hui hai \u2014 encrypted remote server access via command line."}, {"id": "ch4_q50", "termRef": "ssh", "type": "category", "difficulty": "medium", "question": "Why is brute-forcing an SSH connection secured with SSH keys considered 'practically impossible'?", "options": ["Because SSH blocks all connection attempts automatically", "Because SSH doesn't allow remote connections at all", "Because the private key never leaves the user's device and isn't a guessable password", "Because SSH keys expire every second"], "correctIndex": 2, "explanation": "Private key kabhi network pe transmit nahi hoti aur itni complex hoti hai ki brute force practically impossible ho jaata hai."}]}, "5": {"chapter": 5, "chapterTitle": "Identity & Access Management", "termCount": 10, "questionCount": 50, "questions": [{"id": "ch5_q01", "termRef": "2fa", "type": "definition", "difficulty": "easy", "question": "What does Two-Factor Authentication (2FA) require at login?", "options": ["Something you know (password) plus something you have or are (like an OTP or fingerprint)", "Only your device's IP address", "Only a security question", "Only a strong, complex password"], "correctIndex": 0, "explanation": "Login ke liye 2 cheezein chahiye: kuch tum jaante ho (password) + kuch tumhare paas hai (phone OTP) ya kuch tum ho (fingerprint) \u2014 password chori bhi ho to koi faida nahi attacker ko."}, {"id": "ch5_q02", "termRef": "2fa", "type": "category", "difficulty": "medium", "question": "Which 2FA method is described as the weakest, due to SIM swap risk?", "options": ["SMS OTP", "Biometric", "Hardware Key (YubiKey)", "Authenticator App"], "correctIndex": 0, "explanation": "SMS OTP (weakest \u2014 SIM swap possible), Authenticator App (better), Hardware Key (strongest \u2014 YubiKey), Biometric."}, {"id": "ch5_q03", "termRef": "2fa", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use for 2FA?", "options": ["An ATM \u2014 you need both your PIN and your physical card", "A postman delivering sealed letters", "A chemical lab's glove box", "A CCTV control room"], "correctIndex": 0, "explanation": "ATM analogy \u2014 PIN (kuch tum jaante ho) + ATM card (kuch tumhare paas hai). Sirf PIN nahi, sirf card nahi \u2014 dono chahiye."}, {"id": "ch5_q04", "termRef": "2fa", "type": "real_world", "difficulty": "hard", "question": "In the 2023 MGM Resorts hack, how much loss was directly attributed to missing MFA, according to the guide?", "options": ["$1 million", "$1 billion", "$10 million", "$100 million or more"], "correctIndex": 3, "explanation": "Social engineering se employee credentials mili, agar proper MFA hota to hack fail ho jaata \u2014 $100M+ loss directly 2FA missing ki wajah se."}, {"id": "ch5_q05", "termRef": "2fa", "type": "scenario", "difficulty": "hard", "question": "An attacker steals your password through a phishing email, but fails to log into your account because they don't have the OTP sent to your phone. What protected you?", "options": ["Network segmentation", "A firewall", "A honeypot", "2FA (Two-Factor Authentication)"], "correctIndex": 3, "explanation": "2FA exactly is scenario ke liye design hui hai \u2014 password chori bhi ho jaaye, dusra factor attacker ke paas nahi hota."}, {"id": "ch5_q06", "termRef": "mfa", "type": "definition", "difficulty": "easy", "question": "How does MFA differ from 2FA?", "options": ["MFA and 2FA are completely unrelated concepts", "MFA only applies to banking systems", "MFA can use two or more factors, while 2FA specifically means exactly two", "2FA is stronger than MFA in every case"], "correctIndex": 2, "explanation": "2FA specifically 2 factors. MFA = 2 ya zyada factors \u2014 MFA is 2FA ka superset."}, {"id": "ch5_q07", "termRef": "mfa", "type": "category", "difficulty": "medium", "question": "Which of these is NOT one of the three core MFA factor categories listed in the guide?", "options": ["Inherence (something you are)", "Possession (something you have)", "Knowledge (something you know)", "Location you frequently visit"], "correctIndex": 3, "explanation": "Three core categories: Knowledge (password), Possession (phone/token), Inherence (biometric). Location-based hai ek bonus layer, core category nahi."}, {"id": "ch5_q08", "termRef": "mfa", "type": "category", "difficulty": "medium", "question": "Which factor category does a fingerprint scan belong to?", "options": ["Location (where you are)", "Possession (something you have)", "Inherence (something you are)", "Knowledge (something you know)"], "correctIndex": 2, "explanation": "\ud83d\udc41\ufe0f Are: fingerprint, face, iris, voice \u2014 yeh sab Inherence category mein aate hain."}, {"id": "ch5_q09", "termRef": "mfa", "type": "scenario", "difficulty": "hard", "question": "A company requires employees to enter a password, tap approve on an authenticator app, AND scan their fingerprint to log in. How many distinct factor categories does this use?", "options": ["Three \u2014 knowledge, possession, and inherence", "Only one \u2014 knowledge", "Only two \u2014 possession and inherence", "Zero, since these aren't real factors"], "correctIndex": 0, "explanation": "Password = knowledge, authenticator app = possession, fingerprint = inherence \u2014 teeno categories mix karna MFA ko harder to breach banata hai."}, {"id": "ch5_q10", "termRef": "mfa", "type": "category", "difficulty": "medium", "question": "Why does mixing multiple factor categories make an account harder to breach?", "options": ["Because it disables the password entirely", "Because it changes the account's IP address", "Because it slows down the login page loading time", "Because an attacker would need to compromise multiple, fundamentally different types of proof simultaneously"], "correctIndex": 3, "explanation": "Mix karo \u2014 harder to breach, kyunki attacker ko alag-alag categories (jaante ho, paas hai, tum ho) sabhi compromise karni padengi."}, {"id": "ch5_q11", "termRef": "iam", "type": "definition", "difficulty": "easy", "question": "What does IAM (Identity & Access Management) define?", "options": ["How malware is detected on endpoints", "Which user can access which resource within an organization", "How fast a network connection is", "How data is encrypted during transit"], "correctIndex": 1, "explanation": "Framework aur tools jo define karte hain ki kaun user kaun sa resource access kar sakta hai \u2014 user accounts banao, permissions assign karo, review karo."}, {"id": "ch5_q12", "termRef": "iam", "type": "category", "difficulty": "medium", "question": "What does the 'Principle of Least Privilege' in IAM mean?", "options": ["Every user should have full admin access by default", "Access should never be reviewed once granted", "Each user should only get the minimum access absolutely necessary for their job", "Only the CEO should have any system access"], "correctIndex": 2, "explanation": "Least Privilege: har user sirf woh access mile jo kaam ke liye absolutely zaroori hai \u2014 extra nahi."}, {"id": "ch5_q13", "termRef": "iam", "type": "category", "difficulty": "medium", "question": "Which of these is mentioned in the guide as a popular IAM tool?", "options": ["Okta", "Photoshop", "Slack", "Zoom"], "correctIndex": 0, "explanation": "Okta, Microsoft Azure AD popular IAM tools hain guide ke mutabik."}, {"id": "ch5_q14", "termRef": "iam", "type": "scenario", "difficulty": "hard", "question": "A database administrator requests access to the company's billing system for an unrelated task, but the request is denied because it isn't required for their role. What IAM principle is being enforced?", "options": ["Least Privilege", "Zero Trust exclusively", "Single Sign-On", "Multi-Factor Authentication"], "correctIndex": 0, "explanation": "Agar DB admin ko billing system access nahi chahiye kaam ke liye, nahi milega \u2014 yehi Least Privilege principle hai."}, {"id": "ch5_q15", "termRef": "iam", "type": "category", "difficulty": "medium", "question": "What two actions does an IAM system typically perform for every user, according to the guide?", "options": ["Only monitor internet speed", "Only manage physical door locks", "Only track employee attendance", "Create accounts and assign permissions"], "correctIndex": 3, "explanation": "User accounts banao, permissions assign karo, review karo \u2014 yeh IAM ke core functions hain."}, {"id": "ch5_q16", "termRef": "pam", "type": "definition", "difficulty": "easy", "question": "What does PAM (Privileged Access Management) specifically protect?", "options": ["Only the physical office building", "Privileged accounts like admins, root, and service accounts", "Regular employee email accounts only", "Only guest WiFi access"], "correctIndex": 1, "explanation": "IAM ka subset jo specifically privileged accounts (admins, root, service accounts) ko protect karta hai \u2014 highest risk accounts."}, {"id": "ch5_q17", "termRef": "pam", "type": "category", "difficulty": "medium", "question": "What is 'just-in-time access' in the context of PAM?", "options": ["Granting privileged access only when it is actually needed, not permanently", "Giving every employee permanent admin rights", "Allowing access only during office hours", "Removing all access controls entirely"], "correctIndex": 0, "explanation": "Just-in-time access (sirf jab zaroori) \u2014 PAM ka ek key feature, permanent privileged access ka risk kam karta hai."}, {"id": "ch5_q18", "termRef": "pam", "type": "category", "difficulty": "medium", "question": "Which PAM feature records what an admin actually did during a privileged session?", "options": ["MFA enforcement", "Just-in-time access", "Password vaulting", "Session recording"], "correctIndex": 3, "explanation": "Session recording (admin ne kya kiya) ek core PAM feature hai \u2014 accountability aur audit ke liye zaroori."}, {"id": "ch5_q19", "termRef": "pam", "type": "category", "difficulty": "medium", "question": "Why are privileged accounts considered especially high-risk, according to the guide?", "options": ["Because they are only used for marketing tasks", "Because they are never used by anyone in the company", "Because they have no password at all", "Because controlling them means gaining full control of the system"], "correctIndex": 3, "explanation": "These accounts are highest risk \u2014 inka control matlab full system control, isliye special protection zaroori hai."}, {"id": "ch5_q20", "termRef": "pam", "type": "scenario", "difficulty": "hard", "question": "A company automatically rotates its admin account passwords regularly and stores them in a secure vault rather than letting employees memorize static passwords. Which PAM feature does this describe?", "options": ["Token-based authentication", "Single Sign-On", "Zero Trust", "Password vaulting"], "correctIndex": 3, "explanation": "Password vaulting (auto-rotate passwords) \u2014 PAM ka feature jo privileged account passwords ko securely manage karta hai."}, {"id": "ch5_q21", "termRef": "sso", "type": "definition", "difficulty": "easy", "question": "What does Single Sign-On (SSO) allow a user to do?", "options": ["Log in once and automatically gain access to multiple connected apps", "Only access one app forever without any other access", "Use a different password for every single application", "Bypass all authentication requirements entirely"], "correctIndex": 0, "explanation": "Ek baar login karo (Google ya company account se), sab apps automatically accessible \u2014 'Sign in with Google' = SSO."}, {"id": "ch5_q22", "termRef": "sso", "type": "category", "difficulty": "medium", "question": "Which technologies commonly power SSO behind the scenes, according to the guide?", "options": ["DNS and DHCP", "OAuth and SAML", "TCP and UDP", "AES and RSA only"], "correctIndex": 1, "explanation": "Token exchange hota hai behind the scenes (OAuth, SAML) \u2014 yeh SSO ko technically implement karne wale protocols hain."}, {"id": "ch5_q23", "termRef": "sso", "type": "category", "difficulty": "medium", "question": "What is the biggest security risk associated with SSO?", "options": ["It makes logging in slower for users", "If the SSO account is compromised, all connected apps become compromised too", "It requires every app to have a separate password", "It cannot be used with MFA at all"], "correctIndex": 1, "explanation": "SSO account compromise = sab apps compromise \u2014 isliye SSO account pe strong MFA absolutely zaroori. 'Single point of failure' bhi ho sakta hai."}, {"id": "ch5_q24", "termRef": "sso", "type": "scenario", "difficulty": "hard", "question": "An attacker compromises an employee's single company Google account and suddenly gains access to a dozen connected internal tools without needing separate passwords for each. What made this possible?", "options": ["SSO \u2014 a single compromised account exposed every connected app", "Network segmentation failure", "A firewall bypass", "A honeypot misconfiguration"], "correctIndex": 0, "explanation": "Yeh exactly SSO ka risk hai \u2014 single point of failure, isliye strong MFA SSO account pe zaroori hai."}, {"id": "ch5_q25", "termRef": "sso", "type": "category", "difficulty": "easy", "question": "Which everyday feature is a real-world example of SSO?", "options": ["Using a physical key to open a door", "Entering a separate password for every website", "Scanning a fingerprint on your own phone only", "'Sign in with Google' buttons on other websites"], "correctIndex": 3, "explanation": "'Sign in with Google' = SSO \u2014 ek baar login, sab apps automatically accessible."}, {"id": "ch5_q26", "termRef": "zerotrust", "type": "definition", "difficulty": "easy", "question": "What is the core principle of Zero Trust Security?", "options": ["Trust is based purely on job title", "Trust every device that connects to the internal network automatically", "Never trust, always verify \u2014 no user or device is trusted by default, inside or outside the network", "Only verify users once a year"], "correctIndex": 2, "explanation": "Traditional model: network ke andar ho to trusted. Zero Trust: andar ya bahar koi fark nahi \u2014 har request verify karo, least privilege do, assume breach."}, {"id": "ch5_q27", "termRef": "zerotrust", "type": "category", "difficulty": "medium", "question": "Why has Zero Trust become especially important in the remote work and cloud era, according to the guide?", "options": ["Because cloud services don't require any authentication", "Because passwords have become obsolete entirely", "Because all employees now work from a single physical office", "Because the traditional concept of a fixed 'corporate network' boundary no longer applies"], "correctIndex": 3, "explanation": "Remote work, cloud era mein 'corporate network' ka concept gone. Employees anywhere se kaam karte hain \u2014 Zero Trust ke bina insider threats devastating ho sakte hain."}, {"id": "ch5_q28", "termRef": "zerotrust", "type": "real_world", "difficulty": "hard", "question": "Google's BeyondCorp, the industry's first large-scale Zero Trust implementation, was built following which major security incident?", "options": ["The SolarWinds breach", "The WannaCry outbreak", "The Colonial Pipeline attack", "Operation Aurora (2010 China hack)"], "correctIndex": 3, "explanation": "Google ka BeyondCorp \u2014 post-Operation Aurora (2010 China hack) \u2014 industry ka pehla large-scale Zero Trust implementation, ab industry standard recommendation."}, {"id": "ch5_q29", "termRef": "zerotrust", "type": "scenario", "difficulty": "hard", "question": "An employee working from home, connected via the company VPN, is still required to re-verify their identity for every sensitive request, exactly as if they were an unknown external user. What philosophy is being applied?", "options": ["SSO without MFA", "No security policy at all", "Zero Trust Security", "Traditional perimeter-based trust"], "correctIndex": 2, "explanation": "'Never trust, always verify' \u2014 andar ya bahar koi fark nahi, har request verify karna Zero Trust ka core hai."}, {"id": "ch5_q30", "termRef": "zerotrust", "type": "category", "difficulty": "medium", "question": "How does the traditional security model differ fundamentally from Zero Trust?", "options": ["There is no real difference between the two models", "Traditional model trusts anyone already inside the network; Zero Trust trusts no one by default", "Zero Trust only applies to physical security, not digital", "Traditional model has no concept of passwords at all"], "correctIndex": 1, "explanation": "Traditional model: network ke andar ho to trusted. Zero Trust: 'Trust but verify' se 'Never trust, always verify' ki taraf shift."}, {"id": "ch5_q31", "termRef": "accesscontrol", "type": "definition", "difficulty": "easy", "question": "What is the general purpose of access control models?", "options": ["Managing a company's physical inventory", "Encrypting network traffic between two devices", "Detecting malware signatures automatically", "Enforcing policy on who can access which resources"], "correctIndex": 3, "explanation": "Resources tak kaun ja sakta hai \u2014 policy enforcement, alag-alag models (DAC, MAC, RBAC, ABAC) yeh alag tareeke se karte hain."}, {"id": "ch5_q32", "termRef": "accesscontrol", "type": "category", "difficulty": "medium", "question": "In which access control model does the system (rather than the resource owner) decide access, typically used for classified/military data?", "options": ["ABAC (Attribute-Based Access Control)", "RBAC (Role-Based Access Control)", "DAC (Discretionary Access Control)", "MAC (Mandatory Access Control)"], "correctIndex": 3, "explanation": "MAC: system decide karta hai (military, classified). DAC: owner decide karta hai (files on your PC)."}, {"id": "ch5_q33", "termRef": "accesscontrol", "type": "category", "difficulty": "medium", "question": "Which access control model grants permissions based on job roles, like 'HR', 'Finance', or 'Developer'?", "options": ["MAC (Mandatory Access Control)", "None of these use roles", "DAC (Discretionary Access Control)", "RBAC (Role-Based Access Control)"], "correctIndex": 3, "explanation": "RBAC: role-based (employees, managers, admins). HR role = employee data access, Finance role = payroll access, Developer role = code repo access."}, {"id": "ch5_q34", "termRef": "accesscontrol", "type": "scenario", "difficulty": "hard", "question": "An access control system grants or denies a request based on multiple real-time factors like the time of day, the user's location, and the device being used. Which model does this describe?", "options": ["RBAC (Role-Based Access Control) alone", "MAC (Mandatory Access Control) alone", "DAC (Discretionary Access Control)", "ABAC (Attribute-Based Access Control)"], "correctIndex": 3, "explanation": "ABAC: attribute-based (time, location, device) \u2014 yeh multiple dynamic factors ke basis pe access decide karta hai."}, {"id": "ch5_q35", "termRef": "accesscontrol", "type": "category", "difficulty": "medium", "question": "In RBAC, what happens automatically when an employee's role changes (e.g. from developer to manager)?", "options": ["Nothing changes; permissions must be manually reset from scratch", "Their permissions automatically change to match the new role", "Their account is permanently deleted", "Their password is reset to a default value"], "correctIndex": 1, "explanation": "Role change karo, permissions automatically change \u2014 yeh RBAC ka core benefit hai, manual reassignment ki zaroorat nahi."}, {"id": "ch5_q36", "termRef": "authn", "type": "definition", "difficulty": "easy", "question": "What question does Authentication answer?", "options": ["'Where are you located?'", "'What can you do?'", "'Who are you?'", "'How much data can you access?'"], "correctIndex": 2, "explanation": "Identity verify karna \u2014 prove karo tum wahi ho jo tum claim karte ho. Password, biometric, token \u2014 sab authentication methods hain."}, {"id": "ch5_q37", "termRef": "authn", "type": "category", "difficulty": "medium", "question": "Which of these is described as an authentication method in the guide?", "options": ["A CDN", "A CVE score", "Password", "A firewall rule"], "correctIndex": 2, "explanation": "Password, biometric, token \u2014 sab authentication methods hain, identity verify karne ke liye."}, {"id": "ch5_q38", "termRef": "authn", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use for authentication versus authorization?", "options": ["Authentication is a passport check; authorization is what areas your visa allows you into", "Authentication is a lock; authorization is a key duplicate", "Authentication is a CCTV camera; authorization is a smoke detector", "Authentication is a firewall; authorization is a VPN"], "correctIndex": 0, "explanation": "Authentication = WHO are you? (Passport check). Authorization = WHAT can you do? (Visa allows entry to certain areas)."}, {"id": "ch5_q39", "termRef": "authn", "type": "scenario", "difficulty": "hard", "question": "A user successfully proves their identity with a correct username, password, and fingerprint scan. Which security step has just occurred?", "options": ["Authorization", "Network segmentation", "Authentication", "Encryption"], "correctIndex": 2, "explanation": "Identity verify hona \u2014 'tum kaun ho' prove karna \u2014 yeh authentication hai, authorization ke pehle ka step."}, {"id": "ch5_q40", "termRef": "authn", "type": "category", "difficulty": "medium", "question": "What comes logically before Authorization in the access process?", "options": ["Network segmentation", "Encryption", "Digital forensics", "Authentication"], "correctIndex": 3, "explanation": "Pehle identity prove karo (Authentication), phir decide hota hai kya access hai (Authorization) \u2014 authentication pehle aata hai."}, {"id": "ch5_q41", "termRef": "authz", "type": "definition", "difficulty": "easy", "question": "What does Authorization determine after a user has logged in?", "options": ["Whether the user's password is strong enough", "Whether the user's device has antivirus installed", "What resources and actions the authenticated user is permitted to access", "The user's physical location"], "correctIndex": 2, "explanation": "Authenticated user ko kya resources access karne ki permission hai \u2014 login ke baad \u2014 'can this user read/write/delete this file?'"}, {"id": "ch5_q42", "termRef": "authz", "type": "category", "difficulty": "hard", "question": "What is 'Broken Access Control', and where does it rank on the OWASP Top 10?", "options": ["It's when a password is too short; it ranks #10", "It's a type of physical break-in; not covered by OWASP", "It's a hardware failure in a firewall; it isn't part of OWASP Top 10", "It's when authorization checks fail, allowing unauthorized access; it ranks #1 on OWASP Top 10"], "correctIndex": 3, "explanation": "Broken Access Control \u2014 OWASP Top 10 mein #1. User A ki ID change karke User B ka data access karna (IDOR) \u2014 horizontal aur vertical privilege escalation."}, {"id": "ch5_q43", "termRef": "authz", "type": "category", "difficulty": "medium", "question": "What does IDOR (Insecure Direct Object Reference) typically involve?", "options": ["Changing an ID in a request to access another user's data without permission", "Installing a rootkit on a server", "Sending too many login requests at once", "Encrypting a database with a weak key"], "correctIndex": 0, "explanation": "User A ki ID change karke User B ka data access karna (IDOR) \u2014 Broken Access Control ka classic example."}, {"id": "ch5_q44", "termRef": "authz", "type": "scenario", "difficulty": "hard", "question": "A logged-in user changes a number in the website's URL from their own account ID to someone else's, and successfully views that other person's private data. What vulnerability class does this fall under?", "options": ["Broken Access Control / IDOR", "DNS Poisoning", "SQL Injection", "Cross-Site Scripting"], "correctIndex": 0, "explanation": "Yeh classic IDOR (Insecure Direct Object Reference) hai, jo Broken Access Control ke under aata hai \u2014 OWASP Top 10 ka #1 issue."}, {"id": "ch5_q45", "termRef": "authz", "type": "category", "difficulty": "medium", "question": "What is the difference between horizontal and vertical privilege escalation?", "options": ["Horizontal means gaining admin rights; vertical means accessing peer data", "Horizontal is accessing another same-level user's data; vertical is gaining higher-level (admin) privileges", "They are the same thing with different names", "Neither relates to Broken Access Control"], "correctIndex": 1, "explanation": "Horizontal: User A ka access User B ke data tak (same level). Vertical: normal user se admin tak escalate karna."}, {"id": "ch5_q46", "termRef": "token", "type": "definition", "difficulty": "easy", "question": "What is the purpose of a token after a user logs in?", "options": ["It automatically encrypts the entire disk", "It permanently deletes the user's password", "It blocks all future login attempts", "It replaces the password for subsequent requests, so the user doesn't need to log in repeatedly"], "correctIndex": 3, "explanation": "Login ke baad server ek token deta hai (string of characters) \u2014 agle requests mein password ki jagah token bhejo, limited time ke liye valid."}, {"id": "ch5_q47", "termRef": "token", "type": "category", "difficulty": "medium", "question": "What are the three parts of a JWT (JSON Web Token), separated by dots?", "options": ["Header, Payload, Signature", "Key, Value, Hash", "Source, Destination, Port", "Username, Password, IP address"], "correctIndex": 0, "explanation": "Header.Payload.Signature \u2014 3 parts dot se separated. Payload mein user info (encrypted nahi, base64 encoded!), signature server verify karta hai."}, {"id": "ch5_q48", "termRef": "token", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use for a token?", "options": ["A CCTV camera in a control room", "A postman delivering sealed letters", "A movie ticket \u2014 you showed ID once at the counter, now you just show the ticket", "A firewall blocking traffic"], "correctIndex": 2, "explanation": "Movie ticket jaisa \u2014 counter pe ID dikhaya (login), ticket mila (token). Ab har movie hall mein token dikhao \u2014 baar baar ID nahi dikhani, ticket expire hoti hai."}, {"id": "ch5_q49", "termRef": "token", "type": "category", "difficulty": "hard", "question": "Is the payload section of a JWT encrypted?", "options": ["Yes, it's protected by RSA encryption", "Yes, it's fully AES-256 encrypted", "No, it's only base64 encoded, not encrypted", "It doesn't contain any user information at all"], "correctIndex": 2, "explanation": "Payload mein user info encrypted nahi hai, base64 encoded hai! \u2014 matlab koi bhi decode kar sakta hai (par tamper nahi kar sakta bina signature tode)."}, {"id": "ch5_q50", "termRef": "token", "type": "scenario", "difficulty": "hard", "question": "After a user logs in once, their app keeps making requests over the next hour without ever asking for the password again \u2014 until the token eventually expires. What mechanism explains this?", "options": ["A firewall allowing unlimited requests", "A honeypot logging all requests", "A token, such as a JWT, replacing repeated password entry", "A CASB monitoring cloud data"], "correctIndex": 2, "explanation": "Token limited time ke liye valid hai \u2014 expire hone tak baar baar login karne ki zaroorat nahi, movie ticket jaisa concept."}]}, "6": {"chapter": 6, "chapterTitle": "Network & Cloud Security", "termCount": 10, "questionCount": 50, "questions": [{"id": "ch6_q01", "termRef": "vpn", "type": "definition", "difficulty": "easy", "question": "What does a VPN create between your device and its server?", "options": ["A firewall rule set", "A backup copy of your files", "A physical cable connection", "An encrypted tunnel that hides your traffic from ISPs, admins, and hackers"], "correctIndex": 3, "explanation": "Tumhare device aur VPN server ke beech encrypted tunnel \u2014 ISP, network admin, hackers koi nahi dekh sakta tum kya browse kar rahe ho."}, {"id": "ch6_q02", "termRef": "vpn", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use to describe a VPN?", "options": ["A smoke detector", "A postman reading your letters", "An opaque armored tube versus a glass tunnel that everyone can see through", "A guard checking IDs"], "correctIndex": 2, "explanation": "Normal internet = glass tunnel \u2014 sab dekh sakte hain. VPN = opaque armored tube \u2014 bahar se kuch nazar nahi."}, {"id": "ch6_q03", "termRef": "vpn", "type": "category", "difficulty": "medium", "question": "What warning does the guide give about free VPN services?", "options": ["They are illegal in every country", "They may sell your data", "They are always faster than paid VPNs", "They cannot be used on mobile devices"], "correctIndex": 1, "explanation": "Free VPNs se beware \u2014 they sell your data. Privacy protect karne ke naam pe khud data bech sakte hain."}, {"id": "ch6_q04", "termRef": "vpn", "type": "scenario", "difficulty": "hard", "question": "You connect to a coffee shop's public WiFi while using a VPN, and even someone monitoring the WiFi network cannot see which websites you're visiting. What is enabling this protection?", "options": ["The VPN's encrypted tunnel", "DNS caching", "A honeypot on the network", "The coffee shop's firewall"], "correctIndex": 0, "explanation": "VPN encrypted tunnel banaata hai \u2014 public WiFi pe safety ke liye ek prime use case hai."}, {"id": "ch6_q05", "termRef": "vpn", "type": "category", "difficulty": "medium", "question": "What IP address does a website see when you're browsing through a VPN?", "options": ["The website's own IP address", "No IP address at all", "Your actual home IP address, unchanged", "The VPN server's IP address, not your own"], "correctIndex": 3, "explanation": "Tumhara IP bhi VPN server ka IP dikhta hai \u2014 yeh regional content access aur privacy ke liye use hota hai."}, {"id": "ch6_q06", "termRef": "netseg", "type": "definition", "difficulty": "easy", "question": "What does network segmentation do?", "options": ["Combines multiple small networks into one large network", "Encrypts all data on a single server", "Divides a large network into smaller isolated segments to contain damage", "Blocks all outbound internet traffic entirely"], "correctIndex": 2, "explanation": "Ek bada network ko smaller segments mein divide karna (VLANs, subnets) \u2014 finance network se developer network alag."}, {"id": "ch6_q07", "termRef": "netseg", "type": "category", "difficulty": "medium", "question": "What specific attack behavior does network segmentation help prevent?", "options": ["Weak password usage by employees", "Physical theft of laptops", "Phishing emails reaching employee inboxes", "Lateral movement \u2014 an attacker moving freely across the whole network after compromising one machine"], "correctIndex": 3, "explanation": "Lateral movement prevent karta hai \u2014 attacker ek machine compromise kare par poore network mein freely nahi ghoom sakta."}, {"id": "ch6_q08", "termRef": "netseg", "type": "scenario", "difficulty": "hard", "question": "A worm compromises one workstation in the marketing department, but is unable to spread into the finance department's systems because they sit on a completely separate network segment. What prevented the spread?", "options": ["A VPN", "NAT", "Network segmentation", "DNS Poisoning defenses"], "correctIndex": 2, "explanation": "Ek zone compromise ho to doosre safe rahein \u2014 yeh network segmentation ka core benefit hai, jaise Colonial Pipeline worm ko bhi is se roka ja sakta tha."}, {"id": "ch6_q09", "termRef": "netseg", "type": "category", "difficulty": "medium", "question": "Which real-world incident does the guide say could have been contained better with proper network segmentation?", "options": ["The MGM Resorts hack", "The Capital One breach", "The Colonial Pipeline attack", "The GitHub DDoS attack"], "correctIndex": 2, "explanation": "Colonial Pipeline worm bhi segmentation se rok sakte the \u2014 guide is example ko specifically mention karti hai."}, {"id": "ch6_q10", "termRef": "netseg", "type": "category", "difficulty": "medium", "question": "Which technical tools does the guide mention for implementing network segmentation?", "options": ["VLANs and subnets", "Digital certificates and CAs", "Password managers and vaults", "Honeypots and sandboxes"], "correctIndex": 0, "explanation": "Ek bada network ko smaller segments mein divide karna (VLANs, subnets) \u2014 yeh technical implementation ka tareeka hai."}, {"id": "ch6_q11", "termRef": "dnspois", "type": "definition", "difficulty": "easy", "question": "What happens during DNS poisoning?", "options": ["Fake records get injected into a DNS server's cache, redirecting users to the wrong IP", "A user's browser history gets deleted", "All DNS servers worldwide go offline simultaneously", "A DNS server is physically destroyed"], "correctIndex": 0, "explanation": "DNS server ki cache mein fake records inject karna \u2014 'google.com = galat IP' record return karta hai, user attacker site pe pahunch jaata hai."}, {"id": "ch6_q12", "termRef": "dnspois", "type": "analogy", "difficulty": "medium", "question": "How does the guide describe what DNS itself is, before explaining poisoning?", "options": ["A type of encrypted messaging protocol", "A firewall rule engine", "A backup storage system", "The 'phone book' of the internet, translating domain names into IP addresses"], "correctIndex": 3, "explanation": "Phone book of internet \u2014 'google.com' \u2192 '142.250.195.46' translate karta hai. DNS poisoning is phonebook mein galat entries daalna hai."}, {"id": "ch6_q13", "termRef": "dnspois", "type": "scenario", "difficulty": "hard", "question": "A user types 'google.com' correctly into their browser, but ends up on a fake malicious website instead. Which attack likely caused this, assuming their own device isn't infected?", "options": ["A CASB failure", "A firewall misconfiguration", "DNS Poisoning", "SSH key theft"], "correctIndex": 2, "explanation": "DNS poisoning se galat IP wapas milta hai even though URL sahi type kiya gaya \u2014 user ko pata bhi nahi chalta ki fake site pe pahunch gaya."}, {"id": "ch6_q14", "termRef": "dnspois", "type": "category", "difficulty": "medium", "question": "What does a poisoned DNS cache record for a legitimate domain like 'google.com' actually contain?", "options": ["The user's own personal IP address", "The correct IP address, but encrypted differently", "An incorrect IP address controlled by the attacker", "No IP address at all"], "correctIndex": 2, "explanation": "'google.com = 1.2.3.4' \u2014 yeh galat IP hai par DNS ye record return karta hai jab poisoning ho chuki ho."}, {"id": "ch6_q15", "termRef": "dnspois", "type": "category", "difficulty": "medium", "question": "DNS poisoning is essentially an attack on which core internet function?", "options": ["User authentication", "File encryption at rest", "Data compression", "Domain name to IP address translation"], "correctIndex": 3, "explanation": "DNS ka core function domain name ko IP address mein translate karna hai \u2014 poisoning isi function ko corrupt karta hai."}, {"id": "ch6_q16", "termRef": "nat", "type": "definition", "difficulty": "easy", "question": "What is the primary security benefit of NAT (Network Address Translation)?", "options": ["It automatically manages user passwords", "It encrypts all internet traffic automatically", "Internal devices' private IPs are hidden from the internet, so they can't be accessed directly", "It blocks all malware regardless of source"], "correctIndex": 2, "explanation": "Router andar private IPs maintain karta hai, internet se direct access nahi hota internal devices ko \u2014 security benefit."}, {"id": "ch6_q17", "termRef": "nat", "type": "category", "difficulty": "medium", "question": "In a typical home network, what does the outside internet see?", "options": ["Only the phone's IP, never the laptop's", "Every individual device's private IP address", "Only the router's single public IP address", "Nothing at all, the network is invisible"], "correctIndex": 2, "explanation": "Router: 103.45.67.89 \u2014 public IP. Internet pe sirf router ka IP dikhta hai, andar ke devices ke private IPs hidden rehte hain."}, {"id": "ch6_q18", "termRef": "nat", "type": "category", "difficulty": "medium", "question": "Which of these is an example of a private IP address, as shown in the guide's home network example?", "options": ["8.8.8.8", "192.168.1.5", "1.1.1.1", "103.45.67.89"], "correctIndex": 1, "explanation": "Phone: 192.168.1.5, Laptop: 192.168.1.6 \u2014 yeh private IPs hain, sirf ghar ke network ke andar valid."}, {"id": "ch6_q19", "termRef": "nat", "type": "scenario", "difficulty": "hard", "question": "An attacker scanning the internet cannot directly find or connect to your home laptop's private IP address, even though they can see your router's public IP. What is providing this protection?", "options": ["NAT (Network Address Translation)", "A VPN", "DNS Poisoning defenses", "SSH keys"], "correctIndex": 0, "explanation": "NAT internal devices ko internet se direct access se protect karta hai, sirf router ka public IP visible hota hai."}, {"id": "ch6_q20", "termRef": "nat", "type": "category", "difficulty": "easy", "question": "What does NAT stand for?", "options": ["Network Access Token", "Network Authentication Tool", "New Application Traffic", "Network Address Translation"], "correctIndex": 3, "explanation": "NAT = Network Address Translation \u2014 private IPs hide karna internet se, security ka ek natural side-benefit."}, {"id": "ch6_q21", "termRef": "sdn", "type": "definition", "difficulty": "easy", "question": "What does SDN (Software Defined Networking) enable compared to traditional networks?", "options": ["Removing the need for any network security at all", "Only allowing wireless connections", "Physically rewiring the network every time a policy changes", "Centralized, software-based control of the network instead of manual hardware configuration"], "correctIndex": 3, "explanation": "Traditional networks mein hardware configure karo manually. SDN mein software se network control hota hai centrally."}, {"id": "ch6_q22", "termRef": "sdn", "type": "category", "difficulty": "medium", "question": "What security advantage does SDN offer when a threat is detected?", "options": ["It permanently deletes all network logs", "It requires a technician to physically unplug a cable", "It disables the internet for the entire company", "The SDN controller can automatically isolate the affected network segment"], "correctIndex": 3, "explanation": "Threat detect hote hi, SDN controller automatically affected segment isolate kar sakta hai \u2014 faster response to threats."}, {"id": "ch6_q23", "termRef": "sdn", "type": "category", "difficulty": "medium", "question": "Which environments does the guide say typically rely on SDN-like architecture?", "options": ["Standalone offline computers", "Cloud networks", "Physical paper filing systems", "Old dial-up modem networks"], "correctIndex": 1, "explanation": "Cloud networks aise hi work karte hain \u2014 micro-segmentation easily implement, SDN-based architecture common hai."}, {"id": "ch6_q24", "termRef": "sdn", "type": "scenario", "difficulty": "hard", "question": "As soon as a security tool flags anomalous traffic, the network automatically reconfigures itself in seconds to isolate the affected segment, without any human manually reconfiguring hardware. What technology enables this rapid response?", "options": ["DNS Poisoning defenses", "SSH key rotation", "NAT alone", "SDN (Software Defined Networking)"], "correctIndex": 3, "explanation": "SDN security policies dynamically apply ho sakti hain \u2014 automated, fast response jo traditional hardware configuration se possible nahi tha."}, {"id": "ch6_q25", "termRef": "sdn", "type": "category", "difficulty": "medium", "question": "What does SDN make easier to implement, according to the guide?", "options": ["Micro-segmentation", "Manual firewall rule entry only", "Paper-based audit trails", "Physical cable management"], "correctIndex": 0, "explanation": "Micro-segmentation easily implement \u2014 SDN ki flexibility isse possible banati hai."}, {"id": "ch6_q26", "termRef": "casb", "type": "definition", "difficulty": "easy", "question": "What does a CASB (Cloud Access Security Broker) primarily monitor?", "options": ["Hardware keyloggers on employee laptops", "What data employees send to cloud apps and detect unauthorized ('shadow IT') app usage", "Email spam filtering rules only", "Physical access to the server room"], "correctIndex": 1, "explanation": "Employees cloud apps (Google Drive, Dropbox, Salesforce) use karte hain \u2014 CASB monitor karta hai kya data cloud pe ja raha hai."}, {"id": "ch6_q27", "termRef": "casb", "type": "category", "difficulty": "medium", "question": "What is 'shadow IT', which a CASB helps detect?", "options": ["A backup server hidden in a data center", "A type of ransomware", "A hacking group operating in the dark web", "Unauthorized apps or cloud services being used without IT department approval"], "correctIndex": 3, "explanation": "Unauthorized apps ka use ('shadow IT') detect karta hai \u2014 jab employees bina approval ke apne cloud tools use karte hain."}, {"id": "ch6_q28", "termRef": "casb", "type": "scenario", "difficulty": "hard", "question": "An employee uploads a confidential company document to their personal Dropbox account, and a security tool immediately flags and alerts the security team. Which tool caught this?", "options": ["CASB", "NAT", "SSH", "DNS Poisoning protection"], "correctIndex": 0, "explanation": "Employee ne confidential doc Dropbox personal pe upload kiya, CASB detect karta hai \u2014 alert ya block. DLP + cloud = CASB."}, {"id": "ch6_q29", "termRef": "casb", "type": "category", "difficulty": "medium", "question": "How does the guide describe CASB in relation to DLP?", "options": ["CASB replaces the need for any encryption", "CASB has nothing to do with DLP", "CASB is essentially DLP combined with cloud visibility", "CASB is only for physical security"], "correctIndex": 2, "explanation": "DLP + cloud = CASB \u2014 guide explicitly is combination ko describe karti hai."}, {"id": "ch6_q30", "termRef": "casb", "type": "category", "difficulty": "medium", "question": "Which of these apps would a CASB typically monitor employee usage of?", "options": ["Only the company's internal firewall", "Only the office printer", "Only the company's physical badge system", "Google Drive, Dropbox, and Salesforce"], "correctIndex": 3, "explanation": "Employees cloud apps (Google Drive, Dropbox, Salesforce) use karte hain \u2014 CASB inhi apps pe data flow monitor karta hai."}, {"id": "ch6_q31", "termRef": "iot", "type": "definition", "difficulty": "easy", "question": "What is the Internet of Things (IoT)?", "options": ["Internet-connected physical devices like smart bulbs, cameras, and thermostats", "A type of encryption algorithm", "A network security monitoring tool", "A cloud storage provider"], "correctIndex": 0, "explanation": "Smart devices jo internet se connected hain \u2014 smart bulbs, cameras, fridges, thermostats, wearables, industrial sensors, medical devices."}, {"id": "ch6_q32", "termRef": "iot", "type": "category", "difficulty": "medium", "question": "How many IoT devices are expected globally by 2030, according to the guide?", "options": ["7.5 million", "75 billion or more", "7.5 billion", "750,000"], "correctIndex": 1, "explanation": "2030 tak 75 billion+ IoT devices expected \u2014 har device ek potential entry point banta hai."}, {"id": "ch6_q33", "termRef": "iot", "type": "category", "difficulty": "medium", "question": "What common security problem does the guide highlight about most IoT devices?", "options": ["They often have weak passwords, outdated firmware, and no security updates", "They cannot connect to the internet at all", "They are only used by governments", "They are always more secure than laptops"], "correctIndex": 0, "explanation": "Most IoT devices have terrible security \u2014 no updates, weak passwords, old firmware \u2014 isliye har device ek potential entry point banta hai."}, {"id": "ch6_q34", "termRef": "iot", "type": "scenario", "difficulty": "hard", "question": "A smart doorbell, a smart thermostat, and a smart TV in your house all still have their default factory passwords set. What does this collectively represent?", "options": ["An expanded attack surface due to poor IoT security practices", "A DNS poisoning vulnerability specifically", "A guaranteed DDoS attack within 24 hours", "No risk at all since they're just household appliances"], "correctIndex": 0, "explanation": "Default passwords change na karna common IoT mistake hai \u2014 har unsecured device ek potential entry point ban jaata hai attackers ke liye."}, {"id": "ch6_q35", "termRef": "iot", "type": "category", "difficulty": "medium", "question": "Which of these is an example of an IoT device, according to the guide's list?", "options": ["A traditional desktop PC only", "A smart bulb", "A landline telephone", "A physical paper document"], "correctIndex": 1, "explanation": "Smart bulbs, cameras, fridges, thermostats, wearables, industrial sensors, medical devices \u2014 sab IoT devices hain."}, {"id": "ch6_q36", "termRef": "iotsec", "type": "definition", "difficulty": "easy", "question": "Why does the guide describe securing IoT devices as especially difficult?", "options": ["Because IoT devices don't connect to the internet at all", "Because IoT devices are always encrypted by default", "Because IoT devices have unlimited processing power", "Limited processing power, no screen for setup, and vendors rarely issue updates"], "correctIndex": 3, "explanation": "Limited processing power (can't run complex security), no screen/keyboard for setup, vendors update nahi karte, users default passwords change nahi karte."}, {"id": "ch6_q37", "termRef": "iotsec", "type": "real_world", "difficulty": "hard", "question": "In the 2017 casino hack, attackers used a smart fish tank thermometer to exfiltrate how much data from the casino's high-roller database?", "options": ["100MB", "100GB", "1GB", "10GB"], "correctIndex": 3, "explanation": "Casino ka smart fish tank thermometer hack hua \u2014 attackers ne isse network access liya aur casino's high-roller database exfiltrate ki, 10GB data."}, {"id": "ch6_q38", "termRef": "iotsec", "type": "category", "difficulty": "medium", "question": "Which of these is a recommended best practice for IoT security, according to the guide?", "options": ["Keep IoT devices on a separate network/VLAN from critical systems", "Connect every IoT device directly to the main corporate network", "Always keep default passwords unchanged for compatibility", "Never update IoT device firmware, to avoid breaking it"], "correctIndex": 0, "explanation": "Default passwords change karo, separate network/VLAN pe rakho IoT devices, firmware update karo, unnecessary features disable karo, network monitoring rakho."}, {"id": "ch6_q39", "termRef": "iotsec", "type": "scenario", "difficulty": "hard", "question": "A seemingly harmless smart device on a network becomes the entry point for a much larger data breach into supposedly unrelated systems. Which real-world incident does this describe?", "options": ["The GitHub DDoS attack", "The Zeus Trojan campaign", "The Colonial Pipeline attack", "The casino fish tank thermometer hack"], "correctIndex": 3, "explanation": "Hospital/casino hack via fish tank thermometer (2017) \u2014 exactly is scenario ko describe karta hai, ek chhota IoT device bada breach ka entry point bana."}, {"id": "ch6_q40", "termRef": "iotsec", "type": "category", "difficulty": "medium", "question": "Why is IoT device lifecycle a security challenge, according to the guide?", "options": ["Devices never need power and thus never need updates", "Devices are replaced every month, causing config chaos", "Devices are always managed by a dedicated IT team", "Devices can remain in use for 10-20 years, often without ongoing security support"], "correctIndex": 3, "explanation": "Long lifecycle (10-20 years) \u2014 vendor support kabhi khatam ho jaata hai but device abhi bhi use ho raha hota hai, security gap create karta hai."}, {"id": "ch6_q41", "termRef": "netsec", "type": "definition", "difficulty": "easy", "question": "What does Network Security encompass, as an umbrella term?", "options": ["Only physical locks on server room doors", "Only antivirus software installed on individual laptops", "Only employee training programs", "Policies, tools, and practices that protect network infrastructure from unauthorized access, misuse, and denial"], "correctIndex": 3, "explanation": "Policies, tools, aur practices jo network infrastructure protect karte hain \u2014 unauthorized access, misuse, modification, denial prevent karna."}, {"id": "ch6_q42", "termRef": "netsec", "type": "category", "difficulty": "medium", "question": "What is 'defense in depth', as described in the guide's Network Security layers?", "options": ["Removing all layers to simplify the network", "Only using antivirus and nothing else", "Relying on a single very strong firewall alone", "Using multiple layers (firewall, IDS, WAF, endpoint, SIEM) so that if one layer fails, another catches the threat"], "correctIndex": 3, "explanation": "Defense in depth \u2014 ek layer breach ho to doosri catch kare. Firewall \u2192 IDS \u2192 WAF \u2192 Endpoint \u2192 SIEM \u2014 layered approach best practice hai."}, {"id": "ch6_q43", "termRef": "netsec", "type": "category", "difficulty": "medium", "question": "Which of these tools is listed as a component of overall Network Security?", "options": ["Firewall", "A physical paper filing cabinet", "A coffee machine", "An office chair"], "correctIndex": 0, "explanation": "Firewall, IDS/IPS, VPN, segmentation sab Network Security ke components hain."}, {"id": "ch6_q44", "termRef": "netsec", "type": "scenario", "difficulty": "hard", "question": "An attacker bypasses the firewall, but is then caught by the IDS, and even if that failed too, the WAF would have blocked the web-layer attack anyway. What security philosophy is being demonstrated?", "options": ["Zero Trust alone", "Defense in depth", "Single Sign-On", "Network Address Translation alone"], "correctIndex": 1, "explanation": "Ek layer breach ho to doosri catch kare \u2014 yeh defense in depth ka core idea hai, multiple layers overlapping protection dete hain."}, {"id": "ch6_q45", "termRef": "netsec", "type": "category", "difficulty": "easy", "question": "Which order does the guide list as a typical layered defense-in-depth stack?", "options": ["SIEM \u2192 Firewall \u2192 Endpoint \u2192 IDS \u2192 WAF", "Endpoint \u2192 SIEM \u2192 Firewall \u2192 WAF \u2192 IDS", "Firewall \u2192 IDS \u2192 WAF \u2192 Endpoint \u2192 SIEM", "WAF \u2192 SIEM \u2192 IDS \u2192 Firewall \u2192 Endpoint"], "correctIndex": 2, "explanation": "Firewall \u2192 IDS \u2192 WAF \u2192 Endpoint \u2192 SIEM \u2014 layered approach best practice hai jo guide mein specifically likha gaya hai."}, {"id": "ch6_q46", "termRef": "threatactor", "type": "definition", "difficulty": "easy", "question": "What is a 'threat actor'?", "options": ["Only an insider employee", "Anyone who carries out a cyberattack, regardless of their motivation or skill level", "Only a piece of malicious software", "Only a government employee working in cybersecurity"], "correctIndex": 1, "explanation": "Koi bhi jo cyberattack kare \u2014 multiple types: nation-state, cybercriminals, hacktivists, insider threats, script kiddies."}, {"id": "ch6_q47", "termRef": "threatactor", "type": "category", "difficulty": "medium", "question": "Which threat actor type is primarily motivated by political causes?", "options": ["Nation-State actors", "Cybercriminals", "Hacktivists", "Script Kiddies"], "correctIndex": 2, "explanation": "Hacktivists: Political (Anonymous) \u2014 cybercriminals financial motivation rakhte hain, nation-state government-backed hote hain."}, {"id": "ch6_q48", "termRef": "threatactor", "type": "category", "difficulty": "medium", "question": "Why does knowing the type of threat actor matter for defense, according to the guide?", "options": ["It reveals their likely motivation and resources, helping tailor defenses accordingly", "It has no practical impact on defense strategy at all", "It determines which color the security badge should be", "It only matters for legal prosecution, not security"], "correctIndex": 0, "explanation": "Threat actor type se pata chalta hai motivation kya hai, resources kitne hain \u2014 nation-state actors ka zero-day budget \u2260 script kiddie ka free tools."}, {"id": "ch6_q49", "termRef": "threatactor", "type": "scenario", "difficulty": "hard", "question": "A government-backed group like Russia's APT28 launches a highly sophisticated, well-funded, multi-year campaign against a target. Which threat actor category does this represent?", "options": ["Script Kiddie", "Hacktivist", "Insider Threat", "Nation-State"], "correctIndex": 3, "explanation": "Nation-State: government-backed (Russia APT28, China APT40) \u2014 highly resourced aur sophisticated compared to other threat actor types."}, {"id": "ch6_q50", "termRef": "threatactor", "type": "category", "difficulty": "medium", "question": "Which threat actor type does the guide describe as motivated purely by financial gain?", "options": ["Cybercriminals", "Script Kiddies", "Hacktivists", "Nation-State actors"], "correctIndex": 0, "explanation": "Cybercriminals: Financial motivation \u2014 yeh unhe hacktivists (political) ya nation-state (geopolitical) se alag karta hai."}]}, "7": {"chapter": 7, "chapterTitle": "Advanced Threats & Social Engineering", "termCount": 10, "questionCount": 50, "questions": [{"id": "ch7_q01", "termRef": "apt", "type": "definition", "difficulty": "easy", "question": "What is an APT (Advanced Persistent Threat)?", "options": ["A firewall configuration error", "A quick, single-hit ransomware attack", "A basic phishing email sent to random users", "A long-term, targeted attack where an attacker stays hidden inside a network for months or years"], "correctIndex": 3, "explanation": "Long-term targeted attack \u2014 attacker mahino ya saalo tak network mein chupa rehta hai bina detect hue. Nation-states typically karte hain."}, {"id": "ch7_q02", "termRef": "apt", "type": "category", "difficulty": "medium", "question": "What does the 'Persistent' in APT specifically refer to?", "options": ["A single attack that happens instantly", "A months- or years-long campaign inside the target's network", "The attacker's persistence in sending spam emails", "A malware that repeatedly crashes the system"], "correctIndex": 1, "explanation": "Persistent: Months/years long campaign \u2014 yehi APT ko ordinary attacks se alag banata hai."}, {"id": "ch7_q03", "termRef": "apt", "type": "real_world", "difficulty": "hard", "question": "The SolarWinds (2020) APT attack, attributed to Russia's SVR, went undetected for how long inside US government agencies?", "options": ["9 years", "9 days", "9 months", "9 weeks"], "correctIndex": 2, "explanation": "Russia's SVR ne SolarWinds software update mein malware inject kiya (supply chain), 18,000 organizations infected, US government agencies breach \u2014 9 months undetected."}, {"id": "ch7_q04", "termRef": "apt", "type": "category", "difficulty": "medium", "question": "What is typically the goal of an APT, as opposed to a quick ransomware attack?", "options": ["Immediate financial extortion only", "Displaying advertisements to the target", "Data exfiltration or sabotage, not a quick financial hit", "Testing a company's firewall configuration"], "correctIndex": 2, "explanation": "Goal: data exfiltration ya sabotage \u2014 not ransomware quick hit. APT ka objective long-term rehta hai."}, {"id": "ch7_q05", "termRef": "apt", "type": "scenario", "difficulty": "hard", "question": "Security investigators discover that an attacker had quiet, ongoing access to a company's network for over a year before being detected, slowly extracting sensitive data the whole time. What type of threat does this match?", "options": ["Adware", "An APT (Advanced Persistent Threat)", "A DDoS attack", "A simple phishing attempt"], "correctIndex": 1, "explanation": "Long-term stealth presence, gradual data exfiltration \u2014 yeh exactly APT ki defining characteristic hai."}, {"id": "ch7_q06", "termRef": "espionage", "type": "definition", "difficulty": "easy", "question": "What is Cyber Espionage?", "options": ["Stealing sensitive government or corporate information through digital means", "Publicly disclosing a company's security vulnerabilities", "A defensive tool used to detect intrusions", "A type of ransomware that targets governments only"], "correctIndex": 0, "explanation": "Government ya corporations ke sensitive information chori karna digital means se \u2014 traditional spy agencies ka cyber equivalent."}, {"id": "ch7_q07", "termRef": "espionage", "type": "category", "difficulty": "medium", "question": "Which of these groups is mentioned in the guide as associated with cyber espionage?", "options": ["APT28 'Fancy Bear' (Russia)", "The Tor Project", "MITRE", "OWASP"], "correctIndex": 0, "explanation": "China (APT40, APT10), Russia (APT28 Fancy Bear, APT29 Cozy Bear), North Korea (Lazarus Group), Iran \u2014 sab cyber espionage players hain."}, {"id": "ch7_q08", "termRef": "espionage", "type": "category", "difficulty": "medium", "question": "What kind of information is typically targeted in cyber espionage, according to the guide?", "options": ["Only social media likes and comments", "Only publicly available news articles", "Military plans, technology secrets, and trade secrets", "Only weather forecast data"], "correctIndex": 2, "explanation": "Military plans, technology secrets, diplomatic cables, trade secrets \u2014 sab target hote hain cyber espionage mein."}, {"id": "ch7_q09", "termRef": "espionage", "type": "category", "difficulty": "hard", "question": "Which nation-state group is specifically associated with North Korea, according to the guide?", "options": ["Lazarus Group", "APT28 Fancy Bear", "APT40", "APT29 Cozy Bear"], "correctIndex": 0, "explanation": "North Korea ka Lazarus Group \u2014 guide mein specifically North Korea se associate kiya gaya hai."}, {"id": "ch7_q10", "termRef": "espionage", "type": "scenario", "difficulty": "hard", "question": "A foreign intelligence agency secretly accesses a defense contractor's servers to steal blueprints for a new weapons system. What is this an example of?", "options": ["A simple DDoS attack", "Cyber Espionage", "Adware distribution", "Credential stuffing"], "correctIndex": 1, "explanation": "Sensitive military/technology information government ke through chori karna \u2014 exactly cyber espionage ki definition hai."}, {"id": "ch7_q11", "termRef": "warfare", "type": "definition", "difficulty": "easy", "question": "What is Cyber Warfare?", "options": ["State-sponsored cyberattacks designed to disrupt or damage another nation", "A friendly competition between two companies' security teams", "A type of antivirus software update", "A training exercise for ethical hackers"], "correctIndex": 0, "explanation": "State-sponsored cyberattacks dusre nations ko disrupt ya damage karne ke liye \u2014 power grids, water systems, financial systems target hote hain."}, {"id": "ch7_q12", "termRef": "warfare", "type": "category", "difficulty": "medium", "question": "According to the guide, cyber is considered which numbered 'domain of warfare'?", "options": ["Not considered a domain of warfare at all", "The 3rd domain, after land and sea", "The 1st and only domain of modern warfare", "The 5th domain, alongside land, sea, air, and space"], "correctIndex": 3, "explanation": "5th domain of warfare \u2014 land, sea, air, space, cyber. Iska matlab hai cyber attacks ko literally war ke acts ki tarah treat kiya jaata hai."}, {"id": "ch7_q13", "termRef": "warfare", "type": "real_world", "difficulty": "hard", "question": "NotPetya, which spread from a Ukraine-targeted cyberattack, caused how much in global damage?", "options": ["$1 billion", "$10 billion or more", "$100 million", "$1 trillion"], "correctIndex": 1, "explanation": "NotPetya Ukraine attack ($10B+ global damage) \u2014 guide is figure ko specifically cyber warfare ke context mein mention karti hai."}, {"id": "ch7_q14", "termRef": "warfare", "type": "category", "difficulty": "medium", "question": "Which of these is listed as a real cyber warfare example in the guide?", "options": ["The Blackshades RAT case", "The Capital One breach", "The MGM Resorts hack", "Ukraine power grid attacks by Russia (2015, 2016)"], "correctIndex": 3, "explanation": "Ukraine power grid attacks by Russia (2015, 2016), Estonia DDoS (2007), Stuxnet vs Iran, NotPetya \u2014 sab examples of cyber warfare acts of war."}, {"id": "ch7_q15", "termRef": "warfare", "type": "category", "difficulty": "medium", "question": "What kind of systems are the primary targets in cyber warfare, according to the guide?", "options": ["Power grids, water systems, and military systems", "Only personal social media accounts", "Only university research databases", "Only online shopping websites"], "correctIndex": 0, "explanation": "Power grids, water systems, financial systems, military systems target hote hain \u2014 critical infrastructure cyber warfare ka main focus hai."}, {"id": "ch7_q16", "termRef": "supply", "type": "definition", "difficulty": "easy", "question": "What is a Supply Chain Attack?", "options": ["Sending phishing emails directly to the target", "Flooding a target's website with traffic", "Directly hacking the target's own servers with no third party involved", "Compromising a trusted third-party vendor so the real target installs infected software unknowingly"], "correctIndex": 3, "explanation": "Direct target attack mushkil hai, to attacker uske software supplier, hardware vendor, ya IT provider ko compromise karta hai."}, {"id": "ch7_q17", "termRef": "supply", "type": "category", "difficulty": "medium", "question": "Why is a supply chain attack especially devastating in terms of scale?", "options": ["It requires physical access to every victim's building", "Compromising one vendor can simultaneously compromise thousands of that vendor's customers", "It only ever affects a single individual user", "It only works against small startups"], "correctIndex": 1, "explanation": "Scale: ek vendor compromise = hazaron customers compromise simultaneously \u2014 defense very difficult hai."}, {"id": "ch7_q18", "termRef": "supply", "type": "real_world", "difficulty": "hard", "question": "The XZ Utils backdoor (2024) was inserted after how long a patient social engineering effort, according to the guide?", "options": ["2 weeks", "2 years", "2 months", "2 days"], "correctIndex": 1, "explanation": "Open source library mein backdoor inject kiya gaya 2 years ke patient social engineering ke baad \u2014 nearly compromised OpenSSH on millions of Linux servers."}, {"id": "ch7_q19", "termRef": "supply", "type": "category", "difficulty": "medium", "question": "Why do supply chain attacks often bypass normal security measures?", "options": ["They only target air-gapped systems", "The malicious software comes from a trusted, already-approved source", "They require the victim's password beforehand", "They always use zero antivirus-detectable code"], "correctIndex": 1, "explanation": "Trusted source se aata hai \u2014 security bypasses. Target khud infected software install kar leta hai thinking it's legitimate."}, {"id": "ch7_q20", "termRef": "supply", "type": "scenario", "difficulty": "hard", "question": "Thousands of organizations unknowingly install a legitimate software update from a trusted vendor, not realizing attackers compromised the vendor's build process to embed malware in it. What kind of attack is this?", "options": ["A Supply Chain Attack", "Credential Stuffing", "A phishing campaign", "A DDoS attack"], "correctIndex": 0, "explanation": "Yeh exactly SolarWinds Orion (2020) jaisa scenario hai \u2014 trusted vendor compromise karke uske customers ko target karna."}, {"id": "ch7_q21", "termRef": "social", "type": "definition", "difficulty": "easy", "question": "What does Social Engineering exploit, rather than technical vulnerabilities?", "options": ["A software bug in a web application", "Human psychology, manipulating people into revealing information or performing actions", "A weak encryption algorithm", "An unpatched operating system vulnerability"], "correctIndex": 1, "explanation": "Humans ko manipulate karke confidential info reveal karwana ya actions perform karwana \u2014 technical skills ki zaroorat nahi, psychological manipulation."}, {"id": "ch7_q22", "termRef": "social", "type": "category", "difficulty": "medium", "question": "What is 'baiting' as a social engineering technique?", "options": ["Physically following someone through a secure door", "Creating a fake identity claiming to be IT support", "Offering IT help in exchange for a password", "Leaving an infected USB drive somewhere the victim will find and plug it in"], "correctIndex": 3, "explanation": "Baiting: Infected USB chhodna parking mein \u2014 victim curiosity se plug in kar deta hai, malware install ho jaata hai."}, {"id": "ch7_q23", "termRef": "social", "type": "category", "difficulty": "medium", "question": "What is 'tailgating' in the context of social engineering?", "options": ["Sending a fake email pretending to be a bank", "Offering fake IT help in exchange for a password", "Physically following someone through a secure door without their own access credentials", "Leaving an infected USB drive in a parking lot"], "correctIndex": 2, "explanation": "Tailgating: Physically follow someone through a secure door \u2014 a physical social engineering technique."}, {"id": "ch7_q24", "termRef": "social", "type": "scenario", "difficulty": "hard", "question": "An attacker calls an employee claiming to be from the IT department, saying the employee's PC is infected, and asks for remote access to 'fix' it. Which technique is this?", "options": ["Network segmentation bypass", "SQL Injection", "A supply chain attack", "Social Engineering (pretexting)"], "correctIndex": 3, "explanation": "'Tumhara PC virus infected hai, main IT se hun, abhi remote access do' \u2014 yahi social engineering hai. Firewall bypass nahi kiya, tumhe manipulate kiya."}, {"id": "ch7_q25", "termRef": "social", "type": "category", "difficulty": "medium", "question": "What is 'quid pro quo' in social engineering, according to the guide?", "options": ["Creating a fake CA-issued certificate", "Physically tailgating through a secure door", "Leaving an infected USB drive as bait", "Offering something (like IT help) in exchange for information such as a password"], "correctIndex": 3, "explanation": "Quid Pro Quo: 'IT help ke badle password do' \u2014 ek transaction jaisa dikhta hai lekin manipulation hai."}, {"id": "ch7_q26", "termRef": "brute", "type": "definition", "difficulty": "easy", "question": "What does a brute force attack do?", "options": ["Exploits a software vulnerability directly", "Encrypts files and demands a ransom", "Systematically tries every possible password/key combination until the correct one is found", "Tricks a user into revealing their password voluntarily"], "correctIndex": 2, "explanation": "Systematically har possible password/key combination try karna jab tak sahi na mile \u2014 simple 4-digit PIN = 10,000 combinations."}, {"id": "ch7_q27", "termRef": "brute", "type": "category", "difficulty": "medium", "question": "Which brute force variant uses a list of commonly used words and phrases instead of every possible combination?", "options": ["Dictionary Attack", "Simple Brute Force", "Hybrid Attack", "Rainbow Table"], "correctIndex": 0, "explanation": "Dictionary Attack: Common words list use karta hai, jabki Simple Brute Force har combination try karta hai (aaa, aab, aac...)."}, {"id": "ch7_q28", "termRef": "brute", "type": "defense", "difficulty": "medium", "question": "Which defense against brute force attacks locks an account after a small number of failed login attempts?", "options": ["Rate limiting", "Long passwords alone", "MFA alone", "CAPTCHA alone"], "correctIndex": 0, "explanation": "Rate limiting \u2014 3 attempts failed \u2192 lockout. Yeh ek specific defense hai jo failed attempts ko count karke account lock karti hai."}, {"id": "ch7_q29", "termRef": "brute", "type": "scenario", "difficulty": "hard", "question": "An attacker's automated tool systematically tries thousands of pre-computed password hashes against a stolen hash file, looking for a match. Which brute-force technique is this closest to?", "options": ["Supply chain attack", "Social engineering", "Rainbow Table attack", "Simple sequential brute force (aaa, aab, aac...)"], "correctIndex": 2, "explanation": "Rainbow Table: Pre-computed hash lookups \u2014 yeh ek efficient technique hai jo pehle se calculated hashes ka use karti hai."}, {"id": "ch7_q30", "termRef": "brute", "type": "category", "difficulty": "medium", "question": "Which password is described as breakable 'in seconds' due to its commonness?", "options": ["'abc123'", "A biometric fingerprint", "'Tr0ub4dor&3'", "A 20-character random string"], "correctIndex": 0, "explanation": "'abc123' jaise common passwords seconds mein crack ho jaate hain \u2014 length aur complexity dono zaroori hain."}, {"id": "ch7_q31", "termRef": "cred", "type": "definition", "difficulty": "easy", "question": "What is Credential Stuffing?", "options": ["Tricking a user into revealing their password via a fake email", "Physically stealing a written password note", "Guessing a password character by character", "Using leaked username-password pairs from one breach to try logging into many other sites"], "correctIndex": 3, "explanation": "Data breach se leaked username-password pairs ko automated tools se hazaron other sites pe try karna."}, {"id": "ch7_q32", "termRef": "cred", "type": "category", "difficulty": "medium", "question": "Why does credential stuffing work so effectively against people who reuse passwords?", "options": ["It works only on sites that don't use HTTPS", "It requires physical access to the victim's device", "It only works against government accounts", "A single breach on one site can compromise all of their accounts across many other sites"], "correctIndex": 3, "explanation": "Same password everywhere use karte ho? Ek site breach = sab sites compromise \u2014 yehi credential stuffing ka core risk hai."}, {"id": "ch7_q33", "termRef": "cred", "type": "category", "difficulty": "medium", "question": "Even at a very low success rate, why can credential stuffing still cause massive impact?", "options": ["Because it only needs a single attempt to work", "Because every attempt is guaranteed to succeed", "Because it targets only one account at a time by design", "Because billions of leaked credentials are available, so even 0.1% success means millions of accounts"], "correctIndex": 3, "explanation": "0.1% success rate bhi millions of accounts = huge impact, kyunki billions of credentials dark web pe available hain."}, {"id": "ch7_q34", "termRef": "cred", "type": "defense", "difficulty": "medium", "question": "What is the single most effective personal defense against credential stuffing, according to the guide?", "options": ["Using the same strong password everywhere for consistency", "Disabling all password requirements", "Never logging into any website", "Using a unique password for every site with a password manager"], "correctIndex": 3, "explanation": "Unique password har site pe \u2014 password manager use karo (Bitwarden, 1Password) \u2014 isse ek breach dusri sites ko affect nahi karta."}, {"id": "ch7_q35", "termRef": "cred", "type": "scenario", "difficulty": "hard", "question": "After a data breach at one shopping website, an attacker successfully logs into a completely unrelated user's email account using the exact same leaked username and password. What attack technique was used?", "options": ["SQL Injection", "Brute Force", "Credential Stuffing", "Cyber Espionage"], "correctIndex": 2, "explanation": "Same leaked credentials ko dusri site pe try karna \u2014 exactly credential stuffing ki definition hai, password reuse ka direct consequence."}, {"id": "ch7_q36", "termRef": "insider", "type": "definition", "difficulty": "easy", "question": "Which of these is one of the three insider threat types listed in the guide?", "options": ["Automated \u2014 a bot with no human control", "External \u2014 someone with no access at all", "Negligent \u2014 someone who accidentally makes a security mistake", "Anonymous \u2014 someone using Tor exclusively"], "correctIndex": 2, "explanation": "Malicious: deliberately data steal ya damage kare. Negligent: accidentally security mistake kare. Compromised: external attacker ne account hijack kiya."}, {"id": "ch7_q37", "termRef": "insider", "type": "category", "difficulty": "medium", "question": "Which technology does the guide say is used to detect insider threats through behavioral deviation?", "options": ["A basic packet-filtering firewall", "NAT alone", "SSL alone", "UEBA (User & Entity Behavior Analytics)"], "correctIndex": 3, "explanation": "UEBA (behavior analytics) \u2014 normal se deviation. Unusual access times, large data downloads, off-hours logins."}, {"id": "ch7_q38", "termRef": "insider", "type": "real_world", "difficulty": "hard", "question": "Edward Snowden, an NSA contractor, copied how many classified documents in the 2013 insider threat case?", "options": ["17 million", "1.7 million", "170,000", "17,000"], "correctIndex": 1, "explanation": "NSA contractor Snowden \u2014 1.7 million classified documents copied aur media ko diye \u2014 sab access legitimate tha, audit trail nahi tha."}, {"id": "ch7_q39", "termRef": "insider", "type": "category", "difficulty": "medium", "question": "What made the Snowden case difficult to catch in real time, according to the guide?", "options": ["He physically broke into an NSA data center", "He bribed multiple NSA employees", "He used a zero-day exploit to gain access", "His access to the documents was entirely legitimate \u2014 there was no audit trail flagging the bulk download"], "correctIndex": 3, "explanation": "Sab access legitimate tha \u2014 audit trail nahi tha ki woh itna sab ek saath download kar raha hai \u2014 is is insider threat detection ki mushkil ko highlight karta hai."}, {"id": "ch7_q40", "termRef": "insider", "type": "scenario", "difficulty": "hard", "question": "A disgruntled employee deliberately deletes critical company files right before resigning. Which type of insider threat does this represent?", "options": ["Malicious insider threat", "Negligent insider threat", "Not an insider threat at all", "Compromised insider threat"], "correctIndex": 0, "explanation": "Malicious: deliberately data steal ya damage kare (disgruntled employee) \u2014 exactly is scenario ko match karta hai."}, {"id": "ch7_q41", "termRef": "kiddie", "type": "definition", "difficulty": "easy", "question": "What is a Script Kiddie?", "options": ["A software developer who builds security tools", "A highly skilled nation-state hacker", "An unskilled individual who uses publicly available hacking tools without understanding how they work", "A cybersecurity professional working in a SOC"], "correctIndex": 2, "explanation": "Unskilled individuals jo publicly available tools/scripts use karte hain attacks ke liye bina understanding ke \u2014 'point and click' hacking."}, {"id": "ch7_q42", "termRef": "kiddie", "type": "category", "difficulty": "medium", "question": "Why are script kiddies still considered a real threat, despite their lack of skill?", "options": ["They always target only large corporations", "Their sheer numbers can add up to a significant collective impact, like a large DDoS", "They are immune to law enforcement action", "They always have nation-state level funding"], "correctIndex": 1, "explanation": "Volume mein dangerous \u2014 hazaron script kiddies = significant DDoS. Basic vulnerabilities exploit kar lete hain."}, {"id": "ch7_q43", "termRef": "kiddie", "type": "category", "difficulty": "medium", "question": "What does the prevalence of script kiddies successfully exploiting basic vulnerabilities reveal about an organization?", "options": ["The importance of keeping systems patched", "That their SIEM is broken", "That their firewall is definitely misconfigured", "That they must be a target of nation-state espionage"], "correctIndex": 0, "explanation": "Patched systems ka importance inhi se pata chalta hai \u2014 agar basic vulnerabilities patched na hon, script kiddies bhi exploit kar sakte hain."}, {"id": "ch7_q44", "termRef": "kiddie", "type": "scenario", "difficulty": "hard", "question": "A teenager downloads a free hacking tool from a forum and, without understanding how it works internally, manages to deface a poorly-secured small business website. What category of threat actor does this represent?", "options": ["Nation-State actor", "APT group", "Script Kiddie", "Insider Threat"], "correctIndex": 2, "explanation": "'Point and click' hacking bina samjhe \u2014 exactly script kiddie ki definition hai, unlike sophisticated APT groups."}, {"id": "ch7_q45", "termRef": "kiddie", "type": "category", "difficulty": "medium", "question": "How do experienced hackers generally view script kiddies, according to the guide?", "options": ["As the most dangerous threat actor category overall", "As completely harmless with zero impact", "As equivalent to nation-state actors in skill", "Not seriously in terms of skill, but their volume is still a legitimate threat"], "correctIndex": 3, "explanation": "Real hackers inhe seriously nahi lete, par inka sheer volume ek threat hai \u2014 dono baaten guide mein explicitly likhi hain."}, {"id": "ch7_q46", "termRef": "cyberphys", "type": "definition", "difficulty": "easy", "question": "What are Cyber-Physical Systems?", "options": ["Only refers to social media platforms", "Systems where digital and physical worlds meet, like industrial control systems and SCADA", "Purely software applications with no hardware component", "Only refers to smartphones and tablets"], "correctIndex": 1, "explanation": "Systems jahan digital aur physical world meet karte hain \u2014 industrial control systems (ICS), SCADA, power plants, water treatment, hospital equipment."}, {"id": "ch7_q47", "termRef": "cyberphys", "type": "category", "difficulty": "medium", "question": "Why does the guide describe attacks on cyber-physical systems as 'life-and-death scenarios'?", "options": ["They cannot be executed remotely at all", "A hack can cause real physical harm, like poisoning water or disabling hospital equipment", "They only affect video game servers", "They only ever result in minor data theft"], "correctIndex": 1, "explanation": "Power grid hack \u2192 lights off city mein. Water treatment hack \u2192 poison in water. Hospital device hack \u2192 patient harm \u2014 not just data theft."}, {"id": "ch7_q48", "termRef": "cyberphys", "type": "category", "difficulty": "medium", "question": "Which term refers to the industrial/physical-facing technology (as opposed to standard IT) that has become critical to secure?", "options": ["SSO (Single Sign-On)", "OT (Operational Technology)", "DLP (Data Loss Prevention)", "CASB (Cloud Access Security Broker)"], "correctIndex": 1, "explanation": "OT (Operational Technology) security critical ho gayi hai \u2014 smart cities, connected infrastructure, Industry 4.0 ki wajah se attack surface badh gaya hai."}, {"id": "ch7_q49", "termRef": "cyberphys", "type": "scenario", "difficulty": "hard", "question": "An attacker gains digital access to a hospital's connected medical equipment and remotely alters its settings, directly endangering patients. What category of attack does this fall under?", "options": ["Cyber-Physical attack", "Adware infection", "A simple phishing campaign", "Credential stuffing"], "correctIndex": 0, "explanation": "Digital command jiske physical, real-world consequences hain \u2014 exactly cyber-physical systems attack ki definition hai."}, {"id": "ch7_q50", "termRef": "cyberphys", "type": "category", "difficulty": "medium", "question": "Why is 'more connectivity' identified as a growing risk factor for cyber-physical systems?", "options": ["More connected infrastructure means a larger attack surface for attackers to exploit", "More connectivity always makes systems automatically more secure", "Connectivity only matters for social media platforms", "Connectivity has no relationship to security risk at all"], "correctIndex": 0, "explanation": "Smart cities, connected infrastructure, Industry 4.0 \u2014 jitna zyada connectivity, utna zyada attack surface."}]}, "8": {"chapter": 8, "chapterTitle": "Governance & Compliance", "termCount": 10, "questionCount": 50, "questions": [{"id": "ch8_q01", "termRef": "risk", "type": "definition", "difficulty": "easy", "question": "How does the guide define Risk in cybersecurity terms?", "options": ["Risk = Threat \u00d7 Vulnerability \u00d7 Impact", "Risk = Only the size of the company", "Risk = Only the cost of a firewall", "Risk = Only the number of employees"], "correctIndex": 0, "explanation": "Risk = Threat \u00d7 Vulnerability \u00d7 Impact \u2014 identify karo kya risks hain, kitni probability hai, agar hua to kitna damage."}, {"id": "ch8_q02", "termRef": "risk", "type": "category", "difficulty": "medium", "question": "Which of these is NOT one of the four ways to treat a risk, according to the guide?", "options": ["Mitigate", "Ignore", "Transfer (insurance)", "Accept"], "correctIndex": 1, "explanation": "Decide karo accept karo, mitigate karo, transfer karo (insurance) ya avoid karo \u2014 'Ignore' formal risk treatment option nahi hai."}, {"id": "ch8_q03", "termRef": "risk", "type": "category", "difficulty": "medium", "question": "Why is it practically impossible to eliminate every single risk, according to the guide?", "options": ["It is practically and financially impossible; an acceptable risk level must be defined instead", "Because all risks are always equally severe", "Because risks are randomly generated and unpredictable", "Because insurance companies forbid it"], "correctIndex": 0, "explanation": "Har risk ko eliminate karna practically/financially impossible hai \u2014 business decision hai, acceptable risk level define karna zaroori hai."}, {"id": "ch8_q04", "termRef": "risk", "type": "category", "difficulty": "medium", "question": "What is the correct order of the risk management framework cycle, according to the guide?", "options": ["Repeat \u2192 Treatment \u2192 Monitoring \u2192 Assessment", "Risk Assessment \u2192 Treatment \u2192 Monitoring \u2192 Repeat", "Monitoring \u2192 Repeat \u2192 Assessment \u2192 Treatment", "Treatment \u2192 Assessment \u2192 Repeat \u2192 Monitoring"], "correctIndex": 1, "explanation": "Risk Assessment \u2192 Treatment \u2192 Monitoring \u2192 Repeat \u2014 yeh cyclical framework guide mein specifically diya gaya hai."}, {"id": "ch8_q05", "termRef": "risk", "type": "scenario", "difficulty": "hard", "question": "A company decides to purchase cyber insurance instead of spending heavily to fully prevent a low-probability, high-cost risk. Which risk treatment strategy is this?", "options": ["Mitigate", "Avoid", "Accept", "Transfer"], "correctIndex": 3, "explanation": "Transfer karo (insurance) \u2014 yeh risk ko kisi third party ko transfer karna hai, exactly jaise cyber insurance karti hai."}, {"id": "ch8_q06", "termRef": "compliance", "type": "definition", "difficulty": "easy", "question": "What does compliance mean in cybersecurity?", "options": ["Personally choosing your own preferred security tools", "A synonym for encryption", "Following laws and standards as a legal obligation", "Only applies to government agencies, never businesses"], "correctIndex": 2, "explanation": "Laws aur standards follow karna \u2014 legal obligation, jaise GDPR, PCI-DSS, HIPAA, ISO 27001, SOC 2."}, {"id": "ch8_q07", "termRef": "compliance", "type": "category", "difficulty": "medium", "question": "Which compliance standard specifically protects credit card data?", "options": ["PCI-DSS", "ISO 27001", "HIPAA", "GDPR"], "correctIndex": 0, "explanation": "PCI-DSS: Credit card data. GDPR: EU data privacy. HIPAA: US healthcare data \u2014 sab alag domains cover karte hain."}, {"id": "ch8_q08", "termRef": "compliance", "type": "category", "difficulty": "hard", "question": "What critical distinction does the guide make between compliance and real security?", "options": ["Compliance is always identical to real security, with no difference at all", "Compliance means a company can never be breached", "Compliance is more important than actual security in every scenario", "Compliance is only a minimum bar; a compliant system can still be insecure"], "correctIndex": 3, "explanation": "Critical distinction! Compliant system can still be insecure. Compliance is minimum bar. Many breached companies were 'compliant.'"}, {"id": "ch8_q09", "termRef": "compliance", "type": "category", "difficulty": "medium", "question": "How severe can GDPR fines be, according to the guide?", "options": ["A flat $100 fee regardless of company size", "There are no financial penalties under GDPR", "Fines apply only to companies based in the EU, never elsewhere", "Up to 4% of global revenue"], "correctIndex": 3, "explanation": "GDPR: EU data privacy (fines up to 4% revenue) \u2014 yeh ek significant financial risk hai non-compliant companies ke liye."}, {"id": "ch8_q10", "termRef": "compliance", "type": "scenario", "difficulty": "hard", "question": "A company passes all its official PCI-DSS compliance audits, yet still suffers a major data breach shortly afterward due to a security gap the audit didn't cover. What does this illustrate?", "options": ["Compliance and security are always exactly the same thing", "Compliance is a minimum bar, not a guarantee of actual security", "The breach must have been the auditor's direct fault legally", "PCI-DSS audits are always 100% accurate and thorough"], "correctIndex": 1, "explanation": "Guide explicitly warns \u2014 many breached companies were 'compliant.' Compliance \u2260 Security, yeh critical distinction hai."}, {"id": "ch8_q11", "termRef": "insurance", "type": "definition", "difficulty": "easy", "question": "What does cyber insurance typically cover?", "options": ["Free antivirus software for all employees", "Physical damage to office furniture", "Ransomware payments, breach notification costs, legal fees, and business interruption", "Employee salary increases"], "correctIndex": 2, "explanation": "Ransomware payment, data breach notification costs, legal fees, business interruption, regulatory fines, PR/crisis management."}, {"id": "ch8_q12", "termRef": "insurance", "type": "category", "difficulty": "medium", "question": "What do insurers increasingly require before issuing a cyber insurance policy, according to the guide?", "options": ["A public disclosure of the company's source code", "MFA, EDR, and backups being mandatory in place", "A guarantee of zero prior security incidents ever", "A minimum of 100 employees"], "correctIndex": 1, "explanation": "Insurers ab MFA, EDR, backups mandatory require karte hain policy ke liye \u2014 poor security = no insurance ya very high premium."}, {"id": "ch8_q13", "termRef": "insurance", "type": "category", "difficulty": "medium", "question": "Why has cyber insurance premium been increasing significantly, according to the guide?", "options": ["Due to the surge in ransomware attacks", "Because MFA has become obsolete", "Because compliance requirements have been removed", "Due to fewer companies buying policies"], "correctIndex": 0, "explanation": "Premium increasingly expensive \u2014 ransomware surge se, insurers ko zyada claims handle karne padte hain."}, {"id": "ch8_q14", "termRef": "insurance", "type": "scenario", "difficulty": "hard", "question": "A company applies for cyber insurance but is denied coverage because it doesn't use MFA or maintain regular backups. What does this reflect about the insurance industry today?", "options": ["Insurers no longer offer any cyber insurance products at all", "MFA and backups have no relevance to insurance decisions", "Insurers now require baseline security practices before offering coverage", "This company will automatically be exempt from all cyberattacks"], "correctIndex": 2, "explanation": "Poor security = no insurance ya very high premium \u2014 insurers ne apni requirements tighten kar di hain ransomware surge ki wajah se."}, {"id": "ch8_q15", "termRef": "insurance", "type": "category", "difficulty": "medium", "question": "Besides ransomware payments, what other cost category does cyber insurance help cover, according to the guide?", "options": ["Employee holiday bonuses", "PR and crisis management costs", "Office rent payments", "Marketing campaign costs"], "correctIndex": 1, "explanation": "Ransomware payment, data breach notification costs, legal fees, business interruption, regulatory fines, PR/crisis management \u2014 sab cover hota hai."}, {"id": "ch8_q16", "termRef": "vuln", "type": "definition", "difficulty": "easy", "question": "How does the guide define a 'Vulnerability' in cybersecurity terminology?", "options": ["An actual code or method used to exploit a weakness", "A weakness, such as unpatched software or a misconfiguration", "A public database listing known attackers", "The potential for harm from an attacker wanting to cause damage"], "correctIndex": 1, "explanation": "Vulnerability: weakness (unpatched software, misconfiguration). Threat: potential for harm. Exploit: actual code/method to use the vulnerability."}, {"id": "ch8_q17", "termRef": "vuln", "type": "category", "difficulty": "medium", "question": "What does CVE stand for?", "options": ["Common Vulnerabilities & Exposures", "Cyber Vulnerability Engine", "Certified Vulnerability Evaluation", "Central Vendor Exchange"], "correctIndex": 0, "explanation": "CVE: Common Vulnerabilities & Exposures \u2014 public database jahan known vulnerabilities track ki jaati hain."}, {"id": "ch8_q18", "termRef": "vuln", "type": "real_world", "difficulty": "hard", "question": "What was the CVSS score of CVE-2021-44228 (Log4Shell), the vulnerability described as literally maximum severity?", "options": ["8/10", "7/10", "9/10", "10/10"], "correctIndex": 3, "explanation": "CVE-2021-44228 (Log4Shell) = 10/10 \u2014 literally maximum severity, yeh guide mein specifically iska example diya gaya hai."}, {"id": "ch8_q19", "termRef": "vuln", "type": "category", "difficulty": "medium", "question": "What CVSS score range does the guide say counts as 'Critical'?", "options": ["0.0 exactly", "1.0 to 3.0", "9.0 and above", "5.0 to 6.0"], "correctIndex": 2, "explanation": "0-10 severity rating. 9.0+ = Critical \u2014 patching priority = CVSS score, higher score means more urgent."}, {"id": "ch8_q20", "termRef": "vuln", "type": "scenario", "difficulty": "hard", "question": "A security researcher discovers a weakness in a company's software but has no code yet to actually take advantage of it. In the guide's terminology, what has been found so far?", "options": ["A vulnerability, but not yet an exploit", "An exploit, but not yet a vulnerability", "A CVE score of exactly zero", "A threat actor"], "correctIndex": 0, "explanation": "Vulnerability = weakness itself. Exploit = actual code/method to use the vulnerability \u2014 dono alag concepts hain."}, {"id": "ch8_q21", "termRef": "pentest", "type": "definition", "difficulty": "easy", "question": "What is Penetration Testing?", "options": ["Company-authorized security professionals attacking systems to find weaknesses before real attackers do", "A method for training employees on phishing awareness only", "A tool for encrypting sensitive files", "An unauthorized attack carried out by criminals"], "correctIndex": 0, "explanation": "Company authorize karta hai security professionals ko attack karne ke liye \u2014 vulnerabilities find karo before real attackers do."}, {"id": "ch8_q22", "termRef": "pentest", "type": "analogy", "difficulty": "easy", "question": "Which analogy does the guide use for penetration testing?", "options": ["A bank legally telling a security expert to 'try to rob us' and fixing the gaps found", "A postman opening and reading letters", "A movie ticket used once for entry", "A smoke detector alerting to danger"], "correctIndex": 0, "explanation": "Bank apne security expert ko bolti hai 'try to rob us' \u2014 legally. Expert koshish karta hai, gaps dhundhta hai, fix hote hain before real robber try kare."}, {"id": "ch8_q23", "termRef": "pentest", "type": "category", "difficulty": "medium", "question": "Which penetration testing type gives the tester no prior information about the target, making it more realistic?", "options": ["Black Box", "Grey Box", "White Box", "Red Team only"], "correctIndex": 0, "explanation": "Black Box: No prior info (realistic). White Box: full access/info given. Grey Box: partial info."}, {"id": "ch8_q24", "termRef": "pentest", "type": "category", "difficulty": "medium", "question": "What term describes penetration testers who are authorized to legally test a system's security?", "options": ["Script kiddies", "Threat actors", "White hat hackers", "Cybercriminals"], "correctIndex": 2, "explanation": "Ethical hackers = white hat hackers \u2014 legally authorized to find vulnerabilities before criminals do."}, {"id": "ch8_q25", "termRef": "pentest", "type": "scenario", "difficulty": "hard", "question": "A company hires a firm and gives them full internal documentation, source code, and architecture diagrams to test the system as thoroughly as possible. Which type of penetration test is this?", "options": ["Script Kiddie testing", "White Box", "Black Box", "Grey Box"], "correctIndex": 1, "explanation": "White Box: Full access/info given \u2014 jitna zyada info tester ke paas hai, utna thorough test possible hai."}, {"id": "ch8_q26", "termRef": "resilience", "type": "definition", "difficulty": "easy", "question": "What is Cyber Resilience, as distinct from prevention?", "options": ["A type of firewall configuration", "The ability to survive an attack and recover quickly, assuming a breach will happen", "A tool for encrypting network traffic", "Only about preventing every attack from ever happening"], "correctIndex": 1, "explanation": "Prevention = attack hone mat do. Resilience = attack hone ke baad bhi business continue karo, jaldi recover karo \u2014 'assume breach' philosophy."}, {"id": "ch8_q27", "termRef": "resilience", "type": "category", "difficulty": "medium", "question": "Which of these is listed as a component of cyber resilience, according to the guide?", "options": ["Free coffee for employees", "A social media marketing plan", "A larger office building", "An Incident Response plan"], "correctIndex": 3, "explanation": "Components: Incident Response plan, backups, disaster recovery, business continuity plan, crisis communication, lessons learned."}, {"id": "ch8_q28", "termRef": "resilience", "type": "category", "difficulty": "medium", "question": "What does RTO (Recovery Time Objective) define?", "options": ["The length of a penetration test", "The number of employees affected by an attack", "The target time within which systems should be restored after an incident", "The total cost of a data breach"], "correctIndex": 2, "explanation": "RTO (Recovery Time Objective) aur RPO define karo \u2014 RTO specifically restore hone ke liye target time define karta hai."}, {"id": "ch8_q29", "termRef": "resilience", "type": "category", "difficulty": "hard", "question": "What modern philosophy does the guide say drives cyber resilience thinking?", "options": ["'Assume breach' \u2014 it WILL happen, so be ready", "'Never trust anyone, including your own IT team'", "'Only focus on prevention, never on recovery'", "'Ignore incidents until they escalate publicly'"], "correctIndex": 0, "explanation": "Modern philosophy: 'assume breach' \u2014 it WILL happen, be ready, isliye resilience prevention jitna hi important hai."}, {"id": "ch8_q30", "termRef": "resilience", "type": "scenario", "difficulty": "hard", "question": "After a ransomware attack, a company restores full operations within hours because it had a tested incident response plan, offline backups, and a clear business continuity strategy. What does this demonstrate?", "options": ["Strong cyber resilience", "Zero Trust security", "A CASB deployment", "A successful penetration test"], "correctIndex": 0, "explanation": "Attack hone ke baad bhi business jaldi continue karna \u2014 exactly cyber resilience ka goal hai, prevention se alag."}, {"id": "ch8_q31", "termRef": "cti", "type": "definition", "difficulty": "easy", "question": "What does CTI (Cyber Threat Intelligence) provide?", "options": ["A physical security camera system", "Actionable, collected information about threat actors and their tactics, for proactive defense", "A backup solution for critical files", "A tool for encrypting company emails"], "correctIndex": 1, "explanation": "Threat actors, their tactics, techniques, procedures (TTPs), indicators of compromise (IoCs) ke baare mein collected aur analyzed information."}, {"id": "ch8_q32", "termRef": "cti", "type": "category", "difficulty": "medium", "question": "Which type of CTI is aimed at board-level, strategic risk decisions?", "options": ["Operational CTI", "Technical CTI", "Strategic CTI", "Tactical CTI"], "correctIndex": 2, "explanation": "Strategic (board level \u2014 risk decisions), Operational (active campaigns), Tactical (specific TTPs), Technical (IPs, hashes, domains)."}, {"id": "ch8_q33", "termRef": "cti", "type": "category", "difficulty": "medium", "question": "Which type of CTI deals with specific technical indicators like IPs, hashes, and domains?", "options": ["Operational CTI", "Tactical CTI", "Technical CTI", "Strategic CTI"], "correctIndex": 2, "explanation": "Technical (SOC \u2014 IPs, hashes, domains) \u2014 yeh sabse granular level hai, SOC analysts ke liye directly usable."}, {"id": "ch8_q34", "termRef": "cti", "type": "category", "difficulty": "hard", "question": "What does TTP stand for in the context of Cyber Threat Intelligence?", "options": ["Transport Traffic Protocol", "Total Threat Prevention", "Trusted Third Party", "Tactics, Techniques, Procedures"], "correctIndex": 3, "explanation": "TTPs (tactics, techniques, procedures) \u2014 threat actors ke behavior patterns document karne ka standard tareeka."}, {"id": "ch8_q35", "termRef": "cti", "type": "scenario", "difficulty": "hard", "question": "A security team receives a report listing specific malicious IP addresses and file hashes seen in a recent campaign, which they immediately load into their SIEM to block. What level of CTI did they use?", "options": ["None of these, this is just antivirus data", "Technical CTI", "Only Tactical CTI", "Strategic CTI"], "correctIndex": 1, "explanation": "IPs, hashes, domains \u2014 yeh Technical CTI ka scope hai, directly SOC tools mein usable hota hai."}, {"id": "ch8_q36", "termRef": "cybercrime", "type": "definition", "difficulty": "easy", "question": "What is Cyber Crime?", "options": ["Only refers to physical theft of computer hardware", "Illegal activities carried out through computers or the internet", "A synonym for penetration testing", "Only refers to government-sponsored attacks"], "correctIndex": 1, "explanation": "Computer ya internet ke through illegal activities \u2014 financial fraud, identity theft, ransomware, hacking, dark web markets, cyber stalking."}, {"id": "ch8_q37", "termRef": "cybercrime", "type": "category", "difficulty": "hard", "question": "What is the estimated global annual cost of cybercrime in 2023, according to the guide?", "options": ["$8 trillion or more", "$8 billion", "$800 million", "$8 million"], "correctIndex": 0, "explanation": "$8 trillion+ global annual cost (2023) \u2014 yeh cybercrime ki scale ko dikhata hai global economy pe."}, {"id": "ch8_q38", "termRef": "cybercrime", "type": "category", "difficulty": "medium", "question": "Which Indian law covers cyber crimes, according to the guide?", "options": ["The Indian Penal Code alone, without any IT-specific law", "The Companies Act 2013", "The Consumer Protection Act", "The IT Act 2000 (amended 2008)"], "correctIndex": 3, "explanation": "IT Act 2000 (amended 2008) covers cyber crimes in India \u2014 cyber cells in major cities handle enforcement."}, {"id": "ch8_q39", "termRef": "cybercrime", "type": "category", "difficulty": "medium", "question": "Where does the guide say cyber crime incidents can be reported in India?", "options": ["A local police station only, no online option exists", "Only a private law firm", "cybercrime.gov.in", "Only the RBI website"], "correctIndex": 2, "explanation": "Incidents report karo: cybercrime.gov.in \u2014 India mein official reporting portal jo guide mein mention kiya gaya hai."}, {"id": "ch8_q40", "termRef": "cybercrime", "type": "category", "difficulty": "medium", "question": "According to the guide, which IT Act section deals with unauthorized access?", "options": ["Section 43", "Section 100", "Section 66", "Section 67"], "correctIndex": 2, "explanation": "Section 66 = unauthorized access, Section 67 = obscene content \u2014 yeh specific sections guide mein cite kiye gaye hain."}, {"id": "ch8_q41", "termRef": "bully", "type": "definition", "difficulty": "easy", "question": "What is Cyber Bullying?", "options": ["Online harassment, threatening, or humiliation carried out via digital platforms", "A defensive tool that blocks unwanted network traffic", "A type of encryption used in social media apps", "A type of penetration test done for training purposes"], "correctIndex": 0, "explanation": "Digital platforms pe harassment, threatening, humiliation \u2014 social media, gaming, messaging apps ke through hoti hai."}, {"id": "ch8_q42", "termRef": "bully", "type": "category", "difficulty": "medium", "question": "What is 'doxxing', as mentioned in the guide's discussion of cyber bullying?", "options": ["Sending an encrypted message to a friend", "A method for securely backing up data", "Publishing someone's private information publicly without consent", "A type of penetration testing technique"], "correctIndex": 2, "explanation": "Doxxing (private info public karna), revenge porn, trolling, fake profiles \u2014 sab cyber bullying ke forms hain."}, {"id": "ch8_q43", "termRef": "bully", "type": "category", "difficulty": "medium", "question": "What does the guide recommend as a first step if you experience cyber bullying?", "options": ["Ignore it completely and never report it", "Immediately delete all your social media accounts permanently", "Confront the bully in person alone", "Take screenshots as evidence"], "correctIndex": 3, "explanation": "Screenshots rakho evidence ke liye, platform report karo, cyber cell complaint karo \u2014 yeh recommended steps hain."}, {"id": "ch8_q44", "termRef": "bully", "type": "category", "difficulty": "medium", "question": "What kind of consequences does the guide highlight as resulting from cyber bullying?", "options": ["Serious mental health consequences", "Purely financial losses only", "Only minor inconvenience with no lasting impact", "Only affects the bully, not the victim"], "correctIndex": 0, "explanation": "Serious mental health consequences \u2014 guide is impact ko explicitly highlight karti hai, halka mudda nahi hai."}, {"id": "ch8_q45", "termRef": "bully", "type": "scenario", "difficulty": "hard", "question": "Someone's private address and phone number are posted publicly online without their consent, as part of an ongoing harassment campaign. What specific tactic does this represent?", "options": ["Cyber espionage", "Supply chain attack", "Credential stuffing", "Doxxing"], "correctIndex": 3, "explanation": "Private info public karna bina consent ke \u2014 exactly doxxing ki definition hai, cyber bullying ka ek severe form."}, {"id": "ch8_q46", "termRef": "forensics", "type": "definition", "difficulty": "easy", "question": "What is Digital Forensics?", "options": ["A method for training employees on phishing awareness", "Collecting, preserving, and analyzing digital evidence after an incident, for possible use in court", "A type of penetration testing", "A tool for automatically blocking malware in real time"], "correctIndex": 1, "explanation": "Incident ke baad digital evidence collect, preserve, analyze, aur present karna \u2014 court mein use hone ke liye \u2014 disk images, memory dumps, network logs sab include."}, {"id": "ch8_q47", "termRef": "forensics", "type": "category", "difficulty": "medium", "question": "What is a 'write blocker' used for in digital forensics?", "options": ["Encrypting a hard drive automatically", "Preventing employees from writing emails", "Preventing any accidental modification to the original evidence during analysis", "Blocking all outgoing network traffic permanently"], "correctIndex": 2, "explanation": "Write blockers use karo, hashes verify karo, chain of custody maintain karo \u2014 evidence ka original tamper nahi hona chahiye."}, {"id": "ch8_q48", "termRef": "forensics", "type": "category", "difficulty": "medium", "question": "What happens to tampered digital evidence in a court proceeding, according to the guide?", "options": ["It is automatically considered stronger proof", "It is used exactly the same as untampered evidence", "It becomes inadmissible in court", "It is destroyed by the court immediately"], "correctIndex": 2, "explanation": "Tampered evidence court mein inadmissible hai \u2014 isliye evidence integrity maintain karna critical hai."}, {"id": "ch8_q49", "termRef": "forensics", "type": "category", "difficulty": "medium", "question": "Besides disk images, what other type of digital evidence does the guide mention forensic investigators collect?", "options": ["Memory dumps and network logs", "Only handwritten notes from employees", "Only social media likes and shares", "Only physical photographs of the server room"], "correctIndex": 0, "explanation": "Disk images, memory dumps, network logs, deleted file recovery \u2014 sab forensic evidence collection ke part hain."}, {"id": "ch8_q50", "termRef": "forensics", "type": "scenario", "difficulty": "hard", "question": "An investigator makes a forensic copy of a compromised server's hard drive and works only on that copy, never touching the original, while documenting every handling step. What core principle is being followed?", "options": ["Maintaining evidence integrity through chain of custody", "Zero Trust security", "Risk transfer via insurance", "Penetration testing methodology"], "correctIndex": 0, "explanation": "Original kabhi touch nahi \u2014 sirf forensic copy pe kaam karo, evidence integrity aur chain of custody maintain karna key principle hai."}]}, "9": {"chapter": 9, "chapterTitle": "Operations & Response", "termCount": 10, "questionCount": 50, "questions": [{"id": "ch9_q01", "termRef": "ir", "type": "definition", "difficulty": "easy", "question": "What is Incident Response?", "options": ["A structured process for handling a security incident from detection through recovery", "A method for preventing all attacks permanently", "A type of firewall configuration", "A tool for encrypting files automatically"], "correctIndex": 0, "explanation": "Security incident handle karna \u2014 structured process, NIST phases follow karta hai."}, {"id": "ch9_q02", "termRef": "ir", "type": "category", "difficulty": "medium", "question": "Which of these is the correct order of the NIST Incident Response phases, according to the guide?", "options": ["Lessons Learned \u2192 Preparation \u2192 Detection \u2192 Recovery \u2192 Containment \u2192 Eradication", "Containment \u2192 Eradication \u2192 Preparation \u2192 Recovery \u2192 Detection \u2192 Lessons Learned", "Preparation \u2192 Detection & Analysis \u2192 Containment \u2192 Eradication \u2192 Recovery \u2192 Lessons Learned", "Recovery \u2192 Preparation \u2192 Containment \u2192 Detection \u2192 Eradication \u2192 Lessons Learned"], "correctIndex": 2, "explanation": "1. Preparation, 2. Detection & Analysis, 3. Containment, 4. Eradication, 5. Recovery, 6. Lessons Learned \u2014 yeh NIST ka standard order hai."}, {"id": "ch9_q03", "termRef": "ir", "type": "category", "difficulty": "medium", "question": "What does CSIRT stand for?", "options": ["Computer Security Incident Response Team", "Critical Software Integration Response Team", "Central Security Information Report Tool", "Cyber Systems Internal Risk Tracker"], "correctIndex": 0, "explanation": "IR Team = CSIRT (Computer Security Incident Response Team) \u2014 SOC analysts detect karte hain, IR team respond karta hai."}, {"id": "ch9_q04", "termRef": "ir", "type": "category", "difficulty": "medium", "question": "What are pre-defined, documented sets of IR steps for common scenarios called?", "options": ["Honeypots", "Sandboxes", "Playbooks", "Firewalls"], "correctIndex": 2, "explanation": "Playbooks pre-defined hote hain \u2014 jab specific incident type hota hai, team pehle se defined steps follow karti hai."}, {"id": "ch9_q05", "termRef": "ir", "type": "scenario", "difficulty": "hard", "question": "After containing a ransomware attack and restoring systems, a security team holds a formal meeting to document what went wrong and how to prevent it next time. Which IR phase does this represent?", "options": ["Preparation", "Lessons Learned", "Containment", "Detection & Analysis"], "correctIndex": 1, "explanation": "Lessons Learned: Post-mortem \u2014 yeh final phase hai jahan incident se seekh kar future preparation improve ki jaati hai."}, {"id": "ch9_q06", "termRef": "soc", "type": "definition", "difficulty": "easy", "question": "What is a SOC (Security Operations Center)?", "options": ["A tool for encrypting files at rest", "A physical lock on the server room door", "A dedicated team and facility that monitors an organization's security 24/7/365", "A type of firewall hardware"], "correctIndex": 2, "explanation": "Dedicated team aur facility jo 24/7/365 organization ki security monitor karti hai \u2014 SIEM se alerts aate hain, analysts investigate karte hain."}, {"id": "ch9_q07", "termRef": "soc", "type": "category", "difficulty": "medium", "question": "Which SOC tier is responsible for advanced threat hunting and deep analysis?", "options": ["There is only one tier", "Tier 3", "Tier 2", "Tier 1"], "correctIndex": 1, "explanation": "Tier 1: alert triage. Tier 2: investigation. Tier 3: threat hunting, advanced analysis \u2014 hierarchy of increasing expertise."}, {"id": "ch9_q08", "termRef": "soc", "type": "category", "difficulty": "medium", "question": "According to the guide, what is the most common entry-level career point in cybersecurity?", "options": ["Penetration Tester", "Chief Information Security Officer", "Digital Forensics Lead", "SOC Analyst"], "correctIndex": 3, "explanation": "SOC Analyst \u2014 cybersecurity mein most common entry point. Well paid career path bhi hai."}, {"id": "ch9_q09", "termRef": "soc", "type": "category", "difficulty": "medium", "question": "Which SOC tier handles initial alert triage?", "options": ["Tier 3", "None, alerts go directly to management", "Tier 1", "Tier 2"], "correctIndex": 2, "explanation": "Tier 1: alert triage \u2014 pehla level jo initial alerts ko sort aur prioritize karta hai."}, {"id": "ch9_q10", "termRef": "soc", "type": "scenario", "difficulty": "hard", "question": "An analyst quickly reviews an incoming SIEM alert to decide whether it needs deeper investigation or can be dismissed as a false positive. Which SOC tier is most likely performing this task?", "options": ["External auditors", "Only management", "Tier 1", "Tier 3"], "correctIndex": 2, "explanation": "Tier 1 ka kaam hi alert triage hai \u2014 quickly assess karna ki alert genuine hai ya false positive."}, {"id": "ch9_q11", "termRef": "hygiene", "type": "definition", "difficulty": "easy", "question": "What is Cyber Hygiene?", "options": ["A type of encryption algorithm", "A legal compliance framework", "Regular security practices that significantly reduce risk, like physical hygiene habits", "A tool for detecting network intrusions automatically"], "correctIndex": 2, "explanation": "Regular security practices jo risk significantly reduce karte hain \u2014 just like physical hygiene, consistent daily habits."}, {"id": "ch9_q12", "termRef": "hygiene", "type": "category", "difficulty": "medium", "question": "What percentage of attacks could be prevented by patching and basic hygiene, according to the guide?", "options": ["80%", "50%", "20%", "10%"], "correctIndex": 0, "explanation": "80% of attacks patching aur basic hygiene se prevent ho sakte the \u2014 yeh statistic guide mein specifically diya gaya hai."}, {"id": "ch9_q13", "termRef": "hygiene", "type": "category", "difficulty": "medium", "question": "Which of these is listed as a cyber hygiene essential in the guide?", "options": ["Ignoring software updates", "Reusing the same password across sites", "Disabling all backups", "MFA everywhere"], "correctIndex": 3, "explanation": "Strong unique passwords + manager, MFA everywhere, software updates promptly, regular backups, phishing awareness, least privilege, encrypt sensitive data."}, {"id": "ch9_q14", "termRef": "hygiene", "type": "scenario", "difficulty": "hard", "question": "An organization avoids most common attacks simply by consistently applying updates, using unique passwords, and enabling MFA across all accounts \u2014 no advanced tools involved. What does this illustrate?", "options": ["The need for penetration testing alone", "The power of basic cyber hygiene", "The requirement for cyber insurance", "The necessity of an expensive SOC"], "correctIndex": 1, "explanation": "80% of attacks basic hygiene se prevent ho sakte the \u2014 yeh exactly demonstrate karta hai ki fundamentals kitne powerful hain."}, {"id": "ch9_q15", "termRef": "hygiene", "type": "category", "difficulty": "medium", "question": "Which principle from IAM is also listed as part of good cyber hygiene?", "options": ["Shared admin passwords", "No authentication required", "Least privilege", "Maximum privilege for all"], "correctIndex": 2, "explanation": "Least privilege bhi cyber hygiene essentials mein listed hai \u2014 yeh dikhata hai ki concepts ek dusre se linked hote hain."}, {"id": "ch9_q16", "termRef": "coc", "type": "definition", "difficulty": "easy", "question": "What does Chain of Custody document?", "options": ["The list of all firewall rules in place", "The company's annual revenue and profits", "Where evidence is, who handled it, when, and how", "The number of employees in the SOC"], "correctIndex": 2, "explanation": "Documentation jo track karta hai evidence kahan hai, kisne handle kiya, kab, aur kaise."}, {"id": "ch9_q17", "termRef": "coc", "type": "category", "difficulty": "medium", "question": "What happens to evidence in a criminal case if the chain of custody is broken?", "options": ["The evidence automatically becomes stronger proof", "The evidence can become inadmissible in court", "Nothing changes; it remains fully valid regardless", "The case is immediately dismissed with no other consequence"], "correctIndex": 1, "explanation": "Criminal cases mein agar chain break ho to evidence inadmissible ho sakta hai court mein \u2014 legal validity directly is process pe depend karti hai."}, {"id": "ch9_q18", "termRef": "coc", "type": "category", "difficulty": "medium", "question": "In digital forensics, what should investigators avoid touching directly, working only on a copy instead?", "options": ["The original evidence/disk", "The forensic report template", "The incident response playbook", "The SIEM dashboard"], "correctIndex": 0, "explanation": "Original kabhi touch nahi \u2014 sirf forensic copy pe kaam karo, chain of custody maintain karne ke liye zaroori hai."}, {"id": "ch9_q19", "termRef": "coc", "type": "scenario", "difficulty": "hard", "question": "A disk image is taken from a compromised server, its hash is verified, it's placed in sealed storage, and every transport step is logged in detail. What process is being followed here?", "options": ["Risk transfer via insurance", "Penetration testing methodology", "Chain of Custody documentation", "Cyber hygiene practices"], "correctIndex": 2, "explanation": "Disk image lena \u2192 hash verify \u2192 sealed storage \u2192 transport log \u2192 analysis \u2014 har step documented, exactly chain of custody process hai."}, {"id": "ch9_q20", "termRef": "coc", "type": "category", "difficulty": "medium", "question": "Why is documenting who handled evidence and when considered critical?", "options": ["It proves the evidence wasn't tampered with, supporting its admissibility in court", "It replaces the need for encryption entirely", "It has no legal relevance at all", "It only matters for internal HR purposes"], "correctIndex": 0, "explanation": "Documentation evidence ki integrity prove karne ke liye zaroori hai \u2014 court mein admissibility isi par depend karti hai."}, {"id": "ch9_q21", "termRef": "uem", "type": "definition", "difficulty": "easy", "question": "What does UEM (Unified Endpoint Management) allow an organization to do?", "options": ["Only manage employee email accounts", "Only manage physical servers in a data center", "Manage all devices (laptops, phones, tablets) from a single platform", "Only encrypt files on a single device"], "correctIndex": 2, "explanation": "Organization ke saare devices (laptops, phones, tablets) ek platform se manage karna \u2014 policies enforce karo, software deploy karo, remote wipe karo."}, {"id": "ch9_q22", "termRef": "uem", "type": "category", "difficulty": "medium", "question": "Why has UEM become especially important, according to the guide?", "options": ["Because desktop computers are now obsolete", "Because of the BYOD (Bring Your Own Device) era, where employees use personal phones for work email", "Because all companies have banned smartphones entirely", "Because it replaces the need for any password policy"], "correctIndex": 1, "explanation": "BYOD era mein employees apne phones pe corporate email use karte hain \u2014 UEM security policies enforce karta hai without fully controlling personal devices."}, {"id": "ch9_q23", "termRef": "uem", "type": "category", "difficulty": "medium", "question": "What capability does UEM provide if a device is lost or stolen?", "options": ["Nothing can be done at all", "Remote wipe", "Instant device replacement, shipped free", "Automatic physical recovery of the device"], "correctIndex": 1, "explanation": "Remote wipe karo agar device lost ho \u2014 yeh UEM ka ek key security feature hai jo data ko protect karta hai."}, {"id": "ch9_q24", "termRef": "uem", "type": "scenario", "difficulty": "hard", "question": "An employee's personal phone, which also has corporate email set up, gets lost at an airport. The IT team remotely wipes only the corporate data on the device without touching personal photos. What technology enabled this selective control?", "options": ["A firewall", "SSH", "NAT", "UEM (Unified Endpoint Management)"], "correctIndex": 3, "explanation": "UEM policies enforce karta hai without fully controlling personal devices \u2014 exactly BYOD ke liye design kiya gaya feature."}, {"id": "ch9_q25", "termRef": "uem", "type": "category", "difficulty": "medium", "question": "Which of these is a core function of UEM, according to the guide?", "options": ["Enforcing security policies across all managed devices", "Only managing office furniture inventory", "Only tracking employee attendance", "Only handling company payroll"], "correctIndex": 0, "explanation": "Policies enforce karo, software deploy karo, remote wipe karo \u2014 sab UEM ke core functions hain."}, {"id": "ch9_q26", "termRef": "backup", "type": "definition", "difficulty": "easy", "question": "Why is backup called the 'last line of defense against ransomware'?", "options": ["It's a copy of your data that lets you recover without paying the attacker", "It physically blocks all network intrusions", "It encrypts every file permanently", "It automatically detects and removes malware"], "correctIndex": 0, "explanation": "Data ki copy \u2014 last line of defense against ransomware. Agar backup ho, ransom pay karne ki zaroorat nahi padti."}, {"id": "ch9_q27", "termRef": "backup", "type": "category", "difficulty": "medium", "question": "In the 3-2-1 backup rule, what does the '1' represent?", "options": ["1 encryption algorithm used", "1 offsite/offline copy", "1 employee responsible for backups", "1 password for all backups"], "correctIndex": 1, "explanation": "3 copies of data, 2 different storage media types, 1 offsite/offline copy \u2014 offline backup ransomware encrypt nahi kar sakta."}, {"id": "ch9_q28", "termRef": "backup", "type": "category", "difficulty": "medium", "question": "What critical mistake does the guide warn about regarding backup credentials?", "options": ["Storing backups in more than one location", "Using the same account credentials for cloud backup as for the main system", "Testing backups too frequently", "Encrypting the backup data"], "correctIndex": 1, "explanation": "Cloud backup alag account mein \u2014 not same credentials \u2014 agar same ho, ransomware attacker backup bhi encrypt/delete kar sakta hai."}, {"id": "ch9_q29", "termRef": "backup", "type": "category", "difficulty": "medium", "question": "What does the guide say about organizations that have backups but never test restoring them?", "options": ["Testing backups is unnecessary if storage space is limited", "This is the recommended best practice", "Many discover the backup is broken only when an actual disaster strikes", "They are always perfectly safe with no risk at all"], "correctIndex": 2, "explanation": "Backup hai par restore nahi kiya kabhi? Useless. Regular restore tests mandatory \u2014 warna disaster ke waqt pata chalta hai backup kaam nahi kar raha."}, {"id": "ch9_q30", "termRef": "backup", "type": "scenario", "difficulty": "hard", "question": "During a ransomware incident, a company discovers its cloud backup was encrypted too, because the backup used the exact same login credentials as the main compromised system. What mistake caused this?", "options": ["Using an offline backup instead of cloud", "Testing the backup too often", "Following the 3-2-1 rule too strictly", "Not keeping the backup account separate with different credentials"], "correctIndex": 3, "explanation": "Cloud backup alag account mein rakhna chahiye \u2014 not same credentials, warna attacker backup ko bhi compromise kar sakta hai."}, {"id": "ch9_q31", "termRef": "keymgmt", "type": "definition", "difficulty": "easy", "question": "What does Encryption Key Management involve?", "options": ["Only backing up data to the cloud", "Only creating strong passwords for user accounts", "Only encrypting a single file once", "Managing the lifecycle of encryption keys \u2014 generation, distribution, storage, rotation, destruction"], "correctIndex": 3, "explanation": "Encryption keys ka lifecycle manage karna \u2014 generation, distribution, storage, rotation, destruction."}, {"id": "ch9_q32", "termRef": "keymgmt", "type": "category", "difficulty": "medium", "question": "What is the most common mistake in key management, according to the guide?", "options": ["Using AES instead of RSA", "Rotating keys too frequently", "Storing encryption keys in the same location as the data they protect", "Using a Hardware Security Module"], "correctIndex": 2, "explanation": "Keys data ke saath same jagah store nahi karni (sabse common mistake) \u2014 agar attacker data access kare, keys bhi mil jaayengi."}, {"id": "ch9_q33", "termRef": "keymgmt", "type": "category", "difficulty": "medium", "question": "What is an HSM (Hardware Security Module)?", "options": ["A type of software firewall", "Dedicated hardware that physically protects encryption keys", "A cloud-based password manager", "A network monitoring dashboard"], "correctIndex": 1, "explanation": "Hardware Security Module \u2014 dedicated hardware jo keys physically protect karta hai. Banks, governments use karte hain."}, {"id": "ch9_q34", "termRef": "keymgmt", "type": "category", "difficulty": "medium", "question": "Do encryption keys stored in an HSM ever leave the device, according to the guide?", "options": ["Yes, they are exported daily for backup", "Yes, they are emailed to administrators regularly", "Yes, but only once a year", "No, keys never leave the HSM"], "correctIndex": 3, "explanation": "Keys kabhi HSM se bahar nahi jaate \u2014 yeh HSM ka core security guarantee hai."}, {"id": "ch9_q35", "termRef": "keymgmt", "type": "scenario", "difficulty": "hard", "question": "An attacker steals an entire encrypted database along with the encryption key, which was carelessly stored in the same folder. What mistake made the encryption effectively useless?", "options": ["Rotating the key too often", "Using AES instead of RSA", "Using a Hardware Security Module", "Storing the key alongside the data it protects"], "correctIndex": 3, "explanation": "Yeh exactly guide ke mutabik 'sabse common mistake' hai \u2014 keys data ke saath store karna encryption ko pointless bana deta hai."}, {"id": "ch9_q36", "termRef": "cloudsec", "type": "definition", "difficulty": "easy", "question": "What is the 'Shared Responsibility' model in Cloud Security?", "options": ["The cloud provider is responsible for absolutely everything, always", "The cloud provider secures the infrastructure; the customer secures their data, access, and configuration", "The customer is responsible for absolutely everything, always", "Responsibility is randomly assigned each month"], "correctIndex": 1, "explanation": "AWS/Azure/GCP \u2192 cloud infrastructure secure karte hain. Customer \u2192 data, access, application, configuration secure karna customer ki responsibility."}, {"id": "ch9_q37", "termRef": "cloudsec", "type": "real_world", "difficulty": "hard", "question": "The Capital One breach (2019), caused by a misconfigured AWS WAF, exposed how many credit applications and led to what settlement amount?", "options": ["100 million applications, $190 million settlement", "10 million applications, $19 million settlement", "100,000 applications, $1.9 million settlement", "1 billion applications, $1.9 billion settlement"], "correctIndex": 0, "explanation": "Misconfigured AWS WAF se 100 million credit applications exposed. $190M settlement \u2014 ex-Amazon employee ne exploit kiya, misconfiguration, not AWS's fault."}, {"id": "ch9_q38", "termRef": "cloudsec", "type": "category", "difficulty": "medium", "question": "Which of these is listed as a common cloud misconfiguration in the guide?", "options": ["Too much encryption at rest", "Too many MFA prompts", "Overly restrictive firewall rules", "Public S3 buckets"], "correctIndex": 3, "explanation": "Public S3 buckets, weak IAM roles, no encryption at rest, default security groups allowing all traffic, exposed credentials in code repositories."}, {"id": "ch9_q39", "termRef": "cloudsec", "type": "category", "difficulty": "medium", "question": "In the Capital One breach, whose fault was the security failure, according to the guide?", "options": ["The customer's (Capital One's) misconfiguration, not AWS's fault", "No one's fault; it was purely bad luck", "Entirely AWS's fault as the cloud provider", "The end customers whose data was exposed"], "correctIndex": 0, "explanation": "Misconfiguration, not AWS's fault \u2014 yeh exactly shared responsibility model ko illustrate karta hai, customer ki configuration responsibility thi."}, {"id": "ch9_q40", "termRef": "cloudsec", "type": "scenario", "difficulty": "hard", "question": "A company's sensitive database is exposed to the public internet not because of a flaw in AWS itself, but because the company's own security team left default settings unchanged. Whose responsibility does this fall under, per the shared responsibility model?", "options": ["The internet service provider's responsibility", "The customer's responsibility", "The cloud provider's responsibility", "No one's responsibility since it's automated"], "correctIndex": 1, "explanation": "Customer \u2192 data, access, application, configuration secure karna customer ki responsibility hai, exactly jaisa Capital One case mein hua."}, {"id": "ch9_q41", "termRef": "emailsec", "type": "definition", "difficulty": "easy", "question": "Why is email security so critical, according to the guide?", "options": ["Only 1% of attacks involve email", "Email is never used by attackers", "91% of cyberattacks start from a phishing email", "Email is completely immune to all attacks by default"], "correctIndex": 2, "explanation": "91% of cyberattacks start from phishing email \u2014 email sabse exploited vector hai, isliye security critical hai."}, {"id": "ch9_q42", "termRef": "emailsec", "type": "category", "difficulty": "medium", "question": "Which technology publishes a list of servers authorized to send email on behalf of a domain?", "options": ["SPF", "DMARC", "TLS", "DKIM"], "correctIndex": 0, "explanation": "SPF: Authorized mail servers list. DKIM: email digital signature. DMARC: policy for SPF/DKIM failures."}, {"id": "ch9_q43", "termRef": "emailsec", "type": "category", "difficulty": "medium", "question": "Which technology defines what should happen when SPF or DKIM checks fail for an email?", "options": ["DMARC", "DKIM alone", "SPF alone", "TLS alone"], "correctIndex": 0, "explanation": "DMARC: Policy for SPF/DKIM failures \u2014 yeh decide karta hai failed emails ka kya karna hai (reject, quarantine, etc.)."}, {"id": "ch9_q44", "termRef": "emailsec", "type": "category", "difficulty": "medium", "question": "What is the recommended combination for preventing email spoofing on your own domain, according to the guide?", "options": ["SPF + DKIM + DMARC configured together", "Only a firewall on the mail server", "Only a strong company password policy", "Only antivirus on the email server"], "correctIndex": 0, "explanation": "SPF+DKIM+DMARC configure karo apne domain pe \u2014 email spoofing prevent karta hai, tino saath use karna best practice hai."}, {"id": "ch9_q45", "termRef": "emailsec", "type": "scenario", "difficulty": "hard", "question": "A malicious email pretending to be from your own company domain is automatically rejected by the recipient's mail server because it fails an authenticity check based on your domain's published security policy. What technology likely caused this rejection?", "options": ["A WAF", "A honeypot", "NAT", "DMARC"], "correctIndex": 3, "explanation": "DMARC policy define karta hai ki SPF/DKIM fail hone pe email ka kya karna hai \u2014 reject karna is policy ka result hai."}, {"id": "ch9_q46", "termRef": "physec", "type": "definition", "difficulty": "easy", "question": "Why does the guide emphasize that cybersecurity isn't purely digital?", "options": ["Only software matters; hardware access is irrelevant", "Physical security has no relevance to cybersecurity at all", "Physical attacks stopped being a threat years ago", "The best firewall is useless if an attacker can physically access a server room"], "correctIndex": 3, "explanation": "Best firewall bhi useless hai agar attacker physically server room mein ghus jaaye \u2014 lock pick, RFID clone, tailgating physical attacks real hain."}, {"id": "ch9_q47", "termRef": "physec", "type": "category", "difficulty": "medium", "question": "What is a 'mantrap' in the context of physical security?", "options": ["A type of encrypted USB drive", "A double-door airlock that only lets one person through at a time after verification", "A trap set to catch script kiddies online", "A software tool for catching malware"], "correctIndex": 1, "explanation": "Mantrap (double door airlock) \u2014 physical access control jo ek time pe sirf ek verified person ko andar aane deta hai."}, {"id": "ch9_q48", "termRef": "physec", "type": "category", "difficulty": "medium", "question": "Which of these is listed as a physical security control in the guide?", "options": ["Keycards and biometrics", "SPF email records", "TLS handshakes", "SQL parameterized queries"], "correctIndex": 0, "explanation": "Keycards, biometrics, CCTV, guards, mantrap, cable locks on laptops, screen locks, clean desk policy, visitor logs \u2014 sab physical security controls hain."}, {"id": "ch9_q49", "termRef": "physec", "type": "scenario", "difficulty": "hard", "question": "An attacker follows closely behind an employee through a secure badge-access door without swiping their own card, and nobody stops them. Which physical security failure does this represent?", "options": ["A weak TLS handshake", "Tailgating that could have been prevented with a mantrap or vigilant staff", "A DNS poisoning attack", "A CASB misconfiguration"], "correctIndex": 1, "explanation": "Tailgating physical social engineering technique hai \u2014 mantrap jaisa control isko prevent karne ke liye design hua hai."}, {"id": "ch9_q50", "termRef": "physec", "type": "category", "difficulty": "medium", "question": "What does a 'clean desk policy' aim to prevent?", "options": ["Sensitive documents being left visible and accessible to unauthorized people", "Employees using two monitors instead of one", "Employees personalizing their workspace", "Employees eating lunch at their desks"], "correctIndex": 0, "explanation": "Clean desk policy \u2014 sensitive documents khule na chhode jaayein jahan koi bhi dekh/le sakta ho, ek physical security best practice."}]}, "10": {"chapter": 10, "chapterTitle": "Emerging & Essential Concepts", "termCount": 10, "questionCount": 50, "questions": [{"id": "ch10_q01", "termRef": "aisec", "type": "definition", "difficulty": "easy", "question": "What does 'AI Security' cover, according to the guide?", "options": ["Only antivirus software that uses no AI at all", "AI being used both as a tool for attackers and as a tool for defenders", "Only the security of self-driving cars", "Only AI being used to write marketing content"], "correctIndex": 1, "explanation": "AI as attacker aur defender \u2014 new arms race. Deepfake phishing, AI-generated malware ek taraf; anomaly detection, automated response doosri taraf."}, {"id": "ch10_q02", "termRef": "aisec", "type": "category", "difficulty": "medium", "question": "Which of these is listed as an example of 'AI as attacker' in the guide?", "options": ["Deepfake phishing using cloned voice or video", "Behavior analytics (UEBA)", "Automated threat response in a SIEM", "Smart log analysis at scale"], "correctIndex": 0, "explanation": "AI as Attacker: Deepfake phishing (voice/video clone), AI-generated perfect spear phishing emails, automated vulnerability discovery."}, {"id": "ch10_q03", "termRef": "aisec", "type": "real_world", "difficulty": "hard", "question": "WormGPT (2023) was notable for what capability?", "options": ["Detecting deepfakes with perfect accuracy", "Providing free cybersecurity training to students", "Generating phishing emails and malware code with no ethical restrictions, available on the dark web", "Automatically patching vulnerabilities for free"], "correctIndex": 2, "explanation": "WormGPT: ChatGPT jaise AI model, sans restrictions \u2014 phishing emails, malware code generate karta tha, dark web pe subscribe kiya ja sakta tha."}, {"id": "ch10_q04", "termRef": "aisec", "type": "category", "difficulty": "medium", "question": "Which of these is listed as an example of 'AI as defender' in the guide?", "options": ["Adversarial attacks on ML models", "AI-generated malware", "Anomaly detection and automated threat response", "AI-generated spear phishing emails"], "correctIndex": 2, "explanation": "AI as Defender: Anomaly detection, automated threat response, behavior analytics (UEBA), log analysis at scale, vulnerability prediction, smart SIEM."}, {"id": "ch10_q05", "termRef": "aisec", "type": "scenario", "difficulty": "hard", "question": "An attacker uses an AI tool to clone a CEO's voice and calls an employee requesting an urgent wire transfer. What category of AI-enabled threat does this represent?", "options": ["Automated vulnerability discovery", "Deepfake phishing", "Behavior analytics detection", "Smart SIEM defense"], "correctIndex": 1, "explanation": "Deepfake phishing (voice/video clone) \u2014 exactly is scenario ko match karta hai, AI ka attacker-side use."}, {"id": "ch10_q06", "termRef": "root", "type": "definition", "difficulty": "easy", "question": "What does 'root' mean in Linux/Unix systems?", "options": ["Superuser \u2014 full, unrestricted access to the system", "A type of encryption key", "A basic guest-level account with minimal access", "A network monitoring tool"], "correctIndex": 0, "explanation": "Linux/Unix mein 'root' = superuser = god mode. Windows mein 'Administrator'. Full unrestricted access \u2014 files delete, users create, services install."}, {"id": "ch10_q07", "termRef": "root", "type": "category", "difficulty": "medium", "question": "What is 'vertical privilege escalation'?", "options": ["Encrypting a file with a stronger algorithm", "Accessing another same-level user's data", "Moving laterally across a segmented network", "Going from a low-level user account to admin/root access"], "correctIndex": 3, "explanation": "Vertical privilege escalation (user \u2192 admin) \u2014 attackers hamesha root access tak escalate karne ki koshish karte hain."}, {"id": "ch10_q08", "termRef": "root", "type": "category", "difficulty": "medium", "question": "What is the Windows equivalent term for 'root' access on Linux/Unix systems?", "options": ["Domain User", "Standard User", "Administrator", "Guest"], "correctIndex": 2, "explanation": "Linux/Unix mein 'root', Windows mein 'Administrator' \u2014 dono terms same level of full access refer karte hain."}, {"id": "ch10_q09", "termRef": "root", "type": "scenario", "difficulty": "hard", "question": "A low-privilege user account on a compromised server exploits a vulnerability to gain full administrator control of the entire system. What is this called?", "options": ["Network segmentation bypass", "Horizontal privilege escalation", "A CASB failure", "Vertical privilege escalation"], "correctIndex": 3, "explanation": "Low-level user access se root access tak jaana \u2014 yehi vertical privilege escalation ki definition hai, ek critical vulnerability class."}, {"id": "ch10_q10", "termRef": "root", "type": "category", "difficulty": "medium", "question": "What is the goal an attacker typically has once inside a system with limited access, according to the guide?", "options": ["Immediately leaving the system without further action", "Only changing the desktop wallpaper", "Only reading publicly available files", "Escalating to root access for full control"], "correctIndex": 3, "explanation": "Attackers always try to escalate to root \u2014 full control ke liye yeh unka common goal hota hai."}, {"id": "ch10_q11", "termRef": "pwdcrack", "type": "definition", "difficulty": "easy", "question": "How do properly designed systems store passwords, according to the guide?", "options": ["As plain text for easy recovery", "Written down on paper only", "Only in the user's memory, never stored", "As a hash, not as plain text"], "correctIndex": 3, "explanation": "Proper systems passwords plain text nahi store karte \u2014 hash store karte hain. SHA256('password123') = fixed string."}, {"id": "ch10_q12", "termRef": "pwdcrack", "type": "category", "difficulty": "medium", "question": "Which tools does the guide mention as GPU-accelerated password cracking tools?", "options": ["Wireshark and Nmap", "Okta and Azure AD", "Splunk and QRadar", "Hashcat and John the Ripper"], "correctIndex": 3, "explanation": "Hashcat, John the Ripper \u2014 GPU-accelerated password cracking. RTX 4090 = 300 billion MD5 hashes/second."}, {"id": "ch10_q13", "termRef": "pwdcrack", "type": "defense", "difficulty": "medium", "question": "Which hashing algorithms does the guide specifically recommend NEVER using for passwords?", "options": ["Any algorithm at all is forbidden", "scrypt", "MD5 or SHA1", "bcrypt or Argon2"], "correctIndex": 2, "explanation": "Never use MD5 or SHA1 for passwords \u2014 instead bcrypt, Argon2, scrypt use karo, jo specifically slow hashing ke liye designed hain."}, {"id": "ch10_q14", "termRef": "pwdcrack", "type": "defense", "difficulty": "hard", "question": "What is the purpose of adding a 'salt' before hashing a password?", "options": ["Defeating precomputed rainbow table attacks", "Making the password visible in plain text for recovery", "Removing the need for a password entirely", "Speeding up the hashing process significantly"], "correctIndex": 0, "explanation": "Salt (random string add karo before hashing) \u2014 rainbow tables defeat karo, ek same password bhi alag hash produce karega alag salt ke saath."}, {"id": "ch10_q15", "termRef": "pwdcrack", "type": "scenario", "difficulty": "hard", "question": "The password 'password' gets cracked instantly, while 'Tr0ub4dor&3' takes years to crack using the same tool. What does this illustrate?", "options": ["GPU-based cracking tools don't affect crack time at all", "Password complexity and length dramatically affect crack resistance", "Only password length matters, complexity is irrelevant", "All passwords are equally vulnerable regardless of complexity"], "correctIndex": 1, "explanation": "'password' = cracked instantly, 'Tr0ub4dor&3' = years \u2014 yeh directly demonstrate karta hai ki complexity aur length crack resistance ko kitna affect karte hain."}, {"id": "ch10_q16", "termRef": "dos", "type": "definition", "difficulty": "easy", "question": "What is a DoS (Denial of Service) attack?", "options": ["A method for securely managing passwords", "An attack that only steals data, never disrupts availability", "An attack from a single source designed to make a service unavailable", "A type of encrypted backup process"], "correctIndex": 2, "explanation": "Single source se service unavailable karna \u2014 DoS: single machine se attack, DDoS: distributed sources se."}, {"id": "ch10_q17", "termRef": "dos", "type": "category", "difficulty": "medium", "question": "Why is a pure DoS attack described as easier to block than a DDoS attack?", "options": ["Because DoS attacks are illegal but DDoS is not", "Because DoS attacks never actually reach the target server", "Because DoS attacks always use encrypted traffic", "Since it comes from a single machine, you can simply ban that one IP"], "correctIndex": 3, "explanation": "DoS: Single machine se attack. Easy to block (IP ban karo). Limited bandwidth/impact \u2014 DDoS is is se harder hai kyunki hazaron sources hote hain."}, {"id": "ch10_q18", "termRef": "dos", "type": "category", "difficulty": "medium", "question": "Which type of DoS attack exhausts server resources using half-open TCP connections?", "options": ["Application layer attack", "Protocol attack (TCP SYN flood)", "Volumetric attack", "None of these types exist"], "correctIndex": 1, "explanation": "Protocol (TCP SYN flood \u2014 half-open connections exhaust karo), Volumetric (flood karo), Application layer (HTTP requests \u2014 web server crash)."}, {"id": "ch10_q19", "termRef": "dos", "type": "category", "difficulty": "medium", "question": "Which type of DoS attack works by sending HTTP requests that crash the web server directly at the application layer?", "options": ["Protocol attack", "None, this doesn't exist", "Application layer attack", "Volumetric attack"], "correctIndex": 2, "explanation": "Application layer (HTTP requests \u2014 web server crash) \u2014 each type needs different defense, according to the guide."}, {"id": "ch10_q20", "termRef": "dos", "type": "scenario", "difficulty": "hard", "question": "A single machine floods a small website with traffic, and the site's admin quickly identifies and blocks that one IP address, resolving the issue within minutes. What made this attack relatively easy to mitigate?", "options": ["It was a DoS attack from a single source, not a distributed DDoS", "It was an APT campaign", "It was a credential stuffing attempt", "It was actually a supply chain attack"], "correctIndex": 0, "explanation": "DoS single machine se attack hai isliye easy to block hai \u2014 ek IP ban karke resolve ho sakta hai, DDoS ke against yeh mushkil hota."}, {"id": "ch10_q21", "termRef": "ueba", "type": "definition", "difficulty": "easy", "question": "What does UEBA (User & Entity Behavior Analytics) do?", "options": ["Encrypts all network traffic automatically", "Manages a company's cloud storage costs", "Uses machine learning to baseline normal behavior and flag deviations", "Physically blocks unauthorized building access"], "correctIndex": 2, "explanation": "Machine learning se user aur entity ka normal behavior baseline karo, phir deviations flag karo."}, {"id": "ch10_q22", "termRef": "ueba", "type": "category", "difficulty": "medium", "question": "In the guide's example, what does UEBA flag when 'John usually logs in 9-5 from India'?", "options": ["John changing his own password", "John using a company laptop", "Any login during normal business hours", "A sudden 3am login from Russia"], "correctIndex": 3, "explanation": "John usually 9-5 India se login karta hai. Suddenly 3am Russia se login = red flag \u2014 behavioral deviation detect hoti hai."}, {"id": "ch10_q23", "termRef": "ueba", "type": "category", "difficulty": "medium", "question": "What kind of threats can UEBA detect that signature-based tools might miss?", "options": ["Only known malware with existing signatures", "Only threats from outside the organization, never insiders", "Zero-day threats, through unusual behavior rather than known signatures", "Only physical break-ins"], "correctIndex": 2, "explanation": "Zero-day threats bhi pakad sakta hai unusual behavior se \u2014 signature se nahi, behavior se detect karta hai."}, {"id": "ch10_q24", "termRef": "ueba", "type": "category", "difficulty": "medium", "question": "Which of these is listed as something UEBA can detect, according to the guide?", "options": ["Only hardware temperature spikes", "Only weather changes affecting servers", "Only software license expiration", "Data exfiltration and privilege abuse"], "correctIndex": 3, "explanation": "Detects: Insider threats, compromised accounts, data exfiltration, privilege abuse \u2014 sab behavior deviation ke through pakde jaate hain."}, {"id": "ch10_q25", "termRef": "ueba", "type": "scenario", "difficulty": "hard", "question": "An employee who normally downloads a few files a week suddenly downloads the company's entire customer database at 2am on a Sunday. A security tool automatically flags this as unusual. Which technology is most likely responsible?", "options": ["SSH", "UEBA", "NAT", "A digital certificate"], "correctIndex": 1, "explanation": "Unusual access times, large data downloads, off-hours logins \u2014 exactly UEBA jo behavior baseline se deviation detect karta hai."}, {"id": "ch10_q26", "termRef": "darkweb", "type": "definition", "difficulty": "easy", "question": "What technology is required to access the Dark Web?", "options": ["A standard web browser with no special software", "Tor", "A special type of antivirus", "A VPN alone, without any other tool"], "correctIndex": 1, "explanation": "Dark Web: Tor needed, anonymous, not indexed by Google \u2014 ek hidden part of the internet."}, {"id": "ch10_q27", "termRef": "darkweb", "type": "category", "difficulty": "medium", "question": "Roughly what percentage of the internet does the guide say makes up the 'Surface Web'?", "options": ["90%", "6%", "50%", "4%"], "correctIndex": 3, "explanation": "Surface Web: Google index karta hai (4%), Deep Web: not indexed (90%), Dark Web: Tor needed, not indexed (6%)."}, {"id": "ch10_q28", "termRef": "darkweb", "type": "analogy", "difficulty": "medium", "question": "Which analogy does the guide use to describe the layers of the internet?", "options": ["A postman delivering sealed letters", "A phone book listing every website", "A library with locked and unlocked sections", "An ocean, with the Dark Web compared to the Mariana Trench"], "correctIndex": 3, "explanation": "Ocean ki tarah \u2014 Surface = visible waala hissa, Deep = underwater, Dark = Mariana Trench, reach karna mushkil, genuinely dangerous creatures wahan."}, {"id": "ch10_q29", "termRef": "darkweb", "type": "category", "difficulty": "medium", "question": "Who originally created the Tor Project, according to the guide?", "options": ["The United Nations", "Google", "The US Navy", "A private cybercrime organization"], "correctIndex": 2, "explanation": "Tor Project made by US Navy \u2014 journalist whistleblowers, censorship bypass jaise legitimate uses bhi hain, dark web = mostly evil nahi hai."}, {"id": "ch10_q30", "termRef": "darkweb", "type": "category", "difficulty": "medium", "question": "Which of these is listed as a legitimate use of the Dark Web, according to the guide?", "options": ["Only stolen credential sales", "Only hacking-for-hire services", "Censorship bypass for activists in restrictive countries", "Only illegal drug marketplaces"], "correctIndex": 2, "explanation": "Dark web = journalist whistleblowers, censorship bypass (Iran, China activists), privacy enthusiasts \u2014 'not all evil'."}, {"id": "ch10_q31", "termRef": "cpa", "type": "definition", "difficulty": "easy", "question": "What is a Cyber-Physical Attack?", "options": ["A purely theoretical scenario that has never actually happened", "A cyberattack whose consequences manifest in the physical world", "An attack that only steals digital data with no real-world impact", "A type of physical break-in with no digital component"], "correctIndex": 1, "explanation": "Cyber attack jiske physical consequences hain \u2014 power grids off karna, traffic lights hack, water poison \u2014 digital command = physical disaster."}, {"id": "ch10_q32", "termRef": "cpa", "type": "real_world", "difficulty": "hard", "question": "In the Florida Water Treatment attack (2021), by how much did the hacker increase the sodium hydroxide levels?", "options": ["111x", "1.1x", "11x", "1,100x"], "correctIndex": 0, "explanation": "Hacker ne Oldsmar city ke water treatment plant ka SCADA system access kiya aur sodium hydroxide 111x badha diya \u2014 drinking water poison attempt, operator ne catch kiya."}, {"id": "ch10_q33", "termRef": "cpa", "type": "category", "difficulty": "medium", "question": "Who ultimately prevented disaster in the Florida Water Treatment attack case, according to the guide?", "options": ["A firewall automatically blocked the attacker", "The FBI intervened remotely in real time", "A human operator noticed and reversed the change", "An automated AI defense system"], "correctIndex": 2, "explanation": "Operator ne catch kiya, disaster averted \u2014 is case mein human vigilance ne bade damage ko roka."}, {"id": "ch10_q34", "termRef": "cpa", "type": "category", "difficulty": "medium", "question": "Which growing trend does the guide say is increasing the risk of cyber-physical attacks?", "options": ["Companies abandoning cloud computing entirely", "The decline of internet usage overall", "Smart cities and connected infrastructure (Industry 4.0)", "A reduction in the number of IoT devices"], "correctIndex": 2, "explanation": "Smart cities, connected infrastructure, Industry 4.0 \u2014 jitna zyada connectivity, utna zyada attack surface."}, {"id": "ch10_q35", "termRef": "cpa", "type": "scenario", "difficulty": "hard", "question": "An attacker gains access to a city's water treatment SCADA system and attempts to alter chemical dosing levels to dangerous amounts, but a vigilant operator catches and reverses it in time. What type of attack was attempted?", "options": ["A DDoS attack", "A Cyber-Physical Attack", "Credential stuffing", "A supply chain attack"], "correctIndex": 1, "explanation": "Digital command = physical disaster attempt \u2014 exactly cyber-physical attack ki definition, jaisa Florida water treatment case mein hua."}, {"id": "ch10_q36", "termRef": "cloudiam", "type": "definition", "difficulty": "easy", "question": "What does Cloud IAM control?", "options": ["Only email spam filtering rules", "Only physical access to a data center building", "Only which fonts are used in a cloud application", "Access to cloud provider resources like S3 buckets, EC2 instances, and databases"], "correctIndex": 3, "explanation": "Cloud provider ke resources (S3, EC2, databases) tak access control \u2014 roles, policies, permissions, kaunsa service kaunsa resource access kar sakta hai."}, {"id": "ch10_q37", "termRef": "cloudiam", "type": "category", "difficulty": "medium", "question": "What is the most common cause of cloud breaches, according to the guide?", "options": ["Encryption being too strong", "Misconfigured Cloud IAM", "Weather-related outages", "Physical theft of cloud servers"], "correctIndex": 1, "explanation": "Misconfigured Cloud IAM = most common cloud breach cause \u2014 yeh directly Capital One jaise breaches se bhi connect hota hai."}, {"id": "ch10_q38", "termRef": "cloudiam", "type": "category", "difficulty": "medium", "question": "Which of these is a recommended Cloud IAM best practice, according to the guide?", "options": ["Sharing long-lived access keys among all team members", "Not using the root account for daily use", "Disabling MFA on the root account", "Using the root account for all daily tasks"], "correctIndex": 1, "explanation": "Least privilege \u2014 root account daily use mat karo. MFA on root. Roles use karo instead of long-lived access keys."}, {"id": "ch10_q39", "termRef": "cloudiam", "type": "category", "difficulty": "medium", "question": "Which logging feature does the guide recommend enabling for cloud access auditing (specifically for AWS)?", "options": ["SPF records", "DNS Poisoning logs", "SSH key logs", "CloudTrail"], "correctIndex": 3, "explanation": "CloudTrail logging enable karo \u2014 regular access review ke saath, yeh AWS-specific auditing tool hai."}, {"id": "ch10_q40", "termRef": "cloudiam", "type": "scenario", "difficulty": "hard", "question": "A junior developer is given the cloud root account's long-lived access key for a simple daily task instead of a scoped, temporary role. What best practice does this violate?", "options": ["Using roles instead of long-lived access keys, and not using root for daily tasks", "The 3-2-1 backup rule", "The NIST Incident Response phases", "Chain of custody documentation"], "correctIndex": 0, "explanation": "Roles use karo instead of long-lived access keys, root account daily use mat karo \u2014 is scenario mein dono best practices violate ho rahi hain."}, {"id": "ch10_q41", "termRef": "databreach", "type": "definition", "difficulty": "easy", "question": "What is a Data Breach?", "options": ["A planned, authorized penetration test", "Sensitive or confidential information ending up in unauthorized hands", "A type of encrypted backup process", "A firewall configuration update"], "correctIndex": 1, "explanation": "Sensitive, confidential ya protected information unauthorized parties ke hands mein jaana \u2014 intentional ya accidental dono ho sakta hai."}, {"id": "ch10_q42", "termRef": "databreach", "type": "category", "difficulty": "medium", "question": "What is the average cost of a data breach, according to the guide (citing IBM 2023 data)?", "options": ["$4.45 million", "$445,000", "$44.5 million", "$4,450"], "correctIndex": 0, "explanation": "Average cost: $4.45 million (IBM 2023) \u2014 yeh statistic guide mein specifically diya gaya hai."}, {"id": "ch10_q43", "termRef": "databreach", "type": "category", "difficulty": "medium", "question": "Within how many hours must a data breach be reported under GDPR, according to the guide?", "options": ["7 days", "7 hours", "72 hours", "24 hours"], "correctIndex": 2, "explanation": "GDPR notification 72 hours mein required \u2014 yeh ek strict regulatory deadline hai companies ke liye."}, {"id": "ch10_q44", "termRef": "databreach", "type": "real_world", "difficulty": "hard", "question": "A 2018 report suggested that 1.1 billion Indians' Aadhaar data was accessible for how much money via WhatsApp?", "options": ["\u20b9500", "\u20b95,000", "\u20b950", "\u20b950,000"], "correctIndex": 0, "explanation": "Report aaya ki 1.1 billion Indians ka Aadhaar data accessible tha for \u20b9500 via WhatsApp \u2014 UIDAI ne deny kiya, par investigation ne serious vulnerabilities found."}, {"id": "ch10_q45", "termRef": "databreach", "type": "category", "difficulty": "medium", "question": "Which of these is listed as an aftermath consequence of a data breach, according to the guide?", "options": ["No impact on customer trust whatsoever", "Guaranteed government bailout funding", "Automatic exemption from future regulations", "Average stock price drop of 7.5%"], "correctIndex": 3, "explanation": "Stock price drop (avg 7.5%), customer trust loss, class action lawsuits, regulatory fines, executives fired \u2014 sab aftermath consequences hain."}, {"id": "ch10_q46", "termRef": "framework", "type": "definition", "difficulty": "easy", "question": "What is a Cybersecurity Framework?", "options": ["A type of encryption algorithm", "A physical lock mechanism for server rooms", "A single specific antivirus product", "A structured approach to managing cybersecurity risk"], "correctIndex": 3, "explanation": "Structured approach to manage cybersecurity risk \u2014 building code jaisa, ek common language aur standard approach deta hai."}, {"id": "ch10_q47", "termRef": "framework", "type": "category", "difficulty": "medium", "question": "What are the 5 core functions of the NIST Cybersecurity Framework (CSF)?", "options": ["Identify, Protect, Detect, Respond, Recover", "Plan, Build, Test, Deploy, Maintain", "Encrypt, Decrypt, Hash, Salt, Verify", "Scan, Patch, Report, Audit, Repeat"], "correctIndex": 0, "explanation": "NIST CSF: 1. Identify (assets, risks samjho), 2. Protect, 3. Detect, 4. Respond, 5. Recover \u2014 5 core functions."}, {"id": "ch10_q48", "termRef": "framework", "type": "category", "difficulty": "medium", "question": "Which framework specifically documents actual adversary tactics as a matrix?", "options": ["CIS Controls", "ISO 27001", "OWASP Top 10", "MITRE ATT&CK"], "correctIndex": 3, "explanation": "MITRE ATT&CK: Adversary tactics matrix \u2014 actual attack techniques documented, ek unique framework focused on attacker behavior."}, {"id": "ch10_q49", "termRef": "framework", "type": "analogy", "difficulty": "medium", "question": "Which analogy does the guide use to describe a cybersecurity framework?", "options": ["A CCTV control room watching cameras", "A building code for architecture \u2014 a common standard so engineers don't build inconsistently", "A postman delivering sealed letters", "A movie ticket used once for entry"], "correctIndex": 1, "explanation": "Building code for architecture jaisa \u2014 alag-alag engineers alag-alag sochein to inconsistency, framework ek common language aur standard approach deta hai."}, {"id": "ch10_q50", "termRef": "framework", "type": "category", "difficulty": "medium", "question": "Which framework specifically focuses on web application vulnerabilities?", "options": ["OWASP Top 10", "MITRE ATT&CK", "CIS Controls", "NIST CSF"], "correctIndex": 0, "explanation": "OWASP Top 10: Web vulnerabilities \u2014 ISO 27001 international standard hai, MITRE ATT&CK adversary tactics, CIS Controls top 18 security actions."}]}};
